(function setupDevModeBugOverlay() {
    if (window.__ssDevModeOverlayInitialized) return;
    window.__ssDevModeOverlayInitialized = true;

    const DEV_MODE_STORAGE_KEY = "ss.devMode";
    const DEV_PANEL_COLLAPSED_KEY = "ss.devModePanelCollapsed";
    const localHosts = ["127.0.0.1", "localhost"];
    const statFields = [
        { key: "acting", label: "Acting", property: "_actingStat" },
        { key: "comedy", label: "Comedy", property: "_comedyStat" },
        { key: "dance", label: "Dance", property: "_danceStat" },
        { key: "design", label: "Design", property: "_designStat" },
        { key: "improv", label: "Improv", property: "_improvStat" },
        { key: "runway", label: "Runway", property: "_runwayStat" },
        { key: "lipsync", label: "Lip Sync", property: "_lipsyncStat" }
    ];
    const quickChallenges = [
        { key: "acting", label: "Acting", action: () => actingChallenge() },
        { key: "comedy", label: "Comedy", action: () => comedyChallenge() },
        { key: "dance", label: "Dance", action: () => danceChallenge() },
        { key: "design", label: "Design", action: () => designChallenge() },
        { key: "marketing", label: "Marketing", action: () => marketingChallenge() },
        { key: "roast", label: "Roast", action: () => roastChallenge() },
        { key: "snatch", label: "Snatch Game", action: () => snatchGame() },
        { key: "rusical", label: "Rusical", action: () => rusical() },
        { key: "singing", label: "Singing", action: () => singingChallenge() },
        { key: "photoshoot", label: "Photoshoot", action: () => photoshootChallenge() }
    ];

    const query = new URLSearchParams(window.location.search || "");
    const queryEnabled = ["dev", "devmode", "debug"].some((key) => {
        const value = (query.get(key) || "").toLowerCase();
        return value === "1" || value === "true" || value === "on";
    });

    if (queryEnabled) {
        try {
            localStorage.setItem(DEV_MODE_STORAGE_KEY, "true");
        } catch (_err) {}
    }

    const devModeEnabled = localHosts.includes(window.location.hostname) || (() => {
        try {
            return localStorage.getItem(DEV_MODE_STORAGE_KEY) === "true";
        } catch (_err) {
            return false;
        }
    })();

    let overlay = null;
    let launcher = null;
    let list = null;
    let count = null;
    let queenSelect = null;
    let challengeSelect = null;
    let ppeInput = null;
    let trackRecordListEl = null;
    let episodeCountInput = null;
    let episodeListListEl = null;
    let criticalOverlay = null;
    let criticalSummary = null;
    let criticalReason = null;
    let criticalLog = null;
    let entries = [];
    let isCollapsed = false;
    let lastCriticalMessage = "";
    let lastCriticalDetails = "";
    let lastQueenSelectionValue = "";

    function escapeDevHtml(value) {
        return String(value ?? "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#39;");
    }

    function normalizeDevValue(value) {
        if (value instanceof Error) return value.stack || value.message || String(value);
        if (typeof value === "string") return value;
        try {
            return JSON.stringify(value);
        } catch (_err) {
            return String(value);
        }
    }

    function getDevQueens() {
        try {
            return Array.isArray(currentCast) ? currentCast.filter(Boolean) : [];
        } catch (_err) {
            return [];
        }
    }

    function clampStatValue(value) {
        const parsed = Number(value);
        if (!Number.isFinite(parsed)) return 0;
        return Math.max(0, Math.min(15, Math.round(parsed)));
    }

    function getQueenName(queen, index) {
        return queen?._name || queen?.name || `Queen ${index + 1}`;
    }

    function getCurrentQueenStatValue(queen, field) {
        return clampStatValue(queen?.[field.property] ?? queen?.[field.key] ?? 0);
    }

    function hasPendingStatEdits() {
        if (!overlay) return false;
        const queens = getDevQueens();
        const queenIndex = Number(queenSelect?.value ?? -1);
        const queen = queens[queenIndex];
        if (!queen) return false;

        return statFields.some((field) => {
            const input = overlay.querySelector(`[data-stat-key="${field.key}"]`);
            if (!input || input.disabled || input.value === "") return false;
            return clampStatValue(input.value) !== getCurrentQueenStatValue(queen, field);
        });
    }

    function getDevPanelBadgeMarkup() {
        return '<span class="ss-devtools-launcher__badge" data-dev-launcher-count>0</span>';
    }

    function announceDevPanelState() {
        window.dispatchEvent(new CustomEvent("ss-dev-panel-visibility", {
            detail: {
                enabled: devModeEnabled,
                open: devModeEnabled && !isCollapsed
            }
        }));
    }

    function setDevPanelCollapsed(nextValue) {
        isCollapsed = !!nextValue;
        try {
            localStorage.setItem(DEV_PANEL_COLLAPSED_KEY, isCollapsed ? "true" : "false");
        } catch (_err) {}
        if (overlay) overlay.classList.toggle("is-hidden", isCollapsed);
        if (launcher) launcher.classList.toggle("is-visible", isCollapsed);
        announceDevPanelState();
    }

    function formatBugEntriesForReport() {
        if (!entries.length) return "No bug log captured.";
        return entries.slice(-25).map((entry) => {
            const header = `[${entry.time}] ${String(entry.kind || "info").toUpperCase()}: ${entry.message}`;
            return entry.details ? `${header}\n${entry.details}` : header;
        }).join("\n\n");
    }

    function getCriticalBugReport() {
        return [
            "Simulator Superstars critical bug report",
            `Time: ${new Date().toISOString()}`,
            `Page: ${window.location.href}`,
            `User agent: ${navigator.userAgent}`,
            "",
            "Reason:",
            lastCriticalMessage || "Unknown critical error",
            lastCriticalDetails ? `\nDetails:\n${lastCriticalDetails}` : "",
            "",
            "Recent bug log:",
            formatBugEntriesForReport()
        ].join("\n");
    }

    async function copyCriticalBugReport() {
        const text = getCriticalBugReport();
        try {
            if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
                await navigator.clipboard.writeText(text);
            } else {
                const temp = document.createElement("textarea");
                temp.value = text;
                temp.setAttribute("readonly", "readonly");
                temp.style.position = "fixed";
                temp.style.opacity = "0";
                document.body.appendChild(temp);
                temp.focus();
                temp.select();
                document.execCommand("copy");
                temp.remove();
            }
            if (typeof showFloatingNotice === "function") {
                showFloatingNotice("Bug log copied", 1500);
            }
        } catch (_err) {
            window.prompt("Copy this bug log:", text);
        }
    }

    function ensureCriticalOverlay() {
        if (criticalOverlay || !document.body) return criticalOverlay;

        criticalOverlay = document.createElement("div");
        criticalOverlay.id = "ss-critical-bug-overlay";
        criticalOverlay.className = "ss-critical";

        criticalOverlay.innerHTML = `
            <div class="ss-critical__card">
                <div class="ss-critical__head">
                    <div>
                        <div class="ss-critical__title">Critical simulator error</div>
                        <div class="ss-critical__subtitle">The sim hit a fatal bug and stopped safely.</div>
                    </div>
                    <button type="button" data-critical-close class="ss-devtools__btn">Close</button>
                </div>
                <div class="ss-critical__reason-block">
                    <div class="ss-critical__label">Why it broke</div>
                    <div data-critical-summary class="ss-critical__summary">Unknown critical error</div>
                    <pre data-critical-reason class="ss-critical__pre">No extra details were captured.</pre>
                </div>
                <div class="ss-critical__actions">
                    <button type="button" data-critical-copy class="ss-devtools__btn ss-devtools__btn--solid">Copy bug log</button>
                    <button type="button" data-critical-reload class="ss-devtools__btn">Reload sim</button>
                </div>
                <div class="ss-critical__log-wrap">
                    <div class="ss-critical__label">Bug log</div>
                    <pre data-critical-log class="ss-critical__log">No bug log captured.</pre>
                </div>
            </div>
        `;

        criticalSummary = criticalOverlay.querySelector("[data-critical-summary]");
        criticalReason = criticalOverlay.querySelector("[data-critical-reason]");
        criticalLog = criticalOverlay.querySelector("[data-critical-log]");

        const closeBtn = criticalOverlay.querySelector("[data-critical-close]");
        const copyBtn = criticalOverlay.querySelector("[data-critical-copy]");
        const reloadBtn = criticalOverlay.querySelector("[data-critical-reload]");

        if (closeBtn) {
            closeBtn.addEventListener("click", () => {
                criticalOverlay.classList.remove("is-visible");
            });
        }
        if (copyBtn) {
            copyBtn.addEventListener("click", () => {
                copyCriticalBugReport();
            });
        }
        if (reloadBtn) {
            reloadBtn.addEventListener("click", () => {
                window.location.reload();
            });
        }

        document.documentElement.appendChild(criticalOverlay);
        return criticalOverlay;
    }

    function showCriticalBugOverlay(message, details = "") {
        lastCriticalMessage = normalizeDevValue(message || "Unknown critical error");
        lastCriticalDetails = normalizeDevValue(details || "");

        if (!document.body) {
            document.addEventListener("DOMContentLoaded", () => {
                showCriticalBugOverlay(lastCriticalMessage, lastCriticalDetails);
            }, { once: true });
            return;
        }

        const panel = ensureCriticalOverlay();
        if (!panel) return;

        if (criticalSummary) criticalSummary.textContent = lastCriticalMessage;
        if (criticalReason) criticalReason.textContent = lastCriticalDetails || "No extra details were captured.";
        if (criticalLog) criticalLog.textContent = getCriticalBugReport();
        panel.classList.add("is-visible");
    }

    function ensureLauncher() {
        if (launcher || !document.body) return launcher;

        launcher = document.createElement("button");
        launcher.type = "button";
        launcher.id = "ss-dev-bug-launcher";
        launcher.className = "ss-devtools-launcher";
        launcher.innerHTML = `<span>Open Dev Tools</span>${getDevPanelBadgeMarkup()}`;
        launcher.addEventListener("click", () => {
            setDevPanelCollapsed(false);
            renderOverlay();
        });
        document.documentElement.appendChild(launcher);
        return launcher;
    }

    function ensureOverlay() {
        if (overlay || !document.body) return overlay;

        overlay = document.createElement("div");
        overlay.id = "ss-dev-bug-overlay";
        overlay.className = "ss-devtools";

        overlay.innerHTML = `
            <div class="ss-devtools__header">
                <div>
                    <div class="ss-devtools__title">Dev Werkroom</div>
                    <div class="ss-devtools__subtitle">Tools, tuning, and bug tracking</div>
                </div>
                <div class="ss-devtools__actions">
                    <span data-dev-count class="ss-devtools__count">0</span>
                    <button type="button" data-dev-refresh class="ss-devtools__btn">Sync</button>
                    <button type="button" data-dev-clear class="ss-devtools__btn">Clear</button>
                    <button type="button" data-dev-hide class="ss-devtools__btn ss-devtools__btn--solid">Hide</button>
                </div>
            </div>
            <div class="ss-devtools__body">
                <div class="ss-devtools__section">
                    <div class="ss-devtools__section-title">Queen stat editor</div>
                    <select data-dev-queen class="ss-devtools__select"></select>
                    <div data-dev-stats-grid class="ss-devtools__stats-grid"></div>
                    <button type="button" data-dev-apply class="ss-devtools__btn ss-devtools__btn--solid ss-devtools__btn--wide">Apply stats</button>
                </div>
                <div class="ss-devtools__section">
                    <div class="ss-devtools__section-title">Track record toolbox</div>
                    <div class="ss-devtools__field-row">
                        <label class="ss-devtools__field">
                            <span>PPE</span>
                            <input type="number" step="0.01" data-dev-ppe class="ss-devtools__input">
                        </label>
                        <button type="button" data-dev-apply-ppe class="ss-devtools__btn ss-devtools__btn--solid">Apply PPE</button>
                    </div>
                    <div data-dev-trackrecord-list class="ss-devtools__list"></div>
                    <button type="button" data-dev-tr-add class="ss-devtools__btn ss-devtools__btn--ghost ss-devtools__btn--wide">+ Add track record entry</button>
                </div>
                <div class="ss-devtools__section">
                    <div class="ss-devtools__section-title">Season toolbox</div>
                    <div class="ss-devtools__field-row">
                        <label class="ss-devtools__field">
                            <span>Episode count</span>
                            <input type="number" min="0" step="1" data-dev-episode-count class="ss-devtools__input">
                        </label>
                        <button type="button" data-dev-apply-episode-count class="ss-devtools__btn ss-devtools__btn--solid">Apply</button>
                    </div>
                    <div class="ss-devtools__section-title">Episode challenge list</div>
                    <div data-dev-episodelist-list class="ss-devtools__list"></div>
                    <button type="button" data-dev-ep-add class="ss-devtools__btn ss-devtools__btn--ghost ss-devtools__btn--wide">+ Add episode entry</button>
                </div>
                <div class="ss-devtools__section">
                    <div class="ss-devtools__section-title">Challenge tester</div>
                    <div class="ss-devtools__inline-actions">
                        <select data-dev-challenge class="ss-devtools__select"></select>
                        <button type="button" data-dev-run class="ss-devtools__btn ss-devtools__btn--solid">Run</button>
                    </div>
                </div>
                <div class="ss-devtools__section">
                    <div class="ss-devtools__section-title">Bug feed</div>
                    <div data-dev-list class="ss-devtools__list ss-devtools__list--feed"></div>
                </div>
            </div>
        `;

        const body = overlay.querySelector(".ss-devtools__body");
        const sections = Array.from(body.children);
        const tabs = document.createElement("div");
        tabs.className = "ss-devtools__tabs";
        tabs.setAttribute("role", "tablist");
        tabs.setAttribute("aria-label", "Developer tools categories");
        const groups = [
            { id: "queens", label: "Queens", sections: sections.slice(0, 2) },
            { id: "season", label: "Season", sections: sections.slice(2, 4) },
            { id: "bugs", label: "Bug feed", sections: sections.slice(4) }
        ];
        const panels = groups.map(group => {
            const panel = document.createElement("div");
            panel.id = `dev-panel-${group.id}`;
            panel.className = "ss-devtools__tab-panel";
            panel.setAttribute("role", "tabpanel");
            panel.setAttribute("aria-labelledby", `dev-tab-${group.id}`);
            panel.append(...group.sections);
            return panel;
        });
        const buttons = groups.map((group, index) => {
            const button = document.createElement("button");
            button.type = "button";
            button.id = `dev-tab-${group.id}`;
            button.className = "ss-devtools__btn";
            button.textContent = group.label;
            button.setAttribute("role", "tab");
            button.setAttribute("aria-controls", panels[index].id);
            return button;
        });
        const selectTab = index => {
            buttons.forEach((button, position) => {
                button.setAttribute("aria-selected", String(position === index));
                button.tabIndex = position === index ? 0 : -1;
                panels[position].hidden = position !== index;
            });
            body.scrollTop = 0;
        };
        buttons.forEach((button, index) => {
            button.addEventListener("click", () => selectTab(index));
            button.addEventListener("keydown", event => {
                let next;
                if (event.key === "ArrowRight") next = (index + 1) % buttons.length;
                else if (event.key === "ArrowLeft") next = (index + buttons.length - 1) % buttons.length;
                else if (event.key === "Home") next = 0;
                else if (event.key === "End") next = buttons.length - 1;
                else return;
                event.preventDefault();
                selectTab(next);
                buttons[next].focus();
            });
        });
        tabs.append(...buttons);
        body.replaceChildren(...panels);
        body.before(tabs);
        selectTab(0);

        list = overlay.querySelector("[data-dev-list]");
        count = overlay.querySelector("[data-dev-count]");
        queenSelect = overlay.querySelector("[data-dev-queen]");
        challengeSelect = overlay.querySelector("[data-dev-challenge]");
        ppeInput = overlay.querySelector("[data-dev-ppe]");
        trackRecordListEl = overlay.querySelector("[data-dev-trackrecord-list]");
        episodeCountInput = overlay.querySelector("[data-dev-episode-count]");
        episodeListListEl = overlay.querySelector("[data-dev-episodelist-list]");

        const statsGrid = overlay.querySelector("[data-dev-stats-grid]");
        if (statsGrid) {
            statsGrid.innerHTML = statFields.map((field) => `
                <label class="ss-devtools__field">
                    <span>${field.label}</span>
                    <input type="number" min="0" max="15" step="1" data-stat-key="${field.key}" class="ss-devtools__input">
                </label>
            `).join("");
        }

        if (challengeSelect) {
            challengeSelect.innerHTML = quickChallenges.map((challenge) => `<option value="${challenge.key}">${challenge.label}</option>`).join("");
        }

        const clearBtn = overlay.querySelector("[data-dev-clear]");
        const refreshBtn = overlay.querySelector("[data-dev-refresh]");
        const hideBtn = overlay.querySelector("[data-dev-hide]");
        const applyBtn = overlay.querySelector("[data-dev-apply]");
        const runBtn = overlay.querySelector("[data-dev-run]");
        const applyPpeBtn = overlay.querySelector("[data-dev-apply-ppe]");
        const trAddBtn = overlay.querySelector("[data-dev-tr-add]");
        const applyEpisodeCountBtn = overlay.querySelector("[data-dev-apply-episode-count]");
        const epAddBtn = overlay.querySelector("[data-dev-ep-add]");

        if (clearBtn) {
            clearBtn.addEventListener("click", () => {
                entries = [];
                renderOverlay();
            });
        }
        if (refreshBtn) {
            refreshBtn.addEventListener("click", () => {
                populateQueenSelect();
                pushDevBug("info", "Dev panel synced", "The current cast and controls were refreshed.");
            });
        }
        if (hideBtn) {
            hideBtn.addEventListener("click", () => {
                setDevPanelCollapsed(true);
            });
        }
        if (queenSelect) {
            queenSelect.addEventListener("change", () => {
                syncQueenInputsFromSelection({ force: true });
            });
        }
        if (applyBtn) {
            applyBtn.addEventListener("click", applySelectedQueenStats);
        }
        if (runBtn) {
            runBtn.addEventListener("click", runSelectedChallenge);
        }
        if (applyPpeBtn) {
            applyPpeBtn.addEventListener("click", applySelectedQueenPPE);
        }
        if (trAddBtn) {
            trAddBtn.addEventListener("click", addTrackRecordEntry);
        }
        if (applyEpisodeCountBtn) {
            applyEpisodeCountBtn.addEventListener("click", applyEpisodeCountEdit);
        }
        if (epAddBtn) {
            epAddBtn.addEventListener("click", addEpisodeListEntry);
        }

        document.documentElement.appendChild(overlay);
        ensureLauncher();
        populateQueenSelect();
        try {
            isCollapsed = localStorage.getItem(DEV_PANEL_COLLAPSED_KEY) === "true";
        } catch (_err) {
            isCollapsed = false;
        }
        setDevPanelCollapsed(isCollapsed);
        return overlay;
    }

    function populateQueenSelect() {
        if (!overlay || !queenSelect) return;
        const queens = getDevQueens();
        const previousValue = queenSelect.value;

        if (queens.length === 0) {
            queenSelect.innerHTML = '<option value="">No queens in current cast</option>';
            queenSelect.disabled = true;
            lastQueenSelectionValue = "";
            syncQueenInputsFromSelection({ force: true });
            return;
        }

        queenSelect.disabled = false;
        queenSelect.innerHTML = queens.map((queen, index) => `<option value="${index}">${escapeDevHtml(getQueenName(queen, index))}</option>`).join("");

        if (previousValue && queens[Number(previousValue)]) {
            queenSelect.value = previousValue;
        }

        const selectionChanged = queenSelect.value !== lastQueenSelectionValue;
        lastQueenSelectionValue = queenSelect.value;
        syncQueenInputsFromSelection({ force: selectionChanged });
    }

    function syncQueenInputsFromSelection(options = {}) {
        if (!overlay) return;
        const forceSync = !!options.force;
        if (!forceSync && hasPendingStatEdits()) return;

        const queens = getDevQueens();
        const queenIndex = Number(queenSelect?.value ?? -1);
        const queen = queens[queenIndex];

        statFields.forEach((field) => {
            const input = overlay.querySelector(`[data-stat-key="${field.key}"]`);
            if (!input) return;
            input.disabled = !queen;
            input.value = queen ? String(getCurrentQueenStatValue(queen, field)) : "";
        });

        renderTrackRecordEditor();
    }

    function applySelectedQueenStats() {
        const queens = getDevQueens();
        const queenIndex = Number(queenSelect?.value ?? -1);
        const queen = queens[queenIndex];

        if (!queen) {
            pushDevBug("warn", "No queen selected", "Pick a queen from the current cast before editing stats.");
            return;
        }

        statFields.forEach((field) => {
            const input = overlay.querySelector(`[data-stat-key="${field.key}"]`);
            if (!input) return;
            const nextValue = clampStatValue(input.value);
            queen[field.property] = nextValue;
            queen[field.key] = nextValue;
            input.value = String(nextValue);
        });

        pushDevBug("info", `${getQueenName(queen, queenIndex)} updated`, "Stats were changed from the developer panel.");
        if (typeof showFloatingNotice === "function") {
            showFloatingNotice(`${getQueenName(queen, queenIndex)} stats updated`, 1200);
        }
    }

    function getSelectedDevQueen() {
        const queens = getDevQueens();
        const queenIndex = Number(queenSelect?.value ?? -1);
        return queens[queenIndex] || null;
    }

    function renderTrackRecordEditor() {
        if (!overlay || !trackRecordListEl) return;
        const queen = getSelectedDevQueen();

        if (ppeInput) {
            ppeInput.disabled = !queen;
            ppeInput.value = queen ? String(queen.ppe ?? 0) : "";
        }

        if (!queen || !Array.isArray(queen.trackRecord) || queen.trackRecord.length === 0) {
            trackRecordListEl.innerHTML = '<div class="ss-devtools__empty">No track record entries.</div>';
            return;
        }

        trackRecordListEl.innerHTML = queen.trackRecord.map((entry, index) => `
            <div class="ss-devtools__row">
                <div class="ss-devtools__row-main">
                    <span class="ss-devtools__row-index">${index + 1}</span>
                    <input type="text" data-tr-value="${index}" value="${escapeDevHtml(entry)}" class="ss-devtools__row-input">
                </div>
                <div class="ss-devtools__row-actions">
                    <button type="button" data-tr-up="${index}" title="Move up" aria-label="Move up" class="ss-devtools__btn ss-devtools__btn--icon">\u25B2</button>
                    <button type="button" data-tr-down="${index}" title="Move down" aria-label="Move down" class="ss-devtools__btn ss-devtools__btn--icon">\u25BC</button>
                    <button type="button" data-tr-remove="${index}" title="Remove" aria-label="Remove" class="ss-devtools__btn ss-devtools__btn--icon ss-devtools__btn--danger">\u2715</button>
                </div>
            </div>
        `).join("");

        trackRecordListEl.querySelectorAll("[data-tr-value]").forEach((input) => {
            input.addEventListener("change", () => {
                const index = Number(input.getAttribute("data-tr-value"));
                const currentQueen = getSelectedDevQueen();
                if (!currentQueen || !Array.isArray(currentQueen.trackRecord)) return;
                currentQueen.trackRecord[index] = input.value;
                pushDevBug("info", "Track record entry edited", `${getQueenName(currentQueen, Number(queenSelect?.value ?? -1))} episode ${index + 1} set to "${input.value}".`);
            });
        });
        trackRecordListEl.querySelectorAll("[data-tr-up]").forEach((btn) => {
            btn.addEventListener("click", () => moveTrackRecordEntry(Number(btn.getAttribute("data-tr-up")), -1));
        });
        trackRecordListEl.querySelectorAll("[data-tr-down]").forEach((btn) => {
            btn.addEventListener("click", () => moveTrackRecordEntry(Number(btn.getAttribute("data-tr-down")), 1));
        });
        trackRecordListEl.querySelectorAll("[data-tr-remove]").forEach((btn) => {
            btn.addEventListener("click", () => removeTrackRecordEntry(Number(btn.getAttribute("data-tr-remove"))));
        });
    }

    function moveTrackRecordEntry(index, direction) {
        const queen = getSelectedDevQueen();
        if (!queen || !Array.isArray(queen.trackRecord)) return;
        const targetIndex = index + direction;
        if (targetIndex < 0 || targetIndex >= queen.trackRecord.length) return;
        const [entry] = queen.trackRecord.splice(index, 1);
        queen.trackRecord.splice(targetIndex, 0, entry);
        renderTrackRecordEditor();
        pushDevBug("info", "Track record reordered", `${getQueenName(queen, Number(queenSelect?.value ?? -1))}'s track record was rearranged.`);
    }

    function removeTrackRecordEntry(index) {
        const queen = getSelectedDevQueen();
        if (!queen || !Array.isArray(queen.trackRecord)) return;
        if (index < 0 || index >= queen.trackRecord.length) return;
        queen.trackRecord.splice(index, 1);
        renderTrackRecordEditor();
        pushDevBug("info", "Track record entry removed", `${getQueenName(queen, Number(queenSelect?.value ?? -1))}'s episode ${index + 1} entry was removed.`);
    }

    function addTrackRecordEntry() {
        const queen = getSelectedDevQueen();
        if (!queen) {
            pushDevBug("warn", "No queen selected", "Pick a queen before editing their track record.");
            return;
        }
        if (!Array.isArray(queen.trackRecord)) queen.trackRecord = [];
        queen.trackRecord.push("SAFE");
        renderTrackRecordEditor();
    }

    function applySelectedQueenPPE() {
        const queen = getSelectedDevQueen();
        if (!queen || !ppeInput) {
            pushDevBug("warn", "No queen selected", "Pick a queen before editing PPE.");
            return;
        }
        const nextValue = Number(ppeInput.value);
        queen.ppe = Number.isFinite(nextValue) ? nextValue : 0;
        ppeInput.value = String(queen.ppe);
        const queenIndex = Number(queenSelect?.value ?? -1);
        pushDevBug("info", `${getQueenName(queen, queenIndex)} PPE updated`, `PPE set to ${queen.ppe}.`);
        if (typeof showFloatingNotice === "function") {
            showFloatingNotice(`${getQueenName(queen, queenIndex)} PPE updated`, 1200);
        }
    }

    function renderEpisodeListEditor() {
        if (!overlay || !episodeListListEl) return;

        if (episodeCountInput && document.activeElement !== episodeCountInput) {
            episodeCountInput.value = typeof episodeCount === "number" ? String(episodeCount) : "0";
        }

        const list = (typeof episodeChallenges !== "undefined" && Array.isArray(episodeChallenges)) ? episodeChallenges : [];
        if (list.length === 0) {
            episodeListListEl.innerHTML = '<div class="ss-devtools__empty">No episodes logged yet.</div>';
            return;
        }

        episodeListListEl.innerHTML = list.map((entry, index) => `
            <div class="ss-devtools__row">
                <div class="ss-devtools__row-main">
                    <span class="ss-devtools__row-index">${index + 1}</span>
                    <input type="text" data-ep-value="${index}" value="${escapeDevHtml(entry)}" class="ss-devtools__row-input">
                </div>
                <div class="ss-devtools__row-actions">
                    <button type="button" data-ep-up="${index}" title="Move up" aria-label="Move up" class="ss-devtools__btn ss-devtools__btn--icon">\u25B2</button>
                    <button type="button" data-ep-down="${index}" title="Move down" aria-label="Move down" class="ss-devtools__btn ss-devtools__btn--icon">\u25BC</button>
                    <button type="button" data-ep-remove="${index}" title="Remove" aria-label="Remove" class="ss-devtools__btn ss-devtools__btn--icon ss-devtools__btn--danger">\u2715</button>
                </div>
            </div>
        `).join("");

        episodeListListEl.querySelectorAll("[data-ep-value]").forEach((input) => {
            input.addEventListener("change", () => {
                const index = Number(input.getAttribute("data-ep-value"));
                if (!Array.isArray(episodeChallenges)) return;
                episodeChallenges[index] = input.value;
                pushDevBug("info", "Episode entry edited", `Episode ${index + 1} set to "${input.value}".`);
            });
        });
        episodeListListEl.querySelectorAll("[data-ep-up]").forEach((btn) => {
            btn.addEventListener("click", () => moveEpisodeListEntry(Number(btn.getAttribute("data-ep-up")), -1));
        });
        episodeListListEl.querySelectorAll("[data-ep-down]").forEach((btn) => {
            btn.addEventListener("click", () => moveEpisodeListEntry(Number(btn.getAttribute("data-ep-down")), 1));
        });
        episodeListListEl.querySelectorAll("[data-ep-remove]").forEach((btn) => {
            btn.addEventListener("click", () => removeEpisodeListEntry(Number(btn.getAttribute("data-ep-remove"))));
        });
    }

    function moveEpisodeListEntry(index, direction) {
        if (!Array.isArray(episodeChallenges)) return;
        const targetIndex = index + direction;
        if (targetIndex < 0 || targetIndex >= episodeChallenges.length) return;
        const [entry] = episodeChallenges.splice(index, 1);
        episodeChallenges.splice(targetIndex, 0, entry);
        renderEpisodeListEditor();
        pushDevBug("info", "Episode list reordered", "The episode challenge list was rearranged.");
    }

    function removeEpisodeListEntry(index) {
        if (!Array.isArray(episodeChallenges)) return;
        if (index < 0 || index >= episodeChallenges.length) return;
        episodeChallenges.splice(index, 1);
        renderEpisodeListEditor();
        pushDevBug("info", "Episode entry removed", `Episode ${index + 1} entry was removed.`);
    }

    function addEpisodeListEntry() {
        if (!Array.isArray(episodeChallenges)) return;
        episodeChallenges.push("Challenge");
        renderEpisodeListEditor();
    }

    function applyEpisodeCountEdit() {
        if (!episodeCountInput) return;
        const nextValue = Math.floor(Number(episodeCountInput.value));
        if (!Number.isFinite(nextValue) || nextValue < 0) {
            pushDevBug("warn", "Invalid episode count", "Enter a whole number of 0 or more for the episode count.");
            return;
        }
        episodeCount = nextValue;
        episodeCountInput.value = String(episodeCount);
        pushDevBug("info", "Episode count updated", `Episode count set to ${episodeCount}.`);
        if (typeof showFloatingNotice === "function") {
            showFloatingNotice(`Episode count set to ${episodeCount}`, 1200);
        }
    }

    function runSelectedChallenge() {
        const selected = quickChallenges.find((challenge) => challenge.key === challengeSelect?.value);
        const queens = getDevQueens();

        if (!selected) {
            pushDevBug("warn", "No challenge selected", "Choose a challenge from the dropdown first.");
            return;
        }

        if (!queens.length) {
            pushDevBug("warn", "No active cast", "Start or load a cast before running a challenge from dev mode.");
            return;
        }

        try {
            selected.action();
            pushDevBug("info", `${selected.label} launched`, `Triggered for ${queens.length} queen(s).`);
        } catch (err) {
            pushDevBug("error", `Failed to run ${selected.label}`, err?.stack || err?.message || err);
        }
    }

    function renderOverlay() {
        if (!devModeEnabled) return;
        const panel = ensureOverlay();
        if (!panel || !list || !count) return;

        count.textContent = String(entries.length);
        const launcherCount = launcher?.querySelector("[data-dev-launcher-count]");
        if (launcherCount) launcherCount.textContent = String(entries.length);
        renderEpisodeListEditor();

        if (entries.length === 0) {
            list.innerHTML = '<div class="ss-devtools__empty">No bugs logged yet.</div>';
            return;
        }

        list.innerHTML = entries.slice(-18).reverse().map((entry) => {
            const kindClass = entry.kind === "error" ? "ss-devtools__bug-kind--error" : entry.kind === "warn" ? "ss-devtools__bug-kind--warn" : "ss-devtools__bug-kind--info";
            return `
                <div class="ss-devtools__bug">
                    <div class="ss-devtools__bug-head">
                        <strong class="ss-devtools__bug-kind ${kindClass}">${escapeDevHtml(entry.kind)}</strong>
                        <span class="ss-devtools__bug-time">${escapeDevHtml(entry.time)}</span>
                    </div>
                    <div class="ss-devtools__bug-msg">${escapeDevHtml(entry.message)}</div>
                    ${entry.details ? `<details class="ss-devtools__bug-details"><summary>Details</summary><pre>${escapeDevHtml(entry.details)}</pre></details>` : ""}
                </div>
            `;
        }).join("");
    }

    function pushDevBug(kind, message, details = "") {
        entries.push({
            kind,
            message: normalizeDevValue(message),
            details: normalizeDevValue(details || ""),
            time: new Date().toLocaleTimeString()
        });
        if (entries.length > 60) entries = entries.slice(-60);
        if (devModeEnabled) renderOverlay();
        if (criticalOverlay && criticalOverlay.classList.contains("is-visible") && criticalLog) {
            criticalLog.textContent = getCriticalBugReport();
        }
    }

    window.isDevModeEnabled = function() {
        return devModeEnabled;
    };

    window.isDevModePanelOpen = function() {
        return devModeEnabled && !isCollapsed;
    };

    window.enableDevMode = function() {
        try {
            localStorage.setItem(DEV_MODE_STORAGE_KEY, "true");
        } catch (_err) {}
        window.location.reload();
    };

    window.disableDevMode = function() {
        try {
            localStorage.removeItem(DEV_MODE_STORAGE_KEY);
        } catch (_err) {}
        if (overlay) overlay.remove();
        if (launcher) launcher.remove();
    };

    window.refreshDevModePanel = function() {
        populateQueenSelect();
        renderOverlay();
    };

    window.setDevModePanelOpen = function(forceState) {
        if (!devModeEnabled) return false;
        if (forceState) {
            setDevPanelCollapsed(false);
        } else {
            isCollapsed = true;
            try {
                localStorage.setItem(DEV_PANEL_COLLAPSED_KEY, "true");
            } catch (_err) {}
            if (overlay) overlay.classList.add("is-hidden");
            if (launcher) launcher.classList.remove("is-visible");
            announceDevPanelState();
        }
        renderOverlay();
        return true;
    };

    window.toggleDevModePanel = function(forceState) {
        const nextState = typeof forceState === "boolean" ? forceState : !isCollapsed;
        setDevPanelCollapsed(nextState);
        renderOverlay();
    };

    window.showDevBug = pushDevBug;
    window.showCriticalBugOverlay = showCriticalBugOverlay;
    window.__ssCriticalBugReportBuilder = getCriticalBugReport;
    window.getCriticalBugLog = function() {
        try {
            if (typeof window.__ssCriticalBugReportBuilder === "function") {
                return window.__ssCriticalBugReportBuilder();
            }
        } catch (_err) {}
        return "No bug log captured.";
    };

    const originalConsoleError = typeof console.error === "function" ? console.error.bind(console) : null;
    const originalConsoleWarn = typeof console.warn === "function" ? console.warn.bind(console) : null;

    if (originalConsoleError) {
        console.error = function(...args) {
            pushDevBug("error", args.map(normalizeDevValue).join(" "));
            return originalConsoleError(...args);
        };
    }

    if (originalConsoleWarn) {
        console.warn = function(...args) {
            pushDevBug("warn", args.map(normalizeDevValue).join(" "));
            return originalConsoleWarn(...args);
        };
    }

    window.addEventListener("error", (event) => {
        if (!event.message && !event.error) return;
        const target = event.target;
        const targetSource = target && (target.src || target.href || target.currentSrc) ? (target.src || target.href || target.currentSrc) : "";
        const source = event.filename
            ? `${event.filename}:${event.lineno || 0}`
            : targetSource
                ? `resource:${targetSource}`
                : "runtime";
        const message = event.message || "Script error";
        const details = [
            source,
            event.error?.stack || "",
            event.message === "Script error" && !event.filename
                ? "Opaque cross-origin script error; the browser withheld the original source."
                : ""
        ].filter(Boolean).join("\n");
        pushDevBug("error", message, details);
        showCriticalBugOverlay(message, details);
    });

    window.addEventListener("unhandledrejection", (event) => {
        const reason = event.reason;
        const message = reason?.message || (typeof reason === "string" ? reason : "Unhandled promise rejection");
        const details = reason?.stack || (reason && typeof reason === "object" ? JSON.stringify(reason) : "Promise rejection with no stack trace.");
        pushDevBug("error", message, details);
        showCriticalBugOverlay(message, details);
    });

    if (!devModeEnabled) return;

    document.addEventListener("DOMContentLoaded", () => {
        renderOverlay();
        populateQueenSelect();
        pushDevBug("info", "Dev mode enabled", "You can edit active queen stats and force a challenge from here.");
        window.setInterval(() => {
            if (document.hidden) return;
            populateQueenSelect();
        }, 2500);
    }, { once: true });
})();

let finaleManualWinners = [];
let manualLipSyncWinnerQueues = {};
let manualLipSyncSelection = null;

function beginManualLipSyncWinnerSelection(queueKey, matchups, onCompleteFnName, options = {}) {
    if (!Array.isArray(matchups) || matchups.length === 0) {
        if (typeof window[onCompleteFnName] === "function") {
            window[onCompleteFnName]();
        }
        return;
    }
    manualLipSyncSelection = {
        queueKey,
        matchups,
        onCompleteFnName,
        header: options.header || "Choose Lip Sync Winners",
        subtitle: options.subtitle || "Check who stays. Check both for a tie (double shantay), or uncheck both for a double sashay.",
        stepTitle: options.stepTitle || "Matchup",
        currentIndex: 0,
        outcomes: []
    };
    renderManualLipSyncWinnerSelection();
}

function renderManualLipSyncWinnerSelection() {
    if (!manualLipSyncSelection) return;

    const ctx = manualLipSyncSelection;
    if (ctx.currentIndex >= ctx.matchups.length) {
        manualLipSyncWinnerQueues[ctx.queueKey] = ctx.outcomes.slice();
        const nextFn = ctx.onCompleteFnName;
        manualLipSyncSelection = null;
        if (typeof window[nextFn] === "function") {
            window[nextFn]();
        }
        return;
    }

    const screen = new Scene();
    screen.clean();
    screen.createHeader(ctx.header);
    screen.createParagraph(ctx.subtitle);

    const [q1, q2] = ctx.matchups[ctx.currentIndex];
    if (!q1 || !q2) {
        ctx.outcomes.push({ type: "win", winners: [q1 || q2].filter(Boolean), losers: [] });
        ctx.currentIndex += 1;
        renderManualLipSyncWinnerSelection();
        return;
    }

    screen.createBigText(`${ctx.currentIndex + 1} of ${ctx.matchups.length}`);
    screen.createParagraph("", "manualLipSyncPickerContainer");
    const container = document.getElementById("manualLipSyncPickerContainer");
    [q1, q2].forEach((q, idx) => {
        const qNameEscaped = q.name.replace(/"/g, '&quot;');
        container.innerHTML += `<div class="rigItem" style="display:inline-block;text-align:center;margin:6px;">
            <img src="${q.getCurrentImage()}" style="width:96px;height:auto;display:block;margin:0 auto 6px;border-radius:50%;object-fit:cover;"/>
            <label style="cursor:pointer;display:block;">
                <input type="checkbox" class="manualLSCheck" data-idx="${idx}" checked style="cursor:pointer;margin-right:4px;"/>
                <span>${qNameEscaped}</span>
            </label>
        </div>`;
    });
    setTimeout(() => {
        // Default to a single winner (first queen) so the common case needs no extra clicks.
        container.querySelectorAll('.manualLSCheck').forEach(chk => {
            chk.checked = chk.getAttribute('data-idx') === "0";
        });
    }, 0);

    screen.createHorizontalLine();
    screen.createButton("Confirm", "confirmManualLipSyncOutcome()");
}

function confirmManualLipSyncOutcome() {
    if (!manualLipSyncSelection) return;

    const ctx = manualLipSyncSelection;
    const matchup = ctx.matchups[ctx.currentIndex];
    if (!matchup) return;

    const container = document.getElementById("manualLipSyncPickerContainer");
    const checks = container ? Array.from(container.querySelectorAll('.manualLSCheck')) : [];
    const checkedIdx = checks.filter(c => c.checked).map(c => parseInt(c.getAttribute('data-idx'), 10));
    const [q1, q2] = matchup;

    let outcome;
    if (checkedIdx.length === 2) {
        outcome = { type: "doubleShantay", winners: [q1, q2], losers: [] };
    } else if (checkedIdx.length === 0) {
        outcome = { type: "doubleSashay", winners: [], losers: [q1, q2] };
    } else if (checkedIdx[0] === 0) {
        outcome = { type: "win", winners: [q1], losers: [q2] };
    } else {
        outcome = { type: "win", winners: [q2], losers: [q1] };
    }

    ctx.outcomes.push(outcome);
    ctx.currentIndex += 1;
    renderManualLipSyncWinnerSelection();
}

// Resolves the rigged outcome for one matchup, falling back to a single winner if nothing was picked.
function consumeManualLipSyncOutcome(queueKey, matchupIndex, matchup) {
    const validQueens = (matchup || []).filter(Boolean);
    const fallback = { type: "win", winners: validQueens.slice(0, 1), losers: validQueens.slice(1, 2) };
    const queue = manualLipSyncWinnerQueues[queueKey];
    if (!Array.isArray(queue) || !queue[matchupIndex]) return fallback;

    const outcome = queue[matchupIndex];
    const winners = (outcome.winners || []).filter(q => validQueens.includes(q));
    const losers = (outcome.losers || []).filter(q => validQueens.includes(q));

    if (outcome.type === "doubleShantay" && winners.length === 2) {
        return { type: "doubleShantay", winners, losers: [] };
    }
    if (outcome.type === "doubleSashay" && losers.length === 2) {
        return { type: "doubleSashay", winners: [], losers };
    }
    if (winners.length === 1) {
        return { type: "win", winners, losers: validQueens.filter(q => q !== winners[0]) };
    }
    return fallback;
}

function hasManualLipSyncWinnerQueue(queueKey) {
    return Array.isArray(manualLipSyncWinnerQueues[queueKey]);
}

function applyManualLipSyncWinner(queueKey, matchupIndex, lipSync) {
    if (!Array.isArray(lipSync) || lipSync.length < 2 || !hasManualLipSyncWinnerQueue(queueKey)) return lipSync;
    const outcome = consumeManualLipSyncOutcome(queueKey, matchupIndex, lipSync);
    const selectedWinner = outcome.winners[0];
    if (!selectedWinner || !lipSync.includes(selectedWinner)) return lipSync;
    return [selectedWinner, ...lipSync.filter(queen => queen !== selectedWinner)];
}

function chooseRiggedPairLipSyncWinner(lipSync, label = "this lip sync") {
    return new Promise(resolve => {
        const main = document.querySelector("div#MainBlock");
        if (!main || !Array.isArray(lipSync) || lipSync.length !== 2 || !lipSync[0] || !lipSync[1]) {
            resolve(lipSync);
            return;
        }

        const picker = document.createElement("div");
        picker.className = "manual-lipsync-picker rig-lipsync-outcome-picker";
        picker.style.margin = "1rem auto";
        picker.style.textAlign = "center";

        const title = document.createElement("b");
        title.innerHTML = `Choose the outcome for ${label}`;
        picker.appendChild(title);

        const containerId = `rigPairOutcome_${Date.now()}_${Math.floor(Math.random() * 100000)}`;
        const container = document.createElement("p");
        container.id = containerId;
        picker.appendChild(container);

        const choose = (outcome) => {
            picker.remove();
            const chosenNames = outcome.checkedNames || [];
            const chosenQueens = lipSync.filter(queen => chosenNames.includes(queen.name));
            const ordered = chosenQueens.length === 1
                ? [chosenQueens[0], ...lipSync.filter(queen => queen !== chosenQueens[0])]
                : lipSync.slice();
            ordered.rigLipSyncOutcome = outcome.type;
            ordered.rigLipSyncNames = chosenNames;
            resolve(ordered);
        };

        main.appendChild(picker);
        renderRigLSPanel(containerId, lipSync, { mode: "bottom", onApply: choose });
    });
}

async function applyRiggedPairLipSyncWinner(lipSync, label = "this lip sync") {
    if (!rigLSOutcome || !Array.isArray(lipSync) || lipSync.length !== 2 || !lipSync[0] || !lipSync[1]) return lipSync;
    return await chooseRiggedPairLipSyncWinner(lipSync, label);
}

function isRiggedDoubleShantay(lipSync) {
    return lipSync && lipSync.rigLipSyncOutcome === "doubleShantay";
}

function isRiggedDoubleSashay(lipSync) {
    return lipSync && lipSync.rigLipSyncOutcome === "doubleSashay";
}

function clearManualLipSyncWinnerQueue(queueKey) {
    if (Object.prototype.hasOwnProperty.call(manualLipSyncWinnerQueues, queueKey)) {
        delete manualLipSyncWinnerQueues[queueKey];
    }
}

