// REGION GATE //
(function blockIsrael(){
        const blockedCodes = ["IL"];
        const blockedNames = ["Israel"];
    const localHosts = ["127.0.0.1", "localhost"];
        function ban() {
            document.documentElement.style.filter = "grayscale(100%)";
            document.body.style.backgroundColor = "#000";
            document.body.style.color = "#fff";
            document.body.style.fontFamily = "Arial, Helvetica, sans-serif";
            document.body.style.margin = "0";
            document.body.style.padding = "40px";
            document.body.style.lineHeight = "1.5";

            document.body.innerHTML = `    
                <div style="max-width:1000px;margin:0 auto;text-align:center;">
                <h1 style="font-size:48px;margin:0 0 0.25em 0;letter-spacing:4px;">FREE PALESTINE</h1>
                <h2 style="font-weight:400;color:#ddd;margin:0 0 1em 0;">We stand in solidarity with Palestinian civilians suffering a severe humanitarian crisis.</h2>
                    <p style="color:#ccc;max-width:800px;margin:0 auto;">Numerous human-rights organisations and UN agencies report widespread civilian casualties, displacement, and shortages of food, water, medical supplies and shelter. Support credible humanitarian aid and advocacy organisations working to protect civilians and provide relief.</p>
                        <div style="margin-top:1em;">
                            <a href="https://www.un.org/" target="_blank" rel="noopener" style="color:#9ccfff;margin-right:0.75em">United Nations</a>
                            <a href="https://www.unocha.org/" target="_blank" rel="noopener" style="color:#9ccfff;margin-right:0.75em">OCHA</a>
                            <a href="https://www.map.org.uk/" target="_blank" rel="noopener" style="color:#9ccfff;margin-right:0.75em">Medical Aid for Palestinians</a>
                            <a href="https://www.amnesty.org/" target="_blank" rel="noopener" style="color:#9ccfff;margin-right:0.75em">Amnesty</a>
                            <a href="https://www.hrw.org/" target="_blank" rel="noopener" style="color:#9ccfff">Human Rights Watch</a>
                        </div>
                    </div>
                `;
        }

        if (localHosts.includes(window.location.hostname)) {
            return;
        }

        const countryCacheKey = "ss.countryLookup";
        let cachedCountry = "";
        try {
            const cached = JSON.parse(localStorage.getItem(countryCacheKey) || "null");
            if (cached && cached.expiresAt > Date.now()) {
                cachedCountry = String(cached.country || "").toUpperCase();
            }
        } catch (_err) {}
        if (cachedCountry) {
            if (blockedCodes.includes(cachedCountry)) ban();
            return;
        }

        fetch("https://ipapi.co/json/")
            .then(res => {
                if (!res.ok) throw new Error("Country lookup unavailable");
                return res.json();
            })
            .then(data => {
                if (!data) return;
                const countryCode = String(data.country || "").toUpperCase();
                if (countryCode) {
                    try {
                        localStorage.setItem(countryCacheKey, JSON.stringify({
                            country: countryCode,
                            expiresAt: Date.now() + 24 * 60 * 60 * 1000
                        }));
                    } catch (_err) {}
                }
                if (blockedCodes.includes(countryCode) || blockedNames.includes(data.country_name)) {
                    ban();
                } 
            })
            .catch(() => {});
})();

