function addCustomRunwayTheme(theme) {
    if (!theme || theme.trim() === '') return false;
    const trimmedTheme = theme.trim();
    if (customRunwayThemes.includes(trimmedTheme)) return false;
    customRunwayThemes.push(trimmedTheme);
    localStorage.setItem("customRunwayThemes", JSON.stringify(customRunwayThemes));
    return true;
}

function removeCustomRunwayTheme(theme) {
    customRunwayThemes = customRunwayThemes.filter(t => t !== theme);
    localStorage.setItem("customRunwayThemes", JSON.stringify(customRunwayThemes));
}

function clearCustomRunwayThemes() {
    customRunwayThemes = [];
    localStorage.setItem("customRunwayThemes", JSON.stringify(customRunwayThemes));
}

