function startEntrances() {
    let entranceScreen = new Scene();

    if (disallowEntrances === false) {
        entranceScreen.createBigText(`The contestants' entrances`);
        entranceScreen.createBold('All of the contestants enter the work room one by one...');
        entranceScreen.createHorizontalLine();
        currentCast.forEach(q => {
            if (team && q.QueenA && q.QueenB) {
                entranceScreen.createImage(q.QueenA.getCurrentImage(), 'black');
                entranceScreen.createImage(q.QueenB.getCurrentImage(), 'black');
            } else {
                entranceScreen.createImage(q.getCurrentImage(), 'black');
            }
            let chosenLine = '';
            if (all_stars || all_winners || lipsync_assassin) {
                chosenLine = entrancelinesas[randomNumber(0, entrancelinesas.length - 1)];
            } else {
                chosenLine = entrancelinesreg[randomNumber(0, entrancelinesreg.length - 1)];
            }
            entranceScreen.createBold(`${q.name} enters the werkroom...`);
            entranceScreen.createParagraph(`"${chosenLine}"`);
            entranceScreen.createHorizontalLine();
        });
    }
}

// RuPaul mode: make the chosen challenge always run in teams / pairs (off by default, switched off again after the challenge is judged)
let forceTeamChallenge = false;
let forcePairChallenge = false;
const rupaulRuntimeToggles = [
    {
        key: "slayers",
        label: "Slayers",
        buttonId: "toggle_slayers",
        get: () => slayers,
        set: value => {
            slayers = value;
            slayersCheck = false;
        }
    },
    {
        key: "floppers",
        label: "Floppers",
        buttonId: "toggle_floppers",
        get: () => floppers,
        set: value => {
            floppers = value;
            floppersCheck = false;
        }
    },
    {
        key: "doubleLipsync",
        label: "Double Lipsync",
        buttonId: "toggle_doubleLipsync",
        get: () => doubleLipsync,
        set: value => {
            doubleLipsync = value;
            doubleLipsyncCheck = false;
        }
    },
    {
        key: "forceTeams",
        label: "Force Teams",
        buttonId: "toggle_forceTeams",
        get: () => forceTeamChallenge,
        set: value => {
            forceTeamChallenge = value;
            if (value) forcePairChallenge = false;
        }
    },
    {
        key: "forcePairs",
        label: "Force Pairs",
        buttonId: "toggle_forcePairs",
        get: () => forcePairChallenge,
        set: value => {
            forcePairChallenge = value;
            if (value) forceTeamChallenge = false;
        }
    }
];

function getRupaulRuntimeToggle(key) {
    return rupaulRuntimeToggles.find(toggle => toggle.key === key);
}

function updateRupaulRuntimeToggleButton(toggle) {
    const button = document.getElementById(toggle.buttonId);
    if (!button) return;
    const isOn = !!toggle.get();
    button.innerText = `${toggle.label}: ${isOn ? "ON" : "OFF"}`;
    button.classList.add("round-toggle");
    button.classList.toggle("is-on", isOn);
    button.setAttribute("aria-pressed", isOn ? "true" : "false");
}

function updateRupaulRuntimeToggleButtons() {
    rupaulRuntimeToggles.forEach(updateRupaulRuntimeToggleButton);
}

function toggleRupaulRuntimeSetting(key) {
    const toggle = getRupaulRuntimeToggle(key);
    if (!toggle) return;
    toggle.set(!toggle.get());
    updateRupaulRuntimeToggleButtons();
}

function createRupaulRuntimeToggleButtons(screen) {
    rupaulRuntimeToggles.forEach(toggle => {
        screen.createButton(`Toggle ${toggle.label}`, `toggleRupaulRuntimeSetting('${toggle.key}')`, toggle.buttonId);
    });
    updateRupaulRuntimeToggleButtons();
}

function toggleSlayers() {
    toggleRupaulRuntimeSetting("slayers");
}
function toggleFloppers() {
    toggleRupaulRuntimeSetting("floppers");
}
function toggleDoubleLipsync() {
    toggleRupaulRuntimeSetting("doubleLipsync");
}
function toggleForceTeams() {
    toggleRupaulRuntimeSetting("forceTeams");
}
function toggleForcePairs() {
    toggleRupaulRuntimeSetting("forcePairs");
}
