function disqualifyQueen(queen) {
    let screen = new Scene();
    screen.createBigText("Disqualification");
    screen.createImage(queen.getCurrentImage(), "black");
    screen.createBold(`${queen.name} has been disqualified from the competition for looking weird at RuPaul!`);

    queen.addToTrackRecord("DISQ");
    queen.minqdd = "<small>(Disqualified)</small>";
    queen.queenDisqOrDept = true;
    eliminatedCast.unshift(queen);
    currentCast.splice(currentCast.indexOf(queen), 1);
    disqOrDept = true;
    if (chocolateBarTwist && !chocolateBarTwistCheck) {
        if (chocolateBarCheck(queen) == true) {
            chocolateBarTwistCheck = true;
        }
    }
    currentCast = currentCast.filter(q => q !== queen);
}
