function chooseQueenCriticalAction(actionType = "disqualify") {
    const availableQueens = currentCast.filter(q => q && !q.queenDisqOrDept);
    if (availableQueens.length === 0) {
        alert("There are no available queens to select.");
        return;
    }

    const existingPicker = document.getElementById("criticalQueenSelection");
    if (existingPicker) {
        existingPicker.remove();
    }

    const existingConfirmButton = document.getElementById("critical_queen_confirm");
    if (existingConfirmButton) {
        existingConfirmButton.remove();
    }

    let screen = new Scene();
    screen.createHorizontalLine();
    screen.createBold(
        actionType === "depart"
            ? "Choose a queen to depart"
            : actionType === "revealmole"
                ? "Choose a queen to reveal as the mole"
            : actionType === "quitqueen"
                ? "Choose a queen to abandon the competition"    
                : "Choose a queen to disqualify"
    );

    let main = document.querySelector("div#MainBlock");
    if (!main) {
        return;
    }

    let picker = document.createElement("div");
    picker.setAttribute("id", "criticalQueenSelection");
    picker.className = "sim-pick";

    let card = document.createElement("div");
    card.className = "sim-pick__card";

    let img = document.createElement("img");
    img.setAttribute("id", "criticalQueenImage");

    let select = document.createElement("select");
    select.setAttribute("id", "criticalQueenList");

    for (let k = 0; k < availableQueens.length; k++) {
        let option = document.createElement("option");
        option.innerHTML = availableQueens[k].name;
        option.value = k;
        select.add(option);
    }

    select.selectedIndex = randomNumber(0, availableQueens.length - 1);
    img.src = availableQueens[select.selectedIndex].getCurrentImage();

    select.addEventListener("change", () => {
        const selectedIndex = parseInt(select.value);
        if (!Number.isNaN(selectedIndex) && availableQueens[selectedIndex]) {
            img.src = availableQueens[selectedIndex].getCurrentImage();
        }
    });

    card.appendChild(img);
    card.appendChild(select);
    picker.appendChild(card);
    main.appendChild(picker);

    screen.createButton(
        actionType === "depart"
            ? "Confirm Departure"
            : actionType === "revealmole"
                ? "Confirm Mole Reveal"
            : actionType === "quitqueen"
                ? "Confirm Quitter"
                : "Confirm Disqualification",
        `confirmQueenCriticalAction('${actionType}')`,
        "critical_queen_confirm"
    );
}

function confirmQueenCriticalAction(actionType = "disqualify") {
    const select = document.getElementById("criticalQueenList");
    if (!select) {
        return;
    }

    const availableQueens = currentCast.filter(q => q && !q.queenDisqOrDept);
    const selectedIndex = parseInt(select.value);
    const selectedQueen = availableQueens[selectedIndex];

    if (!selectedQueen) {
        alert("Please select a valid queen.");
        return;
    }

    if (actionType === "depart") {
        departQueen(selectedQueen);
    } else if (actionType === "revealmole") {
        revealMoleQueen(selectedQueen);
    } else if (actionType === "quitqueen") {
        quitQueen(selectedQueen);    
    } else {
        disqualifyQueen(selectedQueen);
    }

    const picker = document.getElementById("criticalQueenSelection");
    if (picker) {
        picker.remove();
    }

    const confirmButton = document.getElementById("critical_queen_confirm");
    if (confirmButton) {
        confirmButton.remove();
    }
}

