let team1 = [];
let team2 = [];
let team3 = [];
let team4 = [];
let team5 = [];
let isTeamChallenge = false;
let isPairChallenge = false;
let isWhoWoreItBest = false;
let famGamRun = "";
let pairChallengeTeams = [];

function canUseOutsideRupaulChallenges() {
    return rupaulMode || allowOutsideRupaulChallenges;
}

function canUseOutsideRupaulTeamWins() {
    return rupaulMode || allowOutsideRupaulTeamWins;
}

function canUseOutsideRupaulPairWins() {
    return rupaulMode || allowOutsideRupaulPairWins;
}

function shouldMakeChallengeTeams() {
    if (forceTeamChallenge && rupaulMode && currentCast.length >= 4 && !isTeamChallenge) return true;
    return randomNumber(0, 100) >= 50 && currentCast.length >= 6 && currentCast.length <= 15 && !isTeamChallenge && !miniDisable && regularFormat && canUseOutsideRupaulChallenges();
}

function shouldMakeChallengePairs() {
    if (forcePairChallenge && rupaulMode && canRunPairChallenge() && !isPairChallenge) return true;
    return randomNumber(0, 100) >= 60 && canRunPairChallenge() && !isPairChallenge && regularFormat && canUseOutsideRupaulChallenges();
}

function makeChallengeTeams() {
    if (forceTeamChallenge) {
        formGirlGroupTeams();
    } else {
        teamMaking();
    }
}

function canRunPairChallenge() {
    return (currentCast.length >= 6 || (forcePairChallenge && currentCast.length >= 4)) && currentCast.length % 2 === 0;
}

function getPairTeams() {
    return pairChallengeTeams;
}

function getChallengeTeamAverageScore(team) {
    return team.reduce((totalScore, queen) => totalScore + queen.performanceScore, 0) / team.length;
}

function handlePairChallengeElimination(eliminatedQueen) {
    if (isPairChallenge && pairChallengeTeams.length > 0) {
        for (let team of pairChallengeTeams) {
            if (team.includes(eliminatedQueen)) {
                isPairChallenge = false;
                pairChallengeTeams = [];
                break;
            }
        }
    }
}

function validatePairChallengeByCurrentCast() {
    if (isPairChallenge && pairChallengeTeams.length > 0) {
        for (let team of pairChallengeTeams) {
            for (let queenInTeam of team) {
                if (!currentCast.includes(queenInTeam)) {
                    isPairChallenge = false;
                    pairChallengeTeams = [];
                    return false;
                }
            }
        }
    }
    return true;
}

