let roastRunningOrder = [];
let roastOrderRemaining = [];
function getRoastMiniWinner() {
    return currentCast.find(q => q && q.miniWinner === true) || null;
}

function prepareRoastRunningOrder(screen) {
    roastRunningOrder = [];
    roastOrderRemaining = currentCast.slice();
    const miniWinner = getRoastMiniWinner();

    if (!miniWinner) {
        shuffle(roastOrderRemaining);
        roastRunningOrder = roastOrderRemaining.slice();
        roastOrderRemaining = [];
        screen.createHorizontalLine();
        screen.createBold("The roast running order will be random.");
        return false;
    }

    miniWinner.miniWinner = false;
    const firstPickPool = roastOrderRemaining.filter(q => q !== miniWinner);
    if (firstPickPool.length === 0) {
        roastRunningOrder.push(miniWinner);
        return false;
    }
    const firstPick = firstPickPool.length > 1
        ? bestSister(miniWinner, firstPickPool) || firstPickPool[0]
        : firstPickPool[0];
    roastRunningOrder.push(firstPick);
    roastOrderRemaining = roastOrderRemaining.filter(q => q !== firstPick);
    screen.createHorizontalLine();
    screen.createImage(miniWinner.getCurrentImage(), "royalblue");
    screen.createImage(firstPick.getCurrentImage(), "pink");
    screen.createBold(`${miniWinner.name} picks ${firstPick.name} to go 1st.`);
    while (roastOrderRemaining.length > 0) {
        const pick = roastOrderRemaining.length > 1
            ? bestSister(miniWinner, roastOrderRemaining) || roastOrderRemaining[0]
            : roastOrderRemaining[0];
        roastRunningOrder.push(pick);
        roastOrderRemaining = roastOrderRemaining.filter(q => q !== pick);
        const position = roastRunningOrder.length;
        const positionLabel = position === currentCast.length
            ? "last"
            : `${position}${position % 10 === 1 && position % 100 !== 11 ? "st" : position % 10 === 2 && position % 100 !== 12 ? "nd" : position % 10 === 3 && position % 100 !== 13 ? "rd" : "th"}`;
        screen.createImage(miniWinner.getCurrentImage(), "royalblue");
        screen.createImage(pick.getCurrentImage(), "pink");
        screen.createBold(`${miniWinner.name} picks ${pick.name} to go ${positionLabel}.`);
    }
    return false;
}

function getRoastTargetOptions(performer) {
    const targets = [];
    const seen = new Set();

    for (const queen of currentCast) {
        if (queen && queen.name && queen.name !== performer.name && !seen.has(queen.name)) {
            seen.add(queen.name);
            targets.push({
                name: queen.name,
                image: queen.getCurrentImage()
            });
        }
    }

    if (Array.isArray(judgingpanel)) {
        for (const judge of judgingpanel) {
            if (judge && judge.name && !seen.has(judge.name)) {
                seen.add(judge.name);
                targets.push({
                    name: judge.name,
                    image: judge.image || "image/queens/noimage.jpg"
                });
            }
        }
    }

    if (targets.length === 0) {
        return [];
    }

    shuffle(targets);
    return targets.slice(0, 3);
}

function renderRoastSetForQueen(screen, queen) {
    const roastTargets = getRoastTargetOptions(queen);
    if (!roastTargets.length) {
        screen.createBold(`${queen.name} has no one left to roast.`);
        screen.createHorizontalLine();
        return;
    }

    screen.createImage(queen.getCurrentImage(), "royalblue");
    screen.createBold(`${queen.name}'s roast set:`);

    for (const target of roastTargets) {
        let readEntry = queensReads.find((item) => item && item.queen === target.name);
        if (!readEntry || !Array.isArray(readEntry.reads) || readEntry.reads.length === 0) {
            readEntry = queensReads.find((item) => item && item.queen === "General") || { reads: [] };
        }

        if (!Array.isArray(readEntry.reads) || readEntry.reads.length === 0) {
            screen.createImage(target.image, "lightgreen");
            screen.createBold(`to: ${target.name}`);
            screen.createBold(`${queen.name} says, "No read left, but the shade still lands."`);
            continue;
        }

        const readNumber = randomNumber(0, readEntry.reads.length - 1);
        const readText = readEntry.reads[readNumber];
        readEntry.reads.splice(readNumber, 1);

        screen.createImage(target.image, "lightgreen");
        screen.createBold(`to: ${target.name}`);
        screen.createBold(readText);
    }

    screen.createHorizontalLine();
}

