let lipsyncChallengeCan3 = false;
let canTminiWinners = [];
let canTminiLosers = [];
let canTHigherTeam = [];
function can3LsChallenge() {
    slayoffCheck = true;
    episodeChallenges.push("Lip Sync");
    let challengeScreen = new Scene();
    challengeScreen.clean();
    challengeScreen.createHeader("Maxi-challenge!");
    challengeScreen.createBold("", "Description");

    let challenge = new Can3LsChallenge();
    challenge.generateDescription();

    const shuffledCast = [...currentCast];
    shuffle(shuffledCast);
    team1 = shuffledCast.slice(0, Math.ceil(shuffledCast.length / 2));
    team2 = shuffledCast.slice(Math.ceil(shuffledCast.length / 2));

    challengeScreen.createBold("Team 1");
    team1.forEach(q => challengeScreen.createImage(q.getCurrentImage(), "darkred"));
    challengeScreen.createParagraph(`${team1.map(q => q.name).join(", ")}`);

    challengeScreen.createBold("Team 2");
    team2.forEach(q => challengeScreen.createImage(q.getCurrentImage(), "slateblue"));
    challengeScreen.createParagraph(`${team2.map(q => q.name).join(", ")}`);

    challenge.rankPerformances();

    canTminiWinners = [];
    canTminiLosers = [];
    canTHigherTeam = [];

    let teamScores = { team1: 0, team2: 0 };
    let round = 1;
    const maxPairs = Math.max(team1.length, team2.length);

    challengeScreen.createHorizontalLine();

    isTeamChallenge = true;

    for (let i = 0; i < maxPairs; i++) {
        const q1 = team1[i];
        const q2 = team2[i];

        if (q1 && q2) {
            const score1 = q1.lipsyncScore - q1.favoritism + q1.unfavoritism;
            const score2 = q2.lipsyncScore - q2.favoritism + q2.unfavoritism;

            let winner, loser;
            if (score1 >= score2) {
                winner = q1;
                loser = q2;
                teamScores.team1++;
            } else {
                winner = q2;
                loser = q1;
                teamScores.team2++;
            }

            challengeScreen.createBigText("Round " + round);
            lsSong();
            toAlots([winner], [loser], alotsSong);
            round++;

            challengeScreen.createImage(winner.getCurrentImage(), "royalblue");
            challengeScreen.createBold(`${winner.name}, you are a winner baby!`);
            loser.performanceScore = 0;

            challengeScreen.createImage(loser.getCurrentImage(), "red");
            challengeScreen.createBold(`${loser.name}, you may risk elimination...`);
            loser.performanceScore = 10;

            canTminiWinners.push(winner);
            canTminiLosers.push(loser);
        } else if (q1) {
            teamScores.team1++;
            canTminiWinners.push(q1);
        } else if (q2) {
            teamScores.team2++;
            canTminiWinners.push(q2);
        }

        challengeScreen.createHorizontalLine();
    }

    const winningTeamArr = teamScores.team1 >= teamScores.team2 ? team1 : team2;
    const losingTeamArr = winningTeamArr === team1 ? team2 : team1;

    const winningTeamWinners = winningTeamArr.filter(q => canTminiWinners.includes(q));
    const losingTeamWinners = losingTeamArr.filter(q => canTminiWinners.includes(q));
    const losingTeamLosers = losingTeamArr.filter(q => canTminiLosers.includes(q));

    winningTeamArr.forEach(q => topQueens.push(q));
    losingTeamLosers.forEach(q => bottomQueens.push(q));

    canTHigherTeam = [...winningTeamWinners];

    can3LsChallengeCounter++;
    isDesignChallenge = false;

    if (all_winners) {
        challengeScreen.createButton("Proceed", "winnersJudging()");
    } else {
        challengeScreen.createButton("Proceed", "judgingScreen()");
    }
}

