// Lower modifier = better fabric, since a lower performanceScore is a better placement.
const designMaterialCatalog = [
    { name: "a roll of iridescent sequin fabric", modifier: -4 },
    { name: "premium stretch velvet", modifier: -3 },
    { name: "hand-beaded lace", modifier: -3 },
    { name: "structured leather", modifier: -2 },
    { name: "a bolt of silk chiffon", modifier: -2 },
    { name: "classic black spandex", modifier: -1 },
    { name: "a pile of tulle offcuts", modifier: -1 },
    { name: "plain cotton jersey", modifier: 0 },
    { name: "a bin of mixed denim", modifier: 0 },
    { name: "scratchy burlap", modifier: 2 },
    { name: "shower curtain vinyl", modifier: 2 },
    { name: "a square of astroturf", modifier: 3 },
    { name: "packing foam", modifier: 3 },
    { name: "a tangle of caution tape", modifier: 4 },
    { name: "damp carpet remnants", modifier: 4 }
];

function buildDesignMaterialPool(size) {
    const pool = [];
    while (pool.length < size) {
        const batch = designMaterialCatalog.map(m => ({ ...m }));
        shuffle(batch);
        pool.push(...batch);
    }
    return pool.slice(0, size);
}

function describeDesignMaterial(material) {
    if (material.modifier <= -2) return "It's a serious advantage.";
    if (material.modifier < 0) return "It's a small edge.";
    if (material.modifier === 0) return "It's workable, nothing more.";
    if (material.modifier < 3) return "It's going to be a struggle.";
    return "It's a disaster waiting to happen.";
}

function giveDesignMaterial(queen, material, screen, color = "royalblue") {
    queen.designMaterialModifier = material.modifier;
    screen.createImage(queen.getCurrentImage(), color);
    screen.createParagraph(`${queen.name} gets ${material.name}. ${describeDesignMaterial(material)}`);
}

function runDesignMaterialEvent(screen) {
    for (let i = 0; i < currentCast.length; i++) {
        currentCast[i].designMaterialModifier = 0;
    }
    if (specialEventsOff) return;
    if (currentCast.length < 4) return;
    if (randomNumber(0, 100) > 45) return;

    const miniWinner = currentCast.find(q => q && q.miniWinner === true) || null;
    const eventPool = miniWinner ? ["assign", "snake", "raid"] : ["raid"];
    const eventType = eventPool[randomNumber(0, eventPool.length - 1)];
    const materials = buildDesignMaterialPool(currentCast.length);

    screen.createHorizontalLine();

    if (eventType === "raid" || !miniWinner) {
        screen.createBigText("The queens raid the fabrics!");
        screen.createBold("It's every queen for themselves in the workroom.");
        const raiders = currentCast.slice();
        shuffle(raiders);
        shuffle(materials);
        raiders.forEach((queen, index) => giveDesignMaterial(queen, materials[index], screen, "royalblue"));
        return;
    }

    miniWinner.miniWinner = false;

    if (eventType === "assign") {
        screen.createBigText("The mini challenge winner assigns the materials!");
        screen.createImage(miniWinner.getCurrentImage(), "gold");
        screen.createBold(`${miniWinner.name} gets to decide who works with what.`);
        materials.sort((a, b) => a.modifier - b.modifier);
        giveDesignMaterial(miniWinner, materials.shift(), screen, "gold");

        let remaining = currentCast.filter(q => q !== miniWinner);
        while (remaining.length > 0) {
            const target = remaining.length > 1
                ? (worstSister(miniWinner, remaining) || remaining[0])
                : remaining[0];
            remaining = remaining.filter(q => q !== target);
            giveDesignMaterial(target, materials.pop(), screen, "pink");
        }
        return;
    }

    screen.createBigText("The mini challenge winner picks first!");
    screen.createImage(miniWinner.getCurrentImage(), "gold");
    screen.createBold(`${miniWinner.name} picks ${getPronoun(miniWinner, "possessive")} material first, then chooses who picks next.`);
    const available = materials.slice().sort((a, b) => a.modifier - b.modifier);
    let waiting = currentCast.filter(q => q !== miniWinner);
    let picker = miniWinner;
    while (picker) {
        giveDesignMaterial(picker, available.shift(), screen, picker === miniWinner ? "gold" : "royalblue");
        if (waiting.length === 0) break;
        const next = waiting.length > 1
            ? (bestSister(picker, waiting) || waiting[0])
            : waiting[0];
        waiting = waiting.filter(q => q !== next);
        screen.createBold(`${picker.name} hands the next pick to ${next.name}.`);
        picker = next;
    }
}

function applyDesignMaterialModifiers() {
    let anyApplied = false;
    const rawScores = currentCast.map(q => q.performanceScore);
    const averageRaw = rawScores.reduce((sum, s) => sum + s, 0) / (rawScores.length || 1);

    for (let i = 0; i < currentCast.length; i++) {
        const queen = currentCast[i];
        const modifier = Number(queen.designMaterialModifier) || 0;
        queen.designMaterialModifier = 0;
        if (modifier === 0) {
            queen.designMaterialNarrative = null;
            continue;
        }

        const diff = queen.performanceScore - averageRaw;
        let delta;
        if (modifier > 0 && diff < 0) {
            queen.designMaterialNarrative = "overcame";
            delta = -(Math.abs(modifier) + 1);
        } else if (modifier < 0 && diff > 0) {
            queen.designMaterialNarrative = "underdelivered";
            delta = Math.abs(modifier) + 1;
        } else if (modifier > 0) {
            queen.designMaterialNarrative = "struggled";
            delta = modifier * 0.5;
        } else {
            queen.designMaterialNarrative = "expected";
            delta = modifier * 0.5;
        }

        queen.performanceScore += delta;
        anyApplied = true;
    }
    if (anyApplied) sortPerformances(currentCast);
}

