let activeMakeoverPairs = [];

function applyMakeoverPairGuestPlacements(winnerQueen = null) {
    if (!makeoverChallengeCounter || !Array.isArray(activeMakeoverPairs) || activeMakeoverPairs.length === 0) {
        return;
    }

    const setEpisodePlacement = (queen, placement) => {
        if (!queen || !placement) return;
        if (!Array.isArray(queen.trackRecord)) queen.trackRecord = [];
        if (queen.trackRecord.length === 0) {
            queen.addToTrackRecord(placement);
        } else {
            queen.trackRecord[queen.trackRecord.length - 1] = placement;
        }
    };

    for (let i = 0; i < activeMakeoverPairs.length; i++) {
        const pair = activeMakeoverPairs[i];
        if (!pair || !pair.eliminated) continue;
        setEpisodePlacement(pair.eliminated, "GUEST");
    }

    if (winnerQueen) {
        const winnerPair = activeMakeoverPairs.find((pair) => pair && pair.current === winnerQueen) || null;
        if (winnerPair && winnerPair.eliminated) {
            setEpisodePlacement(winnerPair.eliminated, "GUESTBLUE");
        }
    }

    activeMakeoverPairs = [];
}

function getEligibleEliminatedMakeoverCast() {
    if (!Array.isArray(eliminatedCast)) return [];
    return eliminatedCast.filter((queen) => queen && !currentCast.includes(queen));
}

function canRunEqualEliminatedMakeoverPairs() {
    if (!elimMakeover) return false;
    if (!Array.isArray(currentCast) || currentCast.length === 0) return false;
    return getEligibleEliminatedMakeoverCast().length === currentCast.length;
}

function getEqualEliminatedMakeoverPairs() {
    if (!canRunEqualEliminatedMakeoverPairs()) return [];
    const currentQueens = [...currentCast];
    const eliminatedQueens = [...getEligibleEliminatedMakeoverCast()];
    shuffle(currentQueens);
    shuffle(eliminatedQueens);
    const pairs = [];
    for (let i = 0; i < currentQueens.length; i++) {
        pairs.push({ current: currentQueens[i], eliminated: eliminatedQueens[i] });
    }
    return pairs;
}

