class SisterMakeoverChallenge {
    generateDescription() {
        const description = document.querySelector("b#Description");
        const desc = [
            "turn each other into drag sisters.",
            "swap aesthetics and make each other over in their own style.",
            "make each other over as long-lost twins.",
            "redesign each other from the wig down to the heels.",
            "give each other a full drag makeover, no mirrors allowed.",
            "make each other over into the drag family they never had."
        ];
        description.innerHTML = `It's the sister makeover! The contestants will pair up and ${desc[randomNumber(0, desc.length - 1)]}`;
    }
    rankPerformances(pairs) {
        for (let i = 0; i < currentCast.length; i++) {
            currentCast[i].getMakeover();
        }
        // Partners sink or swim together, so each pair shares one score.
        for (const pair of pairs) {
            const sharedScore = pair.reduce((total, queen) => total + queen.performanceScore, 0) / pair.length;
            pair.forEach(queen => queen.performanceScore = sharedScore);
        }
        sortPerformances(currentCast);
    }
}

function canRunSisterMakeover() {
    return !team && Array.isArray(currentCast) && currentCast.length >= 4;
}

function makeSisterMakeoverPairs() {
    const pool = [...currentCast];
    shuffle(pool);
    const pairs = [];
    while (pool.length >= 2) {
        pairs.push([pool.pop(), pool.pop()]);
    }
    if (pool.length === 1 && pairs.length > 0) {
        pairs[pairs.length - 1].push(pool.pop());
    }
    return pairs;
}

function sisterMakeoverChallenge() {
    if (!canRunSisterMakeover()) {
        makeoverChallenge();
        return;
    }

    let challengeScreen = new Scene();
    challengeScreen.clean();
    challengeScreen.createHeader("Maxi-challenge!");
    challengeScreen.createBold("", "Description");
    let challenge = new SisterMakeoverChallenge();
    challenge.generateDescription();

    const pairs = makeSisterMakeoverPairs();
    challengeScreen.createHorizontalLine();
    challengeScreen.createBigText("The contestants pair up...");
    for (const pair of pairs) {
        pair.forEach(queen => challengeScreen.createImage(queen.getCurrentImage(), "hotpink"));
        const names = pair.length === 3
            ? `${pair[0].name}, ${pair[1].name} and ${pair[2].name}`
            : `${pair[0].name} and ${pair[1].name}`;
        challengeScreen.createParagraph(`${names} will make each other over.`);
        for (let i = 0; i < pair.length; i++) {
            for (let j = i + 1; j < pair.length; j++) {
                modRelation(2, 2, pair[i], pair[j]);
            }
        }
    }

    challenge.rankPerformances(pairs);
    activeMakeoverPairs = [];
    episodeChallenges.push("Make Over");
    makeoverChallengeCounter = true;
    isDesignChallenge = true;
    queensPerformances();
}
