let snatchGroup = [];
let designGroup = [];

let snatchSlots = 5;
let designSlots = 5;

function pickYourPoison() {
    snatchCounter = true;
    designChallengeCounter = true;

    designGroup = [];
    snatchGroup = [];
    
    snatchSlots = 5;
    designSlots = 5;

    let challengeScreen = new Scene();
    challengeScreen.clean();
    challengeScreen.createHeader("Pick Your Poison!");

    let selectionOrder = [...currentCast].sort(() => 0.5 - Math.random());

    for (let i = 0; i < 10; i++) {
        let queen = selectionOrder[i];

        let snatchScore = queen._improvStat + queen._comedyStat;
        let designScore = queen._designStat;
        let totalScore = snatchScore + designScore;

        let snatchChance = snatchScore / totalScore;

        if (
            snatchSlots > 0 &&
            (designSlots === 0 || Math.random() < snatchChance)
        ) {
            snatchGroup.push(queen);
            snatchSlots--;
            queen.chosenChallenge = "Snatch Game";
        } else {
            designGroup.push(queen);
            designSlots--;
            queen.chosenChallenge = "Design";
        }
    }

    let eleventhQueen = selectionOrder[10];

    let snatchScore = eleventhQueen._improvStat + eleventhQueen._comedyStat;
    let designScore = eleventhQueen._designStat;
    let totalScore = snatchScore + designScore;

    if (Math.random() < snatchScore / totalScore) {
        snatchGroup.push(eleventhQueen);
        eleventhQueen.chosenChallenge = "Snatch Game";
    } else {
        designGroup.push(eleventhQueen);
        eleventhQueen.chosenChallenge = "Design";
    }

    challengeScreen.createBold("The Potions have been picked!");
    let snatchNames = snatchGroup.map(q => q.name).join(", ");
    let designNames = designGroup.map(q => q.name).join(", ");
    
    snatchGroup.forEach(q => {
        challengeScreen.createImage(q.getCurrentImage(), "red");
    });
    challengeScreen.createParagraph(`The contestants doing snatch game are... ${snatchNames}`);
    designGroup.forEach(q => {
        challengeScreen.createImage(q.getCurrentImage(), "blue");
    });
    challengeScreen.createParagraph(`The contestants doing design are... ${designNames}`);

    challengeScreen.createHorizontalLine();

    challengeScreen.createBigText("The Snatch Game!");
    challengeScreen.createBold('', 'Description');
    let snatchGame = new SnatchGamePYP();
    snatchGame.generateDescription();
    snatchGame.rankPerformances(snatchGroup); 

    renderPerformanceGroup(snatchGroup, "d");

    challengeScreen.createHorizontalLine();

    let oldDesc = document.getElementById('Description');
    oldDesc.id = 'OldDescription';

    challengeScreen.createBigText("The Design Challenge");
    challengeScreen.createBold('', 'Description');
    let designChallenge = new DesignChallengePYP();
    designChallenge.generateDescription();
    designChallenge.rankPerformances(designGroup);
    
    renderPerformanceGroup(designGroup, "d");

    challengeScreen.createButton("Proceed", "judging()");
    episodeChallenges.push("Snatch Game<nl>Design");
}

function renderPerformanceGroup(group, suffix) {
    for (let i = 0; i < group.length; i++) {
        if (group[i].adv != undefined) {
            group[i].performanceScore -= group[i].adv;
            group[i].adv = undefined;
        }
    }
    let slay = group.filter(q => q.performanceScore < 6);
    let great = group.filter(q => q.performanceScore >= 6 && q.performanceScore < 16);
    let good = group.filter(q => q.performanceScore >= 16 && q.performanceScore < 26);
    let bad = group.filter(q => q.performanceScore >= 26 && q.performanceScore < 31);
    let flop = group.filter(q => q.performanceScore >= 31);
    
    createPerformanceDescPYP(slay, great, good, bad, flop, suffix);
}

