function roastBattles() {
    let challengeScreen = new Scene();
    challengeScreen.clean();
    challengeScreen.createHeader("Maxi-challenge!");
    challengeScreen.createBold("", "Description");
    let challenge = new RoastBattles();
    challenge.generateDescription();
    challenge.rankPerformances();
    const n = currentCast.length;
    if (n !== 6 && n !== 8) {
        queensPerformances();
        episodeChallenges.push("Roast Battles");
        return;
    }

    let queens = currentCast.slice();
    shuffle(queens);

    topQueens = [];
    bottomQueens = [];

    challengeScreen.createHorizontalLine();

    for (let i = 0, round = 1; i < queens.length; i += 2, round++) {
        challengeScreen.createBigText("Round " + round);
        challengeScreen.createImage(queens[i].getCurrentImage(), "lightcoral");
        challengeScreen.createImage(queens[i + 1].getCurrentImage(), "lightblue");
        challengeScreen.createParagraph(queens[i].name + " vs " + queens[i + 1].name);

        let winner = queens[i].performanceScore < queens[i + 1].performanceScore ? queens[i] : queens[i + 1];
        let loser = winner === queens[i] ? queens[i + 1] : queens[i];

        topQueens.push(winner);
        if (!all_winners) {
            bottomQueens.push(loser);
        }

        challengeScreen.createBold("The winner is... " + winner.name + "!");
        challengeScreen.createHorizontalLine();
    }

    isDesignChallenge = false;
    episodeChallenges.push("Roast Battles");

    if (bracketPhaseActive) {
        topQueens.sort((a, b) => a.performanceScore - b.performanceScore);
        topQueens = topQueens.slice(0, 2);
        bracketForcedTopQueens = [...topQueens];
    }

    if (all_winners) {
        challengeScreen.createButton("Proceed", "winnersJudging()");
    } else if (bracketPhaseActive) {
        challengeScreen.createButton("Proceed", "bracketJudgingScreen()");
    } else {
        challengeScreen.createButton("Proceed", "judgingScreen()");
    }
}
