class SnatchGamePairs {
    generateDescription() {
        let description = document.querySelector("b#Description");
        description.innerHTML = "For today's challenge... we're playing the Snatch Game in pairs! The contestants will pair up and showcase their funniest celebrity impersonations together!";
        const snatchVariants = ["Snatch Game", "Snatch Game", "Snatch Game", "Snatch Game", "Snatch Game", "Snatch Game", "Snatch Game", "Snatch Game", "Snatch Game", "Snatch Game"];
        episodeChallenges.push(snatchVariants[randomNumber(0, snatchVariants.length - 1)]);
    }
    rankPerformances() {
        let teams = [team1, team2, team3, team4, team5].filter(t => t.length > 0);
        
        for (let team of teams) {
            let combinedScore = 0;
            for (let queen of team) {
                combinedScore += queen._improvStat + queen._comedyStat;
            }
            combinedScore = combinedScore / team.length;
            
            let baseScore = Math.random() * 20 + 25;
            let performanceVariance = (Math.random() - 0.5) * 20;
            let finalScore = baseScore + (combinedScore / 20) * performanceVariance;
            finalScore = Math.max(25, Math.min(45, finalScore));
            
            for (let queen of team) {
                queen.performanceScore = finalScore;
            }
        }
        sortPerformances(currentCast);
    }
}
