class PageantChallenge {
    generateDescription() {
        const description = document.querySelector("b#Description");
        const desc1 = ["their best hometown looks", "their best national costumes", "their signature looks", "their best evening gowns"];
        const questionPool = [
            {
                topic: "LGBTQ+ issues",
                stat: "improv",
                prompt: "What would you say to someone who is afraid to be themselves?",
                answers: [
                    "You deserve to take up space exactly as you are.",
                    "Find the people who let you be fully yourself, and let them be your chosen family.",
                    "Your truth is worth sharing, even if it takes time to feel ready."
                ]
            },
            {
                topic: "Drag Race trivia",
                stat: "comedy",
                prompt: "Which past challenge would you want to compete in, and why?",
                answers: [
                    "The acting challenge. Give me a character and a camera and I'll make it a moment.",
                    "The roast. I love making people laugh and keeping them just a little nervous.",
                    "The makeover. I want to show how drag can make somebody feel brand new."
                ]
            },
            {
                topic: "the environment",
                stat: "acting",
                prompt: "What is one change people could make to help the planet?",
                answers: [
                    "Start with the choices you make every day, and encourage your community to join you.",
                    "Pay attention to the people most affected and listen when they ask for change.",
                    "Small actions matter, but we should also expect leaders to make bigger ones."
                ]
            },
            {
                topic: "current events",
                stat: "improv",
                prompt: "What issue do you think deserves more attention right now?",
                answers: [
                    "The issues that affect people quietly, long before they make the headlines.",
                    "Making sure every community has the support and resources it needs.",
                    "Listening to people directly instead of deciding their stories for them."
                ]
            },
            {
                topic: "their communities",
                stat: "acting",
                prompt: "What lesson from your community do you carry with you?",
                answers: [
                    "You can build a family from the people who show up for you.",
                    "There is strength in making room for one another.",
                    "Never underestimate what people can create when they work together."
                ]
            }
        ];
        const desc3 = ["at the Brit Gala.", "at the Miss Shutacca Pageant.", "at the National Drag Pageant.", "at the International Drag Pageant."];
        const run1 = desc1[randomNumber(0, 3)];
        shuffle(questionPool);
        this.questions = questionPool.slice(0, 2);
        this.venue = desc3[randomNumber(0, desc3.length - 1)];
        const topics = this.questions.map(question => question.topic).join(" and ");
        description.innerHTML = `The contestants will present ${run1}, compete in swimwear and evening wear, then answer two questions about ${topics} ${this.venue}`;
    }
    rankPerformances(screen) {
        screen.createHorizontalLine();
        screen.createBigText("The pageant interview");
        for (let i = 0; i < currentCast.length; i++) {
            const queen = currentCast[i];
            screen.createImage(queen.getCurrentImage());
            screen.createBold(`${queen.name} takes the microphone.`);
            this.questions.forEach(question => {
                const answer = question.answers[randomNumber(0, question.answers.length - 1)];
                screen.createParagraph(`Q: ${question.prompt}`);
                screen.createParagraph(`${queen.name}: "${answer}"`);
            });
            queen.getPageant(this.questions.map(question => question.stat));
        }
        sortPerformances(currentCast);
    }
}
