class RdrLiveChallenge {
    generateDescription() {
        let description = document.querySelector("b#Description");
        description.innerHTML = "Live from Tuckahoe, it's RDR Live! The contestants will perform a live sketch, with each queen assigned a role to play.";
        this.roles = [
            { name: "The anchor", stats: ["acting", "improv"] },
            { name: "The scene-stealing diva", stats: ["comedy", "improv"] },
            { name: "The straight-faced correspondent", stats: ["acting", "comedy"] },
            { name: "The physical comedian", stats: ["dance", "comedy"] },
            { name: "The over-the-top character", stats: ["acting", "comedy"] },
            { name: "The wildcard", stats: ["improv", "dance"] }
        ];
        this.assignedRoles = new Map();
    }
    assignRoles(screen) {
        const shuffledRoles = [...this.roles];
        shuffle(shuffledRoles);
        screen.createHorizontalLine();
        screen.createBigText("Live sketch roles");
        currentCast.forEach((queen, index) => {
            const role = shuffledRoles[index % shuffledRoles.length];
            this.assignedRoles.set(queen, role);
            screen.createImage(queen.getCurrentImage(), "lightcoral");
            screen.createBold(`${queen.name} will play ${role.name}.`);
        });
    }
    rankPerformances() {
        for (let i = 0; i < currentCast.length; i++) {
            currentCast[i].getRdrLive(this.assignedRoles.get(currentCast[i]));
        }
        sortPerformances(currentCast);
    }
}
