function getConfiguredFinaleCastSize() {
    const explicitSize = Math.floor(Number(finaleSize));
    if (Number.isFinite(explicitSize) && explicitSize >= 2 && explicitSize <= 8) {
        return explicitSize;
    }

    if (top8reg || top8ls || dres4finaleTop8) return 8;
    if (top7reg || top7ls || dres4finaleTop7) return 7;
    if (top6reg || top6ls || top6lsSudden || top6as11) return 6;
    if (top5 || top5ls) return 5;
    if (top4 || canFinale || lftc || maxiLFTC || allstars3Finale || teamsF || dres4finale || lmd3Semis || lmd4Semis || lmd5Semis || lmd6Semis) return 4;
    if (top3 || top3JuryFinale || drtht3 || sverigeTop3 || top3LSF) return 3;
    if (top2F || jurytop2) return 2;
    return 4;
}

function getFallbackFinaleKeyForCastSize(castSize) {
    const size = Math.max(2, Math.min(8, Number(castSize) || 4));

    if (size >= 8) {
        if (top8ls) return "top8ls";
        if (dres4finaleTop8) return "dres4finaleTop8";
        return rankedFinale ? "rankedtop8" : "top8";
    }
    if (size === 7) {
        if (top7ls) return "top7ls";
        if (dres4finaleTop7) return "dres4finaleTop7";
        return rankedFinale ? "rankedtop7" : "top7";
    }
    if (size === 6) {
        if (top6as11) return "top6as11";
        if (top6lsSudden) return "top6lsSudden";
        if (dres4finaleTop6) return "dres4finaleTop6";
        if (top6ls) return "top6ls";
        return rankedFinale ? "rankedtop6" : "top6";
    }
    if (size === 5) {
        if (top5ls) return "top5ls";
        return rankedFinale ? "rankedtop5" : "top5";
    }
    if (size === 4) {
        if (teamsF) return rankedFinale ? "rankedteams" : "teams";
        if (maxiLFTC) return "maxiLFTC";
        if (lftc && drph2Semis) return "drph2f";
        if (lftc) return "LFTC";
        if (canFinale) return "LFTF";
        if (allstars3Finale) return "jury";
        if (dres4finale) return "dres4finale";
        if (lmd3Semis) return "lmd3t4";
        if (lmd4Semis) return "lmd4t4";
        if (lmd5Semis) return "lmd5t4";
        if (lmd6Semis) return "lmd6t4";
        return rankedFinale ? "rankedteams" : "teams";
    }
    if (size === 3) {
        if (top3LSF) return "top3LSF";
        if (sverigeTop3) return "sverigetop3";
        if (top3JuryFinale) return "jurytop3";
        if (drtht3) return "drthtop3";
        if (dres4finaleTop3) return "dres4finaleTop3";
        return rankedFinale ? "rankedtop3" : "top3";
    }
    if (size === 2) {
    if (jurytop2) return "jurytop2";
    return rankedFinale ? "rankedtop2" : "top2";
    }
}

function isFinaleAutoAdjustEnabled() {
    const toggle = document.getElementById("auto-adjust-finale");
    return !toggle || toggle.checked;
}

function enforceTeamFormatFinale() {
    // The teams format has its own finale (the last two teams split into four individual finalists),
    // and it only works with the Teams finale flags, so whatever finale was picked is replaced.
    if (!team || (teamsF && finaleSize === 4)) return false;
    applyFinaleKey(rankedFinale ? "rankedteams" : "teams");
    return true;
}

function normalizeFinaleSelectionForCast() {
    if (team) {
        enforceTeamFormatFinale();
        return false;
    }
    if (bracketPhaseActive) {
        return false;
    }

    if (!isFinaleAutoAdjustEnabled()) {
        return false;
    }

    const castSize = Array.isArray(currentCast) ? currentCast.length : 0;
    const configuredSize = getConfiguredFinaleCastSize();

    if (top6lsSudden && top3 && castSize === 3) {
        return false;
    }

    if (!castSize || castSize < 2 || castSize >= configuredSize) {
        return false;
    }

    const targetSize = castSize > 3 ? castSize - 1 : castSize;
    const previousKey = inferSeasonFinaleKeyFromState() || lastSeasonFinale || "";
    const nextKey = getFallbackFinaleKeyForCastSize(targetSize);
    if (!nextKey) return false;

    applyFinaleKey(nextKey);
    lastSeasonFinale = nextKey;

    const finaleSelect = document.getElementById("finale");
    if (finaleSelect) {
        const matchingOption = Array.from(finaleSelect.options || []).find((option) => option.value === nextKey);
        if (matchingOption) {
            finaleSelect.value = nextKey;
        }
    }

    if (previousKey !== nextKey) {
        try {
            console.warn(`Finale auto-adjusted from ${previousKey || "custom"} to ${nextKey} because only ${castSize} queen(s) remained.`);
        } catch (_err) {}
        if (typeof showFloatingNotice === "function") {
            showFloatingNotice(`Finale auto-adjusted to Top ${targetSize}`, 1800);
        }
        return true;
    }

    return false;
}

function normalizeFinaleSelectionAfterFinaleReturn() {
    if (bracketPhaseActive) {
        return false;
    }

    if (!isFinaleAutoAdjustEnabled()) {
        return false;
    }

    const castSize = Array.isArray(currentCast) ? currentCast.length : 0;
    const configuredSize = getConfiguredFinaleCastSize();

    if (!castSize || castSize <= configuredSize || castSize < 2) {
        return false;
    }

    const nextKey = getFallbackFinaleKeyForCastSize(castSize);
    if (!nextKey) return false;

    const previousKey = inferSeasonFinaleKeyFromState() || lastSeasonFinale || "";
    applyFinaleKey(nextKey);
    lastSeasonFinale = nextKey;

    const finaleSelect = document.getElementById("finale");
    if (finaleSelect) {
        const matchingOption = Array.from(finaleSelect.options || []).find((option) => option.value === nextKey);
        if (matchingOption) {
            finaleSelect.value = nextKey;
        }
    }

    if (previousKey !== nextKey) {
        try {
            console.warn(`Finale auto-adjusted from ${previousKey || "custom"} to ${nextKey} after a finale return.`);
        } catch (_err) {}
        if (typeof showFloatingNotice === "function") {
            showFloatingNotice(`Finale auto-adjusted to Top ${castSize}`, 1800);
        }
        return true;
    }

    return false;
}

function beforeFinale() {
    normalizeFinaleSelectionForCast();
    if ((top8reg || top8ls) && currentCast.length == 9) {
        return true;
    } else if ((top7reg || top7ls) && currentCast.length == 8) {
        return true;
    } else if ((top6reg || top6ls || top6lsSudden || top6as11) && currentCast.length == 7) {
        return true;        
    } else if ((top5 || top5ls) && currentCast.length == 6) {
        return true;
    } else if ((top4 || canFinale || lftc || maxiLFTC || allstars3Finale || teamsF) && currentCast.length == 5) {
        return true;
    } else if ((lmd3Semis || lmd4Semis || lmd5Semis || lmd6Semis) && currentCast.length == 5) {
        return true;
    } else if ((top3 || top3JuryFinale || sverigeTop3 || dres4finale || top3LSF) && currentCast.length == 4) {
        return true;
    } else if ((top2F || jurytop2) && currentCast.length == 3) {
        return true;
    }

    return false;
}

function atFinaleStage() {
    normalizeFinaleSelectionForCast();
    const finalSize = getFinaleCastSize();
    return currentCast.length >= 2 && currentCast.length <= finalSize;
}

function getFinaleCastSize() {
    normalizeFinaleSelectionForCast();
    return getConfiguredFinaleCastSize();
}

function ensurePostBracketMergeHasNonFinaleEpisode() {
    const castSize = Array.isArray(currentCast) ? currentCast.length : 0;
    if (castSize <= 3) return;

    normalizeFinaleSelectionForCast();
    const configuredSize = Math.floor(Number(finaleSize)) || getConfiguredFinaleCastSize();
    if (configuredSize <= 3) return;
    if (castSize > configuredSize) return;

    const targetSize = Math.max(2, castSize - 1);
    if (targetSize >= castSize) return;

    const nextKey = getFallbackFinaleKeyForCastSize(targetSize);
    if (!nextKey) return;

    applyFinaleKey(nextKey);
    lastSeasonFinale = nextKey;

    const finaleSelect = document.getElementById("finale");
    if (finaleSelect) {
        const matchingOption = Array.from(finaleSelect.options || []).find((option) => option.value === nextKey);
        if (matchingOption) {
            finaleSelect.value = nextKey;
        }
    }
}

function resetSeasonHeartTokens() {
    for (let i = 0; i < currentCast.length; i++) {
        currentCast[i].hearts = 1;
        currentCast[i].heartEpisode = [];
    }
}

function isSplitPremiereInProgress() {
    const groupCount = (triplePremiereFlag || ladderClimbPremiere) ? 3 : 2;
    const poolSize = firstCast.length + secondCast.length + thirdCast.length;
    return poolSize > 0 && premiereCounter > 0 && premiereCounter <= groupCount;
}

function canDoDoubleElimination() {
    const remaining = isSplitPremiereInProgress()
        ? firstCast.length + secondCast.length + thirdCast.length
        : currentCast.length;
    return remaining - 2 >= getFinaleCastSize();
}

let targetEpisodeCount = 0;
let seasonPacingActive = false;
let seasonPacingRolls = {};
let seasonPacingNonElimFlavour = {};

function getSelectedFinaleSizeFromUi() {
    const sizeSelect = document.getElementById("finale-size");
    const parsed = Math.floor(Number(sizeSelect?.value));
    return Number.isFinite(parsed) && parsed >= 2 && parsed <= 8 ? parsed : getConfiguredFinaleCastSize();
}

function getTargetEpisodeSetting() {
    const modeSelect = document.getElementById("target-episodes-mode");
    if (modeSelect && modeSelect.value !== "fixed") return 0;
    const input = document.getElementById("target-episodes");
    const parsed = Math.floor(Number(input?.value));
    return Number.isFinite(parsed) && parsed >= 2 ? parsed : 0;
}

// Semi-finale formats cut straight from this cast size down to the finale in one locked episode.
const SEMI_FINALE_CUT_SIZE_BY_FINALE_KEY = {
    lmd3t4: 6,
    lmd4t4: 6,
    lmd5t4: 6,
    lmd6t4: 6,
    drph2f: 6,
    drthtop3: 5
};

function getSemiFinaleCutCastSize() {
    if (lmd3Semis || lmd4Semis || lmd5Semis || lmd6Semis || drph2Semis) return 6;
    if (drtht3) return 5;
    return 0;
}

function getSelectedSemiFinaleCutFromUi() {
    const typeSelect = document.getElementById("finale-type") || document.getElementById("finale");
    return SEMI_FINALE_CUT_SIZE_BY_FINALE_KEY[typeSelect?.value] || 0;
}

function getSelectedReturnCountFromUi() {
    const returningSelect = document.getElementById("returning");
    const value = String(returningSelect?.value || "");
    if (value === "randomDouble" || value === "chooseDouble") return 2;
    const singleReturnValues = [
        "random", "choose", "votes", "lmd5return", "lmd7return",
        "lalaparuza", "queensofcomedy", "reinasdelacomedia",
        "kittygirlgroup", "attentionggroup"
    ];
    return singleReturnValues.includes(value) ? 1 : 0;
}

// Queens still expected to re-enter the cast, so their extra eliminations stay budgeted.
function getExpectedReturningQueenCount() {
    if (returningQueen) return 0;
    if (!Array.isArray(eliminatedCast) || eliminatedCast.length === 0) return 0;
    if (doubleQueenReturns || chooseDoubleReturn) return 2;
    const singleReturnActive = randomReturn || chooseReturn || voteReturn || lmdRunwayReturn
        || lalaparuza || queensOfComedy || reinasDLC || kittyGirlGroup || attentionGGroup;
    return singleReturnActive ? 1 : 0;
}

function getPacingFloorCastSize(finaleCastSize, semiFinaleCutSize) {
    return semiFinaleCutSize > finaleCastSize ? semiFinaleCutSize : finaleCastSize;
}

function getLockedTailEpisodes(finaleCastSize, semiFinaleCutSize) {
    return semiFinaleCutSize > finaleCastSize ? 1 : 0;
}

function getEstimatedSeasonEpisodes(castSize, finaleCastSize, semiFinaleCutSize = 0, pendingReturns = 0) {
    const floor = getPacingFloorCastSize(finaleCastSize, semiFinaleCutSize);
    const tail = getLockedTailEpisodes(finaleCastSize, semiFinaleCutSize);
    const eliminations = Math.max(0, castSize - floor) + Math.max(0, pendingReturns);
    return Math.max(1, eliminations + tail + 1);
}

function getMinimumSeasonEpisodes(castSize, finaleCastSize, semiFinaleCutSize = 0, pendingReturns = 0) {
    const floor = getPacingFloorCastSize(finaleCastSize, semiFinaleCutSize);
    const tail = getLockedTailEpisodes(finaleCastSize, semiFinaleCutSize);
    const eliminations = Math.max(0, castSize - floor) + Math.max(0, pendingReturns);
    return Math.max(1, Math.ceil(eliminations / 2) + tail + 1);
}

function applyTargetEpisodePlan(castSize) {
    seasonPacingActive = false;
    targetEpisodeCount = getTargetEpisodeSetting();
    if (!targetEpisodeCount || brackets_format || !Number.isFinite(castSize) || castSize < 3) {
        targetEpisodeCount = 0;
        return;
    }

    const finaleCastSize = getConfiguredFinaleCastSize();
    const semiFinaleCutSize = getSemiFinaleCutCastSize();
    if (castSize <= getPacingFloorCastSize(finaleCastSize, semiFinaleCutSize)) {
        targetEpisodeCount = 0;
        return;
    }

    const pendingReturns = getSelectedReturnCountFromUi();
    targetEpisodeCount = Math.max(
        targetEpisodeCount,
        getMinimumSeasonEpisodes(castSize, finaleCastSize, semiFinaleCutSize, pendingReturns)
    );
    seasonPacingActive = true;
    seasonPacingRolls = {};
    seasonPacingNonElimFlavour = {};
    if (typeof showFloatingNotice === "function") {
        showFloatingNotice(`Season paced to ${targetEpisodeCount} episodes (Top ${finaleCastSize} finale)`, 2200);
    }
}

function getSeasonPacingOptions(eliminationsLeft, elimSlots) {
    const laterSlots = Math.max(0, elimSlots - 1);
    const fits = (remaining) => remaining <= 2 * laterSlots && (laterSlots === 0 ? remaining === 0 : remaining >= 1);
    const options = [];
    if (eliminationsLeft >= 2 && fits(eliminationsLeft - 2)) options.push("double");
    if (eliminationsLeft >= 1 && fits(eliminationsLeft - 1)) options.push("single");
    if (fits(eliminationsLeft)) options.push("none");
    return options;
}

function rollSeasonPacingDirective(eliminationsLeft, elimSlots) {
    const options = getSeasonPacingOptions(eliminationsLeft, elimSlots);
    if (options.length === 0) return eliminationsLeft >= 2 ? "double" : "single";
    if (options.length === 1) return options[0];

    const surplus = eliminationsLeft - elimSlots;
    const pressure = Math.abs(surplus) / elimSlots;
    const weights = { double: 0, single: 100, none: 0 };
    if (surplus > 0) {
        weights.double = Math.round(pressure * 100) + 12;
    } else if (surplus < 0) {
        weights.none = Math.round(pressure * 100) + 12;
    } else {
        weights.double = 8;
        weights.none = 8;
    }

    const pool = options.filter(option => weights[option] > 0);
    if (pool.length === 0) return options.includes("single") ? "single" : options[0];

    const total = pool.reduce((sum, option) => sum + weights[option], 0);
    let roll = randomNumber(0, total - 1);
    for (const option of pool) {
        roll -= weights[option];
        if (roll < 0) return option;
    }
    return pool[pool.length - 1];
}

function getSeasonPacingDirective() {
    if (!seasonPacingActive || !targetEpisodeCount) return "";
    if (bracketPhaseActive || wildcardBracketPhaseActive) return "";
    if (isSplitPremiereInProgress()) return "";

    const remainingQueens = Array.isArray(currentCast) ? currentCast.length : 0;
    const finaleCastSize = getConfiguredFinaleCastSize();
    const semiFinaleCutSize = getSemiFinaleCutCastSize();
    const floor = getPacingFloorCastSize(finaleCastSize, semiFinaleCutSize);
    if (remainingQueens <= floor) return "";

    const pendingReturns = getExpectedReturningQueenCount();
    const eliminationsLeft = remainingQueens - floor + pendingReturns;
    // The semi-finale cut is locked in, so its episode never counts as a flexible slot.
    const elimSlots = Math.max(1, targetEpisodeCount - episodeCount - getLockedTailEpisodes(finaleCastSize, semiFinaleCutSize));

    const rollKey = `${episodeCount}:${remainingQueens}:${floor}:${pendingReturns}`;
    if (seasonPacingRolls.key !== rollKey) {
        seasonPacingRolls = { key: rollKey, directive: rollSeasonPacingDirective(eliminationsLeft, elimSlots) };
    }
    return seasonPacingRolls.directive;
}

function seasonPacingForcesDoubleElimination() {
    return getSeasonPacingDirective() === "double" && canDoDoubleElimination();
}

function seasonPacingForcesNonElimination() {
    return getSeasonPacingDirective() === "none";
}

function seasonPacingBlocksDoubleElimination() {
    const directive = getSeasonPacingDirective();
    return directive === "single" || directive === "none";
}

function seasonPacingBlocksNonElimination() {
    const directive = getSeasonPacingDirective();
    return directive === "single" || directive === "double";
}

// Non-elimination weeks get some variety: a wider bottom group, or an all-slay week.
function getSeasonPacingNonElimFlavour() {
    if (!seasonPacingForcesNonElimination()) return null;

    const castSize = Array.isArray(currentCast) ? currentCast.length : 0;
    const flavourKey = `${episodeCount}:${castSize}`;
    if (seasonPacingNonElimFlavour.key === flavourKey) return seasonPacingNonElimFlavour;

    const roll = randomNumber(0, 99);
    let bottomCount = 2;
    if (castSize >= 8 && roll < 20) {
        bottomCount = 4;
    } else if (castSize >= 6 && roll < 55) {
        bottomCount = 3;
    }

    const canSlay = castSize > 4 && !slayersCheck && regularFormat && !conjoinedCheck && !specialEventsOff;
    seasonPacingNonElimFlavour = {
        key: flavourKey,
        bottomCount,
        useSlayers: canSlay && randomNumber(0, 99) < 25
    };
    return seasonPacingNonElimFlavour;
}

function getSeasonPacingBottomCount() {
    const flavour = getSeasonPacingNonElimFlavour();
    return flavour ? flavour.bottomCount : 0;
}

function seasonPacingWantsSlayers() {
    const flavour = getSeasonPacingNonElimFlavour();
    return !!(flavour && flavour.useSlayers);
}

function updateTargetEpisodeControls() {
    updateSetupSummary();
    const modeSelect = document.getElementById("target-episodes-mode");
    const input = document.getElementById("target-episodes");
    const descText = document.getElementById("target-episodes-desc-text");
    if (!modeSelect || !input) return;

    const isFixed = modeSelect.value === "fixed";
    input.style.display = isFixed ? "" : "none";
    if (!descText) return;

    const castSize = Array.isArray(currentCast) ? currentCast.length : 0;
    const finaleCastSize = getSelectedFinaleSizeFromUi();
    const semiFinaleCutSize = getSelectedSemiFinaleCutFromUi();
    const pendingReturns = getSelectedReturnCountFromUi();

    if (!isFixed) {
        descText.textContent = castSize
            ? `No forcing: about ${getEstimatedSeasonEpisodes(castSize, finaleCastSize, semiFinaleCutSize, pendingReturns)} episodes with the selected finale.`
            : "No forcing: season length follows eliminations as they happen.";
        return;
    }

    const target = getTargetEpisodeSetting();
    if (!target) {
        descText.textContent = "Enter how many episodes the season should last (2 or more).";
        return;
    }
    if (!castSize) {
        descText.textContent = `Season will be paced to ${target} episodes once a cast is picked.`;
        return;
    }

    const minimum = getMinimumSeasonEpisodes(castSize, finaleCastSize, semiFinaleCutSize, pendingReturns);
    if (target < minimum) {
        descText.textContent = `Too short: ${castSize} queens with a Top ${finaleCastSize} finale need at least ${minimum} episodes.`;
        return;
    }

    const natural = getEstimatedSeasonEpisodes(castSize, finaleCastSize, semiFinaleCutSize, pendingReturns);
    let note = "";
    if (target < natural) {
        note = " Double eliminations get scattered through the season to fit.";
    } else if (target > natural) {
        note = " Non-elimination episodes get scattered through the season to fit.";
    } else {
        note = " Paced week by week, with the odd double or non-elim.";
    }
    if (semiFinaleCutSize > finaleCastSize) {
        note += ` The Top ${semiFinaleCutSize} semi-finale cut is reserved.`;
    }
    if (pendingReturns > 0) {
        note += ` ${pendingReturns} returning queen${pendingReturns === 1 ? "" : "s"} budgeted.`;
    }
    descText.textContent = `${castSize} queens → Top ${finaleCastSize} finale over ${target} episodes.${note}`;
}

function randomizeTargetEpisodesReady() {
    const modeSelect = document.getElementById("target-episodes-mode");
    const input = document.getElementById("target-episodes");
    if (!modeSelect || !input) return;

    const castSize = Array.isArray(currentCast) && currentCast.length ? currentCast.length : 12;
    const finaleCastSize = getSelectedFinaleSizeFromUi();
    const semiFinaleCutSize = getSelectedSemiFinaleCutFromUi();
    const pendingReturns = getSelectedReturnCountFromUi();
    modeSelect.value = "fixed";
    const minimum = getMinimumSeasonEpisodes(castSize, finaleCastSize, semiFinaleCutSize, pendingReturns);
    const maximum = Math.max(minimum, getEstimatedSeasonEpisodes(castSize, finaleCastSize, semiFinaleCutSize, pendingReturns) + 2);
    input.value = String(randomNumber(minimum, maximum));
    updateTargetEpisodeControls();

    modeSelect.classList.remove("setting-randomized");
    void modeSelect.offsetWidth;
    modeSelect.classList.add("setting-randomized");
    setTimeout(() => modeSelect.classList.remove("setting-randomized"), 600);
}
