const CUSTOM_IMAGE_UPLOAD_LIMIT_BYTES = 5 * 1024 * 1024;
const CUSTOM_CLOUD_UPLOAD_LIMIT_BYTES = 1 * 1024 * 1024;
const CUSTOM_IMAGE_TARGET_BYTES = 450 * 1024;
const CUSTOM_BACKGROUND_TARGET_BYTES = 900 * 1024;
const CUSTOM_IMAGE_STORE_KEY = "ssCustomImageStore";
const CUSTOM_IMAGE_REF_PREFIX = "ssimg:";
const pendingCustomImageUploads = new Set();

function formatSizeMb(bytes) {
    return (Math.max(0, Number(bytes) || 0) / (1024 * 1024)).toFixed(2);
}

function getCustomImageStore() {
    try {
        return JSON.parse(localStorage.getItem(CUSTOM_IMAGE_STORE_KEY) || "{}") || {};
    } catch (_err) {
        return {};
    }
}

function saveCustomImageStore(store) {
    try {
        localStorage.setItem(CUSTOM_IMAGE_STORE_KEY, JSON.stringify(store || {}));
    } catch (_err) { }
}

function createTrackedCustomImageRef(id) {
    return CUSTOM_IMAGE_REF_PREFIX + id;
}

function registerTrackedCustomImageEntry(entry, preferredId = "") {
    const store = getCustomImageStore();
    const id = hashCustomImageValue(preferredId || entry?.path || entry?.url || `${Date.now()}-${Math.random()}`);
    store[id] = {
        source: entry?.source || "local",
        url: entry?.url || "",
        path: entry?.path || "",
        savedAt: Date.now()
    };
    saveCustomImageStore(store);
    return createTrackedCustomImageRef(id);
}

function getFirebaseStorageCompat() {
    if (!window.firebase || typeof firebase.storage !== "function") return null;
    try {
        if ((!firebase.apps || !firebase.apps.length) && typeof accountFirebaseConfig !== "undefined") {
            firebase.initializeApp(accountFirebaseConfig);
        }
        return firebase.storage();
    } catch (error) {
        console.warn("Firebase Storage unavailable:", error);
        return null;
    }
}

async function uploadTrackedImageToFirebaseStorage(dataUrl, options = {}) {
    const storage = getFirebaseStorageCompat();
    if (!storage || !dataUrl || typeof dataUrl !== "string" || !dataUrl.startsWith("data:image/")) {
        return null;
    }
    const dataUrlBytes = getDataUrlSizeBytes(dataUrl);
    if (dataUrlBytes > CUSTOM_CLOUD_UPLOAD_LIMIT_BYTES) {
        const limitMb = formatSizeMb(CUSTOM_CLOUD_UPLOAD_LIMIT_BYTES);
        throw new Error(`Image exceeds cloud upload limit (${limitMb} MB). It can still be saved locally.`);
    }

    const authUser = firebase.auth && typeof firebase.auth === "function"
        ? firebase.auth().currentUser
        : null;
    const ownerKey = authUser && authUser.uid ? authUser.uid : "guest";
    const folder = options.folder || "custom-uploads";
    const contentHash = hashCustomImageValue(dataUrl).replace(/^img_/, "");
    const path = `${folder}/${ownerKey}/${contentHash}.jpg`;
    const storageRef = storage.ref().child(path);

    await storageRef.putString(dataUrl, "data_url", {
        contentType: "image/jpeg",
        cacheControl: "public,max-age=31536000,immutable",
        customMetadata: {
            owner: ownerKey,
            kind: options.label || "custom-image"
        }
    });

    const url = await storageRef.getDownloadURL();
    return {
        path,
        url,
        refValue: registerTrackedCustomImageEntry({
            source: "firebase",
            url,
            path
        }, path)
    };
}

function isTrackedCustomImageRef(value) {
    return typeof value === "string" && value.startsWith(CUSTOM_IMAGE_REF_PREFIX);
}

function hashCustomImageValue(value) {
    const input = String(value || "");
    let hash = 0;
    for (let i = 0; i < input.length; i++) {
        hash = ((hash << 5) - hash) + input.charCodeAt(i);
        hash |= 0;
    }
    return `img_${Math.abs(hash).toString(36)}_${input.length.toString(36)}`;
}

function trackCustomImageValue(value) {
    if (typeof value !== "string") return value;
    const trimmed = value.trim();
    if (!trimmed || trimmed === "noimage") return "noimage";
    if (isTrackedCustomImageRef(trimmed)) return trimmed;
    if (trimmed.startsWith("data:image/")) {
        return registerTrackedCustomImageEntry({
            source: "local",
            url: trimmed
        }, trimmed);
    }
    return trimmed;
}

function resolveTrackedCustomImage(value) {
    if (typeof value !== "string") return "image/queens/noimage.jpg";
    const trimmed = value.trim();
    if (!trimmed || trimmed === "noimage") return "image/queens/noimage.jpg";
    if (isTrackedCustomImageRef(trimmed)) {
        const store = getCustomImageStore();
        const storedValue = store[trimmed.slice(CUSTOM_IMAGE_REF_PREFIX.length)];
        if (typeof storedValue === "string") {
            return storedValue || "image/queens/noimage.jpg";
        }
        if (storedValue && typeof storedValue.url === "string") {
            return storedValue.url || "image/queens/noimage.jpg";
        }
        return "image/queens/noimage.jpg";
    }
    return trimmed;
}

function normalizeTrackedImageList(images) {
    const rawImages = Array.isArray(images) ? images : [images];
    const normalized = rawImages
        .map(image => trackCustomImageValue(image))
        .filter(image => typeof image === "string" && image.trim() !== "");
    return normalized.length > 0 ? normalized : ["noimage"];
}

function collectTrackedCustomImageUsage(values, usedRefs) {
    const list = Array.isArray(values) ? values : [values];
    list.forEach(value => {
        if (isTrackedCustomImageRef(value)) {
            usedRefs.add(value.slice(CUSTOM_IMAGE_REF_PREFIX.length));
        }
    });
}

function cleanupUnusedTrackedCustomImages() {
    const usedRefs = new Set();

    if (Array.isArray(allCustomQueens)) {
        allCustomQueens.forEach(q => {
            if (q && Array.isArray(q.images)) {
                q.images = normalizeTrackedImageList(q.images);
                collectTrackedCustomImageUsage(q.images, usedRefs);
            }
        });
    }

    if (Array.isArray(allCustomJudges)) {
        allCustomJudges.forEach(judge => {
            if (judge && typeof judge.imageUrl === "string") {
                judge.imageUrl = trackCustomImageValue(judge.imageUrl);
                collectTrackedCustomImageUsage(judge.imageUrl, usedRefs);
            }
        });
    }

    if (Array.isArray(allCustomBackgrounds)) {
        allCustomBackgrounds.forEach(bg => {
            if (bg && typeof bg.imageUrl === "string") {
                bg.imageUrl = trackCustomImageValue(bg.imageUrl);
                collectTrackedCustomImageUsage(bg.imageUrl, usedRefs);
            }
        });
    }

    if (customHost && typeof customHost.imageUrl === "string") {
        customHost.imageUrl = trackCustomImageValue(customHost.imageUrl);
        collectTrackedCustomImageUsage(customHost.imageUrl, usedRefs);
    }

    try {
        const savedCasts = JSON.parse(localStorage.getItem("customCasts") || "[]");
        if (Array.isArray(savedCasts)) {
            savedCasts.forEach(savedCast => {
                if (savedCast && Array.isArray(savedCast.cast)) {
                    savedCast.cast.forEach(queen => {
                        if (queen && Array.isArray(queen.images)) {
                            queen.images = normalizeTrackedImageList(queen.images);
                            collectTrackedCustomImageUsage(queen.images, usedRefs);
                        }
                    });
                }
            });
            localStorage.setItem("customCasts", JSON.stringify(savedCasts));
        }
    } catch (_err) { }

    const store = getCustomImageStore();
    const storage = getFirebaseStorageCompat();
    Object.keys(store).forEach(id => {
        if (!usedRefs.has(id)) {
            const entry = store[id];
            if (storage && entry && typeof entry === "object" && entry.source === "firebase" && entry.path) {
                storage.ref().child(entry.path).delete().catch((error) => {
                    console.warn("Failed to delete unused Firebase image:", error);
                });
            }
            delete store[id];
        }
    });
    saveCustomImageStore(store);
}

function persistTrackedCustomImages() {
    cleanupUnusedTrackedCustomImages();
    try {
        localStorage.setItem("customQueens", JSON.stringify(allCustomQueens || []));
        localStorage.setItem("customJudges", JSON.stringify(allCustomJudges || []));
        localStorage.setItem("customBackgrounds", JSON.stringify(allCustomBackgrounds || []));
        if (customHost) {
            localStorage.setItem("customHost", JSON.stringify(customHost));
        } else {
            localStorage.removeItem("customHost");
        }
    } catch (_err) { }
}

function getDataUrlSizeBytes(dataUrl) {
    if (!dataUrl || typeof dataUrl !== "string") return 0;
    const base64 = dataUrl.split(",")[1] || "";
    return Math.ceil((base64.length * 3) / 4);
}

function readFileAsDataUrl(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(new Error("Failed to read the image file."));
        reader.readAsDataURL(file);
    });
}

function loadImageElement(src) {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error("The selected file could not be processed as an image."));
        img.src = src;
    });
}

let customImageCropModal = null;

function getCustomCropViewportDimensions(aspectRatio = 1) {
    const ratio = Number(aspectRatio) > 0 ? Number(aspectRatio) : 1;
    const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 1280;
    const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 720;
    const maxWidth = Math.min(Math.round(viewportWidth * 0.82), ratio >= 2.4 ? 720 : ratio >= 1.6 ? 560 : 420);
    const maxHeight = Math.min(Math.round(viewportHeight * 0.55), ratio >= 2.4 ? 260 : 420);

    let width = Math.max(220, maxWidth);
    let height = Math.round(width / ratio);

    if (height > maxHeight) {
        height = Math.max(120, maxHeight);
        width = Math.round(height * ratio);
    }

    return {
        width: Math.max(220, width),
        height: Math.max(120, height)
    };
}

function syncCustomCropModalPosition(overlay) {
    if (!overlay) return;
    overlay.style.position = "fixed";
    overlay.style.inset = "0";
    overlay.style.top = "0";
    overlay.style.left = "0";
    overlay.style.right = "0";
    overlay.style.minHeight = `${window.innerHeight || document.documentElement.clientHeight || 0}px`;
}

function ensureCustomImageCropModal() {
    if (customImageCropModal) return customImageCropModal;

    const overlay = document.createElement("div");
    overlay.className = "custom-image-crop-modal";
    overlay.innerHTML = `
        <div class="custom-image-crop-card" role="dialog" aria-modal="true" aria-label="Crop image">
            <h3>Crop Image</h3>
            <p>Drag to position and use the slider to zoom.</p>
            <div class="custom-image-crop-stage-wrap">
                <div class="custom-image-crop-stage">
                    <img class="custom-image-crop-preview" alt="Crop preview">
                </div>
            </div>
            <label class="custom-image-crop-zoom-label">
                Zoom
                <input type="range" min="1" max="3" step="0.01" value="1" class="custom-image-crop-zoom">
            </label>
            <div class="custom-image-crop-actions">
                <button type="button" class="custom-image-crop-cancel">Cancel</button>
                <button type="button" class="custom-image-crop-apply">Use Crop</button>
            </div>
        </div>
    `;
    document.body.appendChild(overlay);

    customImageCropModal = {
        overlay,
        stage: overlay.querySelector(".custom-image-crop-stage"),
        preview: overlay.querySelector(".custom-image-crop-preview"),
        zoom: overlay.querySelector(".custom-image-crop-zoom"),
        cancel: overlay.querySelector(".custom-image-crop-cancel"),
        apply: overlay.querySelector(".custom-image-crop-apply"),
        note: overlay.querySelector("p")
    };

    const syncCropViewport = () => {
        if (customImageCropModal?.overlay?.classList.contains("active")) {
            requestAnimationFrame(() => syncCustomCropModalPosition(customImageCropModal.overlay));
        }
    };
    window.addEventListener("scroll", syncCropViewport, { passive: true });
    window.addEventListener("resize", syncCropViewport);

    return customImageCropModal;
}

function clampCustomCropOffsets(state) {
    const scaledWidth = state.imageWidth * state.scale;
    const scaledHeight = state.imageHeight * state.scale;
    const minX = Math.min(0, state.viewportWidth - scaledWidth);
    const minY = Math.min(0, state.viewportHeight - scaledHeight);

    state.offsetX = Math.min(0, Math.max(minX, state.offsetX));
    state.offsetY = Math.min(0, Math.max(minY, state.offsetY));
}

function renderCustomCropPreview(state) {
    clampCustomCropOffsets(state);
    state.preview.style.width = `${Math.round(state.imageWidth * state.scale)}px`;
    state.preview.style.height = `${Math.round(state.imageHeight * state.scale)}px`;
    state.preview.style.transform = `translate(${Math.round(state.offsetX)}px, ${Math.round(state.offsetY)}px)`;
}

async function openCustomImageCropper(file, options = {}) {
    if (!options.allowCrop) {
        return null;
    }

    const modal = ensureCustomImageCropModal();
    const dataUrl = await readFileAsDataUrl(file);
    const image = await loadImageElement(dataUrl);
    const aspectRatio = Number(options.cropAspectRatio) > 0 ? Number(options.cropAspectRatio) : 1;
    const viewport = getCustomCropViewportDimensions(aspectRatio);

    modal.stage.style.width = `${viewport.width}px`;
    modal.stage.style.height = `${viewport.height}px`;
    modal.preview.src = dataUrl;
    modal.zoom.value = "1";
    modal.note.textContent = options.cropMessage || "Drag to position and use the slider to zoom.";

    const state = {
        imageWidth: image.naturalWidth || image.width || viewport.width,
        imageHeight: image.naturalHeight || image.height || viewport.height,
        viewportWidth: viewport.width,
        viewportHeight: viewport.height,
        scale: 1,
        baseScale: 1,
        offsetX: 0,
        offsetY: 0,
        preview: modal.preview
    };

    state.baseScale = Math.max(state.viewportWidth / state.imageWidth, state.viewportHeight / state.imageHeight);
    state.scale = state.baseScale;
    state.offsetX = (state.viewportWidth - state.imageWidth * state.scale) / 2;
    state.offsetY = (state.viewportHeight - state.imageHeight * state.scale) / 2;
    renderCustomCropPreview(state);
    modal.overlay.classList.add("active");
    modal.overlay.setAttribute("aria-hidden", "false");
    syncCustomCropModalPosition(modal.overlay);
    if (typeof activateCenteredPopup === "function") {
        activateCenteredPopup(modal.overlay);
    }

    return new Promise((resolve, reject) => {
        let dragging = false;
        let dragStartX = 0;
        let dragStartY = 0;
        let startOffsetX = 0;
        let startOffsetY = 0;

        const cleanup = () => {
            if (typeof deactivateCenteredPopup === "function") {
                deactivateCenteredPopup(modal.overlay);
            }
            modal.overlay.classList.remove("active");
            modal.overlay.setAttribute("aria-hidden", "true");
            modal.stage.classList.remove("is-dragging");
            modal.cancel.removeEventListener("click", handleCancel);
            modal.apply.removeEventListener("click", handleApply);
            modal.zoom.removeEventListener("input", handleZoom);
            modal.stage.removeEventListener("pointerdown", handlePointerDown);
            modal.stage.removeEventListener("pointermove", handlePointerMove);
            modal.stage.removeEventListener("pointerup", handlePointerUp);
            modal.stage.removeEventListener("pointerleave", handlePointerUp);
            modal.overlay.removeEventListener("click", handleOverlayClick);
        };

        const handleCancel = () => {
            cleanup();
            reject(new Error("Image selection cancelled."));
        };

        const handleApply = () => {
            const sourceX = Math.max(0, -state.offsetX / state.scale);
            const sourceY = Math.max(0, -state.offsetY / state.scale);
            const sourceWidth = Math.min(state.imageWidth, state.viewportWidth / state.scale);
            const sourceHeight = Math.min(state.imageHeight, state.viewportHeight / state.scale);
            const outputWidth = Math.max(360, Math.round(options.outputWidth || (aspectRatio >= 1.6 ? 1200 : 800)));
            const outputHeight = Math.max(360, Math.round(outputWidth / aspectRatio));
            const canvas = document.createElement("canvas");
            const ctx = canvas.getContext("2d");
            if (!ctx) {
                cleanup();
                reject(new Error("Your browser could not prepare the crop."));
                return;
            }

            canvas.width = outputWidth;
            canvas.height = outputHeight;
            ctx.fillStyle = "#ffffff";
            ctx.fillRect(0, 0, outputWidth, outputHeight);
            ctx.drawImage(image, sourceX, sourceY, sourceWidth, sourceHeight, 0, 0, outputWidth, outputHeight);

            cleanup();
            resolve(canvas.toDataURL("image/jpeg", 0.94));
        };

        const handleZoom = () => {
            const zoomLevel = Number(modal.zoom.value || "1");
            state.scale = state.baseScale * zoomLevel;
            renderCustomCropPreview(state);
        };

        const handlePointerDown = (event) => {
            dragging = true;
            dragStartX = event.clientX;
            dragStartY = event.clientY;
            startOffsetX = state.offsetX;
            startOffsetY = state.offsetY;
            modal.stage.classList.add("is-dragging");
            try {
                modal.stage.setPointerCapture(event.pointerId);
            } catch (_err) { }
        };

        const handlePointerMove = (event) => {
            if (!dragging) return;
            state.offsetX = startOffsetX + (event.clientX - dragStartX);
            state.offsetY = startOffsetY + (event.clientY - dragStartY);
            renderCustomCropPreview(state);
        };

        const handlePointerUp = (event) => {
            dragging = false;
            modal.stage.classList.remove("is-dragging");
            try {
                modal.stage.releasePointerCapture(event.pointerId);
            } catch (_err) { }
        };

        const handleOverlayClick = (event) => {
            if (event.target === modal.overlay) {
                handleCancel();
            }
        };

        modal.cancel.addEventListener("click", handleCancel);
        modal.apply.addEventListener("click", handleApply);
        modal.zoom.addEventListener("input", handleZoom);
        modal.stage.addEventListener("pointerdown", handlePointerDown);
        modal.stage.addEventListener("pointermove", handlePointerMove);
        modal.stage.addEventListener("pointerup", handlePointerUp);
        modal.stage.addEventListener("pointerleave", handlePointerUp);
        modal.overlay.addEventListener("click", handleOverlayClick);
    });
}

async function resizeImageForStorage(file, options = {}) {
    if (!file) return "";
    if (!file.type || !file.type.startsWith("image/")) {
        throw new Error("Please upload a valid image file.");
    }
    if (file.size > CUSTOM_IMAGE_UPLOAD_LIMIT_BYTES) {
        throw new Error("Images must be 5 MB or smaller.");
    }

    const maxWidth = options.maxWidth || options.maxDimension || 900;
    const maxHeight = options.maxHeight || options.maxDimension || 900;
    const targetBytes = options.targetBytes || CUSTOM_IMAGE_TARGET_BYTES;
    const croppedDataUrl = await openCustomImageCropper(file, options);
    const fileDataUrl = croppedDataUrl || await readFileAsDataUrl(file);
    const image = await loadImageElement(fileDataUrl);

    let width = image.naturalWidth || image.width || maxWidth;
    let height = image.naturalHeight || image.height || maxHeight;
    const ratio = Math.min(1, maxWidth / width, maxHeight / height);
    width = Math.max(1, Math.round(width * ratio));
    height = Math.max(1, Math.round(height * ratio));

    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    if (!ctx) {
        throw new Error("Your browser could not prepare the uploaded image.");
    }

    let quality = typeof options.quality === "number" ? options.quality : 0.9;
    let output = "";

    while (true) {
        canvas.width = width;
        canvas.height = height;
        ctx.clearRect(0, 0, width, height);
        ctx.fillStyle = "#ffffff";
        ctx.fillRect(0, 0, width, height);
        ctx.drawImage(image, 0, 0, width, height);
        output = canvas.toDataURL("image/jpeg", quality);

        if (getDataUrlSizeBytes(output) <= targetBytes) {
            return output;
        }

        if (quality > 0.55) {
            quality -= 0.08;
        } else if (width > 320 || height > 320) {
            width = Math.max(320, Math.round(width * 0.85));
            height = Math.max(320, Math.round(height * 0.85));
            quality = typeof options.quality === "number" ? Math.max(0.72, options.quality - 0.08) : 0.82;
        } else {
            return output;
        }
    }
}

async function waitForPendingCustomUploads() {
    if (pendingCustomImageUploads.size === 0) return;
    await Promise.allSettled(Array.from(pendingCustomImageUploads));
}

function updateUploadStatus(statusElement, message) {
    if (statusElement) {
        statusElement.textContent = message;
    }
}

function getStandaloneModeHint(mode) {
    return mode === "url"
        ? "URL mode: paste an image URL."
        : "Cloud upload: image files up to 5 MB are resized automatically.";
}

function updateStandaloneModeStatus(container, mode) {
    if (!container) return;
    const scope = container.matches?.(".image-input-row")
        ? (container.closest(".image-input-group") || container)
        : container;
    const statusElement = scope.querySelector(".image-upload-status, [id$='ImageStatus']");
    if (!statusElement) return;
    const urlInput = scope.querySelector("input[type='text']");
    const hasUrlValue = Boolean(urlInput && urlInput.value.trim());
    updateUploadStatus(statusElement, hasUrlValue ? "Saved image ready." : getStandaloneModeHint(mode));
}

function handleUploadedImage(fileInput, valueInput, preview, options = {}) {
    if (!fileInput || !valueInput) return;
    const file = fileInput.files && fileInput.files[0];
    if (!file) return;

    const statusElement = options.statusElement || null;
    const previousValue = valueInput.value || "";
    updateUploadStatus(statusElement, options.allowCrop
        ? "Opening crop editor..."
        : "Processing image...");

    const task = (async () => {
        try {
            const resizedImage = await resizeImageForStorage(file, options);
            let storedValue = trackCustomImageValue(resizedImage);
            let uploadedToCloud = false;

            try {
                const cloudUpload = await uploadTrackedImageToFirebaseStorage(resizedImage, options);
                if (cloudUpload && cloudUpload.refValue) {
                    storedValue = cloudUpload.refValue;
                    uploadedToCloud = true;
                }
            } catch (cloudError) {
                console.warn("Firebase Storage upload failed, using local fallback:", cloudError);
            }

            valueInput.value = storedValue;
            if (preview) {
                updateImagePreview(valueInput, preview);
            }
            if (typeof options.afterUpdate === "function") {
                options.afterUpdate(storedValue);
            }
            const storedSizeKb = Math.max(1, Math.round(getDataUrlSizeBytes(resizedImage) / 1024));
            updateUploadStatus(statusElement, uploadedToCloud
                ? `Image uploaded to Firebase Storage. Stored size: ${storedSizeKb} KB.`
                : `Image ready locally. Stored size: ${storedSizeKb} KB.`);
        } catch (error) {
            valueInput.value = previousValue;
            if (preview) {
                updateImagePreview(valueInput, preview);
            }
            if (error && error.message === "Image selection cancelled.") {
                updateUploadStatus(statusElement, previousValue ? "Saved image ready." : "Upload cancelled.");
                return;
            }
            updateUploadStatus(statusElement, "Upload failed.");
            window.alert(error.message || "The uploaded image could not be processed.");
        } finally {
            fileInput.value = "";
        }
    })();

    pendingCustomImageUploads.add(task);
    task.finally(() => pendingCustomImageUploads.delete(task));
}

function setImgMode(btn, mode) {
    const p = btn.closest(".image-input-row, p");
    p.querySelectorAll(".img-mode-btn").forEach(b => b.classList.remove("active"));
    btn.classList.add("active");
    const fileInput = p.querySelector("input[type='file']");
    const urlInput = p.querySelector("input[type='text']");
    if (mode === "upload") {
        if (fileInput) fileInput.style.display = "";
        if (urlInput) urlInput.style.display = "none";
    } else {
        if (fileInput) fileInput.style.display = "none";
        if (urlInput) urlInput.style.display = "";
    }
    updateStandaloneModeStatus(p, mode);
}

function syncStandaloneImgMode(urlInputId) {
    const urlInput = document.getElementById(urlInputId);
    if (!urlInput) return;
    const scope = urlInput.closest(".image-input-row, p") || urlInput.closest(".image-input-group");
    if (!scope) return;
    const btns = scope.querySelectorAll(".img-mode-btn");
    const fileInput = scope.querySelector("input[type='file']");
    if (urlInput.value.trim()) {
        btns.forEach(b => b.classList.remove("active"));
        if (btns[1]) btns[1].classList.add("active");
        if (fileInput) fileInput.style.display = "none";
        urlInput.style.display = "";
        updateStandaloneModeStatus(scope, "url");
    } else {
        btns.forEach(b => b.classList.remove("active"));
        if (btns[0]) btns[0].classList.add("active");
        if (fileInput) fileInput.style.display = "";
        urlInput.style.display = "none";
        updateStandaloneModeStatus(scope, "upload");
    }
}

function bindStandaloneImageUploader(fileInputId, hiddenInputId, previewCallback, options = {}) {
    const fileInput = document.getElementById(fileInputId);
    const hiddenInput = document.getElementById(hiddenInputId);
    if (!fileInput || !hiddenInput || fileInput.dataset.uploadBound === "true") return;

    fileInput.dataset.uploadBound = "true";
    const statusElement = options.statusElementId ? document.getElementById(options.statusElementId) : null;

    fileInput.addEventListener("change", function () {
        handleUploadedImage(fileInput, hiddenInput, null, {
            ...options,
            statusElement,
            afterUpdate: previewCallback
        });
    });

    if (hiddenInput.value && typeof previewCallback === "function") {
        previewCallback(hiddenInput.value);
    }

    hiddenInput.addEventListener("input", function () {
        if (typeof previewCallback === "function") {
            previewCallback(hiddenInput.value.trim());
        }
        if (statusElement) {
            updateUploadStatus(
                statusElement,
                hiddenInput.value.trim() ? "Saved image ready." : getStandaloneModeHint("url")
            );
        }
    });
}

function addImageInput() {
    const container = document.getElementById("imageInputsContainer");
    container.appendChild(createImageInputGroup());
    updateRemoveButtonVisibility();
}

function createImageInputGroup(imageUrl = "") {
    const group = document.createElement("div");
    group.className = "image-input-group";

    const inputRow = document.createElement("div");
    inputRow.className = "image-input-row";

    const controls = document.createElement("div");
    controls.className = "image-sort-controls";

    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.className = "queenImageFile";
    fileInput.accept = "image/*";

    const input = document.createElement("input");
    input.type = "text";
    input.className = "queenImageUrl";
    input.placeholder = "Enter image URL...";
    input.value = imageUrl;

    const toggleUpload = document.createElement("button");
    toggleUpload.type = "button";
    toggleUpload.className = "img-mode-btn active";
    toggleUpload.textContent = "Upload";

    const toggleUrl = document.createElement("button");
    toggleUrl.type = "button";
    toggleUrl.className = "img-mode-btn";
    toggleUrl.textContent = "URL";

    const toggleWrap = document.createElement("span");
    toggleWrap.className = "img-mode-toggle";
    toggleWrap.appendChild(toggleUpload);
    toggleWrap.appendChild(toggleUrl);

    if (imageUrl) {
        toggleUpload.classList.remove("active");
        toggleUrl.classList.add("active");
        fileInput.style.display = "none";
        input.style.display = "";
    } else {
        input.style.display = "none";
    }

    toggleUpload.onclick = function () {
        toggleUpload.classList.add("active");
        toggleUrl.classList.remove("active");
        fileInput.style.display = "";
        input.style.display = "none";
        updateUploadStatus(status, getStandaloneModeHint("upload"));
    };

    toggleUrl.onclick = function () {
        toggleUrl.classList.add("active");
        toggleUpload.classList.remove("active");
        fileInput.style.display = "none";
        input.style.display = "";
        updateUploadStatus(status, input.value.trim() ? "Saved image ready." : getStandaloneModeHint("url"));
    };

    input.addEventListener("input", function () {
        updateImagePreview(input, preview);
        updateUploadStatus(status, input.value.trim() ? "Saved image ready." : getStandaloneModeHint("url"));
    });

    const moveUpButton = document.createElement("button");
    moveUpButton.type = "button";
    moveUpButton.className = "image-move-up-btn";
    moveUpButton.textContent = "Up";
    moveUpButton.setAttribute("aria-label", "Move image up");
    moveUpButton.onclick = function () {
        moveImageInput(this, -1);
    };

    const moveDownButton = document.createElement("button");
    moveDownButton.type = "button";
    moveDownButton.className = "image-move-down-btn";
    moveDownButton.textContent = "Down";
    moveDownButton.setAttribute("aria-label", "Move image down");
    moveDownButton.onclick = function () {
        moveImageInput(this, 1);
    };

    const mainButton = document.createElement("button");
    mainButton.type = "button";
    mainButton.className = "image-main-btn";
    mainButton.textContent = "Set Main";
    mainButton.setAttribute("aria-label", "Set as main image");
    mainButton.onclick = function () {
        setMainImageInput(this);
    };

    const removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.className = "image-remove-btn";
    removeButton.textContent = "Remove";
    removeButton.onclick = function () {
        removeImageInput(this);
    };

    const status = document.createElement("small");
    status.className = "image-upload-status";
    status.textContent = imageUrl ? "Saved image ready." : getStandaloneModeHint("upload");

    const preview = document.createElement("img");
    preview.className = "imagePreview";
    preview.alt = "Preview";
    preview.style.display = "none";

    fileInput.addEventListener("change", function() {
        handleUploadedImage(fileInput, input, preview, {
            maxWidth: 900,
            maxHeight: 900,
            targetBytes: CUSTOM_IMAGE_TARGET_BYTES,
            statusElement: status,
            allowCrop: true,
            cropAspectRatio: 1,
            cropMessage: "Pick the part of the queen image you want to use.",
            label: "queen image",
            folder: "custom-uploads"
        });
    });

    controls.appendChild(moveUpButton);
    controls.appendChild(moveDownButton);
    controls.appendChild(mainButton);
    controls.appendChild(removeButton);
    inputRow.appendChild(toggleWrap);
    inputRow.appendChild(fileInput);
    inputRow.appendChild(input);
    inputRow.appendChild(controls);
    group.appendChild(inputRow);
    group.appendChild(status);
    group.appendChild(preview);

    updateImagePreview(input, preview);

    return group;
}

function resetImageInputs(imageUrls = [""]) {
    const container = document.getElementById("imageInputsContainer");
    if (!container) return;

    container.innerHTML = "";
    imageUrls.forEach(imageUrl => {
        container.appendChild(createImageInputGroup(imageUrl));
    });

    if (container.children.length === 0) {
        container.appendChild(createImageInputGroup());
    }

    updateRemoveButtonVisibility();
}

function moveImageInput(button, direction) {
    const group = button.closest(".image-input-group");
    const container = document.getElementById("imageInputsContainer");
    if (!group || !container) return;

    if (direction < 0) {
        const previous = group.previousElementSibling;
        if (previous) {
            container.insertBefore(group, previous);
        }
    } else {
        const next = group.nextElementSibling;
        if (next) {
            container.insertBefore(next, group);
        }
    }

    updateRemoveButtonVisibility();
}

function setMainImageInput(button) {
    const group = button.closest(".image-input-group");
    const container = document.getElementById("imageInputsContainer");
    if (!group || !container || container.firstElementChild === group) {
        updateRemoveButtonVisibility();
        return;
    }
    container.insertBefore(group, container.firstElementChild);
    updateRemoveButtonVisibility();
}

function removeImageInput(button) {
    const group = button.closest(".image-input-group");
    if (group) {
        group.remove();
    }
    const container = document.getElementById("imageInputsContainer");
    if (container && container.children.length === 0) {
        container.appendChild(createImageInputGroup());
    }
    updateRemoveButtonVisibility();
}

function updateImagePreview(input, preview) {
    const url = resolveTrackedCustomImage(input.value.trim());
    if (url && url !== "image/queens/noimage.jpg") {
        preview.src = url;
        preview.style.display = "block";
        preview.onerror = function() {
            preview.style.display = "none";
        };
    } else {
        preview.style.display = "none";
        preview.src = "";
    }
}
function updateRemoveButtonVisibility() {
    const container = document.getElementById("imageInputsContainer");
    if (!container) return;
    const groups = container.querySelectorAll(".image-input-group");
    groups.forEach((group, index) => {
        const removeBtn = group.querySelector(".image-remove-btn");
        const moveUpBtn = group.querySelector(".image-move-up-btn");
        const moveDownBtn = group.querySelector(".image-move-down-btn");
        const mainBtn = group.querySelector(".image-main-btn");
        if (removeBtn) {
            removeBtn.style.display = groups.length > 1 ? "inline" : "none";
        }
        if (moveUpBtn) {
            moveUpBtn.disabled = index === 0;
        }
        if (moveDownBtn) {
            moveDownBtn.disabled = index === groups.length - 1;
        }
        if (mainBtn) {
            mainBtn.disabled = index === 0;
            mainBtn.textContent = index === 0 ? "Main Image" : "Set Main";
        }
    });
}
function getImageInputs() {
    const container = document.getElementById("imageInputsContainer");
    const inputs = container.querySelectorAll(".queenImageUrl");
    const images = [];
    inputs.forEach(input => {
        const url = input.value.trim();
        if (url) {
            images.push(trackCustomImageValue(url));
        }
    });
    return images.length > 0 ? images : ["noimage"];
}
