function randomizeStats(useTotal = false) {
    let stats = Array.from(document.getElementsByClassName("stats"));
    if (stats.length === 0) return;

    if (!useTotal) {
        for (let i = 0; i < stats.length; i++) {
            stats[i].value = randomNumber(0, 15).toString();
        }
        return;
    }

    const maxTotal = stats.length * 15;
    const prompted = window.prompt(`Total stats to distribute (0-${maxTotal}):`, "49");
    if (prompted === null) return;

    const total = Number(prompted);
    if (!Number.isFinite(total) || total < 0 || total > maxTotal) {
        window.alert(`Please enter a number between 0 and ${maxTotal}.`);
        return;
    }

    let remaining = Math.round(total);
    const values = [];
    for (let i = 0; i < stats.length; i++) {
        const remainingSlots = stats.length - i - 1;
        const minForThis = Math.max(0, remaining - (remainingSlots * 15));
        const maxForThis = Math.min(15, remaining);
        const value = (i === stats.length - 1)
            ? remaining
            : randomNumber(minForThis, maxForThis);
        values.push(value);
        remaining -= value;
    }

    for (let i = 0; i < stats.length; i++) {
        stats[i].value = String(values[i]);
    }
}
