let premiereCounter = 0;
let firstCast = [];
let secondCast = [];
let thirdCast = [];
let premiereGroupColors = ["#000000", "#ffffff", "#000000"];
let premiereGroupTextColors = [null, null, null];

function setPremiereGroupTextColor(group, color) {
    if (![1, 2, 3].includes(group) || !/^#[0-9a-f]{6}$/i.test(color)) {
        console.warn("Invalid premiere group text color.", { group, color });
        return;
    }
    premiereGroupTextColors[group - 1] = color;
    document.querySelectorAll(`[data-premiere-text-color="${group}"]`).forEach(input => { input.value = color; });
    document.querySelectorAll(`[data-premiere-name-group="${group}"]`).forEach(cell => stylePremiereGroupCell(cell, group));
}

function setPremiereGroupColor(group, color) {
    if (![1, 2, 3].includes(group) || !/^#[0-9a-f]{6}$/i.test(color)) {
        console.warn("Invalid premiere group color.", { group, color });
        return;
    }
    premiereGroupColors[group - 1] = color;
    document.querySelectorAll(`[data-premiere-color="${group}"]`).forEach(input => { input.value = color; });
    document.querySelectorAll(`[data-premiere-name-group="${group}"]`).forEach(cell => stylePremiereGroupCell(cell, group));
}

function stylePremiereGroupCell(cell, group) {
    const color = premiereGroupColors[group - 1];
    const rgb = color.slice(1).match(/../g).map(value => parseInt(value, 16));
    cell.style.backgroundColor = color;
    cell.style.color = premiereGroupTextColors[group - 1] ||
        (rgb[0] * 0.299 + rgb[1] * 0.587 + rgb[2] * 0.114 > 150 ? "#000000" : "#fff");
    cell.style.backgroundImage = "none";
    cell.style.fontWeight = "bold";
}

function assignPremiereColorGroups() {
    [firstCast, secondCast, thirdCast].forEach((cast, index) => {
        cast.forEach(queen => { queen.premiereColorGroup = index + 1; });
    });
}

function createPremiereGroupBadge(queen) {
    const group = queen?.premiereColorGroup;
    if (![1, 2, 3].includes(group)) return null;
    const badge = document.createElement("span");
    badge.className = "premiere-group-badge";
    badge.textContent = `(Group ${group})`;
    badge.style.cssText = "display:inline-block;margin-top:6px;font-size:0.85em;font-weight:normal;white-space:nowrap;";
    return badge;
}

function decoratePremiereGroupCell(cell, queen) {
    const badge = createPremiereGroupBadge(queen);
    if (!badge) return;
    cell.dataset.premiereNameGroup = String(queen.premiereColorGroup);
    stylePremiereGroupCell(cell, queen.premiereColorGroup);
    cell.appendChild(document.createElement("br"));
    cell.appendChild(badge);
}


function applyPremiereGroupPreset(preset) {
    const presets = {
        none: [
            ["#000000", "#ffffff"],
            ["#ffffff", "#000000"]
        ],
        season6: [
            ["#ffffff", "#000000"],
            ["#000000", "#f169af"]
        ],
        season12: [
            ["#c00300", "#ffffff"],
            ["#0b0281", "#ffffff"]
        ],
        season13: [
            ["#c4f2ff", "#9c73b0"],
            ["#fffec8", "#9c73b0"]
        ],
        season14: [
            ["#31d3f5", "#4b2a74"],
            ["#ffee3d", "#4b2a74"]
        ],
        season15: [
            ["#db4fa2", "#ffffff"],
            ["#000000", "#ffffff"]
        ],
        season16: [
            ["#4e8185", "#fafa31"],
            ["#fafa31", "#012a37"]
        ],
        season17: [
            ["#07568b", "#e2f0f7"],
            ["#e2f0f7", "#07568b"]
        ],
        "global-all-stars": [
            ["#1d2f8c", "#deb149"],
            ["#deb149", "#1d2f8c"]
        ],
        "philippines-s2": [
            ["#fcbf86", "#ffffff"],
            ["#ff5452", "#ffffff"]
        ],
        "brasil-s1": [
            ["#1db4ab", "#ffffff"],
            ["#f7ea2a", "#053997"]
        ]
    };

    const colors = presets[preset];

    if (!colors) {
        return;
    }

    for (let group = 1; group <= 2; group++) {
        const [background, text] = colors[group - 1];
        const backgroundInput = document.getElementById(`premiereColor${group}`);
        const textInput = document.getElementById(`premiereTextColor${group}`);

        if (backgroundInput) {
            backgroundInput.value = background;
            setPremiereGroupColor(group, background);
        }

        if (textInput) {
            textInput.value = text;
            setPremiereGroupTextColor(group, text);
        }
    }
}


let triplePremiereFlag = false;
let ladderClimbGroupScores = { first: 0, second: 0, third: 0 };
let chaosLotteryAssignments = {};

function isSplitPremiereComplete() {
    const isSplitPremiere = s14Premiere || s12Premiere || s6Premiere || ph2Premiere || newImmTwst || triplePremiereFlag || ladderClimbPremiere;
    if (!isSplitPremiere) return false;
    const premiereGroupCount = (triplePremiereFlag || ladderClimbPremiere) ? 3 : 2;
    return premiereCounter >= premiereGroupCount + 1;
}

function updateSplitPremiereJointRanks() {
    const isSplitPremiere = s14Premiere || s12Premiere || s6Premiere || ph2Premiere || newImmTwst || triplePremiereFlag || ladderClimbPremiere;
    if (!isSplitPremiere || isSplitPremiereComplete()) return;

    const premiereEliminated = eliminatedCast.filter((queen) => {
        const lastPlacement = queen?.trackRecord?.[queen.trackRecord.length - 1] || "";
        return /ELIM/.test(lastPlacement);
    });
    if (premiereEliminated.length === 0) return;

    const premiereGroup = premiereCounter === 1
        ? firstCast
        : premiereCounter === 2
            ? secondCast
            : premiereCounter === 3
                ? thirdCast
                : [];
    const groupEliminated = premiereEliminated.filter((queen) =>
        premiereGroup.includes(queen) || queen.premiereGroupIndex === premiereCounter);
    if (groupEliminated.length === 0) return;

    const jointEliminated = eliminatedCast.filter(queen =>
        queen.rankP === "PREMIERE_JOINT" || groupEliminated.includes(queen));
    const jointRank = totalCastSize - jointEliminated.length + 1;
    jointEliminated.forEach((queen) => {
        queen.rankP = "PREMIERE_JOINT";
        queen.premiereJointRank = jointRank;
        queen.premiereJointRankEnd = totalCastSize;
    });
}

function getEpisodeMergeInfo() {
    const isDoublePremiere = s14Premiere || s12Premiere || s6Premiere || ph2Premiere || newImmTwst;
    
    if (episodeChallenges.length < 2) return { shouldMerge: false, mergeEp1: -1, mergeEp2: -1 };
    if (isDoublePremiere) {
        // BR1 and S15 show both premiere episodes in one "Ep. 1 & 2" column
        return { shouldMerge: true, mergeEp1: 0, mergeEp2: 1, singleColumn: !!(br1Premiere || s15Premiere) };
    } else if (porkchopPremiere) {
        return { shouldMerge: true, mergeEp1: 1, mergeEp2: 2 };
    } else if (triplePremiereFlag && episodeChallenges.length >= 3) {
        return { shouldMerge: true, mergeEp1: 0, mergeEp2: 2 };
    } else if (midSeasonTalentEp1 >= 0 && midSeasonTalentEp2 >= 0) {
        return { shouldMerge: true, mergeEp1: midSeasonTalentEp1, mergeEp2: midSeasonTalentEp2 };
    }
    
    return { shouldMerge: false, mergeEp1: -1, mergeEp2: -1 };
}

function mergeTrackRecordEntries(entry1, entry2) {
    if (!entry1 && !entry2) return "";
    if (!entry1) return entry2;
    if (!entry2) return entry1;
    
    if (entry1 === entry2) return entry1;
    
    return entry1 + "<br>" + entry2;
}

// Folds the two placement cells of the BR1 / S15 premiere into one cell (the one that actually holds a result).
function mergeSingleColumnPremiereCells(trackRecords, firstIndex) {
    trackRecords.querySelectorAll("tr").forEach(row => {
        const cells = Array.from(row.children).filter(cell => cell.tagName === "TD" && cell.classList.contains("placement"));
        const first = cells[firstIndex];
        const second = cells[firstIndex + 1];
        if (!first || !second) return;
        const hasText = cell => cell.textContent.trim() !== "";
        if (hasText(second) && !hasText(first)) {
            first.innerHTML = second.innerHTML;
            first.setAttribute("style", second.getAttribute("style") || "");
        } else if (hasText(second) && hasText(first)) {
            first.innerHTML = mergeTrackRecordEntries(first.innerHTML, second.innerHTML);
        }
        second.remove();
    });
}

function getMergedEpisodeLabel(startIndex, endIndex) {
    const episodeNumbers = [];
    for (let i = startIndex; i <= endIndex; i++) {
        episodeNumbers.push(String(i + 1));
    }
    if (episodeNumbers.length <= 2) {
        return "Ep. " + episodeNumbers.join(" & ");
    }
    return "Eps. " + episodeNumbers.slice(0, -1).join(", ") + " & " + episodeNumbers[episodeNumbers.length - 1];
}

function initializeChaosLottery() {
    if (!chaosLotteryPremiere) return;
    chaosLotteryAssignments = {};
    const effects = ["advantage", "disadvantage", "neutral", "neutral"]; // neutral more common
    for (let i = 0; i < currentCast.length; i++) {
        const queen = currentCast[i];
        const effect = effects[randomNumber(0, effects.length - 1)];
        chaosLotteryAssignments[queen.name] = effect;
    }
}

function applyChaosLotteryModifier(queen) {
    if (!chaosLotteryPremiere || !chaosLotteryAssignments[queen.name]) return;
    const effect = chaosLotteryAssignments[queen.name];
    const modifier = effect === "advantage" ? -2 : effect === "disadvantage" ? 2 : 0;
    queen.performanceScore += modifier;
}

function calculateLadderClimbGroupScore(group) {
    if (group.length === 0) return 0;
    const totalScore = group.reduce((sum, queen) => sum + queen.performanceScore, 0);
    return totalScore / group.length;
}

function updateLadderClimbScores() {
    if (!ladderClimbPremiere) return;
    if (premiereCounter === 1) {
        ladderClimbGroupScores.first = calculateLadderClimbGroupScore(firstCast);
    } else if (premiereCounter === 2) {
        ladderClimbGroupScores.second = calculateLadderClimbGroupScore(secondCast);
    } else if (premiereCounter === 3) {
        ladderClimbGroupScores.third = calculateLadderClimbGroupScore(thirdCast);
    }
}

function getLadderClimbLowestGroup() {
    if (!ladderClimbPremiere || premiereCounter < 4) return null;
    const scores = { first: ladderClimbGroupScores.first, second: ladderClimbGroupScores.second, third: ladderClimbGroupScores.third };
    let lowestGroup = "first";
    let lowestScore = scores.first;
    if (scores.second > lowestScore) {
        lowestScore = scores.second;
        lowestGroup = "second";
    }
    if (scores.third > lowestScore) {
        lowestScore = scores.third;
        lowestGroup = "third";
    }
    return lowestGroup;
}

function doublePremiere() {
    if (premiereCounter === 0) assignPremiereColorGroups();
    woodenbeaverUsed = true;
    transducerUsed = true;
    if (episodeCount == 0 && !porkchopPremiere) {
        currentCast.forEach((queen) => {
            for (let i = 0; i < currentCast.length; i++) {
                if (queen.name != currentCast[i].name) {
                    queen.sisters.push({ queen: currentCast[i], relation: 0 });
                }
            }
        });
    }
    if (premiereCounter == 0) {
        if (porkchopPremiere) {
            currentCast = [...firstCast, ...secondCast];
            newEpisode();
            currentCast = [...firstCast];
            for (let i = 0; i < secondCast.length; i++) {
                if (globalPremiere || squirrelPremiere) {
                    secondCast[i].addToTrackRecord("RUN ");
                } else {
                    secondCast[i].addToTrackRecord("");
                }
            }
        } else {
            newEpisode();
        }
        premiereCounter++;
        slayersCheck = true;
        s14LaLaPaRUZaCheck = true;
    }
    else if (premiereCounter == 1) {
        currentCast = [...firstCast, ...secondCast];
        chocolateBarTwistCheck = false;
        newEpisode();
        currentCast = [...secondCast];
        for (let i = 0; i < firstCast.length; i++) {
            if (globalPremiere || squirrelPremiere) {
                firstCast[i].addToTrackRecord("RUN ");
            } else {
                firstCast[i].addToTrackRecord("");
            }
        }
        premiereCounter++;
        slayersCheck = true;
        s14LaLaPaRUZaCheck = true;
        if (s14Premiere) {
            chocolateBarTwistCheck = true;
        }
    }
    else if (premiereCounter == 2 && s14Premiere) {
        currentCast = [...firstCast, ...secondCast];
        premiereCounter++;
        chocolateBarTwistCheck = false;
        slayersCheck = false;
        s14LaLaPaRUZaCheck = false;
        newEpisode();
    }
    else if (premiereCounter == 2) {
        currentCast = [...firstCast, ...secondCast];
        premiereCounter++;
        slayersCheck = false;
        s14LaLaPaRUZaCheck = false;
        chocolateBarTwistCheck = false;
        newEpisode();
    }
}

function triplePremiere() {
    woodenbeaverUsed = true;
    transducerUsed = true;

    if (premiereCounter === 0) {
        assignPremiereColorGroups();
        currentCast = [...firstCast];
        secondCast.forEach((queen) => queen.addToTrackRecord(""));
        thirdCast.forEach((queen) => queen.addToTrackRecord(""));
        if (slayPremiere) slayPremiereCheck = false;
        premiereCounter = 1;
        newEpisode();
        return;
    }

    if (premiereCounter === 1) {
        currentCast = [...secondCast];
        firstCast.forEach((queen) => queen.addToTrackRecord(""));
        thirdCast.forEach((queen) => queen.addToTrackRecord(""));
        if (slayPremiere) slayPremiereCheck = false;
        premiereCounter = 2;
        newEpisode();
        return;
    }

    if (premiereCounter === 2) {
        currentCast = [...thirdCast];
        firstCast.forEach((queen) => queen.addToTrackRecord(""));
        secondCast.forEach((queen) => queen.addToTrackRecord(""));
        if (slayPremiere) slayPremiereCheck = false;
        premiereCounter = 3;
        newEpisode();
        return;
    }

    currentCast = [...firstCast, ...secondCast, ...thirdCast];
    premiereCounter = 4;
    newEpisode();
}

// Triple premiere: same screen as the double premiere (portrait + dropdown per slot), shown twice:
// first you pick the contestants entering the first premiere, then the second. Whoever is left is the third.
function renderPremiereSlotPicker(pool, slots) {
    const main = document.querySelector("div#MainBlock");
    const centering = document.createElement("center");
    const br = document.createElement("br");
    const tempArr = [];
    for (let i = 0; i < slots; i++) {
        const select = document.createElement("select");
        select.setAttribute("class", "queenList");
        select.setAttribute("id", i);
        select.setAttribute("onchange", "setImage()");
        const img = document.createElement("img");
        img.setAttribute("class", "images");
        img.setAttribute("id", "image" + i);
        img.setAttribute("style", "width: 105px; height: 105px;");
        const p = document.createElement("p");
        p.appendChild(img);
        for (let k = 0; k < pool.length; k++) {
            const option = document.createElement("option");
            option.innerHTML = pool[k].name;
            option.value = pool[k].getCurrentImage();
            select.add(option);
        }
        let numb = randomNumber(0, pool.length - 1);
        while (tempArr.includes(numb)) {
            numb = randomNumber(0, pool.length - 1);
        }
        select.selectedIndex = numb;
        tempArr.push(numb);
        centering.appendChild(p);
        centering.appendChild(select);
        centering.appendChild(br);
        centering.appendChild(br);
    }
    main.appendChild(centering);
    main.appendChild(br);
    setImage();
}

// Reads the slot selects; returns the chosen queens or null when the same contestant was picked twice.
function readPremiereSlotPicks(pool, slots) {
    const picks = [];
    for (let i = 0; i < slots; i++) {
        const select = document.getElementById(i.toString());
        const name = select.options[select.selectedIndex].text;
        const queen = pool.find((q) => q.name == name);
        if (!queen || picks.includes(queen)) {
            window.alert("Choose different contestants.");
            return null;
        }
        picks.push(queen);
    }
    return picks;
}

let triplePremiereDraft = null;

function triplePremiereChoose() {
    const total = currentCast.length;
    const first = Math.ceil(total / 3);
    const second = Math.ceil((total - first) / 2);
    triplePremiereDraft = { pool: [...currentCast], sizes: [first, second, total - first - second] };
    triplePremiereChooseGroup(1, triplePremiereDraft.pool, []);
}

function triplePremiereChooseGroup(step, pool, groupsSoFar) {
    const slots = triplePremiereDraft.sizes[step - 1];
    const screen = new Scene();
    screen.clean();
    screen.createHeader("Triple Premiere");
    screen.createParagraph(`Choose the contestants entering in the ${step === 1 ? "first" : "second"} premiere. Customize track-record group colors in the Twist Menu under Groups.`);
    screen.createHorizontalLine();
    renderPremiereSlotPicker(pool, slots);
    screen.createButton("Proceed", "", "triplePremiereStart");
    document.getElementById("triplePremiereStart").addEventListener("click", () => {
        const picks = readPremiereSlotPicks(pool, slots);
        if (!picks) return;
        const remaining = pool.filter((q) => !picks.includes(q));
        if (step === 1) {
            triplePremiereChooseGroup(2, remaining, [picks]);
            return;
        }
        firstCast = groupsSoFar[0];
        secondCast = picks;
        thirdCast = remaining;
        assignPremiereColorGroups();
        currentCast = [...firstCast];
        premiereCounter = 0;
        triplePremiere();
    });
}

function progressMidSeasonTalent() {
    const screen = new Scene();
    screen.clean();
    if (midSeasonTalentEpisode == 1) {
        // Episode 1 just finished; restore full cast with both groups
        currentCast = [...talentGroup1, ...talentGroup2];
        midSeasonTalentEpisode = 2;
        newEpisode();
        midSeasonTalentEp2 = episodeCount - 1;
    } else if (midSeasonTalentEpisode == 2) {
        // Episode 2 just finished; restore full cast, add RUN to group 1
        currentCast = [...talentGroup1, ...talentGroup2];
        for (let i = 0; i < talentGroup1.length; i++) {
            talentGroup1[i].addToTrackRecord("RUN ");
        }
        midSeasonTalentEpisode = 3;
        newEpisode();
    }
}

