async function getRAQRanking(voter, cast) {
    let ranks = [...cast];
    const selfIndex = ranks.indexOf(voter);
    if (selfIndex !== -1) {
        ranks.splice(selfIndex, 1);
    }
    if (!isClaimedQueen(voter)) {
        if (randomNumber(0, 100) <= 50) {
            return ranks.sort((a, b) => (a.performanceScore - b.performanceScore));
        }
        shuffle(ranks);
        if (ph4Premiere && episodeCount === 1) {
            const bestPerformer = cast.reduce((best, queen) => queen.performanceScore < best.performanceScore ? queen : best);
            const position = ranks.indexOf(bestPerformer);
            if (position > 0) {
                ranks.splice(position, 1);
                ranks.splice(Math.max(0, position - 2), 0, bestPerformer);
            }
        }
        return ranks;
    }

    const ordered = [];
    const pool = [...ranks];
    while (pool.length > 0) {
        const picked = await chooseClaimedQueenTarget(
            voter,
            pool,
            `rank #${ordered.length + 1} in Rate-A-Queen`,
            () => bestSister(voter, pool) || pool[0]
        );
        ordered.push(picked);
        pool.splice(pool.indexOf(picked), 1);
    }
    return ordered;
}

function recordRateAQResults(contestants, voteReceipts, label = "Rate-A-Queen") {
    if (!Array.isArray(contestants) || contestants.length === 0) {
        return;
    }

    const ranked = [...contestants].sort((a, b) => Number(a.votes || 0) - Number(b.votes || 0));
    const rankings = ranked.map((queen, index) => {
        const avgRank = Number(queen.votes || 0);
        return {
            rank: index + 1,
            name: queen.name,
            avgRank: Number.isFinite(avgRank) ? Number(avgRank.toFixed(2)) : null,
        };
    });

    const votes = Array.isArray(voteReceipts)
        ? voteReceipts.map((entry) => {
            const ranking = Array.isArray(entry?.ranking) ? entry.ranking : [];
            return {
                voter: entry?.voter?.name || "Unknown",
                recipient: ranking[0]?.name || "-",
                ranking: ranking.map((q) => q.name),
            };
        })
        : [];

    rateAQ4Chart.push({
        episode: episodeCount,
        label,
        rankings,
        votes,
    });
}

async function rateAQ() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Rate-A-Queen");
    screen.createBold("This week, your fate lies in the hands of your competitors. It will be up to you to rate your fellow contestants.");
    if (ph4Premiere && episodeCount === 1) {
        const bestPerformer = currentCast.reduce((best, queen) => queen.performanceScore < best.performanceScore ? queen : best);
        screen.createImage(bestPerformer.getCurrentImage(), "lightblue");
        screen.createBold(`${bestPerformer.name}, you delivered the strongest performance of the week! Before the queens cast their rankings, you've earned a boost to help you climb the ranks.`);
    }
    document.body.style.backgroundImage = "url('image/rateAQueen.webp')";
    screen.createHorizontalLine();
    screen.createBold("The ranks are in...");

    let judgingCast = [...currentCast];
    if (squirrelPremiere && premiereCounter === 1 && typeof secondCast !== "undefined") {
        judgingCast = [...secondCast];
    } else if (squirrelPremiere && premiereCounter === 2 && typeof firstCast !== "undefined") {
        judgingCast = [...firstCast];
    }
    const claimedSpectatorVoter = claimSpectatorMode
        ? [...eliminatedCast, ...fullCast].find((q) => isClaimedQueen(q))
        : null;
    if (claimedSpectatorVoter && !judgingCast.some((q) => queensMatchByIdentityOrName(q, claimedSpectatorVoter))) {
        judgingCast.unshift(claimedSpectatorVoter);
    }

    const rateAQVoteReceipts = [];

    shuffle(judgingCast);

    for (let i = 0; i < judgingCast.length; i++) {
        let rankedCont = await getRAQRanking(judgingCast[i], currentCast);
        rateAQVoteReceipts.push({
            voter: judgingCast[i],
            ranking: [...rankedCont],
        });
        screen.createImage(judgingCast[i].getCurrentImage());
        screen.createBold(judgingCast[i].name + " ranked:");
        for (let j = 0; j < rankedCont.length; j++) {
            screen.createParagraph((j + 1) + ": " + rankedCont[j].name);
            rankedCont[j].votes = rankedCont[j].votes + (j + 1);
        }
        screen.createHorizontalLine();
    }

    for (let x = 0; x < currentCast.length; x++) {
        currentCast[x].votes = currentCast[x].votes / (judgingCast.length);
    }

    currentCast.sort((a, b) => (a.votes - b.votes));
    recordRateAQResults(currentCast, rateAQVoteReceipts);
    screen.createBold("And that's... The Tea.");

    if (ph4Premiere && episodeCount === 1) {
        topQueens = currentCast.slice(0, 2);
        bottomQueens = currentCast.slice(-2);
        currentCast.forEach(queen => queen.votes = 0);
        screen.createButton("Proceed", "ph4PremiereJudging()");
        return;
    }

    const isSplitPremiereMode = s14Premiere || s12Premiere || s6Premiere || ph2Premiere || newImmTwst || globalPremiere || squirrelPremiere;
    const hasSplitPremiereCastPools = firstCast.length > 0 && secondCast.length > 0;
    const isRateAQPremiere = newImmTwst || squirrelPremiere || uk8Premiere;
    const useRateAQPremiereJudging = (!fullSeasonRateAQ || isRateAQPremiere) && premiereCounter <= 2 && (squirrelPremiere || uk8Premiere || (isSplitPremiereMode && hasSplitPremiereCastPools));

    if (useRateAQPremiereJudging) {
        if (uk8Premiere) {
            const topHalf = currentCast.slice(0, Math.ceil(currentCast.length / 2));
            topQueens = topHalf;
        } else {
            currentCast.sort((a, b) => a.performanceScore - b.performanceScore);
            topQueens.push(currentCast[0], currentCast[1]);
        }
        bottomQueens = [];
        if (squirrelPremiere) {
            bottomQueens.push(currentCast[currentCast.length - 1]);
        }

        const safeCast = currentCast.filter((queen) => !topQueens.includes(queen) && !bottomQueens.includes(queen));
        for (const queen of currentCast) {
            queen.votes = 0;
            if (!bottomQueens.includes(queen)) {
                if (uk8Premiere && topQueens.includes(queen)) {
                    queen.addToTrackRecord("HIGH");
                    queen.ppe += 4;
                } else if (!uk8Premiere && safeCast.includes(queen)) {
                    queen.addToTrackRecord("SAFE");
                    queen.ppe += 3;
                } else if (!topQueens.includes(queen)) {
                    queen.ppe += 3;
                } else {
                    queen.ppe += 3;
                }
            } else {
                queen.ppe += 1;
            }
        }

        const nextFunction = squirrelPremiere
            ? "s17PremiereJudging()"
            : uk8Premiere
                ? "judgingScreen()"
                : "doublePremiereJudging()";
        if (uk8Premiere) {
            uk8PremiereCheck = true;
        }
        screen.createButton("Proceed", nextFunction);

    } else {
        if (fullSeasonRateAQ) {
            currentCast.forEach((q) => {
                const avgRank = Number(q.votes);
                q.rateAQScore = Number.isFinite(avgRank) ? avgRank : 0;
                q.votes = 0;
            });
            topQueens = topQueens.filter((q) => currentCast.includes(q));
            bottomQueens = [];
        } else {
            currentCast.forEach(q => q.votes = 0);
        }
        lastRateAQEpisode = episodeCount;
        raqep3cast = [...currentCast];
        if (fullSeasonRateAQ) {
            screen.createButton("Proceed", "fullSeasonRateAQBottom2Phase()");
        } else {
            screen.createButton("Proceed", "judging()");
        }
    }
}

function upNdownRAQ(currCont, cast) {
    let ranks = [...cast];
    ranks.splice(ranks.indexOf(currCont), 1);
    if (randomNumber(0, 100) <= 50) {
        return ranks.sort((a, b) => (a.performanceScore - b.performanceScore));
    } else {
        return shuffle(ranks);
    }
}
