function makePremiereTeams(screen) {
    const cast = [...currentCast];
    shuffle(cast);
    const teamCount = randomNumber(2, Math.min(4, Math.floor(cast.length / 2)));
    premiereTeams = Array.from({ length: teamCount }, () => []);
    cast.forEach((queen, index) => premiereTeams[index % teamCount].push(queen));
    screen.createBold(`For your first challenge, you'll be forming ${teamCount} girl groups. Let's see who can steal the show!`);
    premiereTeams.forEach((queens, index) => {
        screen.createBigText(`Team ${index + 1}`);
        queens.forEach(queen => screen.createImage(queen.getCurrentImage(), "cyan"));
        screen.createParagraph(queens.map(queen => queen.name).join(", "));
    });
}

