const originalCurrentCast = currentCast;
currentCast = new Proxy(originalCurrentCast, {
    set(target, property, value) {
        target[property] = value;
        populatePushQueenTargetDropdown();
        return true;
    },
    deleteProperty(target, property) {
        delete target[property];
        populatePushQueenTargetDropdown();
        return true;
    },
    get(target, property) {
        if (property === 'push') {
            return function(...args) {
                const result = Array.prototype.push.apply(target, args);
                populatePushQueenTargetDropdown();
                return result;
            };
        }
        if (property === 'splice') {
            return function(...args) {
                const result = Array.prototype.splice.apply(target, args);
                populatePushQueenTargetDropdown();
                return result;
            };
        }
        if (property === 'pop') {
            return function(...args) {
                const result = Array.prototype.pop.apply(target, args);
                populatePushQueenTargetDropdown();
                return result;
            };
        }
        if (property === 'shift') {
            return function(...args) {
                const result = Array.prototype.shift.apply(target, args);
                populatePushQueenTargetDropdown();
                return result;
            };
        }
        if (property === 'unshift') {
            return function(...args) {
                const result = Array.prototype.unshift.apply(target, args);
                populatePushQueenTargetDropdown();
                return result;
            };
        }
        return target[property];
    }
});
