function top7() {
    let screen = new Scene();
    screen.clean();
    if (dragula_format || titans_format) {
    screen.createHeader("The Final Floorshow!");
    } else {
    screen.createHeader("The Grand Finale!");    
    }
    if (fameGames) {
        screen.createBold("It's time to find out who the fans have voted to be crowned Queen of the Fame Games!!");
        fgWnn();
    }
    if (dragula_format || titans_format) {
    screen.createParagraph("The Top 7 monsters will showcase looks representing the three principles of Dragula: Filth, Glamour and Horror!");
    } else {
    screen.createBold("The Top 7 finalists will star in their own individual show-stopping performances!");
    }
    for (let i = 0; i < currentCast.length; i++) {
        currentCast[i].getASLipsync();
    }
    for (let q of eliminatedCast) {
        q.votes = 0;
        if (finaleGuests) {
            q.addToTrackRecord("");
        } else {
            q.addToTrackRecord("GUEST");
        }
    }
    screen.createHorizontalLine();
    let slay = currentCast.filter(function (queen) { return queen.lipsyncScore > 11; });
    let great = currentCast.filter(function (queen) { return queen.lipsyncScore >= 8 && queen.lipsyncScore < 12; });
    let good = currentCast.filter(function (queen) { return queen.lipsyncScore >= 4 && queen.lipsyncScore < 8; });
    let bad = currentCast.filter(function (queen) { return queen.lipsyncScore >= 2 && queen.lipsyncScore < 4; });
    let flop = currentCast.filter(function (queen) { return queen.lipsyncScore >= -10 && queen.lipsyncScore < 2; });
    createLipsyncDesc(slay, great, good, bad, flop);
    for (let i = 0; i < currentCast.length; i++) {
        currentCast[i].lipsyncScore += ((currentCast[i].favoritism - currentCast[i].unfavoritism) / 3);
    }
    currentCast.sort((a, b) => (b.lipsyncScore - a.lipsyncScore));
    episodeChallenges.push("Finale");
    screen.createButton("Proceed", "finaleTop7Judging()");
}

function finaleTop7Judging() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("The final minutes...");
    screen.createHorizontalLine();
    screen.createBigText("The ones moving on to the final lipsync are...");
    screen.createImage(currentCast[0].getCurrentImage(), "silver");
    screen.createImage(currentCast[1].getCurrentImage(), "silver");
    screen.createBold(currentCast[0].name + " and " + currentCast[1].name + ", condragulations, go prepare for your final lipsync.");
    screen.createImage(currentCast[2].getCurrentImage(), "sienna");
    screen.createImage(currentCast[3].getCurrentImage(), "sienna");
    screen.createImage(currentCast[4].getCurrentImage(), "sienna");
    screen.createImage(currentCast[5].getCurrentImage(), "sienna");
    screen.createImage(currentCast[6].getCurrentImage(), "sienna");
    screen.createBold(currentCast[2].name + ", " + currentCast[3].name + ", " + currentCast[4].name + ", " + currentCast[5].name + " and " + currentCast[6].name + ", I'm sorry my dears but it's not your time. I must ask you to sashay away...");
    if (team) {
        for (let i = 2; i <= currentCast.length - 1; i++) {
            currentCast[i].QueenA.addToTrackRecord("ELIMINATED");
            currentCast[i].QueenB.addToTrackRecord("ELIMINATED");
            eliminatedCast.unshift(currentCast[i].QueenA);
            eliminatedCast.unshift(currentCast[i].QueenB);
        }
        firstLS.push(currentCast[0].QueenA);
        firstLS.push(currentCast[0].QueenB);
        secondLS.push(currentCast[1].QueenA);
        secondLS.push(currentCast[1].QueenB);
        screen.createButton("Proceed", "finaleLipSyncsDesc1()");
    } else {
        const placements = ["7THPLACE", "6THPLACE", "5THPLACE", "4THPLACE", "3RDPLACE"];
        const rankPs = ["7LMD", "6LMD", "5LMD", "4LMD", "3LMD"]
        currentCast.forEach((queen, index) => {
            if (index >= 2) {
                const placementIndex = index - 2;
                if (!shouldUseFinalePlacementLabels()) {
                    queen.addToTrackRecord("ELIMINATED");
                    queen.rankP = 34567;
                    eliminatedCast.unshift(queen);
                } else {
                    queen.addToTrackRecord(placements[placementIndex]);
                    queen.rankP = rankPs[placementIndex];
                    eliminatedCast.unshift(queen);
                }
            }
        });
        finalLS = [];
        finalLS.push(currentCast[0]);
        finalLS.push(currentCast[1]);
        screen.createButton("Proceed", "finaleLipSyncsDesc3()");
    }
    currentCast.splice(0, currentCast.length);
    runT5 = true;
}

function top7LS() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Lip Sync For The Crown!");

    onFinale = true;

    for (let q of eliminatedCast) {
        q.votes = 0;
        if (finaleGuests) {
            q.addToTrackRecord("");
        } else {
            q.addToTrackRecord("GUEST");
        }
    }

    if (!solidbk) {
        setBackgroundToNormal();
    }

    screen.createParagraph("The Top 7 finalists will battle it out in a lip sync smackdown for the crown!");
    screen.createHorizontalLine();

    let pool = [...currentCast];
    top7LSBye = [];
    top7LSRound1 = [];
    top7LSRound1Winners = [];
    top7LSRound2 = [];
    top7LSFinalists = [];

    top7LSBye.push(pool.splice(randomNumber(0, pool.length - 1), 1)[0]);

    while (pool.length >= 2) {
        let q1 = pool.splice(randomNumber(0, pool.length - 1), 1)[0];
        let q2 = pool.splice(randomNumber(0, pool.length - 1), 1)[0];
        top7LSRound1.push([q1, q2]);
    }

    screen.createImage(top7LSBye[0].getCurrentImage(), "orchid");
    screen.createBold(`${top7LSBye[0].name}, you have received a bye and will automatically advance to Round 2!`);

    screen.createHorizontalLine();
    screen.createBigText("Round 1 Matchups:");

    top7LSRound1.forEach(([q1, q2]) => {
        screen.createImage(q1.getCurrentImage(), "mediumvioletred");
        screen.createImage(q2.getCurrentImage(), "mediumvioletred");
        screen.createBold(`${q1.name} vs. ${q2.name}`);
    });

    episodeChallenges.push("Finale");
    screen.createButton("Proceed", "top7LSRound1Results()");
}

function top7LSRound1Results() {
    if (rigEPOutcome && (!Array.isArray(manualLipSyncWinnerQueues.top7LSRound1) || manualLipSyncWinnerQueues.top7LSRound1.length !== top7LSRound1.length)) {
        beginManualLipSyncWinnerSelection("top7LSRound1", top7LSRound1, "top7LSRound1Results", {
            header: "Top 7 Smackdown",
            subtitle: "Check who stays in each Round 1 matchup. Check both for a tie, or uncheck both for a double sashay.",
            stepTitle: "Round 1"
        });
        return;
    }

    let screen = new Scene();
    screen.clean();
    screen.createHeader("Round 1 Results!");

    for (let i = 0; i < top7LSRound1.length; i++) {
        const [q1, q2] = top7LSRound1[i];
        screen.createHorizontalLine();

        let outcome;
        if (rigEPOutcome) {
            outcome = consumeManualLipSyncOutcome("top7LSRound1", i, [q1, q2]);
        } else {
            const autoWinner = q1.lipsyncScore >= q2.lipsyncScore ? q1 : q2;
            outcome = { type: "win", winners: [autoWinner], losers: [autoWinner === q1 ? q2 : q1] };
        }

        let song = lsSong().toString();
        toAlots(outcome.winners, outcome.losers, alotsSong);
        toBlots([q1, q2], song);

        if (outcome.type === "doubleShantay") {
            screen.createImage(q1.getCurrentImage(), "silver");
            screen.createImage(q2.getCurrentImage(), "silver");
            screen.createBold(`${q1.name} and ${q2.name}, shantay you both stay.`);
            checkForShantayEvent([q1, q2]);
            top7LSRound1Winners.push(q1, q2);
        } else if (outcome.type === "doubleSashay") {
            screen.createImage(q1.getCurrentImage(), "sienna");
            screen.createImage(q2.getCurrentImage(), "sienna");
            screen.createBold(`${q1.name} and ${q2.name}, neither of you survived this lip sync...`);
            [q1, q2].forEach(loser => applyEliminationRecord(loser, { record: "LOST 1ST ROUND", rankP: 567 }));
        } else {
            const winner = outcome.winners[0];
            const loser = outcome.losers[0];
            screen.createImage(winner.getCurrentImage(), "silver");
            screen.createImage(loser.getCurrentImage(), "sienna");
            screen.createBold(`${winner.name}, shantay you stay.`);
            checkForShantayEvent([winner]);
            screen.createBold(`${loser.name}, sashay away…`);

            top7LSRound1Winners.push(winner);
            applyEliminationRecord(loser, { record: "LOST 1ST ROUND", rankP: 567 });
        }
    }

    clearManualLipSyncWinnerQueue("top7LSRound1");

    screen.createHorizontalLine();
    screen.createButton("Proceed", "top7LSRound2Match()");
}

function top7LSRound2Match() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Round 2!");

    let pool = [...top7LSBye, ...top7LSRound1Winners];
    top7LSRound2 = [];
    top7LSFinalists = [];

    while (pool.length >= 2) {
        let q1 = pool.splice(randomNumber(0, pool.length - 1), 1)[0];
        let q2 = pool.splice(randomNumber(0, pool.length - 1), 1)[0];
        top7LSRound2.push([q1, q2]);
    }

    if (pool.length === 1) {
        top7LSFinalists.push(pool[0]);
        screen.createImage(pool[0].getCurrentImage(), "orchid");
        screen.createBold(`${pool[0].name}, with an odd number of queens remaining, you advance straight to the final!`);
    }

    screen.createHorizontalLine();
    screen.createBigText("Round 2 Matchups:");

    top7LSRound2.forEach(([q1, q2]) => {
        screen.createImage(q1.getCurrentImage(), "orchid");
        screen.createImage(q2.getCurrentImage(), "orchid");
        screen.createBold(`${q1.name} vs. ${q2.name}`);
    });

    if (top7LSRound2.length === 0) {
        screen.createButton("Proceed", "top7LSFinalResults()");
    } else {
        screen.createButton("Proceed", "top7LSRound2Results()");
    }
}

