function top6() {
    let screen = new Scene();
    screen.clean();
    if (dragula_format || titans_format) {
    screen.createHeader("The Final Floorshow!");
    } else {
    screen.createHeader("The Grand Finale!");    
    }
    if (fameGames) {
        screen.createBold("It's time to find out who the fans have voted to be crowned Queen of the Fame Games!!");
        fgWnn();
    }
    if (dragula_format || titans_format) {
    screen.createParagraph("The Top 6 monsters will showcase looks representing the three principles of Dragula: Filth, Glamour and Horror!");
    } else {
    screen.createBold("The Top 6 finalists will star in their own individual show-stopping performances!");
    }
    for (let i = 0; i < currentCast.length; i++) {
        currentCast[i].getASLipsync();
    }
    for (let q of eliminatedCast) {
        q.votes = 0;
        if (finaleGuests) {
            q.addToTrackRecord("");
        } else {
            q.addToTrackRecord("GUEST");
        }
    }
    screen.createHorizontalLine();
    let slay = currentCast.filter(function (queen) { return queen.lipsyncScore > 11; });
    let great = currentCast.filter(function (queen) { return queen.lipsyncScore >= 8 && queen.lipsyncScore < 12; });
    let good = currentCast.filter(function (queen) { return queen.lipsyncScore >= 4 && queen.lipsyncScore < 8; });
    let bad = currentCast.filter(function (queen) { return queen.lipsyncScore >= 2 && queen.lipsyncScore < 4; });
    let flop = currentCast.filter(function (queen) { return queen.lipsyncScore >= -10 && queen.lipsyncScore < 2; });
    createLipsyncDesc(slay, great, good, bad, flop);
    for (let i = 0; i < currentCast.length; i++) {
        currentCast[i].lipsyncScore += ((currentCast[i].favoritism - currentCast[i].unfavoritism) / 3);
    }
    currentCast.sort((a, b) => (b.lipsyncScore - a.lipsyncScore));
    episodeChallenges.push("Finale");
    screen.createButton("Proceed", "finaleTop6Judging()");
}

function finaleTop6Judging() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("The final minutes...");
    screen.createHorizontalLine();
    screen.createBigText("The ones moving on to the final lipsync are...");
    screen.createImage(currentCast[0].getCurrentImage(), "silver");
    screen.createImage(currentCast[1].getCurrentImage(), "silver");
    screen.createBold(currentCast[0].name + " and " + currentCast[1].name + ", condragulations, go prepare for your final lipsync.");
    screen.createImage(currentCast[2].getCurrentImage(), "sienna");
    screen.createImage(currentCast[3].getCurrentImage(), "sienna");
    screen.createImage(currentCast[4].getCurrentImage(), "sienna");
    screen.createImage(currentCast[5].getCurrentImage(), "sienna");
    screen.createBold(currentCast[2].name + ", " + currentCast[3].name + ", " + currentCast[4].name + " and " + currentCast[5].name + ", I'm sorry my dears but it's not your time. I must ask you to sashay away...");
    if (team) {
        for (let i = 2; i <= currentCast.length - 1; i++) {
            currentCast[i].QueenA.addToTrackRecord("ELIMINATED");
            currentCast[i].QueenB.addToTrackRecord("ELIMINATED");
            eliminatedCast.unshift(currentCast[i].QueenA);
            eliminatedCast.unshift(currentCast[i].QueenB);
        }
        firstLS.push(currentCast[0].QueenA);
        firstLS.push(currentCast[0].QueenB);
        secondLS.push(currentCast[1].QueenA);
        secondLS.push(currentCast[1].QueenB);
        screen.createButton("Proceed", "finaleLipSyncsDesc1()");
    } else {
        const placements = ["6THPLACE", "5THPLACE", "4THPLACE", "3RDPLACE"];
        const rankPs = ["6LMD", "5LMD", "4LMD", "3LMD"]
        currentCast.forEach((queen, index) => {
            if (index >= 2) {
                const placementIndex = index - 2;
                if (!shouldUseFinalePlacementLabels()) {
                    queen.addToTrackRecord("ELIMINATED");
                    queen.rankP = 3456;
                    eliminatedCast.unshift(queen);
                } else {
                    queen.addToTrackRecord(placements[placementIndex]);
                    queen.rankP = rankPs[placementIndex];
                    eliminatedCast.unshift(queen);
                }
            }
        });
        finalLS = [];
        finalLS.push(currentCast[0]);
        finalLS.push(currentCast[1]);
        screen.createButton("Proceed", "finaleLipSyncsDesc3()");
    }
    currentCast.splice(0, currentCast.length);
    runT5 = true;
}

