function top6AS11FinalResults() {
    if (top6AS11Finalists.length === 0) {
        const revived = eliminatedCast.find(q => (q.trackRecord[q.trackRecord.length - 1] || "").includes("LOST 2ND ROUND"));
        if (revived) {
            eliminatedCast.splice(eliminatedCast.indexOf(revived), 1);
            revived.trackRecord.pop();
            top6AS11Finalists.push(revived);
        }
    }

    if (top6AS11Finalists.length === 1) {
        let screen = new Scene();
        screen.clean();
        screen.createHeader("I've made my decision…");
        const winner = top6AS11Finalists[0];
        screen.createImage(winner.getCurrentImage(), "yellow");
        screen.createBigText(`${winner.name}!!`);
        launchWinnerConfetti();
        screen.createBold("With no one left to lip sync against, now prance, my queen!");
        winner.addToTrackRecord("WINNER");
        winner.rankP = 1;
        awardSeasonPrize(winner);
        currentCast = [winner];
        screen.createButton("Proceed", "contestantProgress()");
        return;
    }

    if (top6AS11Finalists.length > 2) {
        renderGenericCrownPicker(top6AS11Finalists, (winners, losers) => {
            let screen = new Scene();
            screen.clean();
            screen.createHeader("I've made my decision…");
            toAlots(winners, losers, alotsSong);

            if (winners.length === 2) {
                screen.createImage(winners[0].getCurrentImage(), "yellow");
                screen.createImage(winners[1].getCurrentImage(), "yellow");
                screen.createBigText(`${winners[0].name} and ${winners[1].name}!!`);
                launchWinnerConfetti();
                screen.createBold("For the FIRST TIME in Drag Race herstory, you are both winners, baby");
                screen.createBold("Now prance, my queens!");
            } else {
                screen.createImage(winners[0].getCurrentImage(), "yellow");
                screen.createBigText(`${winners[0].name}!!`);
                launchWinnerConfetti();
                screen.createBold("Now prance, my queen!");
            }

            winners.forEach(w => {
                w.addToTrackRecord("WINNER");
                w.rankP = 1;
                awardSeasonPrize(w);
            });
            losers.forEach(l => applyEliminationRecord(l, { record: "LOST 3RD ROUND", rankP: 2 }));
            currentCast = winners.slice();
            screen.createButton("Proceed", "contestantProgress()");
        }, {
            header: "I've made my decision…",
            subtitle: "Earlier ties left more than 2 finalists. Pick up to 2 winners:"
        });
        return;
    }

    if (rigEPOutcome) {
        const finalMatchup = [[top6AS11Finalists[0], top6AS11Finalists[1]]];
        if (!Array.isArray(manualLipSyncWinnerQueues.top6AS11Final) || manualLipSyncWinnerQueues.top6AS11Final.length !== 1) {
            beginManualLipSyncWinnerSelection("top6AS11Final", finalMatchup, "top6AS11FinalResults", {
                header: "Top 6 Grand Finale",
                subtitle: "Check who wins. Check both to crown co-winners.",
                stepTitle: "Final"
            });
            return;
        }
    }

    let screen = new Scene();
    screen.clean();
    screen.createHeader("I've made my decision…");

    let winners, runners;
    if (rigEPOutcome) {
        const outcome = consumeManualLipSyncOutcome("top6AS11Final", 0, top6AS11Finalists);
        clearManualLipSyncWinnerQueue("top6AS11Final");
        if (outcome.type === "doubleShantay") {
            winners = outcome.winners;
            runners = [];
        } else if (outcome.winners.length === 1) {
            winners = outcome.winners;
            runners = outcome.losers;
        } else {
            const autoWinner = top6AS11Finalists[0].lipsyncScore >= top6AS11Finalists[1].lipsyncScore ? top6AS11Finalists[0] : top6AS11Finalists[1];
            winners = [autoWinner];
            runners = top6AS11Finalists.filter(q => q !== autoWinner);
        }
    } else {
        const autoWinner = top6AS11Finalists[0].lipsyncScore >= top6AS11Finalists[1].lipsyncScore ? top6AS11Finalists[0] : top6AS11Finalists[1];
        winners = [autoWinner];
        runners = top6AS11Finalists.filter(q => q !== autoWinner);
    }

    toAlots(winners, runners, alotsSong);

    if (winners.length === 2) {
        screen.createImage(winners[0].getCurrentImage(), "yellow");
        screen.createImage(winners[1].getCurrentImage(), "yellow");
        screen.createBigText(`${winners[0].name} and ${winners[1].name}!!`);
        launchWinnerConfetti();
        screen.createBold("For the FIRST TIME in Drag Race herstory, you are both winners, baby");
        screen.createBold("Now prance, my queens!");
    } else {
        screen.createImage(winners[0].getCurrentImage(), "yellow");
        screen.createBigText(`${winners[0].name}!!`);
        launchWinnerConfetti();
        screen.createBold("Now prance, my queen!");
    }

    winners.forEach(w => {
        w.addToTrackRecord("WINNER");
        w.rankP = 1;
        awardSeasonPrize(w);
    });
    runners.forEach(r => {
        r.addToTrackRecord("LOST 3RD ROUND");
        r.rankP = 2;
        eliminatedCast.unshift(r);
    });

    currentCast = winners.slice();
    screen.createButton("Proceed", "contestantProgress()");
}

