// Pairs up as many survivors as possible; an odd one out gets a bye straight into the next round.
function pairSurvivorsForNextRound(survivors) {
    const pool = shuffle([...survivors]);
    const pairs = [];
    while (pool.length >= 2) {
        pairs.push([pool.shift(), pool.shift()]);
    }
    return { pairs, bye: pool.length === 1 ? pool[0] : null };
}

