async function finalLipSync() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("The end.");

    if (rigEPOutcome) {
        if (finalLS.length <= 1) {
            crownSoleFinalist(finalLS[0]);
            return;
        }
        renderFinalLipSyncManualPicker();
        return;
    }

    screen.createBold("", "typeF");
    let txt = "Ladies, I've made my decision. The Next Drag Superstar is..."
    let tiempa = 0;
    typeWriter(txt, tiempa);
    screen.createHorizontalLine();
    for (let i = 0; i < finalLS.length; i++) {
        finalLS[i].finaleScore += (finalLS[i].lipsyncScore / 2);
    }
    finalLS.sort((a, b) => b.finaleScore - a.finaleScore);
    let winner = 0;
    await sleep(4000);
    if (finaleof4gurl) {
        if (randomNumber(0, 100) >= (chaosMode ? 85 : 95)) {
            winner = randomNumber(1, 3);
        }
        screen.createImage(finalLS[winner].getCurrentImage(), "yellow");
        screen.createBigText(finalLS[winner].name + "!!");
        launchWinnerConfetti();
        screen.createBold("Now prance, my queen!");
        finalLS[winner].addToTrackRecord("WINNER");
        awardSeasonPrize(finalLS[winner]);
        for (let i = 0; i < finalLS.length; i++) {
            if (!(finalLS.indexOf(finalLS[i]) == winner)) {
                applyEliminationRecord(finalLS[i], {
                    record: "LOST 3RD ROUND",
                    rankP: 234,
                });
            }
        }
        if (winner == 0) {
            toAlots([finalLS[winner]], [finalLS[1], finalLS[2], finalLS[3]], alotsSong);
            finalLS.splice(1, 3);
        } else if (winner == 1) {
            toAlots([finalLS[winner]], [finalLS[0], finalLS[2], finalLS[3]], alotsSong);
            finalLS.splice(2, 2);
            finalLS.splice(0, 1);
        } else if (winner == 2) {
            toAlots([finalLS[winner]], [finalLS[1], finalLS[0], finalLS[3]], alotsSong);
            finalLS.splice(0, 2);
            finalLS.splice(1, 1);
        } else if (winner == 3) {
            toAlots([finalLS[winner]], [finalLS[1], finalLS[2], finalLS[0]], alotsSong);
            finalLS.splice(0, 3);
        }
    }
    else if (isThisA3Way) {
        eliminatedCast[0].rankP = 0;
        if (randomNumber(0, 100) >= 95) {
            winner = randomNumber(1, 2);
        }
        screen.createImage(finalLS[winner].getCurrentImage(), "yellow");
        screen.createBigText(finalLS[winner].name + "!!");
        launchWinnerConfetti();
        screen.createBold("Now prance, my queen!");
        finalLS[winner].addToTrackRecord("WINNER");
        awardSeasonPrize(finalLS[winner]);
        for (let i = 0; i < finalLS.length; i++) {
            if (!(finalLS.indexOf(finalLS[i]) == winner)) {
                applyEliminationRecord(finalLS[i], {
                    record: "LOST 3RD ROUND",
                    rankP: 23,
                });
            }
        }
        if (winner == 0) {
            toAlots([finalLS[winner]], [finalLS[1], finalLS[2]], alotsSong);
            finalLS.splice(1, 2);
        } else if (winner == 1) {
            toAlots([finalLS[winner]], [finalLS[0], finalLS[2]], alotsSong);
            finalLS.splice(2, 1);
            finalLS.splice(0, 1);
        } else if (winner == 2) {
            toAlots([finalLS[winner]], [finalLS[1], finalLS[0]], alotsSong);
            finalLS.splice(0, 2);
        }
    } else {
        if (finalLS[0].finaleScore == finalLS[1].finaleScore && randomNumber(0, 100) >= 50) {
            toAlots(finalLS, [], alotsSong);
            screen.createBold("For the FIRST TIME in Drag Race herstory, you are both winners, baby");
            screen.createImage(finalLS[0].getCurrentImage(), "yellow");
            screen.createImage(finalLS[1].getCurrentImage(), "yellow");
            screen.createBigText(finalLS[0].name + " and " + finalLS[1].name + "!!");
            launchWinnerConfetti();
            screen.createBold("Now prance, my queens!");
            finalLS[0].addToTrackRecord("WINNER");
            finalLS[1].addToTrackRecord("WINNER");
            finalLS[1].rankP = 1;
            awardSeasonPrize(finalLS[0]);
            awardSeasonPrize(finalLS[1]);
            eliminatedCast[0].rankP = 432;
            eliminatedCast[1].rankP = 432;
            finalLS.splice(1, 1);
        } else {
            const winningQueen = finalLS[winner];
            const losingQueens = finalLS.filter((queen) => queen !== winningQueen);
            toAlots([winningQueen], losingQueens, alotsSong);
            if (randomNumber(0, 100) >= 95) {
                winner = 1;
                alots.splice(alots.length - 1, 1);
                const upsetWinner = finalLS[winner];
                toAlots([upsetWinner], finalLS.filter((queen) => queen !== upsetWinner), alotsSong);
                winner = finalLS.indexOf(upsetWinner);
            }
            const crownedQueen = finalLS[winner];
            screen.createImage(crownedQueen.getCurrentImage(), "yellow");
            screen.createBigText(crownedQueen.name + "!!");
            launchWinnerConfetti();
            screen.createBold("Now prance, my queen!");
            crownedQueen.addToTrackRecord("WINNER");
            awardSeasonPrize(crownedQueen);
            finalLS.filter((queen) => queen !== crownedQueen).forEach((queen) => {
                    if (runT5) {
                        applyEliminationRecord(queen, {
                            record: "RUNNER UP",
                            rankP: 2,
                        });
                    } else {
                        applyEliminationRecord(queen, {
                            record: "LOST 3RD ROUND",
                            rankP: 2,
                        });
                    }
            });
            finalLS = [crownedQueen];
        }
    }
    isThisA3Way = false;
    finaleof4gurl = false;
    currentCast = [finalLS[0]];
    screen.createButton("Proceed", "contestantProgress()");
}
