async function finaleJuryTop3() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("The jury!");
    screen.createParagraph("The eliminated queens are coming back, back, back again!");
    screen.createHorizontalLine();
    let voting = [];
    for (let i = 0; i < currentCast.length; i++) {
        screen.createImage(currentCast[i].getCurrentImage());
        currentCast[i].votes = 0;
    }
    screen.createBold("After the Top 3 had their meetings with the eliminated queens... The eliminated queens vote!!");
    for (let i = 0; i < eliminatedCast.length; i++) {
        voting = [...currentCast];
        const isClaimedJuror = claimSpectatorMode && isClaimedQueen(eliminatedCast[i]);
        if (isClaimedJuror) {
            eliminatedCast[i].lipstick = await chooseClaimedQueenTarget(
                eliminatedCast[i],
                voting,
                "vote for (jury - 1st choice, 2pts)",
                () => bestSister(eliminatedCast[i], voting) || voting[randomNumber(0, voting.length - 1)]
            );
        } else {
            eliminatedCast[i].lipstick = bestSister(eliminatedCast[i], voting);
        }
        if (voting.find(q => { return q.name == eliminatedCast[i].lipstick.name }) == undefined) {
            eliminatedCast[i].lipstick = voting[randomNumber(0, voting.length - 1)];
        }
        eliminatedCast[i].lipstick.votes += 2;
        voting.splice(voting.indexOf(eliminatedCast[i].lipstick), 1);
        if (voting.length > 0) {
            if (claimSpectatorMode && isClaimedQueen(eliminatedCast[i])) {
                eliminatedCast[i].lipstick = await chooseClaimedQueenTarget(
                    eliminatedCast[i],
                    voting,
                    "vote for (jury - 2nd choice, 1pt)",
                    () => bestSister(eliminatedCast[i], voting) || voting[randomNumber(0, voting.length - 1)]
                );
            } else {
                eliminatedCast[i].lipstick = bestSister(eliminatedCast[i], voting);
            }
            if (voting.find(q => { return q.name == eliminatedCast[i].lipstick.name }) == undefined) {
                eliminatedCast[i].lipstick = voting[randomNumber(0, voting.length - 1)];
            }
            eliminatedCast[i].lipstick.votes += 1;
        }
    }
    screen.createHorizontalLine();
    screen.createBold("The results are in..!!");
    for (let i = 0; i < currentCast.length; i++) {
        screen.createBold(`${currentCast[i].name}: ${currentCast[i].votes.toString()} points`);
    }

    currentCast.sort((a, b) => (b.votes - a.votes));

    if (currentCast[1].votes == currentCast[2].votes) {
        screen.createHorizontalLine();
        screen.createBold("It is a tie, the contestants must revote between " + currentCast[1].name + " and " + currentCast[2].name + "!!");
        let revoteCast = [currentCast[1], currentCast[2]];
        revoteCast[0].votes = 0;
        revoteCast[1].votes = 0;
        for (let i = 0; i < eliminatedCast.length; i++) {
            const isClaimedJuror = claimSpectatorMode && isClaimedQueen(eliminatedCast[i]);
            if (isClaimedJuror) {
                eliminatedCast[i].lipstick = await chooseClaimedQueenTarget(
                    eliminatedCast[i],
                    revoteCast,
                    "vote for (jury tiebreaker)",
                    () => bestSister(eliminatedCast[i], revoteCast) || revoteCast[randomNumber(0, revoteCast.length - 1)]
                );
            } else {
                eliminatedCast[i].lipstick = bestSister(eliminatedCast[i], revoteCast);
            }
            if (revoteCast.find(q => { return q.name == eliminatedCast[i].lipstick.name }) == undefined) {
                eliminatedCast[i].lipstick = revoteCast[randomNumber(0, revoteCast.length - 1)];
            }
            eliminatedCast[i].lipstick.votes += 1;
        }
        revoteCast.sort((a, b) => (b.votes - a.votes));
        currentCast[1] = revoteCast[0];
    }

    screen.createHorizontalLine();
    screen.createBold(`${currentCast[0].name} and ${currentCast[1].name} are the Top 2 of the season!!`);

    let eliminatedFinalist = currentCast[2];
    eliminatedFinalist.addToTrackRecord("ELIMINATED");
    eliminatedFinalist.rankP = 3;
    eliminatedCast.unshift(eliminatedFinalist);
    currentCast.splice(2, 1);

    let song = lsSong().toString();
    for (let i = 0; i < currentCast.length; i++) {
        currentCast[i].getASLipsync();
    }
    screen.createHorizontalLine();
    let event = checkForLipsyncEvent(currentCast);
    if (event != false) {
        let eventQueen = currentCast.find((q) => {
            return q.name == event.queen.name
        });
        eventQueen.lipsyncScore += event.points;
    }
    let slay = currentCast.filter(function (queen) { return queen.lipsyncScore > 11; });
    let great = currentCast.filter(function (queen) { return queen.lipsyncScore >= 8 && queen.lipsyncScore < 12; });
    let good = currentCast.filter(function (queen) { return queen.lipsyncScore >= 4 && queen.lipsyncScore < 8; });
    let bad = currentCast.filter(function (queen) { return queen.lipsyncScore >= 2 && queen.lipsyncScore < 4; });
    let flop = currentCast.filter(function (queen) { return queen.lipsyncScore >= -10 && queen.lipsyncScore < 2; });
    toBlots(currentCast, song);
    createLipsyncDesc(slay, great, good, bad, flop);
    screen.createHorizontalLine();
    currentCast.sort((a, b) => (b.finaleScore - a.finaleScore));
    screen.createButton("Proceed", "finaleFinale()");
}

