let activeTypeWriterToken = 0;
async function typeWriter(textW, i, targetId = "typeF", token) {
    if (typeof textW !== "string") return;

    const target = document.getElementById(targetId);
    if (!target) return;

    if (i === 0 || typeof token === "undefined") {
        activeTypeWriterToken += 1;
        token = activeTypeWriterToken;
        target.innerHTML = "";
    }

    if (token !== activeTypeWriterToken || i >= textW.length) return;

    const liveTarget = document.getElementById(targetId);
    if (!liveTarget) return;

    liveTarget.innerHTML += textW.charAt(i);
    await sleep(50);
    return typeWriter(textW, i + 1, targetId, token);
}

