async function finaleJuryTop2() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("The Jury");
    screen.createParagraph("The eliminated contestants are coming back, back, back again!");
    screen.createHorizontalLine();

    const finalists = [...currentCast];
    const firstRoundVotes = new Map();

    juryTop2Winner = null;
    juryTop2RunnerUp = null;
    juryTop2WinnerVotes = 0;

    for (let i = 0; i < finalists.length; i++) {
        finalists[i].votes = 0;
        screen.createImage(finalists[i].getCurrentImage());
    }

    screen.createBold("The eliminated contestants will each vote for the winner!");

    for (let i = 0; i < eliminatedCast.length; i++) {
        const juror = eliminatedCast[i];
        const voting = [...finalists];

        const isClaimedJuror = claimSpectatorMode && isClaimedQueen(juror);

        if (isClaimedJuror) {
            juror.lipstick = await chooseClaimedQueenTarget(
                juror,
                voting,
                "vote for (jury finale)",
                () => bestSister(juror, voting) || voting[randomNumber(0, voting.length - 1)]
            );
        } else {
            juror.lipstick = bestSister(juror, voting);
        }

        if (!voting.includes(juror.lipstick)) {
            juror.lipstick = voting[randomNumber(0, voting.length - 1)];
        }

        juror.lipstick.votes += 1;
        screen.createImage(juror.getCurrentImage(), "black");
        screen.createImage(juror.lipstick.getCurrentImage(), "yellow");
        screen.createParagraph(`${juror.name} voted for ${juror.lipstick.name}!`);
    }

    for (let i = 0; i < finalists.length; i++) {
        firstRoundVotes.set(finalists[i], finalists[i].votes);
    }

    let winner = finalists[0];
    let runnerUp = finalists[1];

    if (runnerUp.votes > winner.votes) {
        [winner, runnerUp] = [runnerUp, winner];
    }

    let tiebreakerVotes = false;

    if (winner.votes === runnerUp.votes) {
        tiebreakerVotes = true;

        screen.createHorizontalLine();
        screen.createBold("It's a tie! The jury must vote again!");

        winner.votes = 0;
        runnerUp.votes = 0;

        for (let i = 0; i < eliminatedCast.length; i++) {
            const juror = eliminatedCast[i];
            const voting = [winner, runnerUp];
            const isClaimedJuror = claimSpectatorMode && isClaimedQueen(juror);

            if (isClaimedJuror) {
                juror.lipstick = await chooseClaimedQueenTarget(
                    juror,
                    voting,
                    "vote for (jury tiebreaker)",
                    () => bestSister(juror, voting) || voting[randomNumber(0, voting.length - 1)]
                );
            } else {
                juror.lipstick = bestSister(juror, voting);
            }

            if (!voting.includes(juror.lipstick)) {
                juror.lipstick = voting[randomNumber(0, voting.length - 1)];
            }

            juror.lipstick.votes += 1;
            screen.createImage(juror.getCurrentImage(), "black");
            screen.createImage(juror.lipstick.getCurrentImage(), "yellow");
            screen.createParagraph(`${juror.name} voted for ${juror.lipstick.name} in the tiebreaker!`);
        }

        if (runnerUp.votes > winner.votes) {
            [winner, runnerUp] = [runnerUp, winner];
        }

        if (winner.votes === runnerUp.votes) {
            winner = randomNumber(0, 1) === 0 ? winner : runnerUp;
            runnerUp = finalists.find(q => q !== winner);
            screen.createBold("The jury is still tied! A random tiebreaker decides the winner.");
        }
    }

    juryTop2Winner = winner;
    juryTop2RunnerUp = runnerUp;
    juryTop2WinnerVotes = (firstRoundVotes.get(winner) || 0) + (tiebreakerVotes ? winner.votes : 0);

    currentCast.splice(currentCast.indexOf(winner), 1);
    currentCast.unshift(winner);

    screen.createHorizontalLine();
    screen.createParagraph("The jury has made its decision. The final results will now be revealed.");
    screen.createButton("Proceed", "finaleJuryTop2Results()");
}

