function doubleDiamondTwist() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("The Double Diamond");
    screen.createBigText("The queens will now vote for one sister to receive the Double Diamond!");
    screen.createParagraph("The winner's star total will be doubled before the Grand Finale.");

    for (let i = 0; i < currentCast.length; i++) {
        currentCast[i].votes = 0;
    }

    for (let i = 0; i < currentCast.length; i++) {
        const voter = currentCast[i];
        const eligibleQueens = currentCast.filter(queen => queen !== voter);

        voter.lipstick = bestSister(voter, eligibleQueens);

        if (!voter.lipstick) {
            continue;
        }

        screen.createImage(voter.getCurrentImage(), "black");
        screen.createImage(voter.lipstick.getCurrentImage(), "cyan");
        screen.createBold(voter.name + " voted for " + voter.lipstick.name + "!");

        voter.lipstick.votes = (voter.lipstick.votes || 0) + 1;
    }

    screen.createHorizontalLine();

    currentCast.sort((a, b) => (b.votes || 0) - (a.votes || 0));

    let winner = currentCast[0];

    winner.stars *= 2;

    if (!Array.isArray(winner.doubleDiamond)) {
        winner.doubleDiamond = [];
    }

    winner.doubleDiamond.push(winner.trackRecord.length + 1);

    doubleDiamondUsed = true;

    screen.createImage(winner.getCurrentImage(), "cyan");
    screen.createBold(winner.name + " has won the Double Diamond!");
    screen.createBold("Their stars have been doubled to " + winner.stars + "!");

    screen.createButton("Proceed", "awFinale()");
}
function awFinale() {
    if (all_winners && doubleDiamond && !doubleDiamondUsed) {
        doubleDiamondTwist();
        return;
    }
    onFinale = true;
    chocolateBarTwistCheck = true;
    wht = [];
    qonfi = 0;

    let topCount = 4;
    if (top3) topCount = 3;

    let screen = new Scene();
    screen.clean();
    screen.createHeader("The end...");
    screen.createBold(`The ${topCount} queens with the most stars will advance to the grand finale!`);
    screen.createHorizontalLine();

    currentCast.sort((a, b) => (b.stars - a.stars));

    const tieResult = tiesInFinale(topCount);
    const finalists = Array.isArray(tieResult.finalists) ? [...tieResult.finalists] : [];
    const comparing = Array.isArray(tieResult.comparing) ? [...tieResult.comparing] : [];

    if (finalists.length > 0) {
        const finalistSet = new Set(finalists);
        const comparingSet = new Set(comparing);
        const rest = currentCast.filter((queen) => !finalistSet.has(queen) && !comparingSet.has(queen));
        currentCast = [...finalists, ...comparing, ...rest];
    }

    switch (tieResult.code) {
        case 1:
            screen.createBold("As we have a tie... The contestants I chose to go to the grand finale are...");
            break;

        case 2:
            wht = comparing;
            qonfi = finalists.length;
            screen.createBold(currentCast[0].name + ", you must choose which of your sisters you'd like to invite to the Grand Finale!");

            let queensTied = "";
            for (let i = 0; i < wht.length; i++) {
                if (i != wht.length - 1) {
                    queensTied += wht[i].name + ", ";
                } else {
                    queensTied += " or " + wht[i].name;
                }
            }
            screen.createBold("Will it be... " + queensTied);

            for (let i = qonfi; i < topCount; i++) {
                currentCast[0].lipstick = bestSister(currentCast[0], wht) || wht[0];
                if (!wht.includes(currentCast[0].lipstick)) {
                    currentCast[0].lipstick = wht[0];
                }
                if (!currentCast[0].lipstick) {
                    break;
                }

                screen.createImage(currentCast[0].getCurrentImage(), "black");
                screen.createImage(currentCast[0].lipstick.getCurrentImage(), "black");
                screen.createBold(currentCast[0].name + " chose " + currentCast[0].lipstick.name);

                wht.splice(wht.indexOf(currentCast[0].lipstick), 1);
                currentCast.splice(
                    qonfi,
                    0,
                    currentCast.splice(currentCast.indexOf(currentCast[0].lipstick), 1)[0]
                );
            }

            screen.createHorizontalLine();
            screen.createBold("The contestants advancing to the grand finale are...");
            break;

        case 3:
            screen.createBold("The contestants advancing to the grand finale are...");
            break;

        default:
            break;
    }

    for (let i = 0; i < topCount; i++) {
        screen.createImage(currentCast[i].getCurrentImage(), "gold");
        screen.createBold(currentCast[i].name + " with " + currentCast[i].stars + " stars!");
    }

    screen.createHorizontalLine();

    let p = currentCast.length - 1;

    while (currentCast.length > topCount) {

        let eliminatedQueen = currentCast[p];

        eliminatedQueen.rankP = (topCount === 4 ? 58 : 48);

        if (topCount === 3) {
            eliminatedQueen.addToTrackRecord("ELIMINATED");
            eliminatedCast.push(eliminatedQueen);
        } else {
            if (p > 7) {
                eliminatedQueen.addToTrackRecord("ELIMINATED");
                eliminatedCast.push(eliminatedQueen);
            } else {
                sdadhh.push(eliminatedQueen);
            }
        }

        screen.createImage(eliminatedQueen.getCurrentImage(), "sienna");
        screen.createBold(eliminatedQueen.name + ", sashay away...");

        currentCast.splice(p, 1);

        p--;
    }

    if (topCount === 3) {
        onTop4Finale = false;
        screen.createButton("Proceed", "finale()");
    } else {
        onTop4Finale = true;
        screen.createButton("Proceed", "sheDADHH()");
    }
}

let wht = [];
let qonfi = 0;
function tiesInFinale(size) {
    const sorted = [...currentCast].sort((a, b) => (Number(b.stars) || 0) - (Number(a.stars) || 0));
    if (size <= 0 || sorted.length === 0) {
        return { code: 3, finalists: [] };
    }
    if (sorted.length <= size) {
        return { code: 3, finalists: sorted };
    }

    const boundaryStars = Number(sorted[size - 1].stars) || 0;
    const finalists = sorted.filter((queen) => (Number(queen.stars) || 0) > boundaryStars);
    const comparing = sorted.filter((queen) => (Number(queen.stars) || 0) === boundaryStars);

    if (finalists.length === 0 && comparing.length > size) {
        return { code: 1, finalists: comparing };
    }

    if (finalists.length + comparing.length === size) {
        return { code: 3, finalists: [...finalists, ...comparing] };
    }

    if (finalists.length < size && finalists.length + comparing.length > size) {
        return { code: 2, finalists, comparing };
    }

    return { code: 3, finalists: sorted.slice(0, size) };
}

