function hasMvqTrackRecordData() {
    const contestants = [];
    if (Array.isArray(currentCast)) contestants.push(...currentCast);
    if (Array.isArray(eliminatedCast)) contestants.push(...eliminatedCast);
    if (Array.isArray(fullCast)) contestants.push(...fullCast);

    for (let i = 0; i < contestants.length; i++) {
        const queen = contestants[i];
        const hasWon = Array.isArray(queen.mvqWonHistory) && queen.mvqWonHistory.some(value => Number(value) > 0);
        const hasGifted = Array.isArray(queen.mvqGiftedHistory) && queen.mvqGiftedHistory.some(value => Number(value) > 0);
        if (hasWon || hasGifted) {
            return true;
        }
    }

    return false;
}

function hasLaMasTrackRecordData() {
    const contestants = [];
    if (Array.isArray(currentCast)) contestants.push(...currentCast);
    if (Array.isArray(eliminatedCast)) contestants.push(...eliminatedCast);
    if (Array.isArray(fullCast)) contestants.push(...fullCast);

    for (let i = 0; i < contestants.length; i++) {
        const queen = contestants[i];
        if (Array.isArray(queen.laMasScoreHistory) && queen.laMasScoreHistory.some(value => Number.isFinite(Number(value)))) {
            return true;
        }
    }

    return false;
}

