function addStatsTabs(screen, currentTab = "") {
    const main = document.querySelector("div#MainBlock");
    const tabBar = document.createElement("div");
    tabBar.setAttribute("class", "stat-tabs");

    const addTab = (text, method, icon = "fa-solid fa-chart-simple") => {
        const button = document.createElement("button");
        button.innerHTML = `<i class="${icon}"></i>`;
        button.setAttribute("title", text);
        button.setAttribute("aria-label", text);
        button.setAttribute("onclick", method);
        button.setAttribute("id", "stat");
        button.setAttribute("class", "statistics stat-tab" + (currentTab === text ? " active" : ""));
        tabBar.appendChild(button);
    };

    addTab("Track Records", "contestantProgress()", "fa-solid fa-table-list");
    addTab("Weekly Awards", "weeklyAwardsScreen()", "fa-solid fa-award");
    addTab("Placement Key", "placementKeyScreen()", "fa-solid fa-key");
    if (liveAuditionResults.length > 0) {
        addTab("Auditions", "auditionsChart()", "fa-solid fa-clipboard-check");
    }
    addTab("Relationship Chart", "relationshipChart()", "fa-solid fa-heart");
    addTab("Lip Syncs", "allLipsyncsSeason()", "fa-solid fa-music");
    if (runwayEpisodeLogs.length > 0) {
        addTab("FPR", "runwayJudgingChart()", "fa-solid fa-camera-retro");
    }
    addTab("Money Tracker", "moneyChart()", "fa-solid fa-dollar-sign");
    addTab("Popularity Chart", "popularityChart()", "fa-solid fa-chart-line");
    addTab("Fan Reactions", "weeklyFanReactionsScreen()", "fa-solid fa-comments");
    addTab("Episode Ratings", "episodeRatingsChart()", "fa-solid fa-star");
    if (hasLaMasTrackRecordData()) {
        addTab("Points TR", "laMasPointsTrackRecord()", "fa-solid fa-list-check");
    }
    if (hasMvqTrackRecordData()) {
        addTab("MVQ Points Track Record", "pointsTrackRecord()", "fa-solid fa-crown");
    }
    if (slmFormat) {
        addTab("Summit of Rebirth Stars", "slmStarsTrackRecord()", "fa-solid fa-star");
    }
    if (lipsync_assassin) {
        addTab("RuMocracy", "votingChart()", "fa-solid fa-check-to-slot");
    }
    if (lipsync_assassin || all_stars) {
        addTab("Lipstick Choices", "lsticksChoices()", "fa-solid fa-wand-magic-sparkles");
    }
    if (all_winners) {
        addTab("Legendary Legend Stars", "legLeySt()", "fa-solid fa-certificate");
    }
    if (saveTwist4Chart.length > 0) {
        addTab("Save Twist History", "saveTwistChart()", "fa-solid fa-shield-heart");
    }
    if (rateAQ4Chart.length > 0) {
        addTab("Rate-A-Queen", "rateAQChart()", "fa-solid fa-ranking-star");
    }
    if (safetyFormat || beaverCastVote) {
        addTab("Safety Votes", "safetyVotingChart()", "fa-solid fa-shield");
    }
    if (coinFlip4Chart.length > 0) {
        addTab("Coin Flip", "coinFlipChart()", "fa-solid fa-coins");
    }

    if (main) {
        main.appendChild(tabBar);
    }
}

function normalizeWeeklyAwardPlacement(placement) {
    return String(placement || "").replace(/<[^>]*>/g, " ").trim().toUpperCase();
}

function isWeeklyAwardElimination(placement) {
    const value = normalizeWeeklyAwardPlacement(placement);
    return /ELIM|QUIT|DEPT|DEPARTED|EXT|DISQ|EXPELLED|\b(?:DQ|OUT)\b/.test(value);
}

function getWeeklyAwardSeasonRanks(queen, episodeIndex) {
    let active = true;
    let frontRunnerRank = 0;
    let bottomFeederRank = 0;
    let rankedEpisodes = 0;
    const returnEpisodes = getRetEpEntries(queen).map(Number);
    for (let index = 0; index <= episodeIndex; index++) {
        const placement = queen.trackRecord[index];
        const value = normalizeWeeklyAwardPlacement(placement);
        if (returnEpisodes.includes(index + 1) || (/RTRN|RETURN/.test(value) && !isWeeklyAwardElimination(value))) {
            active = true;
        }
        if (isWeeklyAwardElimination(value)) active = false;
        const ranks = getWeeklyAwardPlacementRanks(placement);
        if (ranks) {
            frontRunnerRank += ranks.frontRunnerRank;
            bottomFeederRank += ranks.bottomFeederRank;
            rankedEpisodes++;
        }
    }
    return active && rankedEpisodes > 0 ? { frontRunnerRank, bottomFeederRank } : null;
}

function getWeeklyAwardPlacementRanks(placement) {
    const value = normalizeWeeklyAwardPlacement(placement).replace(/^RTRN\s*\+?\s*/, "");
    if (!value) return null;

    const isEliminated = isWeeklyAwardElimination(value);
    const isBottom = /BTM|\bBOTTOM\b/.test(value);
    const isLow = /LOW|\bLOW\b/.test(value);
    const isSafe = /\bSAFE\b/.test(value);
    const isHigh = /\bHIGH\b/.test(value);
    const isTopThree = /\bTOP\s*3\b/.test(value);
    const isTopTwo = /\bTOP\s*2\b|\bRUNNER[\s-]*UP\b/.test(value);
    const isWinner = /\bWIN(?:NER)?\b|^WIN(?=BTM|LOW|HIGH)/.test(value);

    if (![isEliminated, isBottom, isLow, isSafe, isHigh, isTopThree, isTopTwo, isWinner].some(Boolean)) {
        return null;
    }

    const frontRunnerRank = isWinner ? 8
        : isTopTwo ? 7
        : isTopThree ? 6
        : isHigh ? 5
        : isSafe ? 4
        : isLow ? 3
        : isBottom ? 2
        : 1;
    const bottomFeederRank = isEliminated ? 8
        : isBottom ? 7
        : isLow ? 6
        : isSafe ? 5
        : isHigh ? 4
        : isTopThree ? 3
        : isTopTwo ? 2
        : 1;

    return { frontRunnerRank, bottomFeederRank };
}

function styleWeeklyAwardTrackRecordPlacement(element, placement) {
    const value = String(placement || "").trim().toUpperCase();
    element.className = "placement weekly-awards-placement";
    element.textContent = placement;

    if (value === "WIN") {
        element.style.cssText = "font-weight:bold;background-color:royalblue;color:white;";
    } else if (/^TOP [2-8]$/.test(value)) {
        element.style.cssText = "font-weight:bold;background-color:springgreen;";
    } else if (/^TOP[23]$/.test(value)) {
        element.style.cssText = "background-color:deepskyblue;";
    } else if (value === "HIGH") {
        element.style.cssText = "background-color:lightblue;";
    } else if (value === "LOW") {
        element.style.cssText = "background-color:pink;";
    } else if (/^BTM[1-6]?$/.test(value)) {
        element.style.cssText = "background-color:tomato;";
    } else if (value === "ELIM" || value === "EXT") {
        element.style.cssText = "font-weight:bold;background-color:red;";
    } else if (value === "ELIMINATED") {
        element.style.cssText = "font-weight:bold;background-color:sienna;color:white;";
        element.textContent = "ELIM";
    } else if (value === "WINNER") {
        element.style.cssText = "font-weight:bold;background-color:yellow;";
    } else if (value === "RUNNER UP") {
        element.style.cssText = "font-weight:bold;background-color:silver;";
    }
}

function weeklyAwardsScreen() {
    const screen = new Scene();
    screen.clean();
    screen.createHeader("Weekly Awards");
    setBackgroundToNormal();
    screen.createParagraph("Awards compare the full track record through each episode. Only queens still in the competition at the end of that episode are eligible; ties are shared.");

    const main = document.querySelector("div#MainBlock");
    const allQueens = [...new Set([...currentCast, ...eliminatedCast])].filter(
        queen => queen && Array.isArray(queen.trackRecord)
    );
    const episodeCount = allQueens.reduce(
        (count, queen) => Math.max(count, queen.trackRecord.length),
        -1
    );

    if (!main || episodeCount <= 0) {
        screen.createBold("No completed episode placements are available yet.");
        addStatsTabs(screen, "Weekly Awards");
        addStatsFooter(screen);
        return;
    }

    const addAwardTable = (title, rankKey, comparator) => {
        const episodeTitle = document.createElement("h2");
        episodeTitle.textContent = title;
        main.appendChild(episodeTitle);

        const tableWrap = document.createElement("div");
        tableWrap.setAttribute("class", "coin-flip-scroll");
        tableWrap.style.overflowX = "auto";
        const table = document.createElement("table");
        table.setAttribute("class", "trtable stats-track-table weekly-awards-table");
        table.setAttribute("border", "2");

        const headerRow = document.createElement("tr");
        ["Ep", title.startsWith("Front") ? "Front runner" : "Power bottom", "Placement"].forEach(label => {
            const header = document.createElement("th");
            header.textContent = label;
            headerRow.appendChild(header);
        });
        table.appendChild(headerRow);

        for (let episodeIndex = 0; episodeIndex < episodeCount; episodeIndex++) {
            const episodePlacements = allQueens
                .filter(queen => episodeIndex < queen.trackRecord.length)
                .map(queen => {
                    const placement = String(queen.trackRecord[episodeIndex] || "").trim();
                    const seasonRanks = getWeeklyAwardSeasonRanks(queen, episodeIndex);
                    return seasonRanks && placement
                        ? { queen, placement, rank: seasonRanks[rankKey] }
                        : null;
                })
                .filter(entry => entry && Number.isFinite(entry.rank));
            const bestRank = episodePlacements.reduce(
                (best, entry) => comparator(entry.rank, best) ? entry.rank : best,
                null
            );
            const winners = bestRank === null
                ? []
                : episodePlacements.filter(entry => entry.rank === bestRank);

            const row = document.createElement("tr");
            const episodeCell = document.createElement("td");
            episodeCell.textContent = String(episodeIndex + 1);
            row.appendChild(episodeCell);

            const namesCell = document.createElement("td");
            if (winners.length > 0) {
                const contestants = document.createElement("div");
                contestants.setAttribute("class", "weekly-awards-contestants");
                winners.forEach(entry => {
                    const contestant = document.createElement("span");
                    contestant.setAttribute("class", "weekly-awards-contestant");
                    const image = document.createElement("img");
                    image.setAttribute("alt", "");
                    image.setAttribute("aria-hidden", "true");
                    if (typeof entry.queen.getCurrentImage === "function") {
                        image.src = entry.queen.getCurrentImage();
                    }
                    const name = document.createElement("span");
                    name.textContent = entry.queen.name || "Contestant";
                    contestant.append(image, name);
                    contestants.appendChild(contestant);
                });
                namesCell.appendChild(contestants);
            } else {
                namesCell.textContent = "No ranked placements";
            }
            row.appendChild(namesCell);

            const placementsCell = document.createElement("td");
            if (winners.length > 0) {
                const placementWrap = document.createElement("div");
                placementWrap.setAttribute("class", "weekly-awards-placements");
                winners.forEach(entry => {
                    const placement = document.createElement("span");
                    styleWeeklyAwardTrackRecordPlacement(placement, entry.placement);
                    placementWrap.appendChild(placement);
                });
                placementsCell.appendChild(placementWrap);
            } else {
                placementsCell.textContent = "-";
            }
            row.appendChild(placementsCell);
            table.appendChild(row);
        }

        tableWrap.appendChild(table);
        main.appendChild(tableWrap);
    };

    addAwardTable("Front runner per episode", "frontRunnerRank", (rank, best) => best === null || rank > best);
    addAwardTable("Power bottom per episode", "bottomFeederRank", (rank, worst) => worst === null || rank > worst);

    addStatsTabs(screen, "Weekly Awards");
    addStatsFooter(screen);
}

function createStatsContestantCell(queen, displayName) {
    let cell = document.createElement("td");
    cell.setAttribute("class", "stats-track-name-cell");

    let wrap = document.createElement("div");
    wrap.setAttribute("class", "stats-track-contestant");

    let img = document.createElement("img");
    img.setAttribute("class", "stats-track-contestant-img");
    img.setAttribute("alt", queen && queen.name ? queen.name : "Contestant");
    if (queen && typeof queen.getCurrentImage === "function") {
        img.src = queen.getCurrentImage();
    }
    wrap.appendChild(img);

    let name = document.createElement("span");
    name.setAttribute("class", "stats-track-contestant-name");
    name.innerHTML = displayName || (queen && typeof queen.getTrackRecordDisplayName === "function" ? queen.getTrackRecordDisplayName() : queen?.name || "");
    wrap.appendChild(name);

    cell.appendChild(wrap);
    return cell;
}

function addStatsFooter(screen) {
    screen.createHorizontalLine();
    if (onFinale && !seasonHistoryPreviewMode) {
        screen.createButton("Simulate again!", "reSimulate()");
        screen.createButton("Save to History", "saveSeasonToHistory()");
        screen.createButton("Export Season", "exportCurrentSeasonBackup()");
        screen.createButton("Download", "downloadTR()", "downloadTR");
        screen.createButton("Back to main page", "location.reload()");
    } else {
        screen.createButton("Back", "contestantProgress()");
    }
}



