function normalizePlacementKeyLabel(html) {
    return String(html == null ? "" : html)
        .replace(/<br\s*\/?>/gi, " ")
        .replace(/<[^>]*>/g, " ")
        .replace(/\s+/g, " ")
        .trim()
        .toUpperCase();
}

function getPlacementKeyDescription(label, raw) {
    const has = (k) => Object.prototype.hasOwnProperty.call(PLACEMENT_KEY_DESCRIPTIONS, k);
    if (raw != null && has(raw)) return PLACEMENT_KEY_DESCRIPTIONS[raw];
    if (has(label)) return PLACEMENT_KEY_DESCRIPTIONS[label];
    const compact = label.replace(/[^A-Z0-9]/g, "");
    for (const key of Object.keys(PLACEMENT_KEY_DESCRIPTIONS)) {
        if (key.replace(/[^A-Z0-9]/g, "") === compact) {
            return PLACEMENT_KEY_DESCRIPTIONS[key];
        }
    }
    return `Placeholder description for the “${label}” placement.`;
}

// Stacked track-record markup ("WIN<br>+<br>HIGH") is shown on one line in the key ("WIN + HIGH").
function placementKeyInline(html) {
    return String(html == null ? "" : html)
        .replace(/<br\s*\/?>\s*\+\s*<br\s*\/?>/gi, " + ")
        .replace(/<br\s*\/?>/gi, " ")
        .replace(/\s+/g, " ")
        .trim();
}

function collectPlacementKeyCells() {
    // Reuse the real track record builder (snapshot mode: nothing is drawn) so every swatch is styled exactly like the track record.
    let table = null;
    try {
        table = contestantProgress(true);
    } catch (error) {
        console.error("Placement key: could not read the track record", error);
    }
    const found = new Map();
    if (!table || !table.querySelectorAll) {
        return [];
    }
    table.querySelectorAll("td.placement").forEach((cell) => {
        const style = cell.getAttribute("style") || "";
        if (/url\(/i.test(style)) return;               // portrait cells
        const raw = cell.innerHTML;
        const label = normalizePlacementKeyLabel(raw);
        if (!label || /^[\d.,$%\s-]+$/.test(label)) return;   // empty cells, PPE numbers, dashes
        const key = raw + "|" + style;                   // variants that look different stay separate
        if (!found.has(key)) {
            found.set(key, { label, raw, cell });
        }
    });
    const options = Array.isArray(PLACEMENT_EMOJI_OPTIONS) ? PLACEMENT_EMOJI_OPTIONS : [];
    const order = options.map(normalizePlacementKeyLabel);
    return [...found.values()]
        .map((entry, index) => {
            let rank = options.indexOf(entry.raw);
            if (rank < 0) rank = order.indexOf(entry.label);
            return { ...entry, index, rank };
        })
        .sort((a, b) => {
            const ra = a.rank < 0 ? 9999 + a.index : a.rank;
            const rb = b.rank < 0 ? 9999 + b.index : b.rank;
            return ra - rb;
        });
}

function placementKeyScreen() {
    const screen = new Scene();
    screen.clean();
    screen.createHeader("Placement Key");
    setBackgroundToNormal();
    screen.createParagraph("Every placement that has appeared in this simulation so far, and what it means.");

    const main = document.querySelector("div#MainBlock");
    const entries = collectPlacementKeyCells();

    if (!main || entries.length === 0) {
        screen.createBold("No placements have been recorded yet.");
        addStatsTabs(screen, "Placement Key");
        addStatsFooter(screen);
        return;
    }

    const wrap = document.createElement("div");
    wrap.setAttribute("class", "placement-key-wrap");
    const table = document.createElement("table");
    table.setAttribute("class", "placement-key-table");

    const head = document.createElement("tr");
    ["Swatch", "Meaning"].forEach((text) => {
        const th = document.createElement("th");
        th.textContent = text;
        head.appendChild(th);
    });
    table.appendChild(head);

    entries.forEach((entry) => {
        const row = document.createElement("tr");
        const swatchCell = document.createElement("td");
        swatchCell.setAttribute("class", "placement-key-swatch-cell");
        const swatch = document.createElement("div");
        swatch.setAttribute("class", "placement placement-key-swatch");
        swatch.setAttribute("style", entry.cell.getAttribute("style") || "");
        swatch.innerHTML = placementKeyInline(entry.cell.innerHTML);
        swatchCell.appendChild(swatch);

        const meaning = document.createElement("td");
        meaning.setAttribute("class", "placement-key-meaning");
        meaning.textContent = getPlacementKeyDescription(entry.label, entry.raw);

        row.appendChild(swatchCell);
        row.appendChild(meaning);
        table.appendChild(row);
    });

    wrap.appendChild(table);
    main.appendChild(wrap);

    addStatsTabs(screen, "Placement Key");
    addStatsFooter(screen);
}

function rateAQChart() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Rate-A-Queen History");

    let main = document.querySelector("div#MainBlock");
    let centering = document.createElement("center");

    const toOrdinalRank = (value) => {
        const n = Number(value);
        if (!Number.isFinite(n) || n <= 0) return "-";
        const mod100 = n % 100;
        if (mod100 >= 11 && mod100 <= 13) return `${n}th`;
        const mod10 = n % 10;
        if (mod10 === 1) return `${n}st`;
        if (mod10 === 2) return `${n}nd`;
        if (mod10 === 3) return `${n}rd`;
        return `${n}th`;
    };

    if (!Array.isArray(rateAQ4Chart) || rateAQ4Chart.length === 0) {
        screen.createBold("No Rate-A-Queen rounds were recorded this season.");
    } else {
        const episodes = rateAQ4Chart.map((entry) => ({
            episode: entry?.episode || "-",
            label: entry?.label || "Rate-A-Queen",
            rankings: Array.isArray(entry?.rankings) ? entry.rankings : [],
            votes: Array.isArray(entry?.votes) ? entry.votes : [],
        }));

        const rankingTable = document.createElement("table");
        rankingTable.setAttribute("class", "trtable save-twist-table");
        rankingTable.setAttribute("border", "2");

        const rankingTopHeader = document.createElement("tr");
        rankingTable.appendChild(rankingTopHeader);
        for (let i = 0; i < episodes.length; i++) {
            const ep = episodes[i];
            const th = document.createElement("th");
            th.setAttribute("colspan", "2");
            th.innerHTML = `Episode ${ep.episode}<br><small>${ep.label}</small>`;
            rankingTopHeader.appendChild(th);
        }

        const rankingSubHeader = document.createElement("tr");
        rankingTable.appendChild(rankingSubHeader);
        for (let i = 0; i < episodes.length; i++) {
            const contestantTh = document.createElement("th");
            contestantTh.innerHTML = "Contestant";
            rankingSubHeader.appendChild(contestantTh);

            const rankTh = document.createElement("th");
            rankTh.innerHTML = "Rank";
            rankingSubHeader.appendChild(rankTh);
        }

        const maxRankingRows = episodes.reduce((max, ep) => Math.max(max, ep.rankings.length), 0);
        for (let rowIndex = 0; rowIndex < maxRankingRows; rowIndex++) {
            const row = document.createElement("tr");
            for (let epIndex = 0; epIndex < episodes.length; epIndex++) {
                const ranking = episodes[epIndex].rankings[rowIndex];

                const nameCell = document.createElement("td");
                nameCell.setAttribute("class", "song");
                nameCell.innerHTML = ranking?.name || "-";
                row.appendChild(nameCell);

                const rankCell = document.createElement("td");
                rankCell.setAttribute("class", "song");
                rankCell.innerHTML = toOrdinalRank(ranking?.rank || (ranking ? rowIndex + 1 : 0));
                row.appendChild(rankCell);
            }
            rankingTable.appendChild(row);
        }

        centering.appendChild(rankingTable);

        const votesTitle = document.createElement("p");
        votesTitle.setAttribute("class", "song");
        votesTitle.innerHTML = "Vote Receipts";
        centering.appendChild(votesTitle);

        const votesTable = document.createElement("table");
        votesTable.setAttribute("class", "trtable save-twist-table");
        votesTable.setAttribute("border", "2");

        const votesTopHeader = document.createElement("tr");
        votesTable.appendChild(votesTopHeader);
        for (let i = 0; i < episodes.length; i++) {
            const ep = episodes[i];
            const th = document.createElement("th");
            th.setAttribute("colspan", "3");
            th.innerHTML = `Episode ${ep.episode}`;
            votesTopHeader.appendChild(th);
        }

        const votesSubHeader = document.createElement("tr");
        votesTable.appendChild(votesSubHeader);
        for (let i = 0; i < episodes.length; i++) {
            ["Voter", "Recipient", "Ranking"].forEach((label) => {
                const th = document.createElement("th");
                th.innerHTML = label;
                votesSubHeader.appendChild(th);
            });
        }

        const maxVoteRows = episodes.reduce((max, ep) => Math.max(max, ep.votes.length), 0);
        for (let rowIndex = 0; rowIndex < maxVoteRows; rowIndex++) {
            const row = document.createElement("tr");
            for (let epIndex = 0; epIndex < episodes.length; epIndex++) {
                const vote = episodes[epIndex].votes[rowIndex];
                const rankingList = Array.isArray(vote?.ranking) ? vote.ranking : [];

                const voterCell = document.createElement("td");
                voterCell.setAttribute("class", "song");
                voterCell.innerHTML = vote?.voter || "-";
                row.appendChild(voterCell);

                const recipientCell = document.createElement("td");
                recipientCell.setAttribute("class", "song save-twist-saved");
                recipientCell.innerHTML = vote?.recipient || "-";
                row.appendChild(recipientCell);

                const rankingCell = document.createElement("td");
                rankingCell.setAttribute("class", "song");
                rankingCell.innerHTML = rankingList.length > 0
                    ? rankingList.map((name, idx) => `${idx + 1}. ${name}`).join(" | ")
                    : "-";
                row.appendChild(rankingCell);
            }
            votesTable.appendChild(row);
        }

        centering.appendChild(votesTable);
    }

    if (main) {
        main.appendChild(centering);
    }

    addStatsTabs(screen, "Rate-A-Queen");
    addStatsFooter(screen);
}


function slmStarsTrackRecord() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Summit of Rebirth Stars");
    setBackgroundToNormal();
    let main = document.querySelector("div#MainBlock");
    let centering = document.createElement("center");
    let trackRecords = document.createElement("table");
    trackRecords.setAttribute("id", "trackRecord");
    trackRecords.setAttribute("class", "trtable stats-track-table");
    trackRecords.setAttribute("border", "2");

    const seasonQueensSource = fullCast.length > 0 ? fullCast : [...currentCast, ...eliminatedCast];
    const seasonQueens = [];
    const seenQueens = new Set();
    for (const queen of seasonQueensSource) {
        if (queen && !seenQueens.has(queen)) {
            seenQueens.add(queen);
            seasonQueens.push(queen);
        }
    }

    for (let i = 0; i < seasonQueens.length; i++) {
        getSLMStarsLedgerRow(seasonQueens[i]);
    }

    const rows = slmStarsLedger
        .filter((entry) => entry && entry.queen)
        .sort((a, b) => Number(b.totalP || 0) - Number(a.totalP || 0) || a.queen.name.localeCompare(b.queen.name));

    let maxEpisodes = 0;
    for (let i = 0; i < rows.length; i++) {
        maxEpisodes = Math.max(maxEpisodes, rows[i].episodePoints.length);
    }

    let header = document.createElement("tr");
    trackRecords.appendChild(header);
    let contestantHeader = document.createElement("th");
    contestantHeader.innerHTML = "Contestant";
    contestantHeader.setAttribute("style", "font-weight: bold;");
    header.appendChild(contestantHeader);

    for (let ep = 0; ep < maxEpisodes; ep++) {
        let epHeader = document.createElement("th");
        epHeader.innerHTML = `Ep. ${ep + 1}`;
        epHeader.setAttribute("style", "font-weight: bold;");
        header.appendChild(epHeader);
    }

    let totalHeader = document.createElement("th");
    totalHeader.innerHTML = "Total<br>Points";
    totalHeader.setAttribute("style", "font-weight: bold;");
    header.appendChild(totalHeader);

    const colorByTag = {
        gold: "#f4d300",
        pink: "#efb3c1",
        black: "#8a8a8a",
        rainbow: "#9d42e8",
    };

    const getEpisodeCellStyle = (tags, points) => {
        const safeTags = tags || {};
        const blackCount = Number(safeTags.black || 0);
        if (blackCount >= 2) {
            return "background-color:#e8744b;color:black;font-weight:bold;";
        }

        const orderedTags = ["rainbow", "gold", "pink", "black"];
        const active = orderedTags.filter((tag) => Number(safeTags[tag] || 0) > 0);

        if (active.length >= 2) {
            const first = colorByTag[active[0]];
            const second = colorByTag[active[1]];
            return `background:linear-gradient(135deg, ${first} 0 50%, ${second} 50% 100%);color:${points > 0 ? "white" : "black"};font-weight:bold;`;
        }

        if (active.length === 1) {
            const only = active[0];
            const textColor = only === "black" ? "white" : "black";
            return `background-color:${colorByTag[only]};color:${textColor};font-weight:bold;`;
        }

        return "font-weight:bold;";
    };

    for (let i = 0; i < rows.length; i++) {
        let row = document.createElement("tr");

        row.appendChild(createStatsContestantCell(rows[i].queen, rows[i].queen.name));

        for (let ep = 0; ep < maxEpisodes; ep++) {
            let points = Number(rows[i].episodePoints[ep] || 0);
            let tags = rows[i].episodeTags[ep] || {};
            let epCell = document.createElement("td");
            epCell.setAttribute("class", "rumocracy");
            epCell.innerHTML = points === 0 ? "&ndash;" : (points > 0 ? `+${points}` : `${points}`);
            epCell.setAttribute("style", getEpisodeCellStyle(tags, points));
            row.appendChild(epCell);
        }

        let totalCell = document.createElement("td");
        totalCell.setAttribute("class", "rumocracy");
        totalCell.setAttribute("style", "font-weight:bold;");
        totalCell.innerHTML = Number(rows[i].totalP || 0);
        row.appendChild(totalCell);

        trackRecords.appendChild(row);
    }

    centering.appendChild(trackRecords);

    let br = document.createElement("br");
    centering.appendChild(br);
    main.appendChild(centering);

    addStatsTabs(screen, "Summit of Rebirth Stars");
    addStatsFooter(screen);
}
