function getQueenBottomCountUpToEpisode(queen, epNum) {
    if (!queen || !Array.isArray(queen.trackRecord)) return 1;
    let count = 0;
    const limit = Math.min(epNum, queen.trackRecord.length);
    for (let i = 0; i < limit; i++) {
        const p = String(queen.trackRecord[i] || "").toUpperCase();
        if (/BTM|ELIM|EXT|LOST|QUIT|DEPT/.test(p)) {
            count++;
        }
    }
    return Math.max(1, count);
}

function getHeaderLabelsForCategory(category, subLabel = "") {
    if (category === "audition") {
        return { contestants: `Audition matchup (${subLabel})`, outcome: "Advances to the season" };
    }
    if (category === "top") {
        return { contestants: subLabel ? `Top contestants (${subLabel})` : "Top contestants", outcome: "Winner" };
    }
    if (category === "contestants") {
        return { contestants: subLabel ? `Contestants (${subLabel})` : "Contestants", outcome: "Winner" };
    }
    return { contestants: subLabel ? `Bottom contestants (${subLabel})` : "Bottom contestants", outcome: "Eliminated" };
}

function computeEpisodeMatchupsAnalysis(rawEntries, epNum, allQueens) {
    const isSeasonFinale = Boolean(onFinale && epNum >= episodeChallenges.length);
    const challengeTitle = String(episodeChallenges[epNum - 1] || "");
    const isExplicitSmackdown = /smackdown|lalaparuza|rebirth|tournament|slayoff|battle royale/i.test(challengeTitle) ||
        rawEntries.some(e => /smackdown|lalaparuza/i.test(String(e.rawSong || ""))) ||
        (rawEntries.length >= 3 && !isSeasonFinale);

    // Track queen appearances/losses within this episode to accurately determine bracket round
    const queenLossCount = new Map();
    const queenWinCount = new Map();

    const resolved = [];

    for (let i = 0; i < rawEntries.length; i++) {
        const entry = rawEntries[i];
        const winNames = entry.winnerNames && entry.winnerNames.length > 0
            ? entry.winnerNames
            : (entry.winner ? entry.winner.replace(/<[^>]+>/g, " ").split("&").map(s => s.trim()).filter(Boolean) : []);
        const losNames = entry.loserNames && entry.loserNames.length > 0
            ? entry.loserNames
            : (entry.loser ? entry.loser.replace(/<[^>]+>/g, " ").split("&").map(s => s.trim()).filter(Boolean) : []);

        const allContestants = [...new Set([...winNames, ...losNames])];
        const buildContestantChip = (name) => {
            const queen = allQueens.find(item => item && item.name === name);
            const safeName = escapeSharedDisplayText(name);
            if (!queen || typeof queen.getCurrentImage !== "function") {
                return safeName;
            }
            const safeImage = escapeSharedDisplayText(queen.getCurrentImage());
            return `<span class="ls-queen-chip"><img src="${safeImage}" alt="${safeName}"><span>${safeName}</span></span>`;
        };
        const contestantsText = allContestants.map(buildContestantChip).join(" <span class='ls-versus'>vs.</span> ");

        let songHtml = "";
        if (entry.songName) {
            songHtml = `<span style="color:inherit;font-weight:600;">"${entry.songName}"</span>`;
            if (entry.songArtist) {
                songHtml += `<br><span style="color:inherit;">(${entry.songArtist})</span>`;
            }
        } else if (entry.lsSong) {
            const clean = String(entry.lsSong).replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
            const byIdx = clean.indexOf(" by ");
            if (byIdx !== -1) {
                const title = clean.slice(0, byIdx).trim();
                const artist = clean.slice(byIdx + 4).trim();
                songHtml = `<span style="color:inherit;font-weight:600;">"${title}"</span><br><span style="color:inherit;">(${artist})</span>`;
            } else {
                songHtml = `<span style="color:inherit;font-weight:600;">"${clean}"</span>`;
            }
        } else {
            songHtml = "—";
        }

        const currentLossLevel = Math.max(0, ...allContestants.map(name => queenLossCount.get(name) || 0));
        const currentWinLevel = Math.max(0, ...allContestants.map(name => queenWinCount.get(name) || 0));
        const roundNumber = Math.max(currentLossLevel, currentWinLevel) + 1;

        const eliminatedLosers = losNames.filter(name => {
            const q = allQueens.find(item => item.name === name);
            if (!q) return false;
            const epPlacement = String(q.trackRecord?.[epNum - 1] || "").toUpperCase();
            return /ELIM|EXT|QUIT|DISQ|DEPT/.test(epPlacement);
        });

        const savedQueens = losNames.filter(name => {
            const q = allQueens.find(item => item.name === name);
            if (!q) return false;
            const epPlacement = String(q.trackRecord?.[epNum - 1] || "").toUpperCase();
            return /SAVED|CHOC/.test(epPlacement);
        });

        const isExplicitTop = losNames.length === 0 || winNames.some(name => {
            const q = allQueens.find(item => item.name === name);
            if (!q) return false;
            const epPlacement = String(q.trackRecord?.[epNum - 1] || "").toUpperCase();
            return /WIN|TOP ?2|TOP2/.test(epPlacement) && !/ELIM|BTM/.test(epPlacement);
        });

        const hasCrownWinner = winNames.some(name => {
            const q = allQueens.find(item => item.name === name);
            return q && (q.trackRecord?.includes("WINNER") || (onFinale && currentCast[0] === q));
        });

        let category = "bottom";
        let subLabel = "";
        let outcomeText = "";
        let outcomeColor = "red";
        let outcomeTextColor = "black";

        const isLastMatchupInEpisode = (i === rawEntries.length - 1);

        if (entry.isAudition) {
            category = "audition";
            subLabel = `Match ${i + 1}`;
            outcomeText = winNames.map(escapeSharedDisplayText).join("<br>");
            outcomeColor = "palegreen";
        } else if (isSeasonFinale && hasCrownWinner) {
            category = "top";
            subLabel = "Lip Sync for the Crown";
            outcomeText = winNames.join("<br>");
            outcomeColor = "yellow";
            outcomeTextColor = "black";
        } else if (isSeasonFinale) {
            category = "top";
            subLabel = `Round ${roundNumber}`;
            outcomeText = winNames.join("<br>");
            outcomeColor = allContestants.length >= 3 ? "springgreen" : "royalblue";
            outcomeTextColor = allContestants.length >= 3 ? "black" : "white";
        } else if (isExplicitSmackdown) {
            const isEliminationRound = isLastMatchupInEpisode && (eliminatedLosers.length > 0 || savedQueens.length > 0 || (losNames.length > 0 && !hasCrownWinner));

            if (isEliminationRound) {
                category = "bottom";
                subLabel = "Final Round";
                if (eliminatedLosers.length > 0) {
                    outcomeText = eliminatedLosers.join("<br>");
                    outcomeColor = "red";
                    outcomeTextColor = "white";
                } else if (savedQueens.length > 0) {
                    outcomeText = savedQueens.map(n => `${n} <small>(SAVED)</small>`).join("<br>");
                    outcomeColor = "#FECAA3";
                    outcomeTextColor = "black";
                } else {
                    outcomeText = losNames.join("<br>");
                    outcomeColor = "red";
                    outcomeTextColor = "white";
                }
            } else {
                category = "contestants";
                subLabel = `Round ${roundNumber}`;
                outcomeText = winNames.join("<br>");

                if (roundNumber === 1) {
                    outcomeColor = "#ffd100";
                    outcomeTextColor = "black";
                } else if (roundNumber === 2) {
                    outcomeColor = "#ffae00";
                    outcomeTextColor = "black";
                } else {
                    outcomeColor = "#ff7c00";
                    outcomeTextColor = "black";
                }

                const isSdadhh = winNames.some(name => {
                    const q = allQueens.find(item => item.name === name);
                    return q && String(q.minqdd || "").toLowerCase().includes("sdadhh");
                });
                if (isSdadhh) {
                    outcomeColor = "yellow";
                    outcomeTextColor = "black";
                }
            }
        } else if (isExplicitTop) {
            category = "top";
            subLabel = allContestants.length > 2 ? `Top ${allContestants.length}` : "";
            outcomeText = winNames.join("<br>");
            if (allContestants.length >= 3) {
                outcomeColor = "springgreen";
                outcomeTextColor = "black";
            } else {
                outcomeColor = "royalblue";
                outcomeTextColor = "white";
            }
        } else {
            category = "bottom";
            subLabel = allContestants.length > 2 ? `Bottom ${allContestants.length}` : "";
            if (eliminatedLosers.length > 0) {
                outcomeText = eliminatedLosers.join("<br>");
                outcomeColor = "red";
                outcomeTextColor = "white";
            } else if (savedQueens.length > 0) {
                outcomeText = savedQueens.map(n => `${n} <small>(SAVED)</small>`).join("<br>");
                outcomeColor = "#FECAA3";
                outcomeTextColor = "black";
            } else {
                outcomeText = "None";
                outcomeColor = "white";
                outcomeTextColor = "black";
            }
        }

        winNames.forEach(name => {
            queenWinCount.set(name, (queenWinCount.get(name) || 0) + 1);
        });
        losNames.forEach(name => {
            queenLossCount.set(name, (queenLossCount.get(name) || 0) + 1);
        });

        resolved.push({
            epNum,
            category,
            subLabel,
            contestantsText,
            songHtml,
            outcomeText,
            outcomeColor,
            outcomeTextColor
        });
    }

    return resolved;
}

function allLipsyncsSeason() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Season's Lip Syncs");
    setBackgroundToNormal();

    let main = document.querySelector("div#MainBlock");
    const allQueens = [...currentCast, ...eliminatedCast,
        ...liveAuditionResults.map(entry => ({
            name: entry.name,
            getCurrentImage: () => entry.image
        }))];

    const matchups = [...liveAuditionMatchups, ...(Array.isArray(alots) ? alots : [])];
    if (matchups.length === 0) {
        screen.createBold("There were no lip syncs this season.");
    } else {
        const centering = document.createElement("center");
        centering.style.overflowX = "auto";
        const table = document.createElement("table");
        table.setAttribute("id", "trackRecord");
        table.setAttribute("class", "trtable wiki-lipsync-table");
        table.setAttribute("border", "2");

        // Pre-group raw entries by episode
        const rawByEpisode = new Map();
        matchups.forEach((entry, idx) => {
            const epNum = entry.isAudition ? 0 : Number(entry.epNum) || resolveEpisodeNumber(entry.episode) || (idx + 1);
            if (!rawByEpisode.has(epNum)) {
                rawByEpisode.set(epNum, []);
            }
            rawByEpisode.get(epNum).push(entry);
        });

        // Resolve details with episode context & round tracking
        const byEpisode = new Map();
        rawByEpisode.forEach((rawEntries, epNum) => {
            const resolvedList = computeEpisodeMatchupsAnalysis(rawEntries, epNum, allQueens);
            byEpisode.set(epNum, resolvedList);
        });

        let lastCategoryKey = null;

        byEpisode.forEach((epItems, epNum) => {
            const episodeLabel = epNum === 0 ? "Auditions" : epNum;
            // Group contiguous rows by category + subLabel within the episode
            const groups = [];
            let currentGroup = [];
            let currentKey = null;
            let currentCat = null;
            let currentSub = "";

            epItems.forEach((item) => {
                const key = `${item.category}_${item.subLabel}`;
                if (key !== currentKey) {
                    if (currentGroup.length > 0) {
                        groups.push({ category: currentCat, subLabel: currentSub, items: currentGroup });
                    }
                    currentKey = key;
                    currentCat = item.category;
                    currentSub = item.subLabel;
                    currentGroup = [item];
                } else {
                    currentGroup.push(item);
                }
            });
            if (currentGroup.length > 0) {
                groups.push({ category: currentCat, subLabel: currentSub, items: currentGroup });
            }

            // Total rows rendered for this episode cell (data rows + any category header rows)
            let totalRenderedRows = 0;
            let tempLastKey = lastCategoryKey;
            groups.forEach((g) => {
                const groupKey = `${g.category}_${g.subLabel}`;
                if (groupKey !== tempLastKey) {
                    totalRenderedRows += 1;
                    tempLastKey = groupKey;
                }
                totalRenderedRows += g.items.length;
            });

            let epCellRendered = false;

            groups.forEach((g) => {
                const groupKey = `${g.category}_${g.subLabel}`;
                if (groupKey !== lastCategoryKey) {
                    const labels = getHeaderLabelsForCategory(g.category, g.subLabel);
                    const headerRow = document.createElement("tr");

                    if (!epCellRendered) {
                        headerRow.innerHTML = `
                            <td rowspan="${totalRenderedRows}" style="font-weight: bold; background-color: var(--ss-cell); vertical-align: middle; text-align: center;">${episodeLabel}</td>
                            <th>${labels.contestants}</th>
                            <th style="min-width: 170px;">Song</th>
                            <th style="width: 160px;">${labels.outcome}</th>
                        `;
                        epCellRendered = true;
                    } else {
                        headerRow.innerHTML = `
                            <th>${labels.contestants}</th>
                            <th>Song</th>
                            <th>${labels.outcome}</th>
                        `;
                    }
                    table.appendChild(headerRow);
                    lastCategoryKey = groupKey;
                }

                g.items.forEach((item) => {
                    const tr = document.createElement("tr");
                    if (!epCellRendered) {
                        tr.innerHTML = `
                            <td rowspan="${totalRenderedRows}" style="font-weight: bold; background-color: var(--ss-cell); vertical-align: middle; text-align: center;">${episodeLabel}</td>
                            <td class="ls-contestants">${item.contestantsText}</td>
                            <td class="ls-song">${item.songHtml}</td>
                            <td class="ls-outcome" style="background-color: ${item.outcomeColor}; color: ${item.outcomeTextColor}; font-weight: bold;">${item.outcomeText}</td>
                        `;
                        epCellRendered = true;
                    } else {
                        tr.innerHTML = `
                            <td class="ls-contestants">${item.contestantsText}</td>
                            <td class="ls-song">${item.songHtml}</td>
                            <td class="ls-outcome" style="background-color: ${item.outcomeColor}; color: ${item.outcomeTextColor}; font-weight: bold;">${item.outcomeText}</td>
                        `;
                    }
                    table.appendChild(tr);
                });
            });
        });

        centering.appendChild(table);
        main.appendChild(centering);
    }

    addStatsTabs(screen, "Lip Syncs");
    addStatsFooter(screen);
}

function relationshipChart() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Relationship Chart");
    setBackgroundToNormal();
    let main = document.querySelector("div#MainBlock");
    let centering = document.createElement("center");
    
    let allContestants = [...currentCast, ...eliminatedCast];

    const getSisterLink = (queen, targetQueen) => {
        if (!queen || !Array.isArray(queen.sisters)) return null;
        for (let i = 0; i < queen.sisters.length; i++) {
            const link = queen.sisters[i];
            if (link && link.queen === targetQueen) {
                return link;
            }
        }
        return null;
    };
    
    let relationshipTable = document.createElement("table");
    relationshipTable.setAttribute("id", "relationshipChartTable");
    relationshipTable.setAttribute("class", "trtable");
    relationshipTable.setAttribute("border", "1");
    relationshipTable.setAttribute("style", "margin: 20px auto; border-collapse: collapse; font-size: 11px;");
    
    let headerRow = document.createElement("tr");
    let emptyCorner = document.createElement("th");
    emptyCorner.setAttribute("style", "width: 55px; height: 55px; background-color: #f5ebf5;");
    headerRow.appendChild(emptyCorner);
    
    allContestants.forEach(contestant => {
        let th = document.createElement("th");
        th.setAttribute("style", `width: 55px; height: 55px; padding: 0; background: url('${contestant.getCurrentImage()}') center/cover no-repeat; border: 2px solid #ddd; position: relative;`);
        th.setAttribute("title", contestant.name);
        headerRow.appendChild(th);
    });
    relationshipTable.appendChild(headerRow);

    allContestants.forEach((contestant, idx) => {
        let row = document.createElement("tr");
        
        let rowHeader = document.createElement("td");
        rowHeader.setAttribute("style", `width: 55px; height: 55px; padding: 0; background: url('${contestant.getCurrentImage()}') center/cover no-repeat; border: 2px solid #ddd;`);
        rowHeader.setAttribute("title", contestant.name);
        row.appendChild(rowHeader);
        
        allContestants.forEach((otherContestant, colIdx) => {
            let cell = document.createElement("td");
            cell.setAttribute("style", "width: 40px; height: 40px; text-align: center; vertical-align: middle; padding: 2px; font-weight: bold; font-size: 12px;");
            
            if (idx === colIdx) {
                cell.setAttribute("style", "width: 40px; height: 40px; background-color: #e5e5e5; border: 1px solid #999;");
                cell.innerHTML = "X";
            } else {
                let sisterLink = getSisterLink(contestant, otherContestant);
                if (sisterLink) {
                    let rel = Number(sisterLink.relation);
                    if (!Number.isFinite(rel)) {
                        rel = 0;
                    }

                    cell.style.fontSize = "1.1rem"
                    
                    if (rel > 8) {
                        cell.setAttribute("style", "width: 40px; height: 40px; background-color: #4169E1; color: white;");
                    } else if (rel >= 6 && rel <= 8) {
                        cell.setAttribute("style", "width: 40px; height: 40px; background-color: #90EE90; color: #333;");
                    } else if (rel <= -6) {
                        cell.setAttribute("style", "width: 40px; height: 40px; background-color: #FF6B6B; color: white;");
                    } else {
                        cell.setAttribute("style", "width: 40px; height: 40px; background-color: #D3D3D3; color: #333;");
                    }
                    cell.innerHTML = rel;
                } else {
                    cell.setAttribute("style", "width: 40px; height: 40px; background-color: #f0f0f0;");
                    cell.innerHTML = "—";
                }
            }
            row.appendChild(cell);
        });
        
        relationshipTable.appendChild(row);
    });
    
    centering.appendChild(relationshipTable);
    main.appendChild(centering);
    
    addStatsTabs(screen, "Relationship Chart");
    addStatsFooter(screen);
}

function runwayJudgingChart() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("FPR: Fashion Photo RuView");
    screen.createBold("Episode-by-episode host judging recap.");

    let main = document.querySelector("div#MainBlock");
    let centering = document.createElement("center");
    let trackRecords = document.createElement("table");
    trackRecords.setAttribute("id", "trackRecord");
    trackRecords.setAttribute("class", "trtable stats-table");
    trackRecords.setAttribute("border", "2");
    trackRecords.setAttribute("style", "table-layout: fixed; width: 100%; max-width: 1600px;");

    const logs = [...runwayEpisodeLogs].sort((a, b) => Number(a.episode) - Number(b.episode));
    if (logs.length === 0) {
        let row = document.createElement("tr");
        let empty = document.createElement("td");
        empty.setAttribute("class", "song");
        empty.setAttribute("colspan", "1");
        empty.innerHTML = "No FPR data yet.";
        row.appendChild(empty);
        trackRecords.appendChild(row);
    } else {
        const cellWidthPx = 86;
        const ratingOrder = ["SCOOT", "BOOT", "NOOT", "TOOT", "SHOOT"];
        const clampRatingIndex = (idx) => Math.max(0, Math.min(ratingOrder.length - 1, idx));
        const hashText = (text) => {
            let hash = 0;
            const source = String(text || "");
            for (let i = 0; i < source.length; i++) {
                hash = ((hash << 5) - hash) + source.charCodeAt(i);
                hash |= 0;
            }
            return Math.abs(hash);
        };
        const getHostsForLog = (log) => {
            if (Array.isArray(log.hosts) && log.hosts.length > 0) return log.hosts;
            return [customHost && customHost.name ? customHost.name : "Raven"];
        };
        const getOverallRatingForLog = (log, queenName) => {
            if (!queenName) return "";
            if (log.shoot === queenName) return "SHOOT";
            if (log.topToot === queenName) return "TOP TOOT";
            if (Array.isArray(log.toots) && log.toots.includes(queenName)) return "TOOT";
            if (Array.isArray(log.noots) && log.noots.includes(queenName)) return "NOOT";
            if (Array.isArray(log.boots) && log.boots.includes(queenName)) return "BOOT";
            if (Array.isArray(log.scoots) && log.scoots.includes(queenName)) return "SCOOT";
            return "";
        };
        const getHostSpecificRating = (baseRating, hostName, queenName, episode) => {
            if (baseRating === "TOP TOOT") {
                baseRating = "TOOT";
            }
            const baseIndex = ratingOrder.indexOf(baseRating);
            if (baseIndex === -1) return "";
            const seed = hashText(hostName + "|" + queenName + "|" + episode);
            const offset = (seed % 3) - 1;

            let nextIndex = clampRatingIndex(baseIndex + offset);
            if (baseRating === "SHOOT" && nextIndex < ratingOrder.indexOf("TOOT")) {
                nextIndex = ratingOrder.indexOf("TOOT");
            }
            if (baseRating === "SCOOT" && nextIndex > ratingOrder.indexOf("BOOT")) {
                nextIndex = ratingOrder.indexOf("BOOT");
            }
            return ratingOrder[nextIndex];
        };
        const styleForCell = (value, isTopToot, isShoot) => {
            if (isShoot) {
                return "background-color:#f7cb15;font-weight:800;color:#1f2937;text-align:center;width:" + cellWidthPx + "px;";
            }
            if (isTopToot) {
                return "background-color:#fff35a;font-weight:800;color:#1f2937;text-align:center;width:" + cellWidthPx + "px;";
            }
            if (value === "TOOT") return "background-color:#6cd87a;font-weight:700;color:#065f1f;text-align:center;width:" + cellWidthPx + "px;";
            if (value === "BOOT") return "background-color:#f0a082;font-weight:700;color:#7f1d1d;text-align:center;width:" + cellWidthPx + "px;";
            if (value === "NOOT") return "background-color:#9be29c;font-weight:700;color:#14532d;text-align:center;width:" + cellWidthPx + "px;";
            if (value === "SCOOT") return "background-color:#ef6b6b;font-weight:700;color:#7f1d1d;text-align:center;width:" + cellWidthPx + "px;";
            if (value === "SHOOT") return "background-color:#b8f136;font-weight:700;color:#1f2937;text-align:center;width:" + cellWidthPx + "px;";
            return "background-color:#b7b7bd;text-align:center;width:" + cellWidthPx + "px;";
        };

        const firstNameFrom = (fullName) => String(fullName || "").trim().split(/\s+/)[0] || "";
        const lastInitialFrom = (fullName) => {
            const parts = String(fullName || "").trim().split(/\s+/).filter(Boolean);
            if (parts.length < 2) return "";
            return parts[parts.length - 1].charAt(0).toUpperCase();
        };
        const buildQueenLabelMap = (queens) => {
            const firstNameCounts = {};
            for (let i = 0; i < queens.length; i++) {
                const first = firstNameFrom(queens[i] && queens[i].name);
                if (!first) continue;
                firstNameCounts[first] = (firstNameCounts[first] || 0) + 1;
            }

            const labels = {};
            const usedLabels = new Set();
            const bumpCounts = {};

            for (let i = 0; i < queens.length; i++) {
                const queen = queens[i];
                const full = queen && queen.name ? queen.name : "";
                const first = firstNameFrom(full);
                if (!first) {
                    labels[full] = "";
                    continue;
                }

                let base = first;
                if ((firstNameCounts[first] || 0) > 1) {
                    const initial = lastInitialFrom(full);
                    base = initial ? (first + " " + initial + ".") : first;
                }

                let finalLabel = base;
                if (usedLabels.has(finalLabel)) {
                    bumpCounts[base] = (bumpCounts[base] || 1) + 1;
                    finalLabel = base + " " + bumpCounts[base];
                } else {
                    bumpCounts[base] = 1;
                }

                usedLabels.add(finalLabel);
                labels[full] = finalLabel;
            }

            return labels;
        };

        let headerTop = document.createElement("tr");
        let queenHeader = document.createElement("th");
        queenHeader.setAttribute("class", "nameTR");
        queenHeader.setAttribute("rowspan", "2");
        queenHeader.setAttribute("style", "width:200px;min-width:200px;");
        queenHeader.innerHTML = "Queen";
        headerTop.appendChild(queenHeader);

        for (let i = 0; i < logs.length; i++) {
            const log = logs[i];
            const hosts = getHostsForLog(log);
            let th = document.createElement("th");
            th.setAttribute("class", "nameTR");
            th.setAttribute("colspan", String(hosts.length));
            th.setAttribute("style", "text-align:center;");
            th.innerHTML = "EP " + log.episode + "<br><small>" + String(log.theme || "Best Drag") + "</small>";
            headerTop.appendChild(th);
        }
        trackRecords.appendChild(headerTop);

        let headerBottom = document.createElement("tr");
        for (let i = 0; i < logs.length; i++) {
            const hosts = getHostsForLog(logs[i]);
            for (let h = 0; h < hosts.length; h++) {
                let th = document.createElement("th");
                th.setAttribute("class", "nameTR");
                th.setAttribute("style", "width:" + cellWidthPx + "px;min-width:" + cellWidthPx + "px;text-align:center;");
                th.innerHTML = hosts[h];
                headerBottom.appendChild(th);
            }
        }
        trackRecords.appendChild(headerBottom);

        const seasonQueens = [...currentCast, ...eliminatedCast]
            .filter((queen, index, arr) => queen && arr.findIndex(q => q.name === queen.name) === index);
        const queenLabelMap = buildQueenLabelMap(seasonQueens);

        for (let i = 0; i < seasonQueens.length; i++) {
            let row = document.createElement("tr");
            let name = document.createElement("td");
            name.setAttribute("class", "nameTR");
            name.setAttribute("style", "width:200px;min-width:200px;");
            name.innerHTML = queenLabelMap[seasonQueens[i].name] || seasonQueens[i].getTrackRecordDisplayName();
            row.appendChild(name);

            for (let l = 0; l < logs.length; l++) {
                const log = logs[l];
                const hosts = getHostsForLog(log);
                const queenName = seasonQueens[i].name;
                const overall = getOverallRatingForLog(log, queenName);

                for (let h = 0; h < hosts.length; h++) {
                    let cell = document.createElement("td");
                    cell.setAttribute("class", "song");

                    if (!overall) {
                        cell.innerHTML = "";
                        cell.setAttribute("style", styleForCell("", false, false));
                        row.appendChild(cell);
                        continue;
                    }

                    const isShoot = overall === "SHOOT";
                    const isTopToot = overall === "TOP TOOT";
                    const hostRating = getHostSpecificRating(overall, hosts[h], queenName, log.episode);
                    const displayText = (isShoot || isTopToot) ? "✓" : hostRating;

                    cell.innerHTML = displayText;
                    cell.setAttribute("style", styleForCell(hostRating, isTopToot, isShoot));
                    row.appendChild(cell);
                }
            }

            trackRecords.appendChild(row);
        }
    }

    centering.appendChild(trackRecords);
    centering.appendChild(document.createElement("br"));

    main.appendChild(centering);

    addStatsTabs(screen, "FPR");
    addStatsFooter(screen);
}


let blots = [];
let runwayEpisodeLogs = [];
let trackRecordRunwayThemes = [];
let runwayLastLoggedEpisode = 0;

function stripHtmlForTrackRecord(value) {
    return String(value || "")
        .replace(/<br\s*\/?\s*>/gi, " ")
        .replace(/<[^>]+>/g, "")
        .replace(/\s+/g, " ")
        .trim();
}

function resolveEpisodeNumber(value) {
    if (typeof normalizeHistoryEpisodeValue === "function") {
        const normalized = normalizeHistoryEpisodeValue(value);
        if (Number.isFinite(normalized)) {
            return normalized;
        }
    }
    const text = stripHtmlForTrackRecord(value);
    const match = text.match(/\d+/);
    return match ? Number(match[0]) : NaN;
}

function findSeasonQueenByName(name) {
    const allQueensInSeason = [...currentCast, ...eliminatedCast];
    return allQueensInSeason.find(q => q && q.name === name) || null;
}

function ensureRunwayStatFields(queen) {
    if (!queen) return;
    if (!Number.isFinite(queen.runwayToots)) queen.runwayToots = 0;
    if (!Number.isFinite(queen.runwayBoots)) queen.runwayBoots = 0;
    if (!Number.isFinite(queen.runwayShoots)) queen.runwayShoots = 0;
    if (!Number.isFinite(queen.runwayTopToots)) queen.runwayTopToots = 0;
    if (!Number.isFinite(queen.runwayNoots)) queen.runwayNoots = 0;
    if (!Number.isFinite(queen.runwayScoots)) queen.runwayScoots = 0;
}

function cleanTrackRecordDetailText(value) {
    return stripHtmlForTrackRecord(value)
        .replace(/\s+,/g, ",")
        .replace(/[\s,]+$/g, "")
        .replace(/\s+and$/i, "")
        .trim();
}

function uniqueTrackRecordDetails(values) {
    const details = [];
    for (let i = 0; i < values.length; i++) {
        const detail = values[i];
        if (detail && !details.includes(detail)) {
            details.push(detail);
        }
    }
    return details;
}

function splitRunwayThemesForTrackRecord(value) {
    const text = cleanTrackRecordDetailText(value);
    if (!text) return [];
    return uniqueTrackRecordDetails(text
        .split(/,|\s+and\s+/i)
        .map(theme => cleanTrackRecordDetailText(theme).replace(/\.+$/g, ""))
        .filter(Boolean));
}

function recordTrackRecordRunwayTheme(themeText, episodeNumber = episodeCount) {
    const episode = Number(episodeNumber);
    const theme = cleanTrackRecordDetailText(themeText);
    if (!Number.isFinite(episode) || episode <= 0 || !theme) return;

    const existing = trackRecordRunwayThemes.find(entry => Number(entry.episode) === episode);
    if (existing) {
        existing.theme = theme;
    } else {
        trackRecordRunwayThemes.push({ episode, theme });
    }
}

function formatTrackRecordSongLabel(entry) {
    if (!entry) return "";
    const rawSong = String(entry.rawSong || "");
    const rawTitle = entry.songName || (rawSong.includes(" by ") ? rawSong.slice(0, rawSong.indexOf(" by ")) : rawSong) || entry.lsSong || "";
    const rawArtist = entry.songArtist || (rawSong.includes(" by ") ? rawSong.slice(rawSong.indexOf(" by ") + 4) : "");
    const title = cleanTrackRecordDetailText(rawTitle);
    const artist = cleanTrackRecordDetailText(rawArtist);

    if (!title) return "";
    return artist ? `${title}<br><small>${artist}</small>` : title;
}

function getEpisodeLipSyncSongLabels(episodeNumber) {
    if (!Array.isArray(alots) || !Number.isFinite(episodeNumber)) return "";
    const byEpisode = alots.filter(entry => resolveEpisodeNumber(entry.episode) === episodeNumber);
    if (byEpisode.length === 0) return [];

    return uniqueTrackRecordDetails(byEpisode
        .map(entry => formatTrackRecordSongLabel(entry))
        .filter(Boolean));
}

function getEpisodeLipSyncSongLabel(episodeNumber) {
    const songs = getEpisodeLipSyncSongLabels(episodeNumber);
    return songs.length ? songs.join("<br>") : "";
}

function getEpisodeRunwayThemeLabels(episodeNumber) {
    if (!Number.isFinite(episodeNumber)) return [];
    if (Array.isArray(trackRecordRunwayThemes)) {
        const trLog = trackRecordRunwayThemes.find(entry => Number(entry.episode) === Number(episodeNumber));
        if (trLog && trLog.theme) return splitRunwayThemesForTrackRecord(trLog.theme);
    }
    if (!Array.isArray(runwayEpisodeLogs)) return [];
    const log = runwayEpisodeLogs.find(entry => Number(entry.episode) === Number(episodeNumber));
    return log ? splitRunwayThemesForTrackRecord(log.theme || "") : [];
}

function getEpisodeRunwayThemeLabel(episodeNumber) {
    const themes = getEpisodeRunwayThemeLabels(episodeNumber);
    return themes.length ? themes.join("<br>") : "";
}

function getTrackRecordEpisodeHeaders() {
    return [...episodeChallenges];
}

// Finale Maxi shares its episode number (and header cell) with the finale that follows it, like Rumix & LSFTC does.
function finaleMaxiPairStart() {
    if (finaleMaxiEpIndex < 0 || !finaleMaxiUsed) return -1;
    if (finaleMaxiEpIndex + 1 >= episodeChallenges.length) return -1;
    return finaleMaxiEpIndex;
}

function appendTrackRecordDetailRows(trackRecords, showFlags, hasDuo, mergeInfo, mergeBelgiqueFinale) {
    if (!trShowRunwayTheme && !trShowLipSyncSong) return;

    const labelColspan = 3 + (showFlags ? 1 : 0) + (hasDuo ? 1 : 0);
    const getDetailItems = (startIndex, endIndex, getValues) => {
        const values = [];
        for (let i = startIndex; i <= endIndex; i++) {
            const detailValues = getValues(i + 1);
            values.push(...(Array.isArray(detailValues) ? detailValues : [detailValues]));
        }
        return uniqueTrackRecordDetails(values.map(value => value || "N/A"));
    };

    const addDetailRows = (label, getValues) => {
        const cells = [];
        for (let i = 0; i < episodeChallenges.length; i++) {
            if (mergeBelgiqueFinale && maxiLFTC && i === episodeChallenges.length - 2) {
                cells.push({ colspan: 2, items: getDetailItems(i, i + 1, getValues) });
                break;
            }

            if (finaleMaxiPairStart() === i) {
                if (mergeBelgiqueFinale && maxiLFTC && i === episodeChallenges.length - 3) {
                    cells.push({ colspan: 3, items: getDetailItems(i, i + 2, getValues) });
                    break;
                }
                cells.push({ colspan: 2, items: getDetailItems(i, i + 1, getValues) });
                i += 1;
                continue;
            }

            if (mergeInfo.shouldMerge && i > mergeInfo.mergeEp1 && i <= mergeInfo.mergeEp2) {
                continue;
            }

            if (mergeInfo.shouldMerge && i === mergeInfo.mergeEp1) {
                cells.push({ colspan: mergeInfo.singleColumn ? 1 : mergeInfo.mergeEp2 - mergeInfo.mergeEp1 + 1, items: getDetailItems(mergeInfo.mergeEp1, mergeInfo.mergeEp2, getValues) });
            } else {
                cells.push({ colspan: 1, items: getDetailItems(i, i, getValues) });
            }
        }

        const rowCount = Math.max(1, ...cells.map(cell => Math.max(1, cell.items.length)));
        for (let rowIndex = 0; rowIndex < rowCount; rowIndex++) {
            let row = document.createElement("tr");
            row.setAttribute("class", "tr-detail-row");

            if (rowIndex === 0) {
                let labelCell = document.createElement("td");
                labelCell.setAttribute("class", "nameTR tr-detail-label");
                labelCell.setAttribute("colspan", String(labelColspan));
                labelCell.setAttribute("rowspan", String(rowCount));
                labelCell.innerHTML = label;
                row.appendChild(labelCell);
            }

            for (let i = 0; i < cells.length; i++) {
                const cell = cells[i];
                const items = cell.items.length ? cell.items : ["N/A"];
                if (items.length === 1 && rowIndex > 0) continue;
                if (items.length > 1 && rowIndex >= items.length) continue;

                let detailCell = document.createElement("td");
                detailCell.setAttribute("class", "episodeTR tr-detail-cell");
                detailCell.setAttribute("colspan", String(cell.colspan));
                if (items.length === 1 && rowCount > 1) {
                    detailCell.setAttribute("rowspan", String(rowCount));
                }
                detailCell.innerHTML = "<small>" + items[rowIndex] + "</small>";
                row.appendChild(detailCell);
            }

            trackRecords.appendChild(row);
        }
    };

    if (trShowRunwayTheme) {
        addDetailRows("Runway Category", getEpisodeRunwayThemeLabels);
    }
    if (trShowLipSyncSong) {
        addDetailRows("Lip Sync Song", getEpisodeLipSyncSongLabels);
    }
}

function parseRunwayHostNameList(value) {
    const rawNames = String(value || "")
        .split(/[,;\n|]+/)
        .map(name => name.trim())
        .filter(Boolean);

    const unique = [];
    const seen = new Set();
    for (let i = 0; i < rawNames.length; i++) {
        const key = rawNames[i].toLowerCase();
        if (seen.has(key)) continue;
        seen.add(key);
        unique.push(rawNames[i]);
    }
    return unique;
}

function getSeasonContestantNameSet() {
    const names = new Set();
    const seasonCast = [...currentCast, ...eliminatedCast];
    for (let i = 0; i < seasonCast.length; i++) {
        const name = String(seasonCast[i] && seasonCast[i].name || "").trim().toLowerCase();
        if (name) names.add(name);
    }
    return names;
}

function pickRandomRunwayGuestHostName(excludedNames = new Set()) {
    const guestPool = [
        "Raven",
        "Raja",
        "Aja",
        "Kim Chi",
        "Carson Kressley",
        "Nicole Byer",
        "Ts Madison",
        "Law Roach"
    ];

    if (customHost && customHost.name) {
        guestPool.unshift(customHost.name);
    }

    const available = guestPool.filter(name => !excludedNames.has(String(name || "").toLowerCase()));
    if (!available.length) return "";
    return available[randomNumber(0, available.length - 1)];
}

function getConfiguredRunwayHostNames(sortedQueens) {
    if (!runwayHostQueens) return [];

    const seasonNames = getSeasonContestantNameSet();
    const requested = parseRunwayHostNameList(runwayHostNames);
    const selectedHosts = [];
    const usedNames = new Set();

    for (let i = 0; i < requested.length; i++) {
        const requestedName = requested[i];
        const loweredRequested = requestedName.toLowerCase();

        if (seasonNames.has(loweredRequested)) {
            // If the requested host is actively competing this season, reroll to a guest host.
            const excluded = new Set([...seasonNames, ...usedNames]);
            let replacement = pickRandomRunwayGuestHostName(excluded);
            if (!replacement && sortedQueens.length > 1) {
                const alternativeContestants = sortedQueens.filter(q => q && q.name && q.name.toLowerCase() !== loweredRequested);
                if (alternativeContestants.length) {
                    replacement = alternativeContestants[randomNumber(0, alternativeContestants.length - 1)].name;
                }
            }
            if (replacement) {
                selectedHosts.push(replacement);
                usedNames.add(replacement.toLowerCase());
            }
            continue;
        }

        if (!usedNames.has(loweredRequested)) {
            selectedHosts.push(requestedName);
            usedNames.add(loweredRequested);
        }
    }

    if (!selectedHosts.length) {
        const fallback = pickRandomRunwayGuestHostName(seasonNames);
        if (fallback) {
            selectedHosts.push(fallback);
        }
    }

    return selectedHosts;
}

function resetRunwayJudgingState() {
    runwayEpisodeLogs = [];
    trackRecordRunwayThemes = [];
    runwayLastLoggedEpisode = 0;
}

function recordRunwayJudgingForEpisode(themeText) {
    recordTrackRecordRunwayTheme(themeText);
    if (!runwayJudgingEnabled) return;
    if (!Number.isFinite(episodeCount) || episodeCount <= 0) return;
    if (runwayLastLoggedEpisode === episodeCount) return;

    let contestants = [...currentCast];
    if (slmFormat) {
        contestants = contestants.concat(eliminatedCast.filter(q => !contestants.includes(q)));
    }
    contestants = contestants.filter(q => q && Number.isFinite(q.runwayScore));
    if (contestants.length === 0) return;

    const sortedByRunway = [...contestants].sort((a, b) => Number(b.runwayScore) - Number(a.runwayScore));
    const participants = [...sortedByRunway];

    let shootQueen = null;
    let topTootQueen = null;
    let bootQueens = [];
    let tootQueens = [];
    let scootQueens = [];
    let nootQueens = [];

    if (runwayJudgingMode === "random") {
        const pool = [...participants];
        if (pool.length >= 4) {
            shootQueen = pool.splice(randomNumber(0, pool.length - 1), 1)[0];
        }
        if (pool.length >= 3) {
            topTootQueen = pool.splice(randomNumber(0, pool.length - 1), 1)[0];
        }
        const bootCount = Math.min(2, Math.max(1, Math.floor(participants.length / 6)));
        for (let i = 0; i < bootCount && pool.length > 0; i++) {
            bootQueens.push(pool.splice(randomNumber(0, pool.length - 1), 1)[0]);
        }
        tootQueens = pool;
    } else {
        if (participants.length >= 4) shootQueen = participants[0];
        if (participants.length >= 3) topTootQueen = participants[1];

        const bootCount = participants.length >= 8 ? 2 : 1;
        bootQueens = participants.slice(Math.max(0, participants.length - bootCount));

        tootQueens = participants.filter(queen => {
            if (queen === shootQueen || queen === topTootQueen) return false;
            if (bootQueens.includes(queen)) return false;
            return Number(queen.runwayScore) >= 0;
        });
        if (tootQueens.length === 0) {
            tootQueens = participants.filter(queen => queen !== shootQueen && queen !== topTootQueen && !bootQueens.includes(queen));
        }
    }

    if (bootQueens.length > 0) {
        const worstBoot = bootQueens[bootQueens.length - 1];
        const veryBadLook = Number(worstBoot && worstBoot.runwayScore || 0) >= 34;
        if (veryBadLook || randomNumber(1, 100) <= 12) {
            const scootPick = bootQueens.pop();
            if (scootPick) scootQueens.push(scootPick);
        }
    }

    if (tootQueens.length > 2 && randomNumber(1, 100) <= 24) {
        const midIndex = Math.floor(tootQueens.length / 2);
        const nootPick = tootQueens.splice(midIndex, 1)[0];
        if (nootPick) nootQueens.push(nootPick);
    }

    const hostNames = getConfiguredRunwayHostNames(sortedByRunway);
    const dislikeTargets = scootQueens.length > 0 ? scootQueens : bootQueens;
    const hostDislikeQueen = (hostNames.length > 0 && dislikeTargets.length > 0 && randomNumber(1, 100) <= 35) ? dislikeTargets[0] : null;

    if (shootQueen) {
        ensureRunwayStatFields(shootQueen);
        shootQueen.runwayShoots += 1;
        shootQueen.runwayToots += 1;
    }
    if (topTootQueen) {
        ensureRunwayStatFields(topTootQueen);
        topTootQueen.runwayTopToots += 1;
        if (topTootQueen !== shootQueen) {
            topTootQueen.runwayToots += 1;
        }
    }
    tootQueens.forEach(queen => {
        ensureRunwayStatFields(queen);
        queen.runwayToots += 1;
    });
    bootQueens.forEach(queen => {
        ensureRunwayStatFields(queen);
        queen.runwayBoots += 1;
    });
    nootQueens.forEach(queen => {
        ensureRunwayStatFields(queen);
        queen.runwayNoots += 1;
    });
    scootQueens.forEach(queen => {
        ensureRunwayStatFields(queen);
        queen.runwayScoots += 1;
    });

    runwayEpisodeLogs.push({
        episode: episodeCount,
        theme: String(themeText || "").trim() || "Best Drag",
        mode: runwayJudgingMode,
        hosts: hostNames,
        shoot: shootQueen ? shootQueen.name : "",
        topToot: topTootQueen ? topTootQueen.name : "",
        toots: tootQueens.map(q => q.name),
        boots: bootQueens.map(q => q.name),
        noots: nootQueens.map(q => q.name),
        scoots: scootQueens.map(q => q.name),
        hostDislike: hostDislikeQueen ? hostDislikeQueen.name : ""
    });

    runwayLastLoggedEpisode = episodeCount;
}

function renderLatestRunwayJudgingRecap(screen) {
    if (runwayEpisodeLogs.length === 0) return false;
    const latest = runwayEpisodeLogs[runwayEpisodeLogs.length - 1];
    if (!latest || Number(latest.episode) !== Number(episodeCount)) return false;

    const ratingOrder = ["SCOOT", "BOOT", "NOOT", "TOOT", "SHOOT"];
    const normalizeRating = (value) => {
        const upper = String(value || "").toUpperCase();
        return ratingOrder.includes(upper) ? upper : "NOOT";
    };
    const clampRatingIndex = (idx) => Math.max(0, Math.min(ratingOrder.length - 1, idx));
    const hashText = (text) => {
        let hash = 0;
        const source = String(text || "");
        for (let i = 0; i < source.length; i++) {
            hash = ((hash << 5) - hash) + source.charCodeAt(i);
            hash |= 0;
        }
        return Math.abs(hash);
    };
    const getOverallRatingForQueen = (queenName) => {
        if (!queenName) return "NOOT";
        if (latest.shoot === queenName) return "SHOOT";
        if (latest.topToot === queenName) return "TOOT";
        if (Array.isArray(latest.toots) && latest.toots.includes(queenName)) return "TOOT";
        if (Array.isArray(latest.noots) && latest.noots.includes(queenName)) return "NOOT";
        if (Array.isArray(latest.boots) && latest.boots.includes(queenName)) return "BOOT";
        if (Array.isArray(latest.scoots) && latest.scoots.includes(queenName)) return "SCOOT";
        return "NOOT";
    };
    const getCritiqueForRating = (rating) => {
        switch (rating) {
            case "SHOOT":
                return "that look was runway perfection.";
            case "TOOT":
                return "you delivered a strong runway presentation.";
            case "NOOT":
                return "the look was fine, but it did not stand out.";
            case "BOOT":
                return "the look missed the mark tonight.";
            case "SCOOT":
                return "that look was a complete miss for this category.";
            default:
                return "the look was fine, but it did not stand out.";
        }
    };
    const getHostSpecificRating = (baseRating, hostName, queenName) => {
        const baseIndex = ratingOrder.indexOf(normalizeRating(baseRating));
        const seed = hashText(hostName + "|" + queenName + "|" + latest.episode);
        const offset = (seed % 3) - 1;

        let nextIndex = clampRatingIndex(baseIndex + offset);
        if (baseRating === "SHOOT" && nextIndex < ratingOrder.indexOf("TOOT")) {
            nextIndex = ratingOrder.indexOf("TOOT");
        }
        if (baseRating === "SCOOT" && nextIndex > ratingOrder.indexOf("BOOT")) {
            nextIndex = ratingOrder.indexOf("BOOT");
        }
        return ratingOrder[nextIndex];
    };
    const inCategoryOrder = [];
    const addUnique = (name) => {
        if (!name || inCategoryOrder.includes(name)) return;
        inCategoryOrder.push(name);
    };

    addUnique(latest.shoot);
    addUnique(latest.topToot);
    (latest.toots || []).forEach(addUnique);
    (latest.noots || []).forEach(addUnique);
    (latest.boots || []).forEach(addUnique);
    (latest.scoots || []).forEach(addUnique);

    screen.createHeader("FPR: Fashion Photo RuView");
    screen.createBigText("Category is... " + (latest.theme || "Best Drag"));
    const hosts = (latest.hosts && latest.hosts.length > 0)
        ? latest.hosts
        : [customHost && customHost.name ? customHost.name : "Raven"];

    for (let i = 0; i < inCategoryOrder.length; i++) {
        const queenName = inCategoryOrder[i];
        const queen = findSeasonQueenByName(queenName);
        const overallRating = getOverallRatingForQueen(queenName);
        const critique = getCritiqueForRating(overallRating);

        screen.createHorizontalLine();
        if (queen) {
            screen.createImage(queen.getCurrentImage(), "royalblue");
        }
        screen.createBold(queenName + ", \"" + critique + "\"");

        for (let h = 0; h < hosts.length; h++) {
            const hostRating = getHostSpecificRating(overallRating, hosts[h], queenName);
            screen.createParagraph(hosts[h] + ": It is a " + hostRating + ".");
        }
    }

    if (latest.hostDislike) {
        screen.createBold("The hosts were not feeling " + latest.hostDislike + "'s look tonight.");
    }

    return true;
}

function getRunwayLeaderboardRows() {
    const seasonQueens = [...currentCast, ...eliminatedCast];
    return seasonQueens
        .map(queen => {
            ensureRunwayStatFields(queen);
            return {
                queen,
                toots: queen.runwayToots,
                boots: queen.runwayBoots,
                topToots: queen.runwayTopToots,
                shoots: queen.runwayShoots,
                noots: queen.runwayNoots,
                scoots: queen.runwayScoots
            };
        })
        .sort((a, b) => {
            if (b.shoots !== a.shoots) return b.shoots - a.shoots;
            if (b.topToots !== a.topToots) return b.topToots - a.topToots;
            if (b.toots !== a.toots) return b.toots - a.toots;
            if (a.scoots !== b.scoots) return a.scoots - b.scoots;
            return a.boots - b.boots;
        });
}

