function normalizeSaveTwistNames(value) {
    if (Array.isArray(value)) {
        return value
            .map(entry => {
                if (!entry) return "";
                if (typeof entry === "string") return entry;
                return entry.name || String(entry);
            })
            .map(name => name.trim())
            .filter(Boolean);
    }

    if (!value) return [];
    if (typeof value === "string") {
        return value
            .split(/<br\s*\/?\s*>|\n|,/i)
            .map(name => name.trim())
            .filter(Boolean);
    }

    if (typeof value === "object" && value.name) {
        return [value.name.trim()].filter(Boolean);
    }

    return [String(value).trim()].filter(Boolean);
}

function recordSaveTwist(winner, saved, couldveSaved) {
    saveTwist4Chart.push({
        episode: episodeChallenges.length,
        winner: normalizeSaveTwistNames(winner),
        saved: normalizeSaveTwistNames(saved),
        couldveSaved: normalizeSaveTwistNames(couldveSaved)
    });
}

function normalizeLoteriaTrackRecord(queen) {
    if (!queen || queen.trackRecord.length === 0) return;
    const lastIndex = queen.trackRecord.length - 1;
    const lastRecord = queen.trackRecord[lastIndex];

    if (typeof lastRecord === "string" && lastRecord.toUpperCase().includes("ELIM")) {
        queen.trackRecord[lastIndex] = " BTM2 ";
    } else {
        queen.addToTrackRecord(" BTM2 ");
    }
}

function getLoteriaEligibleEliminations() {
    const episodeStamp = episodeChallenges.length;
    return eliminatedCast.filter(q => {
        const lastTrack = q.trackRecord[q.trackRecord.length - 1] || "";
        const isElim = /ELIM/.test(lastTrack);
        const alreadyProcessed = q.loteriaProcessedEpisode === episodeStamp;
        return isElim && !alreadyProcessed && !q.queenDisqOrDept;
    });
}

function tryLoteriaUndoElimination(screen, eliminatedQueen, couldveSaved = []) {
    if (!loteriaTwist || !eliminatedQueen || dragula_format) return false;
    if (!Array.isArray(judgingpanel) || judgingpanel.length === 0) return false;

    eliminatedQueen.loteriaProcessedEpisode = episodeChallenges.length;

    screen.createHorizontalLine();
    screen.createBold("Before we finalize this elimination... it's time for La Loteria.");
    screen.createBold("The judges must vote unanimously to undo the elimination.");

    const lipsyncBase = typeof eliminatedQueen.lipsyncScore === "number" ? eliminatedQueen.lipsyncScore : 5;
    const saveChance = Math.max(15, Math.min(70, 30 + Math.floor(lipsyncBase * 4)));
    let unanimousSave = true;

    for (let i = 0; i < judgingpanel.length; i++) {
        const judge = judgingpanel[i];
        const votesToSave = randomNumber(1, 100) <= saveChance;
        screen.createImage(judge.image);
        screen.createBold(`${judge.name} votes ${votesToSave ? "to save" : "to not save"} ${eliminatedQueen.name}.`);
        if (!votesToSave) unanimousSave = false;
    }

    if (!unanimousSave) {
        screen.createBold("The vote is not unanimous. The elimination stands.");
        return false;
    }

    const elimIndex = eliminatedCast.indexOf(eliminatedQueen);
    if (elimIndex !== -1) eliminatedCast.splice(elimIndex, 1);
    if (!currentCast.includes(eliminatedQueen)) currentCast.push(eliminatedQueen);

    normalizeLoteriaTrackRecord(eliminatedQueen);
    eliminatedQueen.unfavoritism = Math.max(0, eliminatedQueen.unfavoritism - 2);
    eliminatedQueen.ppe += 1;
    if (eliminatedQueen.rankP === "PREMIERE_JOINT" || (typeof eliminatedQueen.rankP === "string" && eliminatedQueen.rankP.startsWith("tie"))) {
        eliminatedQueen.rankP = 0;
        eliminatedQueen.premiereJointRank = 0;
        eliminatedQueen.premiereJointRankEnd = 0;
    }

    const candidates = couldveSaved.length > 0 ? couldveSaved : [eliminatedQueen];
    recordSaveTwist({ name: "Judges (La Loteria)" }, eliminatedQueen, candidates);
    screen.createImage(eliminatedQueen.getCurrentImage(), "gold");
    screen.createBold(`The votes are unanimous. ${eliminatedQueen.name}, you have been saved by La Loteria!`);
    loteriaTwistUsed = true;
    return true;
}

