let totalCastSize;
function randomNumber(min, max) {
    let randomNumber = Math.floor(Math.random() * (max - min + 1)) + min;
    return randomNumber;
}

function normalizeStrategyLevel(value) {
    const normalized = String(value || "balanced").trim().toLowerCase();
    const aliases = {
        aggressive: "cutthroat",
        defensive: "fairness",
        loyal: "loyalty",
        fair: "fairness",
        patriotic: "patriotism"
    };
    const strategy = aliases[normalized] || normalized;
    const allowed = ["balanced", "cutthroat", "loyalty", "fairness", "patriotism", "chaotic", "mixed", "custom"];
    return allowed.includes(strategy) ? strategy : "balanced";
}

function randomStrategyLevel() {
    const options = ["balanced", "cutthroat", "loyalty", "fairness", "patriotism", "chaotic"];
    return options[randomNumber(0, options.length - 1)];
}

function getStrategyProfile(strategy) {
    if (normalizeStrategyLevel(strategy) === "custom") {
        const readSlider = (id, fallback) => {
            const input = document.getElementById(id);
            const value = Number(input?.value);
            return Number.isFinite(value) ? Math.max(0, Math.min(100, value)) / 100 : fallback;
        };
        return {
            threat: 0.15 + readSlider("strategyCutthroat", 0.25) * 1.1,
            relation: readSlider("strategyLoyalty", 0.5) * 1.8,
            fairness: readSlider("strategyFairness", 0.5) * 1.5,
            patriotism: readSlider("strategyPatriotism", 0.25) * 20,
            rng: readSlider("strategyRng", 0.2)
        };
    }
    const profiles = {
        balanced: { threat: 0.15, relation: 0.35, fairness: 0.35, patriotism: 2.5, rng: 0.2 },
        cutthroat: { threat: 1.1, relation: -0.8, fairness: -0.25, patriotism: 0, rng: 0.2 },
        loyalty: { threat: 0.05, relation: 1.8, fairness: 0.2, patriotism: 1.5, rng: 0.2 },
        fairness: { threat: 0.15, relation: 0, fairness: 1.5, patriotism: 0, rng: 0.2 },
        patriotism: { threat: 0.2, relation: 0.45, fairness: 0.25, patriotism: 20, rng: 0.2 },
        chaotic: { threat: 0, relation: 0, fairness: 0, patriotism: 0, rng: 1 }
    };
    return profiles[normalizeStrategyLevel(strategy)] || profiles.balanced;
}

function syncStrategySliderLabels() {
    ["Cutthroat", "Loyalty", "Fairness", "Patriotism", "Rng"].forEach((name) => {
        const input = document.getElementById("strategy" + name);
        const output = document.getElementById("strategy" + name + "Value");
        if (input && output) output.textContent = input.value + "%";
    });
}

function normalizeStrategyIdentity(value) {
    const normalized = String(value || "").trim().toLowerCase();
    const aliases = {
        usa: "united states",
        us: "united states",
        american: "united states",
        americans: "united states",
        uk: "united kingdom",
        britain: "united kingdom",
        british: "united kingdom"
    };
    return aliases[normalized] || normalized;
}

document.addEventListener("input", (event) => {
    if (event.target && event.target.id && event.target.id.startsWith("strategy")) {
        syncStrategySliderLabels();
    }
});

function normalizePushQueenTarget(value) {
    return String(value || "").trim().toLowerCase();
}

function isPushQueen(queen) {
    if (!queen) return false;
    const target = normalizePushQueenTarget(pushQueenTarget);
    if (!target) return false;
    const queenName = String(queen._name || queen.name || "").trim().toLowerCase();
    return queenName !== "" && queenName === target;
}

function assignAIStrategyToCast(cast) {
    if (!Array.isArray(cast)) return;
    const configured = normalizeStrategyLevel(aiStrategyLevel);
    cast.forEach((queen) => {
        if (!queen) return;
        if (configured === "mixed") {
            queen.strategyLevel = randomStrategyLevel();
            return;
        }
        queen.strategyLevel = configured;
    });
}

// Chaos mode helper function to boost chaotic event probabilities
function chaosBoost(baseThreshold, multiplier = 2.5) {
    if (!chaosMode) return baseThreshold;
    // Increase the threshold to make events more likely
    // For example: if base is 50, chaos makes it 75 (50 + (100-50)*0.5)
    // if base is 8, chaos makes it ~28 (8 * multiplier, capped at reasonable values)
    let boosted = Math.min(95, baseThreshold * multiplier);
    return Math.round(boosted);
}

function sortPerformances(cast) {
    const weightedScore = (queen) => {
        const base = Number(queen?.performanceScore || 0);
        if (!Number.isFinite(base)) return 0;
        // Push target gets a subtle nudge; this is intentionally small to avoid hard rigging.
        return base + (isPushQueen(queen) ? -1.5 : 0);
    };
    cast.sort((a, b) => weightedScore(a) - weightedScore(b));
}
//generate spaces to insert cast:
function generateSpace() {
    let castSize = document.querySelector("input#castSize").valueAsNumber;
    totalCastSize = castSize;
    let castSelection = document.querySelector("p#castSelection");
    castSelection.innerHTML = '';
    if (totalCastSize < 5) {
        window.alert("Please, use at least 5 queens on your cast!");
    } else if (totalCastSize > 20) {
        window.alert("Please, use less than 20 queens in your cast!");
    } else {
        for (let i = 0; i < castSize; i++) {
            let select = document.createElement("select");
            select.setAttribute("class", "queenList");
            select.setAttribute("id", i.toString());
            select.setAttribute("onchange", "setImage()");
            let img = document.createElement("img");
            img.setAttribute("class", "images");
            img.setAttribute("id", "image" + i.toString());
            img.setAttribute("style", "width: 105px; height: 105px;")
            let p = document.createElement("p");
            p.appendChild(img);
            if (document.getElementById("onlyCustomQueens").checked == true) {
                let customy = allQueens.filter(function (queen) { return queen.customqueen == true; });
                for (let k = 0; k < customy.length; k++) {
                    let option = document.createElement("option");
                    option.innerHTML = customy[k].name;
                    option.value = customy[k].getCurrentImage();
                    select.add(option);
                }
                select.selectedIndex = randomNumber(0, customy.length - 1);
            }
            else {
                for (let k = 0; k < allQueens.length; k++) {
                    let option = document.createElement("option");
                    option.innerHTML = allQueens[k].name;
                    option.value = allQueens[k].getCurrentImage();
                    select.add(option);
                }
                select.selectedIndex = randomNumber(0, allQueens.length - 1);
            }
            let br = document.createElement("br");
            castSelection.appendChild(p);
            castSelection.appendChild(select);
            castSelection.appendChild(br);
        }
    }
    setImage();
}
function setImage() {
    let images = document.getElementsByClassName("images");
    for (let i = 0; i < images.length; i++) {
        let img = document.getElementById("image" + i.toString());
        let select = document.getElementById(i.toString());
        if (img && select && select.options && select.selectedIndex >= 0) {
            img.src = select.options[select.selectedIndex].value;
        }
    }
}
