function applyPresetImages(cast) {
    if (cast.imagePresets) {
        cast.forEach(queen => {
            const queenName = queen._name;
            if (queenName in cast.imagePresets) {
                let imageIndex = cast.imagePresets[queenName];
                if (queen.images && imageIndex < queen.images.length) {
                    queen.currentImageIndex = imageIndex;
                }
            }
        });
    }
}

