let mobileNavShow;
let mobileNavHide;

function mobileNavToogle() {
    if (!mobileNavShow || !mobileNavHide) return;
    document.querySelector('body').classList.toggle('mobile-nav-active');
    mobileNavShow.classList.toggle('d-none');
    mobileNavHide.classList.toggle('d-none');
}

function initMobileNav() {
    if (document.body.dataset.navInit === "true") return;

    mobileNavShow = document.querySelector('.mobile-nav-show');
    mobileNavHide = document.querySelector('.mobile-nav-hide');
    const toggles = document.querySelectorAll('.mobile-nav-toggle');

    if (!mobileNavShow || !mobileNavHide || !toggles.length) return;

    toggles.forEach(el => {
        el.addEventListener('click', function (event) {
            event.preventDefault();
            mobileNavToogle();
        });
    });

    // Close menu when any navbar link is clicked (not just hash links)
    document.querySelectorAll('#navbar a').forEach(navbarlink => {
        navbarlink.addEventListener('click', () => {
            if (navbarlink.closest('.dropdown') && navbarlink.parentElement?.classList.contains('dropdown')) {
                return;
            }

            if (document.querySelector('.mobile-nav-active')) {
                mobileNavToogle();
            }
        });
    });

    const navDropdowns = document.querySelectorAll('.navbar .dropdown > a');
    navDropdowns.forEach(el => {
        el.addEventListener('click', function (event) {
            if (document.querySelector('.mobile-nav-active')) {
                event.preventDefault();
                this.classList.toggle('active');
                this.nextElementSibling.classList.toggle('dropdown-active');

                let dropDownIndicator = this.querySelector('.dropdown-indicator');
                if (dropDownIndicator) {
                    dropDownIndicator.classList.toggle('bi-chevron-up');
                    dropDownIndicator.classList.toggle('bi-chevron-down');
                }
            }
        });
    });

    // Close menu when clicking outside of the navbar
    document.addEventListener('click', function (event) {
        const navbar = document.querySelector('.navbar');
        const mobileNavShow = document.querySelector('.mobile-nav-show');
        
        if (!navbar || !mobileNavShow) return;
        
        // Check if click is outside navbar and outside the toggle button
        if (document.querySelector('.mobile-nav-active') && 
            !navbar.contains(event.target) && 
            !mobileNavShow.contains(event.target) &&
            !document.querySelector('.mobile-nav-hide').contains(event.target)) {
            mobileNavToogle();
        }
    }, true); // Use capture phase to ensure it fires before other handlers

    // Close menu when window is resized to desktop size
    window.addEventListener('resize', () => {
        if (window.matchMedia("(min-width: 1280px)").matches) {
            // Screen is larger than mobile breakpoint
            const body = document.querySelector('body');
            if (body && body.classList.contains('mobile-nav-active')) {
                mobileNavToogle();
            }
        }
    });

    document.body.dataset.navInit = "true";
}

initMobileNav();
document.addEventListener("navbar:loaded", initMobileNav);
const tabs = document.querySelectorAll('.tab-btn');
const all_content = document.querySelectorAll('.content-tab');
tabs.forEach((tab, index) => {
    tab.addEventListener('click', (e) => {
        tabs.forEach(tab => {
            tab.classList.remove('active');
        })
        tab.classList.add('active');

        all_content.forEach(content => {
            content.classList.remove('active');
        })
        all_content[index].classList.add('active');
    })
});

let allCustomCasts = [];
if (localStorage.getItem("customCasts") != null) {
    allCustomCasts = JSON.parse(localStorage.getItem("customCasts") || "{}");
}
// remove any stored custom casts that reference a prohibited name (Lexi Love)
if (allCustomCasts && allCustomCasts.length) {
    const originalLen = allCustomCasts.length;
    allCustomCasts.forEach(cast => {
        if (cast && Array.isArray(cast.cast)) {
            cast.cast = cast.cast.filter(entry => {
                if (!entry) return false;
                if (typeof entry === 'string') return entry.trim().toLowerCase() !== 'lexi love';
                if (typeof entry === 'object') {
                    const n = entry._name || entry.name || '';
                    return String(n).trim().toLowerCase() !== 'lexi love';
                }
                return true;
            });
        }
    });
    // remove any empty casts left after cleaning
    allCustomCasts = allCustomCasts.filter(c => c && Array.isArray(c.cast) && c.cast.length > 0 || (c && c.name && String(c.name).trim().toLowerCase() !== 'lexi love'));
    if (allCustomCasts.length !== originalLen) localStorage.setItem('customCasts', JSON.stringify(allCustomCasts));
}
