if (document.location.pathname.includes("predef.html")) {

    const tabBox = document.querySelector('.tab-box');
    const grColums = document.querySelectorAll('.content-seasons');
    grColums.forEach((sin) => {
        let number = sin.children.length;
        sin.classList.remove('cs-count-1', 'cs-count-2', 'cs-count-odd', 'cs-count-even');
        if (number === 1) sin.classList.add('cs-count-1');
        else if (number === 2) sin.classList.add('cs-count-2');
        else if (number % 2 === 1) sin.classList.add('cs-count-odd');
        else sin.classList.add('cs-count-even');
    });
    // Arrows removed: enable smooth native scrolling for tab row
    if (tabBox) {
        tabBox.style.scrollBehavior = 'smooth';
        tabBox.setAttribute('aria-label', 'Franchise tabs');
    }

    if (allCustomCasts.length > 0) {
        const holder = document.getElementById("custom-cast-holder");
        holder.innerHTML = "";

        if (allCustomCasts.length > 0) {
            const holder = document.getElementById("custom-cast-holder");
            holder.innerHTML = "";

            allCustomCasts.forEach((castObj, index) => {
                const card = document.createElement("div");
                card.className = "content-season";

                card.innerHTML = `
                    <h3 class="content-season-title">${castObj.name}</h3>

                    <div class="cast-buttons">
                        <button onclick="simulateCustomCast(${index})" title="Simulate">
                            Simulate
                        </button>
                        <button onclick="openTrackRecordModeFromCustomCast(${index})" class="tr-mode-btn" title="Track Record Mode">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <br>
                        <button onclick="editCustomCast(${index})" title="Edit">
                            <i class="fa-solid fa-cog"></i>
                        </button>

                        <button onclick="deleteCustomCast(${index})" class="danger" title="Delete">
                            <i class="fa-solid fa-trash"></i>
                        </button>
                    </div>
                `;

                holder.appendChild(card);
            });
        }
    }
}

async function editCustomCast(index) {
    const cast = allCustomCasts[index];
    if (!cast) return;

    const newName = await window.showInHousePrompt("Edit cast name:", cast.name, "Rename Custom Cast");
    if (newName === null || !String(newName).trim()) return;

    cast.name = String(newName).trim();
    localStorage.setItem("customCasts", JSON.stringify(allCustomCasts));

    location.reload();
}

async function deleteCustomCast(index) {
    const confirmed = await window.showInHouseConfirm("Are you sure you want to delete this custom cast?", "Delete Custom Cast");
    if (!confirmed) return;

    allCustomCasts.splice(index, 1);
    localStorage.setItem("customCasts", JSON.stringify(allCustomCasts));

    location.reload();
}

function openTrackRecordModeFromCustomCast(index) {
    const castObj = allCustomCasts[index];
    if (!castObj) {
        alert("Cast not found.");
        return;
    }

    const options = castObj.options || {};
    const format = options.format || "";
    const finale = options.finale || "";
    const premiere = options.premiere || "";
    const returning = options.returning || "";

    const queenObjects = [];

    for (const entry of (castObj.cast || [])) {
        if (typeof entry === 'string') {
            let found = allQueens.find(q => q.name === entry);
            if (!found) {
                const cust = allCustomQueens.find(c => (c._name || c.name) === entry || c.name === entry);
                if (cust) {
                    if (typeof cust.getCurrentImage === 'function') {
                        found = cust;
                    } else {
                        const name = cust._name || cust.name || entry;
                        const acting = cust._actingStat ?? cust.acting ?? 0;
                        const comedy = cust._comedyStat ?? cust.comedy ?? 0;
                        const dance = cust._danceStat ?? cust.dance ?? 0;
                        const design = cust._designStat ?? cust.design ?? 0;
                        const improv = cust._improvStat ?? cust.improv ?? 0;
                        const runway = cust._runwayStat ?? cust.runway ?? 0;
                        const lipsync = cust._lipsyncStat ?? cust.lipsync ?? 0;
                        const images = cust.images || cust._images || cust.image || "noimage";
                        const newQ = new Queen(name, acting, comedy, dance, design, improv, runway, lipsync, images, true);
                        newQ.country = cust.country || cust._country || null;
                        newQ.customqueen = true;
                        const idx = allCustomQueens.indexOf(cust);
                        if (idx !== -1) allCustomQueens[idx] = newQ;
                        allQueens.push(newQ);
                        found = newQ;
                    }
                }
            }
            if (found) queenObjects.push(found);
        } else if (entry && typeof entry === 'object') {
            const name = entry._name || entry.name;
            const acting = entry._actingStat ?? entry.acting ?? 0;
            const comedy = entry._comedyStat ?? entry.comedy ?? 0;
            const dance = entry._danceStat ?? entry.dance ?? 0;
            const design = entry._designStat ?? entry.design ?? 0;
            const improv = entry._improvStat ?? entry.improv ?? 0;
            const runway = entry._runwayStat ?? entry.runway ?? 0;
            const lipsync = entry._lipsyncStat ?? entry.lipsync ?? 0;
            const images = entry.images || entry._images || entry.image || "noimage";
            const newQ = new Queen(name, acting, comedy, dance, design, improv, runway, lipsync, images, true);
            newQ.customqueen = true;
            queenObjects.push(newQ);
        }
    }

    if (queenObjects.length === 0) {
        alert("No valid contestants found in this custom cast.");
        return;
    }

    openTrackRecordMode(queenObjects, format, finale, premiere, returning, castObj.name);
}

function simulateCustomCast(index) {
    const castObj = allCustomCasts[index];
    if (!castObj) {
        alert("Cast not found.");
        return;
    }

    const options = castObj.options || {};

    const format = options.format || "";
    const finale = options.finale || "";
    const premiere = options.premiere || "";
    const returning = options.returning || "";

    const queenObjects = [];

    for (const entry of (castObj.cast || [])) {
        if (typeof entry === 'string') {
            let found = allQueens.find(q => q.name === entry);
            if (!found) {
                const cust = allCustomQueens.find(c => (c._name || c.name) === entry || c.name === entry);
                if (cust) {
                    if (typeof cust.getCurrentImage === 'function') {
                        found = cust;
                    } else {
                        const name = cust._name || cust.name || entry;
                        const acting = cust._actingStat ?? cust.acting ?? 0;
                        const comedy = cust._comedyStat ?? cust.comedy ?? 0;
                        const dance = cust._danceStat ?? cust.dance ?? 0;
                        const design = cust._designStat ?? cust.design ?? 0;
                        const improv = cust._improvStat ?? cust.improv ?? 0;
                        const runway = cust._runwayStat ?? cust.runway ?? 0;
                        const lipsync = cust._lipsyncStat ?? cust.lipsync ?? 0;
                        const images = cust.images || cust._images || cust.image || "noimage";
                        const newQ = new Queen(name, acting, comedy, dance, design, improv, runway, lipsync, images, true);
                        newQ.customqueen = true;
                        const idx = allCustomQueens.indexOf(cust);
                        if (idx !== -1) allCustomQueens[idx] = newQ;
                        allQueens.push(newQ);
                        found = newQ;
                    }
                }
            }
            if (found) queenObjects.push(found);
        } else if (entry && typeof entry === 'object') {
            const name = entry._name || entry.name;
            const acting = entry._actingStat ?? entry.acting ?? 0;
            const comedy = entry._comedyStat ?? entry.comedy ?? 0;
            const dance = entry._danceStat ?? entry.dance ?? 0;
            const design = entry._designStat ?? entry.design ?? 0;
            const improv = entry._improvStat ?? entry.improv ?? 0;
            const runway = entry._runwayStat ?? entry.runway ?? 0;
            const lipsync = entry._lipsyncStat ?? entry.lipsync ?? 0;
            const images = entry.images || entry._images || entry.image || "noimage";
            const country = entry.country || entry._country || "";
            const customFlag = true;

            let existing = findQueenByUid(allQueens, entry.uid || name);
            if (!existing) {
                const newQ = new Queen(name, acting, comedy, dance, design, improv, runway, lipsync, images, customFlag);
                newQ.customqueen = true;
                newQ.country = country || null;
                allCustomQueens.push(newQ);
                allQueens.push(newQ);
                existing = newQ;
            }
            queenObjects.push(existing);
        }
    }

    if (queenObjects.length === 0) {
        alert("No valid queens found for this cast.");
        return;
    }

    saveCustomQueens();

    predefCast(queenObjects, format, finale, premiere, returning);
}


