function addImagesToPredef() {
    if (document.getElementById("usseason1") != undefined) {
        for (let i = 0; i < imgTxtPrdf.length; i++) {
            document.getElementById(imgTxtPrdf[i].id).style.background = "url('" + imgTxtPrdf[i].link + "')";
            document.getElementById(imgTxtPrdf[i].id).style.backgroundRepeat = "no-repeat";
            document.getElementById(imgTxtPrdf[i].id).style.backgroundSize = "cover";
            document.getElementById(imgTxtPrdf[i].id).style.backgroundPosition = "center";
        }
    }
}

addImagesToPredef();

const getVal = id => document.getElementById(id)?.value;
const isChecked = id => document.getElementById(id)?.checked;
const rand = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;

function applySquareTRClass() {
    document.body.classList.toggle("tr-square", squareTR);
    document.body.classList.toggle("tr-square-pics", squareTRPictures);
}

function applyRoundTRClass() {
    document.body.classList.toggle("tr-round", roundTR);
}

function populatePushQueenTargetDropdown() {
    const dropdown = document.getElementById("pushQueenTarget");
    if (!dropdown || !currentCast || currentCast.length === 0) return;
    
    const previousValue = dropdown.value;
    const options = ['<option value="">-- Select Queen --</option>'];
    
    for (const queen of currentCast) {
        const queenName = queen.name || "";
        options.push(`<option value="${queenName}">${queenName}</option>`);
    }
    
    dropdown.innerHTML = options.join("");
    
    if (previousValue && [...currentCast].some(q => q.name === previousValue)) {
        dropdown.value = previousValue;
    } else {
        dropdown.value = "";
    }
}

