function addConfettiEffect() {
    if (document.getElementById("confetti-container")) return;

    const container = document.createElement("div");
    container.id = "confetti-container";
    Object.assign(container.style, {
        position: "fixed",
        top: "0",
        left: "0",
        width: "100%",
        height: "100%",
        pointerEvents: "none",
        overflow: "hidden",
        zIndex: "9999"
    });
    document.body.appendChild(container);

    if (!document.querySelector("#confettiAnimation")) {
        const style = document.createElement("style");
        style.id = "confettiAnimation";
        style.textContent = `
            @keyframes confettiRain {
                0% {
                    transform: translate3d(0, -12vh, 0) rotate(0deg);
                    opacity: 0;
                }
                10% {
                    opacity: 1;
                }
                100% {
                    transform: translate3d(var(--drift-x, 0px), 112vh, 0) rotate(var(--spin-deg, 720deg));
                    opacity: 0.95;
                }
            }
        `;
        document.head.appendChild(style);
    }

    const colors = ["#ff4d6d", "#ffd166", "#06d6a0", "#118ab2", "#9b5de5", "#ff9f1c"];
    const spawnPiece = () => {
        const piece = document.createElement("div");
        piece.style.position = "absolute";
        piece.style.left = Math.random() * 100 + "vw";
        piece.style.top = "-12vh";
        piece.style.width = 4 + Math.random() * 9 + "px";
        piece.style.height = 6 + Math.random() * 13 + "px";
        piece.style.borderRadius = Math.random() > 0.5 ? "2px" : "999px";
        piece.style.background = colors[Math.floor(Math.random() * colors.length)];
        piece.style.opacity = (0.65 + Math.random() * 0.35).toString();
        piece.style.transform = `rotate(${Math.random() * 360}deg)`;
        piece.style.setProperty("--drift-x", `${-90 + Math.random() * 180}px`);
        piece.style.setProperty("--spin-deg", `${540 + Math.random() * 900}deg`);
        piece.style.animation = `confettiRain ${3.8 + Math.random() * 3.8}s linear forwards`;
        piece.addEventListener("animationend", () => piece.remove(), { once: true });
        container.appendChild(piece);

        if (Math.random() > 0.68) {
            const twin = piece.cloneNode(true);
            twin.style.left = Math.random() * 100 + "vw";
            twin.style.animationDuration = `${3.6 + Math.random() * 4.2}s`;
            twin.style.setProperty("--drift-x", `${-110 + Math.random() * 220}px`);
            twin.addEventListener("animationend", () => twin.remove(), { once: true });
            container.appendChild(twin);
        }
    };

    for (let i = 0; i < 45; i++) spawnPiece();
    setInterval(spawnPiece, 150);
}


