function frEp() {
    let select = document.getElementById("challenge");
    if (!select || !select.options || select.selectedIndex < 0) return;

    const selectedValue = select.options[select.selectedIndex].value;
    const selectedChallenge = FIRST_EPISODE_CHALLENGE_OPTIONS.find((option) => option.value === selectedValue) || FIRST_EPISODE_CHALLENGE_OPTIONS[0];

    firstEpisodeChallengeCommand = selectedChallenge.command;
    setLegacyFirstEpisodeFlags(selectedChallenge.legacyFlag || 0);

}
//see if there is two of the same queens:
function duplicateQueens(cast) {
    let valuesAlreadySeen = [];
    for (let i = 0; i < cast.length; i++) {
        let value = cast[i];
        if (valuesAlreadySeen.indexOf(value) !== -1) {
            currentCast = [];
            return true;
        }
        valuesAlreadySeen.push(value);
    }
    return false;
}
function shuffle(array) {
    let currentIndex = array.length, randomIndex;
    // While there remain elements to shuffle...
    while (0 !== currentIndex) {
        // Pick a remaining element...
        randomIndex = Math.floor(Math.random() * currentIndex);
        currentIndex--;
        // And swap it with the current element.
        [array[currentIndex], array[randomIndex]] = [
            array[randomIndex], array[currentIndex]
        ];
    }
    return array;
}
