        const cutoffScore = total[Math.max(0, baseTopCount - 1)].performanceScore;
        const tieInclusiveTop = total.filter(q => q.performanceScore <= cutoffScore);
        topQueens = tieInclusiveTop.filter((q, index, arr) => arr.indexOf(q) === index);
