let homeTrigger = 0;
let forceCallout = false;
let calloutUsed = false;
let calloutCondemnChance = 50;
function applyPendingLipstickTargets() {
    if (!lipstickDrawTwist || pendingLipstickTargets.length === 0) return [];

    const predictedWinners = new Set(
        (Array.isArray(rigWB2Winners) ? rigWB2Winners : [])
            .map(name => currentCast.find(q => q.name === name))
            .filter(Boolean)
    );
    if (predictedWinners.size === 0 && topQueens.length > 0) {
        const likelyWinners = topQueens.map(queen => ({
            queen,
            score: queen.performanceScore - (rigEPOutcome ? 0 : queen.runwayScore - queen.favoritism)
        })).sort((a, b) => a.score - b.score);
        predictedWinners.add(likelyWinners[0].queen);
        if (
            likelyWinners.length > 1 &&
            (rigWB2DoubleWin || likelyWinners[0].score === likelyWinners[1].score)
        ) {
            predictedWinners.add(likelyWinners[1].queen);
        }
    }

    const forcedTargets = [...new Set(pendingLipstickTargets)]
        .filter(q => currentCast.includes(q) && !predictedWinners.has(q))
        .slice(0, 2);
    pendingLipstickTargets = [];
    if (forcedTargets.length === 0) return [];

    lipstickTargetsForcedThisEpisode = true;
    topQueens = topQueens.filter(q => !forcedTargets.includes(q));
    const remainingBottoms = bottomQueens.filter(q => !forcedTargets.includes(q));
    const candidates = [...new Set([
        ...remainingBottoms,
        ...currentCast.filter(q => !forcedTargets.includes(q) && !predictedWinners.has(q))
    ])].sort((a, b) => b.performanceScore - a.performanceScore);
    const bottomFillers = candidates.slice(0, 2 - forcedTargets.length);

    bottomQueens = [...forcedTargets, ...bottomFillers];
    thirdqueen = false;
    fourthqueen = false;
    rigbtm3 = false;
    return forcedTargets;
}

function judgingScreen() {
    ensureJudgingPools();
    enforceForcedBottomThree();
    const lipstickForcedTargets = applyPendingLipstickTargets();

    let judgingScreen = new Scene();
    judgingScreen.clean();
    judgingScreen.createHeader("Judging!");
    if (lipstickForcedTargets.length > 0) {
        judgingScreen.createBold(`${lipstickForcedTargets.map(q => q.name).join(" and ")} were targeted by lipstick and are automatically in the Bottom 2 this week.`);
        judgingScreen.createHorizontalLine();
    }
    if (isNoTeamFlag) {
        isNoTeamFlag = false;
        judgingScreen.createBold("This week you competed as teams. But tonight you'll be judged individually.")
        judgingScreen.createHorizontalLine();
    }
    judgingScreen.createBold("Based on tonight's performances...");
    if (!solidbk) {
        setBackgroundToStage();
    }
    if (slmFormat) {
        let total = [...currentCast, ...eliminatedCast];
        shuffle(total);
        for (let i = 0; i < total.length; i++) {
            judgingScreen.createImage(total[i].getCurrentImage(), "cyan");
        }
        judgingScreen.createBold("", "judged");
        let judged = document.getElementById("judged");
        for (let i = 0; i < total.length; i++) {
            judged.innerHTML += `${total[i].name}, `;
        }
        judged.innerHTML += "you will all be recieving feedback on your performances...";
        judgingScreen.createButton("Proceed", "critiqueScreen()");
        return;
    }
    if (!lipstickTargetsForcedThisEpisode && bottomQueens.length != 3) {
        if (shouldForceBottomThree()) {
            while (bottomQueens.length < 3) {
                const candidates = currentCast.filter(q => !bottomQueens.includes(q) && q !== topQueens[0]);
                if (candidates.length === 0) break;
                candidates.sort((a, b) => b.performanceScore - a.performanceScore);
                bottomQueens.push(candidates[0]);
            }
        }
    }
    const pacingBottomCount = getSeasonPacingBottomCount();
    while (!lipstickTargetsForcedThisEpisode && pacingBottomCount > bottomQueens.length) {
        const candidates = currentCast.filter(q => !bottomQueens.includes(q) && !topQueens.includes(q));
        if (candidates.length === 0) break;
        candidates.sort((a, b) => b.performanceScore - a.performanceScore);
        bottomQueens.push(candidates[0]);
    }
    shuffle(bottomQueens);
    shuffle(topQueens);
    if ((forceCallout || randomNumber(0, 100) < 1) && !calloutUsed && !slmFormat) {
        forceCallout = false;
        calloutUsed = true;
        const ruleBreakerNr = randomNumber(1, 2);
        const ruleBreakers = [];

        while (ruleBreakers.length < ruleBreakerNr && currentCast.length > 0) {
            const candidate = currentCast[randomNumber(0, currentCast.length - 1)];
            if (!ruleBreakers.includes(candidate)) {
                ruleBreakers.push(candidate);
            }
        }

        judgingScreen.createHorizontalLine();

        judgingScreen.createBigText("Before we get onto critiques...");

        ruleBreakers.forEach(ruleBreaker => {
            judgingScreen.createImage(ruleBreaker.getCurrentImage(), "black");

            const condemned = randomNumber(0, 100) < calloutCondemnChance;

            if (condemned) {
                const topIndex = topQueens.indexOf(ruleBreaker);
                if (topIndex > -1) {
                    topQueens.splice(topIndex, 1);
                }

                const wasInTop = topIndex > -1;
                const isInBottom = bottomQueens.includes(ruleBreaker);
                if (!wasInTop && !isInBottom) {
                    ruleBreaker.trackRecord.pop();
                }

                if (!bottomQueens.includes(ruleBreaker)) {
                    bottomQueens.push(ruleBreaker);
                }

                ruleBreaker.condemnedToBottom = true;
                ruleBreaker.brokeRules = false;
                ruleBreaker.unfavoritism += 5;
                ruleBreaker.performanceScore = 999;
                judgingScreen.createBold("We have heard that you are BREAKING the rules behind the scenes...");
                judgingScreen.createBold(`This competition has rules for a reason, there are consequences for breaking them, you are now up for elimination...`);

                judgingScreen.createParagraph("Alright... now let's continue with critiques.");
            } else {
                ruleBreaker.brokeRules = false;
                ruleBreaker.unfavoritism += 2;
                judgingScreen.createBold("We have heard that you are BREAKING the rules behind the scenes...");
                judgingScreen.createBold(`This competition has rules for a reason, remember that!`);

                judgingScreen.createParagraph("Alright... now let's continue with critiques.");
            }
        });

        judgingScreen.createHorizontalLine();
    }

    if (team == true) {
        if (sealTwist) {
            useSealsTeam();
        }
        if (hasImmunityPotions() && stills16Imm()) {
            drinkornorTeam();
        }
        
        judgingScreen.createImage(topQueens[0].QueenA.getCurrentImage(), "cyan");
        judgingScreen.createImage(topQueens[1].QueenA.getCurrentImage(), "cyan");
        judgingScreen.createImage(topQueens[0].QueenB.getCurrentImage(), "cyan");
        judgingScreen.createImage(topQueens[1].QueenB.getCurrentImage(), "cyan");
        judgingScreen.createImage(bottomQueens[0].QueenB.getCurrentImage(), "cyan");
        judgingScreen.createImage(bottomQueens[1].QueenB.getCurrentImage(), "cyan");
        judgingScreen.createImage(bottomQueens[2].QueenB.getCurrentImage(), "cyan");
        judgingScreen.createImage(bottomQueens[0].QueenA.getCurrentImage(), "cyan");
        judgingScreen.createImage(bottomQueens[1].QueenA.getCurrentImage(), "cyan");
        judgingScreen.createImage(bottomQueens[2].QueenA.getCurrentImage(), "cyan");
        judgingScreen.createBold(`${topQueens[0].name}, ${topQueens[1].name}, ${bottomQueens[0].name}, ${bottomQueens[1].name}, ${bottomQueens[2].name}, you represent the tops and bottoms of the week.`);
    }
    else {
        let totaljudged = [...topQueens, ...bottomQueens]
        shuffle(totaljudged);
        if (hasImmunityPotions() && stills16Imm()) {
            drinkornot();
        }
        useSeals();
        for (let i = 0; i < totaljudged.length; i++) {
            judgingScreen.createImage(totaljudged[i].getCurrentImage(), "cyan");
        }
        judgingScreen.createBold("", "judged");
        let judged = document.getElementById("judged");
        for (let i = 0; i < totaljudged.length; i++) {
            judged.innerHTML += `${totaljudged[i].name}, `;
        }
        if ((slayPremiere || can7Premiere || uk8Premiere) && episodeCount == 1) {
            judged.innerHTML += "you represent the tops of the week.";
            if (uk8Premiere) {
                judgingScreen.createBold("The top half of the cast will receive critiques before the final Top 2 is announced.");
            } else {
                judgingScreen.createBold("No one is going home this episode!");
            }
        } else {
            judged.innerHTML += "you represent the tops and bottoms of the week.";
        }
    }
    judgingScreen.createHorizontalLine();
    judgingScreen.createParagraph("", "safeQueens");
    let safeQueens = document.querySelector("p#safeQueens");
    //check if the queen is in the top or in the bottom, and if not put her as safe:
    for (let i = 0; i < currentCast.length; i++) {
        if (topQueens.indexOf(currentCast[i]) == -1 && bottomQueens.indexOf(currentCast[i]) == -1) {
            safeQueens.innerHTML += currentCast[i].name + ", ";
            if (team == false) {
                currentCast[i].addToTrackRecord("SAFE");
                currentCast[i].ppe += 3;
            }
            if (team == true) {
                currentCast[i].addToTrackRecord("SAFE");
                currentCast[i].QueenA.addToTrackRecord("SAFE");
                currentCast[i].QueenA.ppe += 3;
                currentCast[i].QueenB.addToTrackRecord("SAFE");
                currentCast[i].QueenB.ppe += 3;
            }
        }
    }
    let safeQObjs = currentCast.filter(q => !topQueens.includes(q) && !bottomQueens.includes(q));
    if (safeQueens.innerHTML == "") {
        safeQueens.innerHTML += "";
    } else {
        safeQueens.innerHTML += "you are safe.";
    }

    if (safeQObjs.length > 0) {
        judgingScreen.createButton("Proceed","safeQueensUntuck()");
    } else {
        judgingScreen.createButton("Proceed","critiqueScreen()");
    }
}

function safeQueensUntuck() {
    let screen = new Scene();
    screen.clean();
    if (!solidbk) { setBackgroundToUntucked(); }
    screen.createHeader("The safe queens untuck...");

    const safeList = currentCast.filter(q => !topQueens.includes(q) && !bottomQueens.includes(q));
    if (safeList.length === 0) {
        critiqueScreen();
        return;
    }

    if (team) {
        if (safeList.length === 1) {
            screen.createImage(safeList[0].QueenA.getCurrentImage(), "cyan");
            screen.createImage(safeList[0].QueenB.getCurrentImage(), "cyan");
            screen.createBold(`${safeList[0].name} grab a drink, and wait for the other queens.`);
        } else {
            for (let i = 0; i < safeList.length; i++) {
                screen.createImage(safeList[i].QueenA.getCurrentImage(), "cyan");
                screen.createImage(safeList[i].QueenB.getCurrentImage(), "cyan");
            }
            let names = safeList.map(t => t.name).join(", ");
            screen.createBold(`${names}, you all grab a drink and wait for the other teams.`);
        }
        screen.createButton("Proceed","critiqueScreen()");
        return;
    }
    
    if (safeList.length === 1) {
        screen.createImage(safeList[0].getCurrentImage(), "cyan");
        screen.createBold(`${safeList[0].name}, grabs a drink, and waits for the other queens.`);
    } else {
        const maxInteractions = Math.min(4, Math.max(1, Math.floor(safeList.length)));
        const howManyInteractions = randomNumber(1, Math.min(4, safeList.length));

        for (let i = 0; i < howManyInteractions; i++) {
            let howManyQueens = 2;
            const r = randomNumber(0, 100);
            if (safeList.length >= 4) {
                if (r > 95) howManyQueens = 4;
                else if (r > 75) howManyQueens = 3;
                else howManyQueens = 2;
            } else if (safeList.length === 3) {
                howManyQueens = (r > 80) ? 3 : 2;
            } else {
                howManyQueens = 2;
            }
            
            howManyQueens = Math.min(howManyQueens, safeList.length);

            const picked = [];
            while (picked.length < howManyQueens) {
                const candidate = safeList[randomNumber(0, safeList.length - 1)];
                if (picked.indexOf(candidate) === -1) picked.push(candidate);
            }

            if (howManyQueens === 1) interactions(1, picked[0]);
            else if (howManyQueens === 2) interactions(2, picked[0], picked[1]);
            else if (howManyQueens === 3) interactions(3, picked[0], picked[1], picked[2]);
            else if (howManyQueens === 4) interactions(4, picked[0], picked[1], picked[2], picked[3]);
        }
    }

    screen.createButton("Proceed","critiqueScreen()");
}
