function getJudgeCritiqueProfile(judge) {
    if (judge === judgingpanel[0] || judge === Ru) {
        return { role: "host", positivity: 0.18 };
    }
    if (judge === Michelle) return { role: "michelle", positivity: -0.22 };
    if (judge === Carson) return { role: "carson", positivity: -0.08 };
    if (judge === Ross) return { role: "ross", positivity: 0.12 };
    return { role: "guest", positivity: 0 };
}

