function getJudgeCritique(queen, judge, topic) {
    const profile = getJudgeCritiqueProfile(judge);
    let positiveChance = 0.5;
    if (profile.role !== "guest") {
        if (topic === "runway") {
            if (isDesignChallenge || isWhoWoreItBest) {
                // Fashion challenges retain raw scores (lower is better), unlike normalized runway bonuses.
                positiveChance = queen.runwayScore < 16 ? 0.75 : queen.runwayScore >= 26 ? 0.25 : 0.5;
            } else {
                positiveChance = queen.runwayScore > 0 ? 0.75 : queen.runwayScore < 0 ? 0.25 : 0.5;
            }
        } else {
            positiveChance = topQueens.includes(queen) ? 0.75 : bottomQueens.includes(queen) ? 0.25 : 0.5;
        }
        positiveChance = Math.max(0.1, Math.min(0.9, positiveChance + profile.positivity));
    }
    const positive = Math.random() < positiveChance;
    const tone = positive ? "positive" : "negative";
    const customOptions = allCustomCritiques.filter(critique =>
        critique.topic === topic && critique.tone === tone &&
        (critique.judge === "any" ||
            (critique.judge === "host" && profile.role === "host") ||
            critique.judge === `judge:${judge.name}`)
    );
    let text;
    if (customOptions.length > 0 && Math.random() < 0.35) {
        const custom = customOptions[randomNumber(0, customOptions.length - 1)];
        text = custom.text.includes("{queen}")
            ? custom.text.replace(/\{queen\}/g, () => queen.name)
            : `${queen.name}, ${custom.text}`;
    } else {
        const exclusive = judgeExclusiveCritiques[profile.role]?.[topic]?.[tone];
        let line;
        if (exclusive && Math.random() < 0.4) {
            line = exclusive[randomNumber(0, exclusive.length - 1)];
        } else if (topic === "runway") {
            const runwayLines = positive
                ? [", your styling feels polished and your look has a clear point of view.", ", I love the silhouette and the way you sold this look on the runway.", ", this look interprets the theme in a fresh, memorable way."]
                : [", the styling feels unfinished, and I wanted a more cohesive look.", ", the silhouette needs refining; the details are distracting from the idea.", ", I wanted a clearer connection between this look and the runway theme."];
            line = runwayLines[randomNumber(0, runwayLines.length - 1)];
        } else {
            line = positive ? getGoodCritique(queen) : getBadCritique(queen);
        }
        text = queen.name + line;
    }
    return { text, positive, topic };
}

const critiqueChallengeIntros = [
    "Let's talk about your challenge.",
    "Starting with the challenge:",
    "So, the challenge.",
    "First things first, your challenge.",
    "About your challenge:"
];
const critiqueRunwayIntros = {
    positive: [
        "Now, onto your runway.",
        "And the runway? Honey.",
        "Moving on to your runway look.",
        "As for the runway:"
    ],
    negative: [
        "Now, onto your runway.",
        "Moving on to your runway look.",
        "As for the runway...",
        "Then there's the runway."
    ]
};

function pickCritiqueLine(lines) {
    return lines[randomNumber(0, lines.length - 1)];
}

function endCritiqueSentence(text) {
    const trimmed = text.trim();
    return /[.!?…"')]$/.test(trimmed) ? trimmed : `${trimmed}.`;
}

function dropCritiqueAddress(text, queen) {
    const prefix = `${queen.name}, `;
    if (!text.startsWith(prefix)) return text;
    const rest = text.slice(prefix.length);
    return rest.charAt(0).toUpperCase() + rest.slice(1);
}

function createJudgeCritiques(screen, queen, judge) {
    const challenge = getJudgeCritique(queen, judge, "challenge");
    const runway = getJudgeCritique(queen, judge, "runway");
    const runwayIntro = pickCritiqueLine(critiqueRunwayIntros[runway.positive ? "positive" : "negative"]);
    const paragraph = document.createElement("p");
    const label = document.createElement("b");
    label.textContent = `${judge.name}: `;
    paragraph.append(label, document.createTextNode(
        `"${pickCritiqueLine(critiqueChallengeIntros)} ${endCritiqueSentence(challenge.text)} ${runwayIntro} ${endCritiqueSentence(dropCritiqueAddress(runway.text, queen))}"`
    ));
    screen._MainBlock.appendChild(paragraph);
}

let faintOccurred = false;
let rigFaint = false;
function critiqueScreen() {
    const screen = new Scene();
    screen.clean();
    screen.createHeader("On the main stage...");
    if (!solidbk) { setBackgroundToStage(); }

    const availableJudges = (Array.isArray(judgingpanel) ? judgingpanel : []).filter(judge => judge && judge.image);
    const fallbackJudge = (typeof Ru !== "undefined" && Ru && Ru.image) ? Ru : null;

    let totaljudged = [];
    if (!slmFormat) {
        totaljudged = [...topQueens, ...bottomQueens];
    } else {
        totaljudged = [...currentCast];
    }
    shuffle(totaljudged);

    screen.createBigText("This week judging panel is...");
    availableJudges.forEach(judge => {
        screen.createImage(judge.image);
    });
    screen.createBold(`${judgetext || ""}`);

    screen.createHorizontalLine();

    let critiquedQueens = totaljudged.slice();
    critiquedQueens.forEach(q => {
        screen.createImage(q.getCurrentImage(), "cyan");
    });
    screen.createBold("", "judged");
    const judgedText = document.getElementById("judged");

    judgedText.innerHTML =
        critiquedQueens.map(q => q.name).join(", ") +
        ((slayPremiere || can7Premiere || uk8Premiere) && episodeCount === 1
            ? " represent the tops of the week."
            : " represent the tops and bottoms of the week.");

    if ((slayPremiere || can7Premiere || uk8Premiere) && episodeCount === 1) {
        screen.createBold("No one is going home this episode!");
    }

    shuffle(critiquedQueens);

    screen.createBold(
        "Now it's time for the judges' critiques."
    );

    critiquedQueens.forEach((queen, index) => {
        screen.createHorizontalLine();

        if (index === 0)
            screen.createBold(`First up, we have ${queen.name}!`);
        else if (index === critiquedQueens.length - 1)
            screen.createBold(`Finally, we have ${queen.name}!`);
        else
            screen.createBold(`Next, we have ${queen.name}!`);

        screen.createImage(queen.getCurrentImage(), "cyan");
        const queenJudges = availableJudges.length > 0 ? availableJudges : fallbackJudge ? [fallbackJudge] : [];
        queenJudges.forEach(judge => {
            screen.createImage(judge.image);
            createJudgeCritiques(screen, queen, judge);
        });

        if (rigFaint || (!specialEventsOff && !faintOccurred && Math.random() < 0.06) && bottomQueens.includes(queen)) {
            faintOccurred = true;
            rigFaint = false;
            screen.createHorizontalLine();
            screen.createImage(queen.getCurrentImage(), "red")
            screen.createBold(`${queen.name} faints during critiques! Production intervenes...`);
            screen.createParagraph(`Medical staff rushes to the stage to attend to ${queen.name}. After a few tense moments, ${getPronoun(queen, "subject")} is helped off the stage for further evaluation.`);
            screen.createParagraph(`After a quick check-up, the doctors confirm that ${getPronoun(queen, "subject")} is okay to continue in the competition.`);
        }
    });

    if (
        currentCast.length <= 10 &&
        episodeCount > 3 &&
        (regularFormat || thailandFormat) &&
        randomNumber(0, 10) === 7 &&
        homeTrigger < 2 &&
        !team &&
        !returningQueen && !slmFormat
    ) {
        homeTrigger++;
        whoShouldGoHomeTonight();
    }

    createCritiqueProceedButton(screen);
}

let nomQueen = null;
let slmCoNominees = [];
let winQueen = null;
let slmNoNomineeReason = "";
let slmNoNomineeSelectorQueen = null;
let slmLastLipsyncWinner = null;
let slmActiveNomineeInLipsync = null;
let slmVotedNomineeInLipsync = null;
let slmSavedNomineeThisEpisode = null;
let slmStarsLedger = [];
let pendingPostLipsyncFight = null;

function getSLMStarsLedgerRow(queen) {
    if (!queen) {
        return null;
    }
    for (let i = 0; i < slmStarsLedger.length; i++) {
        if (slmStarsLedger[i].queen === queen) {
            return slmStarsLedger[i];
        }
    }
    const row = {
        queen,
        episodePoints: [],
        episodeTags: [],
        totalP: 0,
    };
    slmStarsLedger.push(row);
    return row;
}

function ensureSLMStarsLedgerEpisodeSlot(row, episodeIndex) {
    while (row.episodePoints.length <= episodeIndex) {
        row.episodePoints.push(0);
        row.episodeTags.push({});
    }
}

function recordSLMStarsEvent(queen, delta = 0, eventTag = "", count = 1) {
    if (!slmFormat || !queen) {
        return;
    }
    const row = getSLMStarsLedgerRow(queen);
    if (!row) {
        return;
    }
    const episodeIndex = Math.max(0, Number(episodeCount || 1) - 1);
    ensureSLMStarsLedgerEpisodeSlot(row, episodeIndex);

    const safeDelta = Number(delta) || 0;
    row.episodePoints[episodeIndex] += safeDelta;
    row.totalP += safeDelta;

    if (eventTag) {
        const safeCount = Math.max(1, Number(count) || 1);
        row.episodeTags[episodeIndex][eventTag] = Number(row.episodeTags[episodeIndex][eventTag] || 0) + safeCount;
    }
}

function markCoinFlipNomination(queen) {
    if (!queen) return;
    if (!Array.isArray(queen.nomEp)) {
        queen.nomEp = [];
    }
    if (!queen.nomEp.includes(episodeCount)) {
        queen.nomEp.push(episodeCount);
    }
}

function getRandomUntuckedFightPair() {
    if (!Array.isArray(currentCast) || currentCast.length < 2) return null;
    const eligibleQueens = currentCast.filter((queen) => queen && typeof queen.getCurrentImage === "function");
    if (eligibleQueens.length < 2) return null;
    const shuffled = [...eligibleQueens];
    shuffle(shuffled);
    return [shuffled[0], shuffled[1]];
}

function queuePostLipsyncRandomFight(screen) {
    if (specialEventsOff) return;
    if (pendingPostLipsyncFight && pendingPostLipsyncFight.episode === episodeCount) return;
    const pair = getRandomUntuckedFightPair();
    if (!pair) return;
    if (randomNumber(0, 100) > 40) return;

    const [queen1, queen2] = pair;
    pendingPostLipsyncFight = {
        episode: episodeCount,
        queen1Name: queen1.name,
        queen2Name: queen2.name,
    };

    screen.createHorizontalLine();
    screen.createImage(queen1.getCurrentImage(), "tomato");
    screen.createImage(queen2.getCurrentImage(), "tomato");
    screen.createBold(`${queen1.name} and ${queen2.name} start arguing the second they get off the stage.`);
    screen.createParagraph("Production has to separate them, and the argument clearly isn't over yet.");
    modRelation(2, 4, queen1, queen2);
    CheckFriend(queen1, queen2);
}

function clearSLMBlackStarAfterLipsync() {
    if (!slmFormat) {
        return;
    }
    for (let i = 0; i < bottomQueens.length; i++) {
        const queen = bottomQueens[i];
        if (queen && currentCast.includes(queen) && queen.blackStar > 0) {
            removeSLMBlackStar(queen);
        }
    }
}

function addSLMBlackStar(queen, count = 1) {
    if (!queen) {
        return false;
    }
    const starsToAdd = Math.max(0, Number(count) || 0);
    if (starsToAdd <= 0) {
        return false;
    }
    queen.blackStar = Number(queen.blackStar || 0) + starsToAdd;
    queen.stars = Number(queen.stars || 0) - (2 * starsToAdd);
    recordSLMStarsEvent(queen, -2 * starsToAdd, "black", starsToAdd);
    return true;
}

function removeSLMBlackStar(queen, count = 1) {
    if (!queen) {
        return false;
    }
    const starsToRemove = Math.min(Number(queen.blackStar || 0), Math.max(0, Number(count) || 0));
    if (starsToRemove <= 0) {
        return false;
    }
    queen.blackStar = Number(queen.blackStar || 0) - starsToRemove;
    queen.stars = Number(queen.stars || 0) + (2 * starsToRemove);
    recordSLMStarsEvent(queen, 2 * starsToRemove);
    return true;
}

function consumeSLMRainbowStar(queen, screen = null, message = "") {
    if (!queen || queen.rainbowStar <= 0) {
        return false;
    }
    queen.rainbowStar--;
    if (screen && message) {
        screen.createBold(message);
    }
    return true;
}

function getSLMStealableStarCount(queen) {
    if (!queen) {
        return 0;
    }
    return Number(queen.goldenStar || 0) + Number(queen.pinkStar || 0) + Number(queen.blackStar || 0);
}

function transferOneSLMStar(sourceQueen, targetQueen) {
    if (!sourceQueen || !targetQueen) {
        return null;
    }
    if (Number(sourceQueen.goldenStar || 0) > 0) {
        sourceQueen.goldenStar--;
        sourceQueen.stars = Math.max(0, Number(sourceQueen.stars || 0) - 6);
        targetQueen.goldenStar = Number(targetQueen.goldenStar || 0) + 1;
        targetQueen.stars = Number(targetQueen.stars || 0) + 6;
        return "Golden Star";
    }
    if (Number(sourceQueen.pinkStar || 0) > 0) {
        sourceQueen.pinkStar--;
        sourceQueen.stars = Math.max(0, Number(sourceQueen.stars || 0) - 3);
        targetQueen.pinkStar = Number(targetQueen.pinkStar || 0) + 1;
        targetQueen.stars = Number(targetQueen.stars || 0) + 3;
        return "Pink Star";
    }
    if (Number(sourceQueen.blackStar || 0) > 0) {
        removeSLMBlackStar(sourceQueen);
        addSLMBlackStar(targetQueen);
        return "Black Star";
    }
    return null;
}

function trySLMRainbowStarSteal(queen, screen = null) {
    if (!slmFormat || !slm2Modifier || !queen || queen.rainbowStar <= 0) {
        return false;
    }

    const targets = currentCast
        .filter((other) => other && other !== queen && getSLMStealableStarCount(other) > 0)
        .sort((a, b) => getSLMStealableStarCount(b) - getSLMStealableStarCount(a));

    if (targets.length === 0) {
        return false;
    }

    const target = targets[0];
    const stolenStarType = transferOneSLMStar(target, queen);
    if (!stolenStarType) {
        return false;
    }
    queen.rainbowStar--;

    if (screen) {
        screen.createImage(queen.getCurrentImage(), "violet");
        screen.createImage(target.getCurrentImage(), "tomato");
        screen.createBold(`${queen.name} uses a Rainbow Star to steal a ${stolenStarType} from ${target.name}.`);
    }

    return true;
}

function applySLMBlackStar(queen, screen = null, reasonLabel = "") {
    if (!slmFormat || !queen) {
        return false;
    }

    const reason = reasonLabel ? ` (${reasonLabel})` : "";
    if (slm2Modifier && queen.rainbowStar > 0) {
        consumeSLMRainbowStar(queen, screen, `${queen.name} uses a Rainbow Star to block a Black Star${reason}.`);
        return false;
    }

    addSLMBlackStar(queen);
    return true;
}

function enforceSLMRainbowStarDeadline(screen = null) {
    if (!slmFormat || !slm2Modifier || !hasReachedSLMFinaleCutoff()) {
        return;
    }

    const doomedQueens = currentCast.filter((queen) => queen && queen.rainbowStar > 0);
    for (let i = 0; i < doomedQueens.length; i++) {
        const queen = doomedQueens[i];
        queen.rainbowStar = 0;
        addSLMBlackStar(queen, 5);
        if (screen) {
            screen.createImage(queen.getCurrentImage(), "black");
            screen.createBold(`${queen.name} did not use their Rainbow Star before the semifinals and receives 5 Black Stars.`);
        }
    }
}

function applySLMBlackStarCarryPenalty(queen, screen = null) {
    return;
}

function ensureSLMEpisodePlacementIndex(queen) {
    if (!queen) return -1;
    if (!Array.isArray(queen.trackRecord)) {
        queen.trackRecord = [];
    }
    while (queen.trackRecord.length < episodeCount) {
        queen.addToTrackRecord("");
    }
    return Math.max(0, episodeCount - 1);
}

function getSLMCurrentEpisodePlacement(queen) {
    const index = ensureSLMEpisodePlacementIndex(queen);
    if (index < 0) return "";
    return String(queen.trackRecord[index] || "").trim();
}

function setSLMCurrentEpisodePlacement(queen, placement) {
    const index = ensureSLMEpisodePlacementIndex(queen);
    if (index < 0) return;
    queen.trackRecord[index] = placement;
}

function applySLMSafePlacement(queen) {
    const currentPlacement = getSLMCurrentEpisodePlacement(queen);
    if (!currentPlacement) {
        setSLMCurrentEpisodePlacement(queen, "SAFE");
    }
}

function applySLMBottomPlacement(queen) {
    const currentPlacement = getSLMCurrentEpisodePlacement(queen);

    if (!currentPlacement) {
        setSLMCurrentEpisodePlacement(queen, "BTM2");
        return;
    }

    if (currentPlacement.includes("BTM2")) {
        return;
    }

    if (currentPlacement.startsWith("WIN")) {
        setSLMCurrentEpisodePlacement(queen, "WIN BTM2");
        return;
    }

    if (currentPlacement.startsWith("HIGH")) {
        setSLMCurrentEpisodePlacement(queen, "HIGHBTM2");
        return;
    }

    if (currentPlacement.startsWith("SAFE") || currentPlacement.startsWith("LOW")) {
        setSLMCurrentEpisodePlacement(queen, "BTM2");
        return;
    }

    setSLMCurrentEpisodePlacement(queen, "BTM2");
}

function applySLMSavedPlacement(queen) {
    const currentPlacement = getSLMCurrentEpisodePlacement(queen);

    if (!currentPlacement) {
        setSLMCurrentEpisodePlacement(queen, "SAVED");
        return;
    }

    if (currentPlacement.includes("SAVED")) {
        return;
    }

    if (currentPlacement.startsWith("HIGH")) {
        setSLMCurrentEpisodePlacement(queen, "HIGH SAVED");
        return;
    }

    setSLMCurrentEpisodePlacement(queen, "SAVED");
}

function applySLMBottomThreePlacement(queen) {
    const currentPlacement = getSLMCurrentEpisodePlacement(queen);

    if (!currentPlacement) {
        setSLMCurrentEpisodePlacement(queen, "BTM3");
        return;
    }

    if (currentPlacement.includes("BTM2") || currentPlacement.includes("BTM3")) {
        return;
    }

    if (currentPlacement.startsWith("WIN")) {
        setSLMCurrentEpisodePlacement(queen, "WIN BTM3");
        return;
    }

    if (currentPlacement.startsWith("HIGH")) {
        setSLMCurrentEpisodePlacement(queen, "HIGHBTM3");
        return;
    }

    setSLMCurrentEpisodePlacement(queen, "BTM3");
}

function slmJudging() {
    let screen = new Scene();
    winQueen = topQueens[0];
    slmNoNomineeSelectorQueen = null;
    slmSavedNomineeThisEpisode = null;
    screen.clean();
    screen.createHeader("Judging!");
    if (!solidbk) {
        setBackgroundToStage();
    }
    enforceSLMRainbowStarDeadline(screen);
    if (currentCast.length === 0) {
        screen.createBold("No contestants remain in the competition.");
        screen.createButton("Proceed", "newEpisode()");
        return;
    }

    let total = [...currentCast, ...eliminatedCast];

    shuffle(total);
    for (let i = 0; i < total.length; i++) {
        screen.createImage(total[i].getCurrentImage(), "cyan");
    }

    for (let i = 0; i < eliminatedCast.length; i++) {
        const lastEntry = eliminatedCast[i].trackRecord[eliminatedCast[i].trackRecord.length - 1];
        if (lastEntry === "" || lastEntry === "TBA") {
            eliminatedCast[i].trackRecord.pop();
        }
        if (!slm2Modifier) {
            eliminatedCast[i].addToTrackRecord("LOST SOUL");
        }
    }

    for (let i = 0; i < topQueens.length; i++) {
        const q = topQueens[i];
        const elimIdx = eliminatedCast.indexOf(q);
        if (elimIdx !== -1) {
            const lastEntry = q.trackRecord[q.trackRecord.length - 1];
            if (!slm2Modifier && lastEntry === "LOST SOUL") {
                q.trackRecord.pop();
            }
            insOgPla(q);
            appendRetEp(q, episodeCount);
            eliminatedCast.splice(elimIdx, 1);
            currentCast.push(q);
            screen.createImage(q.getCurrentImage(), "gold");
            screen.createBold(`${q.name} has proven ${getPronoun(q, "reflexive")} worthy of competing! They are back in the game!!`);
        }
    }

    screen.createBold("The best performer of this week... is... yes, it's you...");
    screen.createHorizontalLine();
    screen.createImage(topQueens[0].getCurrentImage(), "royalblue");
    screen.createBold(`${topQueens[0].name}! Congratulations, you are the winner of this week!`);
    topQueens[0].addToTrackRecord("WIN");
    awardCustomizedChallengePrizes([topQueens[0]]);
    topQueens[0].ppe += 5;
    topQueens[0].favoritism += 3;
    topQueens[0].goldenStar++;
    topQueens[0].stars += 6;
    recordSLMStarsEvent(topQueens[0], 6, "gold", 1);

    let gbm = topQueens[0];

    if (topQueens[0] === nomQueen) {
        screen.createParagraph("You have officially lost your nomination status...");
        screen.createParagraph(`${topQueens[0].name} will now select the voted queen's lip sync opponent this week.`);

        slmNoNomineeReason = "goldenstar";
        slmNoNomineeSelectorQueen = topQueens[0];

        if (topQueens[0].blackStar > 0) {
            removeSLMBlackStar(topQueens[0]);
        }

        nomQueen = null;
    }

    const currentNomineePool = [];
    if (nomQueen && currentCast.includes(nomQueen) && nomQueen !== topQueens[0]) {
        currentNomineePool.push(nomQueen);
    }
    if (Array.isArray(slmCoNominees)) {
        for (let i = 0; i < slmCoNominees.length; i++) {
            const coNominee = slmCoNominees[i];
            if (coNominee && currentCast.includes(coNominee) && coNominee !== topQueens[0] && !currentNomineePool.includes(coNominee)) {
                currentNomineePool.push(coNominee);
            }
        }
    }

    if (currentNomineePool.length > 1 || (slm2Modifier && episodeCount == 2)) {
        let savedNominee = bestSister(topQueens[0], currentNomineePool);
        if (!savedNominee || !currentNomineePool.includes(savedNominee)) {
            savedNominee = currentNomineePool[randomNumber(0, currentNomineePool.length - 1)];
        }
        const remainingNominees = currentNomineePool.filter((q) => q !== savedNominee);
        nomQueen = remainingNominees[0] || null;
        slmCoNominees = remainingNominees.slice(1);
        slmSavedNomineeThisEpisode = savedNominee;

        setSLMCurrentEpisodePlacement(savedNominee, "SAVED");
        screen.createImage(topQueens[0].getCurrentImage(), "royalblue");
        screen.createImage(savedNominee.getCurrentImage(), "deepskyblue");
        screen.createBold(`${topQueens[0].name} saved ${savedNominee.name} from the lip sync.`);
    }

    topQueens.splice(0, 1);

    if (topQueens.length > 0) {
        for (let i = 0; i < topQueens.length; i++) {
            topQueens[i].addToTrackRecord("HIGH");
            topQueens[i].ppe += 4;
            topQueens[i].favoritism += 2;
            topQueens[i].stars += 3;
            topQueens[i].pinkStar++;
            recordSLMStarsEvent(topQueens[i], 3, "pink", 1);
        }
        for (let i = 0; i < topQueens.length; i++) {
            screen.createImage(topQueens[i].getCurrentImage(), "lightblue");
        }
        screen.createBold("", "highQueens");
        let highQueens = document.getElementById("highQueens");
        for (let i = 0; i < topQueens.length; i++) {
            highQueens.innerHTML += topQueens[i].name + ", ";
        }
        if (topQueens.length > 1) {
            highQueens.innerHTML += "you are all safe!";
        } else {
            highQueens.innerHTML += "you are safe!";
        }
    }

    if (hasReachedSLMFinaleCutoff()) {
        screen.createHorizontalLine();
        slmCutToFinaleByPoints(screen,gbm);
        return;
    }

    screen.createHorizontalLine();
    screen.createBigText("It's time for El Purgatorio.");
    screen.createParagraph("You will now privately vote for the contestant who performed the worst this week.");
    screen.createButton("Proceed", "slmVoting()");
}

function slmVoting() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Purgatory...");
    screen.createBold("The queens will now privately vote for who they think performed the worst this week.");
    if (slm2Modifier) {
        screen.createParagraph("Tonight, the current nominee cannot receive votes.");
    } else {
        screen.createParagraph("The challenge winner and any currently nominated queens are immune from receiving votes.");
    }
    screen.createHorizontalLine();
    let previousNominees = [];
    if (nomQueen && currentCast.includes(nomQueen)) {
        previousNominees.push(nomQueen);
    }
    if (Array.isArray(slmCoNominees)) {
        for (let i = 0; i < slmCoNominees.length; i++) {
            const coNominee = slmCoNominees[i];
            if (coNominee && currentCast.includes(coNominee) && !previousNominees.includes(coNominee)) {
                previousNominees.push(coNominee);
            }
        }
    }
    let nomineesForLipsync = [...previousNominees];
    if (slmSavedNomineeThisEpisode && nomineesForLipsync.includes(slmSavedNomineeThisEpisode)) {
        nomineesForLipsync = nomineesForLipsync.filter((q) => q !== slmSavedNomineeThisEpisode);
    }
    slmSavedNomineeThisEpisode = null;

    const previousNomQueen = nomineesForLipsync.length > 0 ? nomineesForLipsync[0] : null;
    const isSLMTalentShowPremiere = episodeCount === 1 && /Talent Show/i.test(String(episodeChallenges[episodeChallenges.length - 1] || ""));
    slmActiveNomineeInLipsync = previousNomQueen;
    slmVotedNomineeInLipsync = null;
    bottomQueens = [];
    currentCast.forEach(q => {
        q.votes = 0;
        q.votesTalent = 0;
        q.votesRunway = 0;
        q.votesOverall = 0;
    });
    let eligibleTargets = slm2Modifier
        ? currentCast.filter(q => !previousNominees.includes(q))
        : currentCast.filter(q => q !== winQueen && q.blackStar <= 0 && !topQueens.includes(q));
    if (isSLMTalentShowPremiere) {
        screen.createParagraph("Tonight, each queen will cast 3 votes: Talent Show, Runway, and Overall.");
    }
    let votingQueens = [...currentCast];
    shuffle(votingQueens);
    for (let i = 0; i < votingQueens.length; i++) {
        screen.createImage(votingQueens[i].getCurrentImage(), "black");
        let castWithoutSelfAndWinner = eligibleTargets.filter(q => q !== votingQueens[i]);
        if (castWithoutSelfAndWinner.length === 0) {
            continue;
        }

        const chooseWorstByMetric = (candidates, metricGetter) => {
            const sorted = [...candidates].sort((a, b) => metricGetter(b) - metricGetter(a));
            if (sorted.length === 0) {
                return null;
            }
            const worstValue = metricGetter(sorted[0]);
            const tiedWorst = sorted.filter((q) => metricGetter(q) === worstValue);
            return tiedWorst[randomNumber(0, tiedWorst.length - 1)];
        };

        if (isSLMTalentShowPremiere) {
            const talentVoted = chooseWorstByMetric(castWithoutSelfAndWinner, (q) => Number(q.performanceScore || 0));
            const runwayVoted = chooseWorstByMetric(castWithoutSelfAndWinner, (q) => Number(q.runwayScore || 0));
            const overallVoted = chooseWorstByMetric(
                castWithoutSelfAndWinner,
                (q) => (Number(q.performanceScore || 0) + Number(q.runwayScore || 0)) / 2
            );

            if (talentVoted) {
                talentVoted.votes++;
                talentVoted.votesTalent++;
            }
            if (runwayVoted) {
                runwayVoted.votes++;
                runwayVoted.votesRunway++;
            }
            if (overallVoted) {
                overallVoted.votes++;
                overallVoted.votesOverall++;
            }
            screen.createBold(`${votingQueens[i].name} has cast 3 category votes.`);
            continue;
        }

        let voted = worstSister(votingQueens[i], castWithoutSelfAndWinner);
        if (!voted) {
            voted = castWithoutSelfAndWinner[randomNumber(0, castWithoutSelfAndWinner.length - 1)];
        }
        voted.votes++;
        screen.createBold(`${votingQueens[i].name} has cast their vote.`);
    }

    let voted = [...eligibleTargets].sort((a, b) => b.votes - a.votes);
    let votedNominee = null;
    screen.createHorizontalLine();

    if (isSLMTalentShowPremiere) {
        const categoryDefs = [
            { label: "Talent Show", key: "votesTalent" },
            { label: "Runway", key: "votesRunway" },
            { label: "Overall", key: "votesOverall" },
        ];
        const categoryNominees = [];
        const chosenNominees = new Set();

        for (let i = 0; i < categoryDefs.length; i++) {
            const category = categoryDefs[i];
            const rankedForCategory = [...eligibleTargets].sort((a, b) => {
                const categoryDelta = Number(b[category.key] || 0) - Number(a[category.key] || 0);
                if (categoryDelta !== 0) {
                    return categoryDelta;
                }
                const totalDelta = Number(b.votes || 0) - Number(a.votes || 0);
                if (totalDelta !== 0) {
                    return totalDelta;
                }
                return 0;
            });

            let nominee = rankedForCategory.find((q) => !chosenNominees.has(q)) || rankedForCategory[0] || null;
            if (!nominee) {
                continue;
            }

            chosenNominees.add(nominee);
            categoryNominees.push(nominee);
            applySLMBlackStar(nominee, screen, `${category.label} vote result`);

            screen.createImage(nominee.getCurrentImage(), "tomato");
            screen.createBold(`${nominee.name} received the most ${category.label.toLowerCase()} votes and becomes that category's nominee.`);
            screen.createParagraph(
                `Votes - Talent Show: ${nominee.votesTalent || 0}, Runway: ${nominee.votesRunway || 0}, Overall: ${nominee.votesOverall || 0}.`
            );
        }

        bottomQueens = categoryNominees.filter((q, idx, arr) => q && currentCast.includes(q) && arr.indexOf(q) === idx);
        if (bottomQueens.length < 3) {
            const fallbackPool = [...voted].filter((q) => q && !bottomQueens.includes(q));
            while (bottomQueens.length < 3 && fallbackPool.length > 0) {
                bottomQueens.push(fallbackPool.shift());
            }
        }

        if (bottomQueens.length === 0) {
            screen.createBold("No eligible queen could be nominated this week.");
        }
    } else {
        if (voted.length > 0) {
            for (let i = 0; i < voted.length; i++) {
                const candidate = voted[i];
                if (applySLMBlackStar(candidate, screen, "vote result")) {
                    votedNominee = candidate;
                    break;
                }
            }
        }
        if (votedNominee) {
            slmVotedNomineeInLipsync = votedNominee;
            screen.createImage(votedNominee.getCurrentImage(), "tomato");
            screen.createBold(`${votedNominee.name} received the most votes and gets a Black Star.`);
            if (episodeCount === 1 && !slm2Modifier) {
                nomQueen = votedNominee;
                slmCoNominees = [];
                votedNominee.nomEp.push(episodeCount);
                if (topQueens.includes(nomQueen)) {
                    nomQueen.ppe -= 2;
                } else {
                    nomQueen.ppe += 1;
                    applySLMSafePlacement(nomQueen);
                }
                nomQueen.unfavoritism += 3;
                applySLMBlackStarCarryPenalty(nomQueen, screen);
                for (let i = 0; i < currentCast.length; i++) {
                    if (currentCast[i] !== winQueen && !topQueens.includes(currentCast[i]) && currentCast[i] !== votedNominee) {
                        applySLMSafePlacement(currentCast[i]);
                        currentCast[i].ppe += 3;
                    }
                }
                screen.createParagraph(`${votedNominee.name} will face a lip sync next episode unless they lose the nominee status.`);
                screen.createButton("Proceed", "newEpisode()");
                return;
            }

            let opponent = null;
            if (nomineesForLipsync.length > 0) {
                opponent = nomineesForLipsync[0];
                screen.createImage(opponent.getCurrentImage(), "tomato");
                screen.createBold(`${opponent.name}, as a current nominee, you must lip sync to defend your place in the competition.`);
                for (let i = 1; i < nomineesForLipsync.length; i++) {
                    const coNominee = nomineesForLipsync[i];
                    screen.createImage(coNominee.getCurrentImage(), "tomato");
                    screen.createBold(`${coNominee.name}, as a current nominee, you must also lip sync to defend your place in the competition.`);
                }
            } else {
                const pool = currentCast.filter(q => q !== winQueen && q !== votedNominee);
                if (pool.length > 0) {
                    let selector = null;
                    if (slmNoNomineeReason === "eliminated" && slmLastLipsyncWinner && currentCast.includes(slmLastLipsyncWinner)) {
                        selector = slmLastLipsyncWinner;
                        screen.createParagraph(`${selector.name}, as the winner of the previous nominee lip sync, you must choose this week's opponent.`);
                    } else if (slmNoNomineeReason === "saved" && slmNoNomineeSelectorQueen && currentCast.includes(slmNoNomineeSelectorQueen)) {
                        selector = slmNoNomineeSelectorQueen;
                        screen.createParagraph(`${selector.name}, as the queen who won and saved the nominee last week, you must choose this week's opponent.`);
                    } else if (slmNoNomineeReason === "goldenstar" && slmNoNomineeSelectorQueen && currentCast.includes(slmNoNomineeSelectorQueen)) {
                        selector = slmNoNomineeSelectorQueen;
                        screen.createParagraph(`${selector.name}, as the former nominee who secured a Golden Star, you must choose this week's opponent.`);
                    }

                    if (selector) {
                        opponent = worstSister(selector, pool);
                    }
                    if (!opponent) {
                        opponent = pool[randomNumber(0, pool.length - 1)];
                    }

                    screen.createImage(opponent.getCurrentImage(), "tomato");
                    screen.createBold(`${opponent.name} has been selected as the lip sync opponent.`);
                }
            }

            bottomQueens.push(votedNominee);
            if (opponent && opponent !== votedNominee) {
                bottomQueens.push(opponent);
            }
            if (nomineesForLipsync.length > 1) {
                for (let i = 1; i < nomineesForLipsync.length; i++) {
                    const coNominee = nomineesForLipsync[i];
                    if (coNominee && coNominee !== votedNominee && coNominee !== opponent) {
                        bottomQueens.push(coNominee);
                    }
                }
            }

            slmNoNomineeReason = "";
            slmNoNomineeSelectorQueen = null;
        } else {
            screen.createBold("No eligible queen could be nominated this week.");
        }
    }

    bottomQueens = bottomQueens.filter((q, idx, arr) => q && currentCast.includes(q) && arr.indexOf(q) === idx);

    if (bottomQueens.length < 2) {
        const fallbackBottom = currentCast
            .filter(q => q !== winQueen && !bottomQueens.includes(q))
            .sort((a, b) => b.performanceScore - a.performanceScore)[0];
        if (fallbackBottom) {
            bottomQueens.push(fallbackBottom);
        }
    }

    if (slm2Modifier && episodeCount === 1) {
        if (bottomQueens.length < 3) {
            const thirdBottomFallback = voted.find((q) => q && !bottomQueens.includes(q))
                || currentCast.find((q) => q && q !== winQueen && !bottomQueens.includes(q));
            if (thirdBottomFallback) {
                bottomQueens.push(thirdBottomFallback);
            }
        }
        if (bottomQueens.length > 2) {
            const thirdBottom = bottomQueens[2];
            if (thirdBottom) {
                applySLMBottomThreePlacement(thirdBottom);
            }
        }
    } else if (bottomQueens.length > 3) {
        bottomQueens = bottomQueens.slice(0, 3);
    }

    for (let i = 0; i < currentCast.length; i++) {
        if (currentCast[i] !== winQueen && !bottomQueens.includes(currentCast[i]) && !topQueens.includes(currentCast[i])) {
            currentCast[i].addToTrackRecord("SAFE");
            currentCast[i].ppe += 3;
        }
    }

    screen.createButton("Proceed", "slmLipsyncDesc()");
}

function slmLipsyncDesc() {
    let screen = new Scene();
    screen.clean();

    bottomQueens = bottomQueens.filter((q, idx, arr) => q && currentCast.includes(q) && arr.indexOf(q) === idx);

    if (bottomQueens.length < 2) {
        screen.createBold("A valid bottom group could not be formed for this lip sync.");
        screen.createButton("Proceed", "createPostLSBtn()")
        return;
    }

    if (riggoryLipsync) {
        for (let i = 0; i < bottomQueens.length; i++) {
            bottomQueens[i].getASLipsync();
        }
    } else {
        for (let i = 0; i < bottomQueens.length; i++) {
            bottomQueens[i].getLipsync();
            bottomQueens[i].lipsyncScore = (bottomQueens[i].lipsyncScore - bottomQueens[i].favoritism) + bottomQueens[i].unfavoritism;
        }
    }

    screen.createHeader("The time has come...");
    screen.createBold("For you to lip-sync... for your lives and your Black Star fate! Good luck, and don't fuck it up.");

    const song = lsSong().toString();
    getLSConfessionals(bottomQueens, screen);

    const event = checkForLipsyncEvent(bottomQueens);
    if (event != false) {
        const eventQueen = bottomQueens.find((q) => q.name == event.queen.name);
        if (eventQueen) {
            eventQueen.lipsyncScore += event.points;
        }
    }

    const slay = bottomQueens.filter(function (queen) { return queen.lipsyncScore > 11; });
    const great = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 8 && queen.lipsyncScore < 12; });
    const good = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 4 && queen.lipsyncScore < 8; });
    const bad = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 2 && queen.lipsyncScore < 4; });
    const flop = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= -10 && queen.lipsyncScore < 2; });

    if (!riggoryLipsync) {
        for (let i = 0; i < bottomQueens.length; i++) {
            bottomQueens[i].lipsyncScore = (bottomQueens[i].lipsyncScore + bottomQueens[i].favoritism) - bottomQueens[i].unfavoritism;
        }
    }

    createLipsyncDesc(slay, great, good, bad, flop);
    screen.createButton("Show result", "slmLipSync()");
}

function slmLipSync() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("I've made my decision.");

    bottomQueens = bottomQueens.filter((q, idx, arr) => q && currentCast.includes(q) && arr.indexOf(q) === idx);

    if (bottomQueens.length < 2) {
        if (bottomQueens.length === 1) {
            const loneQueen = bottomQueens[0];
            if (loneQueen.blackStar > 0) {
                removeSLMBlackStar(loneQueen);
            }
            if (nomQueen === loneQueen) {
                nomQueen = null;
            }
            screen.createImage(loneQueen.getCurrentImage(), "tomato");
            screen.createBold(`${loneQueen.name}, there is no valid opponent. You stay in the competition and your Black Star is removed.`);
        } else {
            screen.createBold("No valid queens were available for the lip-sync.");
        }
        createPostLSBtn();
        return;
    }

    bottomQueens.sort((a, b) => (b.lipsyncScore - a.lipsyncScore));
    const winner = bottomQueens[0];
    const loser = bottomQueens[bottomQueens.length - 1];
    const additionalLosers = bottomQueens.slice(1, -1);
    const wasLoserCurrentNominee = !!(slmActiveNomineeInLipsync && loser === slmActiveNomineeInLipsync);
    const wasWinnerCurrentNominee = !!(slmActiveNomineeInLipsync && winner === slmActiveNomineeInLipsync);
    const losingQueensForResult = [...additionalLosers, loser];
    const enforceWeekOneBottomThreeNominees = () => {
        if (episodeCount !== 1 || bottomQueens.length < 3) {
            return;
        }
        nomQueen = loser;
        slmCoNominees = additionalLosers.filter((q) => q && q !== loser && currentCast.includes(q));
        slmNoNomineeReason = "";
    };

    toBlots(bottomQueens, alotsSong);

    screen.createImage(winner.getCurrentImage(), "tomato");
    screen.createBold(`${winner.name}, shantay you stay. You are safe.`);

    if (bottomQueens.length >= 3) {
        applySLMBottomThreePlacement(winner);
    } else if (slm2Modifier) {
        setSLMCurrentEpisodePlacement(winner, wasWinnerCurrentNominee ? "WIN NOM" : "WIN BTM2");
    } else {
        applySLMBottomPlacement(winner);
    }
    winner.unfavoritism += 3;
    winner.ppe += 1;

    if (winner.blackStar > 0) {
        removeSLMBlackStar(winner);
    }

    for (let i = 0; i < additionalLosers.length; i++) {
        const losingQueen = additionalLosers[i];
        if (!losingQueen || losingQueen === winner || losingQueen === loser) {
            continue;
        }
        screen.createImage(losingQueen.getCurrentImage(), "tomato");
        screen.createBold(`${losingQueen.name}, you lost this lip sync.`);
        applySLMBottomThreePlacement(losingQueen);
        applySLMBlackStar(losingQueen, screen, "nominee lip sync loss");
        if (losingQueen.nomEp.indexOf(episodeCount) === -1) {
            losingQueen.nomEp.push(episodeCount);
        }
        losingQueen.unfavoritism += 4;
        losingQueen.ppe += 1;
    }

    if (wasWinnerCurrentNominee) {
        nomQueen = null;
        slmCoNominees = [];
        slmNoNomineeReason = "saved";
        slmNoNomineeSelectorQueen = winner;
    }

    let loserEliminated = false;
    if (wasLoserCurrentNominee) {
        const gainedSecondBlackStar = applySLMBlackStar(loser, screen, "second Black Star lip sync loss");
        if (!gainedSecondBlackStar) {
            screen.createImage(loser.getCurrentImage(), "tomato");
            screen.createBold(`${loser.name} blocked the second Black Star and remains in the competition.`);
            nomQueen = loser;
            slmCoNominees = additionalLosers.filter((q) => q && q !== loser);
            enforceWeekOneBottomThreeNominees();
            loser.unfavoritism += 5;
            loser.ppe += 1;
            slmNoNomineeReason = "";
            toAlots([winner], losingQueensForResult, alotsSong);
            slmLastLipsyncWinner = winner;
            slmActiveNomineeInLipsync = null;
            slmVotedNomineeInLipsync = null;
            createPostLSBtn();
            return;
        }
        if (slm2Modifier) {
            screen.createImage(loser.getCurrentImage(), "tomato");
            screen.createBold(`${loser.name}, this is your second Black Star, but the rules keep you in the competition.`);
            if (loser.nomEp.indexOf(episodeCount) === -1) {
                loser.nomEp.push(episodeCount);
            }
            if (bottomQueens.length >= 3) {
                applySLMBottomThreePlacement(loser);
            } else {
                applySLMBottomPlacement(loser);
            }
            loser.unfavoritism += 5;
            loser.ppe += 1;
            nomQueen = loser;
            slmCoNominees = additionalLosers.filter((q) => q && q !== loser);
            enforceWeekOneBottomThreeNominees();
            slmNoNomineeReason = "";
            toAlots([winner], losingQueensForResult, alotsSong);
            slmLastLipsyncWinner = winner;
            slmActiveNomineeInLipsync = null;
            slmVotedNomineeInLipsync = null;
            createPostLSBtn();
            return;
        }
        screen.createImage(loser.getCurrentImage(), "red");
        screen.createBold(`${loser.name}, this is your second Black Star. Sashay away...`);

        if (topQueens.includes(loser)) {
            loser.editTrackRecord("ELIM");
            elimQueenWithTwists({
                screen,
                queen: loser,
                eliminationRecord: null,
                eliminationText: `${loser.name}, this is your second Black Star. Sashay away...`,
                skipImage: true,
            });
        } else {
            elimQueenWithTwists({
                screen,
                queen: loser,
                eliminationRecord: "ELIM",
                eliminationText: `${loser.name}, this is your second Black Star. Sashay away...`,
                skipImage: true,
            });
        }

        nomQueen = null;
        slmCoNominees = [];
        slmNoNomineeReason = "eliminated";
        loserEliminated = true;
    } else {
        applySLMBlackStar(loser, screen, "nominee lip sync loss");
        if (loser.nomEp.indexOf(episodeCount) === -1) {
            loser.nomEp.push(episodeCount);
        }

        screen.createImage(loser.getCurrentImage(), "tomato");
        screen.createBold(`${loser.name}, you now hold nominee status and must survive another lip sync to clear your Black Star.`);
        if (bottomQueens.length >= 3) {
            applySLMBottomThreePlacement(loser);
        } else {
            applySLMBottomPlacement(loser);
        }
        loser.unfavoritism += 5;
        loser.ppe += 1;
        nomQueen = loser;
        slmCoNominees = additionalLosers.filter((q) => q && q !== loser);
        enforceWeekOneBottomThreeNominees();
        applySLMBlackStarCarryPenalty(loser, screen);
        slmNoNomineeReason = "";
    }

    toAlots([winner], losingQueensForResult, alotsSong);

    slmLastLipsyncWinner = winner;
    slmActiveNomineeInLipsync = null;
    slmVotedNomineeInLipsync = null;

    if (loserEliminated) {
        doExitLines([loser]);
    }
    createPostLSBtn();
}

function createCritiqueProceedButton(screen) {
    if (slmFormat) {
        screen.createButton("Proceed", "slmJudging()");
        return;
    }
    if (pypTwist && !pypTwistUsed && currentCast.length == 11) 
        screen.createButton("Proceed", "pypJudging()");
    if (uk3Premiere && episodeCount === 1)
        screen.createButton("Proceed", "uk3PremiereJudging()");
    else if (uk8Premiere && episodeCount === 1)
        screen.createButton("Proceed", "uk8PremiereJudging()");
    else if (slayPremiere && (episodeCount === 1 || triplePremiereFlag && premiereCounter <= 3))
        screen.createButton("Proceed", "slayPremiereJudging()");
    else if (rosebudPremiere && episodeCount === 1)
        screen.createButton("Proceed", "rosePremiereJudging()");
    else if (can7Premiere && episodeCount === 1)
        screen.createButton("Proceed", "lsaPremiereJudging()");
    else if (attentionGGroup && currentCast.length === Math.round(totalCastSize / 2) && totalCastSize > 8 && !attggCounter)
        screen.createButton("Proceed", "winAndBtm2()");
    else if (regularFormat) {
        if (woodenbeaver && !woodenbeaverUsed && currentCast.length === 7)
            screen.createButton("Proceed", "winAndSafetyChain()");
        else
            screen.createButton("Proceed", "winAndBtm2()");
    }
    else if (safetyFormat) {
        screen.createButton("Proceed", "winAndSafetyChain()");
    }
    else if (dragula_format)
        screen.createButton("Proceed", "winAndUpForExt()");
    else if (titans_format)
        generateTitansButton(screen);
    else if (all_stars)
        screen.createButton("Proceed", "top2AndBtm()");
    else if (lipsync_assassin)
        screen.createButton("Proceed", "topAndBtm()");
    else if (team)
        screen.createButton("Proceed", "teamWinAndBtm2()");
    else
        screen.createButton("Proceed", "winAndBtm2()");
}

function uk8PremiereJudging() {
    const screen = new Scene();
    screen.clean();
    screen.createHeader("I've made my decision.");
    screen.createBold("After considering the performances and the judges' critiques...");

    topQueens.sort((a, b) => a.performanceScore - b.performanceScore);
    const judgedTopQueens = topQueens.slice(0, 2);
    if (judgedTopQueens.length < 2) {
        screen.createBold("There were not enough eligible contestants to form a Top 2.");
        screen.createButton("Proceed", "contestantProgress()");
        return;
    }

    topQueens = judgedTopQueens;
    topQueens.forEach((queen) => {
        if (queen.trackRecord[queen.trackRecord.length - 1] === "HIGH") {
            queen.trackRecord.pop();
        }
    });
    screen.createImage(topQueens[0].getCurrentImage(), "cyan");
    screen.createImage(topQueens[1].getCurrentImage(), "cyan");
    screen.createBold(`${topQueens[0].name}, ${topQueens[1].name}, condragulations, you're the Top 2 of the week!`);
    screen.createBold("You earned your place here through the Rate-A-Queen results and your performances in the Talent Show.");
    screen.createButton("Proceed", "doublePremiereJudging()");
}

