function drinkornot() {
    let judgingScreen = new Scene();
    let totaljudged = [...topQueens, ...bottomQueens]
    shuffle(totaljudged);
    if (hasImmunityPotions() && stills16Imm()) {
        for (let i = 0; i < currentCast.length; i++) {
            if (currentCast[i].immPotion && stills16Imm()) {
                judgingScreen.createHorizontalLine();
                judgingScreen.createImage(currentCast[i].getCurrentImage(), "magenta");
                if (currentCast.length === getImmunityPotionLastCastSize() && immunityPotionExpiry !== "none") {
                    judgingScreen.createBold(currentCast[i].name + ", this is your last chance before it expires. Do you wish to use your immunity potion this week?");
                } else {
                    judgingScreen.createBold(currentCast[i].name + ", do you wish to use your immunity potion this week?");
                }
                let answer = usePotion(currentCast[i]);
                judgingScreen.createImage(currentCast[i].getCurrentImage(), "magenta");
                if (answer) {
                    judgingScreen.createParagraph(currentCast[i].name + " said yes.");
                    judgingScreen.createHorizontalLine();
                    judgingScreen.createBold(currentCast[i].name + ", do you want to save yourself or one of your competitors?");
                    let meorthem = potionChoice(currentCast[i], currentCast);
                    if (meorthem == currentCast[i]) {
                        judgingScreen.createImage(currentCast[i].getCurrentImage(), "magenta");
                        judgingScreen.createParagraph(currentCast[i].name + " would like to save themselves.");
                        judgingScreen.createHorizontalLine();
                        judgingScreen.createImage(currentCast[i].getCurrentImage(), "black");
                        judgingScreen.createBold(currentCast[i].name + ", you are safe to slay another day.");
                        judgingScreen.createHorizontalLine();
                        currentCast[i].immPotion = false;
                        currentCast[i].immuneEp.push(episodeCount - 1);
                        if (topQueens.includes(currentCast[i])) {
                            topQueens.splice(topQueens.indexOf(currentCast[i]), 1);
                            totaljudged.splice(totaljudged.indexOf(currentCast[i]), 1);
                        } else if (bottomQueens.includes(currentCast[i])) {
                            bottomQueens.splice(bottomQueens.indexOf(currentCast[i]), 1);
                            totaljudged.splice(totaljudged.indexOf(currentCast[i]), 1);
                            if (bottomQueens.length < 2) {
                                currentCast.sort((a, b) => (a.performanceScore - b.performanceScore));
                                for (let y = currentCast.length - 1; y >= 0; y--) {
                                    if (!(currentCast[y].immuneEp.includes(episodeCount - 1) || bottomQueens.includes(currentCast[y]))) {
                                        bottomQueens.push(currentCast[y]);
                                        totaljudged.push(currentCast[y]);
                                        if (attentionGGroup && topQueens.includes(currentCast[y])) {
                                            topQueens.splice(topQueens.indexOf(currentCast[y]), 1);
                                            totaljudged.splice(totaljudged.indexOf(currentCast[y]), 1);
                                        }
                                        y = 0;
                                    }
                                }
                            }
                        }
                    } else {
                        judgingScreen.createImage(currentCast[i].getCurrentImage(), "black");
                        judgingScreen.createImage(meorthem.getCurrentImage(), "magenta");
                        judgingScreen.createParagraph(currentCast[i].name + " would like to save " + meorthem.name + ".");
                        modRelation(2, 2, currentCast[i], meorthem);
                        judgingScreen.createHorizontalLine();
                        judgingScreen.createImage(meorthem.getCurrentImage(), "magenta");
                        judgingScreen.createBold(meorthem.name + ", do you accept " + currentCast[i].name + "'s gift of immunity?");
                        judgingScreen.createHorizontalLine();
                        let answer2 = usePotion(currentCast[i]);
                        judgingScreen.createImage(meorthem.getCurrentImage(), "magenta");
                        if (answer2) {
                            judgingScreen.createParagraph(meorthem.name + " said yes.");
                            judgingScreen.createHorizontalLine();
                            judgingScreen.createImage(meorthem.getCurrentImage());
                            judgingScreen.createBold(meorthem.name + ", you are safe to slay another day.");
                            judgingScreen.createHorizontalLine();
                            currentCast[i].immPotion = false;
                            meorthem.immPotion = false;
                            meorthem.immuneEp.push(episodeCount - 1);
                            if (topQueens.includes(meorthem)) {
                                topQueens.splice(topQueens.indexOf(meorthem), 1);
                                totaljudged.splice(totaljudged.indexOf(meorthem), 1);
                            } else if (bottomQueens.includes(meorthem)) {
                                bottomQueens.splice(bottomQueens.indexOf(meorthem), 1);
                                totaljudged.splice(totaljudged.indexOf(meorthem), 1);
                                if (bottomQueens.length < 2) {
                                    currentCast.sort((a, b) => (a.performanceScore - b.performanceScore));
                                    for (let y = currentCast.length - 1; y >= 0; y--) {
                                        if (!(currentCast[y].immuneEp.includes(episodeCount - 1) || bottomQueens.includes(currentCast[y]))) {
                                            bottomQueens.push(currentCast[y]);
                                            totaljudged.push(currentCast[y]);
                                            if (attentionGGroup && topQueens.includes(currentCast[y])) {
                                                topQueens.splice(topQueens.indexOf(currentCast[y]), 1);
                                                totaljudged.splice(totaljudged.indexOf(currentCast[y]), 1);
                                            }
                                            y = 0;
                                        }
                                    }
                                }
                            }
                        } else {
                            judgingScreen.createParagraph(meorthem.name + " said no.");
                            judgingScreen.createHorizontalLine();
                        }
                    }
                } else {
                    judgingScreen.createParagraph(currentCast[i].name + " said no.");
                    judgingScreen.createHorizontalLine();
                }
            }
        }
    }
}

