function dropQueenImage(queen) {
    const images = Array.from(document.querySelectorAll("img"));
    const queenImg = queen.getCurrentImage();

    const matches = images.filter(img => img.src.includes(queenImg));
    if (matches.length === 0) return;

    const img = matches[matches.length - 1];

    img.style.transition = "transform 1.2s ease-in, opacity 1.2s ease-in";
    img.style.transform = "translateY(600px)";
    img.style.opacity = "0";
}

let pendingElims = 0;
let allElimsDone = false;
let ghostlyElimQueue = [];

function spawnElimButtonGlobal(qName) {
    const oldBtn = document.getElementById('elim-btn');
    if (oldBtn) oldBtn.remove();
    let screen = new Scene();
    console.log('[ghostly] spawnElimButtonGlobal called for', qName, 'queue=', ghostlyElimQueue);
    screen.createButton(
        "Proceed",
        `elimButtonHandler("${qName}")`,
        "elim-btn"
    );
}

function waitForClick(callback) {
    function handler() {
        document.removeEventListener("click", handler);
        callback();
    }
    document.addEventListener("click", handler);
}

function bottomGhostlyGallows() {
    let screen = new Scene();

    screen.createHorizontalLine();

    bottomQueens.forEach(q => {
        screen.createImage(q.getCurrentImage(), "tomato");
    });

    screen.createBold("You must now step right up to the ghostly gallows...");

    bottomQueens.sort((a, b) => a.performanceScore - b.performanceScore);

    let btmsize = bottomQueens.length;
    let safeQueens = [];
    let eliminatedQueens = [];

    if (bottomQueens.length === 4) {
        resolvePair(bottomQueens[0], bottomQueens[2]);
        resolvePair(bottomQueens[1], bottomQueens[3]);
    } else if (bottomQueens.length === 3) {
        stay(bottomQueens[1]);
        stay(bottomQueens[2]);
        sashay(bottomQueens[0]);
    } else if (bottomQueens.length === 2) {
        eliminateOne(bottomQueens[0], bottomQueens[1]);
    }

    function resolvePair(q1, q2) {
        screen.createParagraph(`${q1.name} and ${q2.name}, step forward.`);

        if (q1.performanceScore > q2.performanceScore) {
            stay(q1);
            sashay(q2);
        } else {
            stay(q2);
            sashay(q1);
        }
    }

    function eliminateOne(q1, q2) {
        let winner = q1.performanceScore > q2.performanceScore ? q1 : q2;
        let loser  = winner === q1 ? q2 : q1;

        stay(winner);
        sashay(loser);
    }

    function stay(q) {
        safeQueens.push(q);
        q.addToTrackRecord("BTM" + btmsize);
        q.ppe += 1;
    }

    function sashay(q) {
        pendingElims++;
        ghostlyElimQueue.push(q.name);
        if (ghostlyElimQueue.length === 1) {
            spawnElimButtonGlobal(ghostlyElimQueue[0]);
        }
    }
}

function elimButtonHandler(qId) {
    console.log('[ghostly] elimButtonHandler called for', qId, 'queue=', ghostlyElimQueue);
    let screen = new Scene();
    const btn = document.getElementById('elim-btn');
    if (btn) btn.remove();

    let q = bottomQueens.find(queen => queen.name === qId) ||
            currentCast.find(queen => queen.name === qId) ||
            eliminatedCast.find(queen => queen.name === qId);

    if (!q) {
        console.warn('[ghostly] queen object not found for', qId, '- removing from queue and continuing');
        ghostlyElimQueue = ghostlyElimQueue.filter(name => name !== qId);
        if (ghostlyElimQueue.length > 0) {
            console.log('[ghostly] spawning next for', ghostlyElimQueue[0], 'queue=', ghostlyElimQueue);
            spawnElimButtonGlobal(ghostlyElimQueue[0]);
        } else if (!allElimsDone) {
            allElimsDone = true;
            createPostLSBtn();
        }
        return;
    }

    screen.createBold(`${q.name}... you have been eliminated...`);

    elimQueenWithTwists({
        screen,
        queen: q,
        eliminationRecord: "ELIM",
        eliminationText: `${q.name}... you have been eliminated...`,
        skipImage: true,
    });

    const mainEl = screen._MainBlock;
    if (mainEl) {
        mainEl.style.transition = "transform 0.05s";
        mainEl.style.transform = "translateX(10px)";
        setTimeout(() => { mainEl.style.transform = "translateX(-10px)"; }, 50);
        setTimeout(() => { mainEl.style.transform = "translateX(5px)"; }, 100);
        setTimeout(() => { mainEl.style.transform = "translateX(-5px)"; }, 150);
        setTimeout(() => { mainEl.style.transform = "translateX(0px)"; }, 200);
    }


    dropQueenImage(q);

    if (ghostlyElimQueue.length > 0) {
        ghostlyElimQueue = ghostlyElimQueue.filter(name => name !== q.name);
        console.log('[ghostly] removed', q.name, 'from queue; queue now=', ghostlyElimQueue);
    }

    pendingElims--;

    if (ghostlyElimQueue.length > 0) {
        console.log('[ghostly] elim handled for', q.name, 'spawning next for', ghostlyElimQueue[0], 'queue=', ghostlyElimQueue);
        spawnElimButtonGlobal(ghostlyElimQueue[0]);
        return;
    }

    if (pendingElims <= 0 && !allElimsDone) {
        allElimsDone = true;
        createPostLSBtn();
    }
}


