let alotsExt = "";
let exts = [];
let allExts = [];
// Parses the textFiles lists: one entry per line, ignoring blank lines and any trailing comma left on an entry.
function parseTextFileList(data) {
    return String(data)
        .replace(/"/g, "")
        .split(/\r\n|\r|\n/)
        .map(line => line.trim().replace(/,+$/, "").trim())
        .filter(line => line.length > 0);
}

function loadExts() {
    fetch('textFiles/exterminations.txt')
        .then(res => res.text())
        .then(data => {
            let xts = parseTextFileList(data);

            exts = [...xts];      // main working array
            allExts = [...xts];   // backup/reset array
        });
}

loadExts()

function getExterminationFashaViss() {
    let screen = new Scene();
    let ext = randomNumber(0, exts.length - 1);
    while (exts[ext].trim().length < 1) {
        ext = randomNumber(0, exts.length - 1);
    }
    alotsExt = exts[ext].toString();
    screen.createBold(`The extermination challenge is... ${exts[ext]}!`);
    return exts.splice(ext, 1);
}

function bottomExtermination() {
    let screen = new Scene();
    screen.clean();
    if (riggoryLipsync) {
        for (let i = 0; i < bottomQueens.length; i++) {
            bottomQueens[i].getASLipsync();
        }
    } else {
        for (let i = 0; i < bottomQueens.length; i++) {
            bottomQueens[i].getLipsync();
            bottomQueens[i].lipsyncScore = (bottomQueens[i].lipsyncScore - bottomQueens[i].favoritism) + bottomQueens[i].unfavoritism;
        }
    }
    screen.createHeader("The extermination trial...");
    screen.createBold("The monsets will face off in the extermination trial to prove themselves...");
    let lowQueen = currentCast.find(q => q.trackRecord[q.trackRecord.length - 1] === "LOW") || currentCast.find(q => q.trackRecord[q.trackRecord.length - 1] === "SAVED");

    getExterminationFashaViss();
    if (luckydoll && !luckydollused && lowQueen !== undefined && currentCast.length >= 6) {
        let dollHolder = bottomQueens.find(q => q.luckydoll === true);

        if (dollHolder) {
            luckydollused = true;

            let saveCandidates = bottomQueens.slice();
            recordSaveTwist({name: "Lucky Doll"}, dollHolder, saveCandidates);
            if (dollHolder.maxiT == true) {
                dollHolder.editTrackRecord("SAVED");
            } else {
                dollHolder.addToTrackRecord("SAVED");
            }
            dollHolder.ppe += 2;

            screen.createImage(dollHolder.getCurrentImage(), "pink");
            screen.createImage("image/Queen.png", "gold");
            screen.createBold(`${dollHolder.name} you hold the lucky doll! This means you are now safe!`);

            lowQueen.trackRecord.pop();
            screen.createImage(lowQueen.getCurrentImage(), "tomato")
            screen.createBold(`${lowQueen.name}... I'm sorry my dear, but that means you are no longer safe, and up for elimination...`);
            bottomQueens.splice(bottomQueens.indexOf(dollHolder), 1, lowQueen);

            screen.createHorizontalLine();
        }
    }

    bottomQueens.forEach(q => q.addToTrackRecord("TBA"));

    let slay = bottomQueens.filter(function (queen) { return queen.lipsyncScore > 11; });
    let great = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 8 && queen.lipsyncScore < 12; });
    let good = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 4 && queen.lipsyncScore < 8; });
    let bad = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 2 && queen.lipsyncScore < 4; });
    let flop = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= -10 && queen.lipsyncScore < 2; });
    createExtDesc(slay, great, good, bad, flop);
    createPostLSBtn();
}

function extDeathScene() {
    checkDGULAElims();
    let screen = new Scene();
    screen.clean();
    if (!solidbk) {
        setBackgroundToStage();
    }
    screen.createHeader("Extermination");

    screen.createBold("The fate of the exterminated contestant is revealed...");
    screen.createHorizontalLine();

    const deathScenarios = [
        q => `${q.name} is sitting at a tea party. As the tea reaches ${getPronoun(q, "possessive")} lips, foam begins to spill from ${getPronoun(q, "possessive")} mouth, followed by a sudden collapse to the ground...`,
        q => `${q.name} is taking a peaceful stroll through a garden when a strange cloud of poisonous gas surrounds ${getPronoun(q, "object")}. Within seconds, ${getPronoun(q, "possessive")} knees buckle and ${getPronoun(q, "subject")} falls lifelessly to the ground...`,
        q => `${q.name} is admiring a beautiful mirror when it suddenly shatters. A mysterious mist escapes from the glass, engulfing ${getPronoun(q, "object")} before ${getPronoun(q, "subject")} collapses...`,
        q => `${q.name} is enjoying a luxurious bubble bath when the water begins to change color. Bubbles cover ${getPronoun(q, "possessive")} face, and soon ${getPronoun(q, "subject")} sinks beneath the surface...`,
        q => `${q.name} is enjoying a candlelit dinner when every candle suddenly goes out. A mysterious figure appears behind ${getPronoun(q, "object")}, and a moment later, ${getPronoun(q, "subject")} is found motionless on the floor...`
    ];

    dragulaElm.forEach(q => {
        const deathScenario = deathScenarios[Math.floor(Math.random() * deathScenarios.length)];
        screen.createBWImage(q.getCurrentImage(), "red");
        screen.createParagraph(deathScenario(q));
        screen.createBold(`${q.name} has been exterminated.`);
        screen.createHorizontalLine();
    });

    if (dragulaElm.length === 0) {
        screen.createParagraph("No contestant was exterminated.");
    }

    screen.createButton("Proceed", "untucked()");
}

