// Looks up the partner(s) that would come back from eliminatedCast for the given winner name(s)
// during the Conjoined Queens twist, so the rig screen can preview a return before it's confirmed.
function getConjoinedReturnPreviewNames(winnerNames) {
    if (!conjoinedQueens || !conjoinedCheck || !Array.isArray(twinsMakeover) || !Array.isArray(winnerNames)) return [];
    const names = [];
    winnerNames.forEach(winnerName => {
        for (let i = 0; i < twinsMakeover.length - 1; i++) {
            if (twinsMakeover[i].name === winnerName) {
                const partner = twinsMakeover[i + 1];
                if (partner && partner.name !== winnerName && !names.includes(partner.name)) {
                    names.push(partner.name);
                }
            }
        }
    });
    return names;
}

function rigWB2OC(screen) {
    screen.clean();
    screen.createHeader("Make your decision...");
    screen.createBold("Ladies, I've made some decisions...");

    if (!solidbk) setBackgroundToStage();

    screen.createBold("Top Queens - Toggle winners:");
    screen.createParagraph("", "rigTopContainer");
    const rigTopContainer = document.getElementById("rigTopContainer");
    topQueens.forEach((q, index) => {
        const selected = rigWB2Winners.includes(q.name);
        const trackRecordStr = q.trackRecord.join(' - ') || 'No track record yet';
        const qNameEscaped = q.name.replace(/"/g, '&quot;');
        const trackEscaped = trackRecordStr.replace(/"/g, '&quot;');
        rigTopContainer.innerHTML += `<div class="rigItem" data-queen-name="${qNameEscaped}" data-track-record="${trackEscaped}" style="display:inline-block;text-align:center;margin:6px;" title="${trackRecordStr}">
            <img src="${q.getCurrentImage()}" style="width:96px;height:auto;display:block;margin:0 auto 6px;border-radius:50%;object-fit:cover;"/>
            <button data-queen-name="${qNameEscaped}" data-toggle-type="top" class="rigToggleBtn" style="min-width:120px">${q.name.split(' ')[0]} ${selected ? "★" : "☆"}</button>
        </div>`;
    });
    bindRigLongPressTrackRecord(rigTopContainer);
    
    setTimeout(() => {
        document.querySelectorAll('[data-toggle-type="top"]').forEach(btn => {
            btn.onclick = () => toggleRigTop(btn.getAttribute('data-queen-name'));
        });
    }, 0);

    if (conjoinedQueens && conjoinedCheck) {
        const returningNames = getConjoinedReturnPreviewNames(rigWB2Winners);
        screen.createBold(returningNames.length > 0
            ? `Conjoined Queens twist: ${returningNames.join(", ")} will return to the competition if this win is confirmed.`
            : "Conjoined Queens twist is active — toggle a winner to preview who returns.");
        screen.createHorizontalLine();
    }

    screen.createButton(
        `Double Win: ${rigWB2DoubleWin ? "Y" : "N"}`,
        `toggleDoubleWin()`
    );
    if (isTeamChallenge && canUseOutsideRupaulTeamWins()) {
        screen.createButton(
            `Team Win: ${rigWB2TeamWin ? "Y" : "N"}`,
            `toggleTeamWin()`
        );
    }

    screen.createHorizontalLine();

    let isGoldenBeaver = goldenBeaverTwist && stillBeaver() && !immunityTwist && bottomQueens.length > 2;
    let isMandatoryNoSave = isMandatoryBottomNoSaveRound();
    let hasWinner = rigWB2Winners.length > 0;
    let isNotDoubleWin = !rigWB2DoubleWin;
    
    if (isGoldenBeaver && topQueens.length > 0 && hasWinner && isNotDoubleWin) {
        try {
            let winnerQueen = topQueens.find(q => q.name === rigWB2Winners[0]);
            if (winnerQueen) {
                let predictedSaved = bestSister(winnerQueen, bottomQueens);
                rigGoldenBeaverSaved = predictedSaved.name;
                if (!rigBottomQueens.includes(rigGoldenBeaverSaved)) {
                    rigBottomQueens.push(rigGoldenBeaverSaved);
                }
                screen.createBold("A Saving Twist is Active - Auto-Predicted Save:");
                screen.createParagraph(`${winnerQueen.name} will save their best friend: ${rigGoldenBeaverSaved}`, "");
                screen.createHorizontalLine();
            } else {
                rigGoldenBeaverSaved = null;
            }
        } catch (e) {
            rigGoldenBeaverSaved = null;
        }
    } else {
        rigGoldenBeaverSaved = null;
    }

    screen.createBold("Bottom Queens - Toggle safe:");
    if (isMandatoryNoSave) {
        screen.createParagraph("Safe picks are locked this round because this format requires all bottom queens to stay at risk.");
    }
    screen.createParagraph("", "rigBottomContainer");
    const rigBottomContainer = document.getElementById("rigBottomContainer");
    bottomQueens.forEach((q) => {
        const selected = rigBottomQueens.includes(q.name);
        const isGBSaved = rigGoldenBeaverSaved === q.name;
        const trackRecordStr = q.trackRecord.join(' - ') || 'No track record yet';
        const qNameEscaped = q.name.replace(/"/g, '&quot;');
        const trackEscaped = trackRecordStr.replace(/"/g, '&quot;');

        const disableSafePick = isGoldenBeaver || isMandatoryNoSave;
        const buttonDisabled = disableSafePick ? 'disabled' : '';
        const buttonStyle = disableSafePick ? 'opacity:0.6;cursor:not-allowed;' : '';

        rigBottomContainer.innerHTML += `<div class="rigItem" data-queen-name="${qNameEscaped}" data-track-record="${trackEscaped}" style="display:inline-block;text-align:center;margin:6px;" title="${isGBSaved ? 'Golden Beaver Saved: ' + trackRecordStr : trackRecordStr}">
            <img src="${q.getCurrentImage()}" style="width:96px;height:auto;display:block;margin:0 auto 6px;border-radius:50%;object-fit:cover;${isGBSaved ? 'border:2px solid gold;' : ''}" title="${isGBSaved ? 'Golden Beaver Saved: ' + trackRecordStr : trackRecordStr}" />
            <button data-queen-name="${qNameEscaped}" data-toggle-type="bottom" class="rigToggleBtn" style="min-width:120px;${buttonStyle}" ${buttonDisabled}>${q.name.split(' ')[0]} ${selected ? "★" : "☆"}${isGBSaved ? ' 🛟' : ''}</button>
        </div>`;
    });
    bindRigLongPressTrackRecord(rigBottomContainer);
    
    setTimeout(() => {
        document.querySelectorAll('[data-toggle-type="bottom"]').forEach(btn => {
            btn.onclick = () => toggleRigBottom(btn.getAttribute('data-queen-name'));
        });
    }, 0);

    if (bottomQueens.length == 3) {
        screen.createButton(
            `Bottom Three: ${rigbtm3 ? "Y" : "N"}`,
            `toggleBottomThree()`
        );
    }

    if (bottomQueens.length == 4) {
        screen.createButton(
            `Bottom Four: ${rigBottomFour ? "Y" : "N"}`,
            `toggleBottomFour()`
        );
    }

    screen.createHorizontalLine();
    screen.createButton("Finish Rigging", "finishRigging()");
    rigTimeOver = true;
}

function toggleRigTop(name) {
    const i = rigWB2Winners.indexOf(name);
    if (i > -1) rigWB2Winners.splice(i, 1);
    else rigWB2Winners.push(name);
    rigWB2OC(new Scene());
}
