    screen.createHorizontalLine();

    const vaporizedQueen = worstSister(winner, evaporateableQueens);

    screen.createImage(winner.getCurrentImage(), "royalblue");
    screen.createImage(vaporizedQueen.getCurrentImage(), "red", "vaporizedQueenImg");
    screen.createBold(vaporizedQueen.name + "...");

    elimQueenWithTwists({
        screen,
        queen: vaporizedQueen,
        eliminationRecord: "ELIM",
        eliminationText: vaporizedQueen.name + "...",
        skipImage: true,
    });
    vaporizedQueen.ppe += 0;

    const savedQueens = evaporateableQueens.filter(q => q !== vaporizedQueen);
