let mismovoto = false;
function animateLipstickRevealNode(revealImg) {
    if (!revealImg) return;

    const styleId = "lipstickRevealAnimationStyles";
    if (!document.getElementById(styleId)) {
        const style = document.createElement("style");
        style.id = styleId;
        style.textContent = `
@keyframes lipstickRevealPop {
    0% {
        opacity: 0;
        transform: translateY(16px) scale(0.86) rotate(-6deg);
        filter: blur(2px);
    }
    60% {
        opacity: 1;
        transform: translateY(-4px) scale(1.03) rotate(1deg);
        filter: blur(0);
    }
    100% {
        opacity: 1;
        transform: translateY(0) scale(1) rotate(0);
        filter: blur(0);
    }
}
.lipstick-reveal-anim {
    animation: lipstickRevealPop 520ms cubic-bezier(0.22, 0.61, 0.36, 1);
    will-change: transform, opacity, filter;
}
        `;
        document.head.appendChild(style);
    }

    const target = revealImg.parentElement || revealImg;
    target.hidden = false;
    target.style.display = "inline-block";
    target.classList.remove("lipstick-reveal-anim");
    // Restart animation on repeated reveals.
    void target.offsetWidth;
    target.classList.add("lipstick-reveal-anim");
}

function showvotes() {
    let button = document.querySelector("button#showvotes");
    let div = document.querySelector("div#votes");
    button.remove();

    let winV = document.querySelectorAll("p#winVP");

    winV.forEach(node => node.removeAttribute("hidden"));
    div.removeAttribute("hidden");
    div.style.display = "block";

    if (lipsync_assassin) {
        const revealId = top2[0] ? top2[0].lipstickRevealId : null;
        const revealImg = revealId ? document.getElementById(revealId) : null;
        if (revealImg) {
            animateLipstickRevealNode(revealImg);
        } else {
            let imageVoted = document.querySelectorAll("img[src='" + top2[0].lipstick.getCurrentImage() + "']");
            if (imageVoted.length > 1) imageVoted[1].removeAttribute("hidden");
        }
    }
    else if (all_stars) {
        const revealIds = top2.map(q => q.lipstickRevealId).filter(Boolean);
        if (revealIds.length) {
            revealIds.forEach(id => {
                const revealImg = document.getElementById(id);
                animateLipstickRevealNode(revealImg);
            });
        } else if (mismovoto) {
            let sharedImgs = document.querySelectorAll(`img[src='${top2[0].lipstick.getCurrentImage()}']`);
            sharedImgs.forEach((img, i) => { if (i > 0) img.removeAttribute("hidden"); });
        }
        else {
            top2.forEach((queen, i) => {
                let votedImgs = document.querySelectorAll(`img[src='${queen.lipstick.getCurrentImage()}']`);
                if (votedImgs.length > i + 1) votedImgs[i + 1].removeAttribute("hidden");
            });
        }
    }
}
