function addMoney(q, s) {
    q.money += s;
}

const defaultPrizeSettings = Object.freeze({
    enabled: false,
    currency: "USD",
    grand: 100000,
    runnerUp: 0,
    challenge: 5000,
    title: 0,
    shared: "each",
    challengeMode: "cash",
    challengeReward: ""
});
let prizeSettings = { ...defaultPrizeSettings };

function applyPrizeSettings() {
    const enabledControl = document.getElementById("custom-prizes");
    if (!enabledControl) return true;
    if (!enabledControl.checked) {
        prizeSettings = { ...defaultPrizeSettings };
        return true;
    }
    const settings = { ...defaultPrizeSettings, enabled: true };
    const amountControls = {
        grand: "prize-grand",
        runnerUp: "prize-runner-up",
        challenge: "prize-challenge",
        title: "prize-title"
    };
    for (const [key, id] of Object.entries(amountControls)) {
        const input = document.getElementById(id);
        if (!input || input.value.trim() === "" || !input.checkValidity()) {
            showCustomStatusPopup("Enter a valid prize amount between 0 and 1,000,000,000, with at most two decimal places.", "Prize Customization");
            if (input) input.reportValidity();
            return false;
        }
        settings[key] = Number(input.value);
    }
    settings.currency = document.getElementById("prize-currency").value;
    settings.shared = document.getElementById("prize-shared").value;
    settings.challengeMode = document.getElementById("prize-challenge-mode").value;
    settings.challengeReward = document.getElementById("prize-challenge-reward").value.trim();
    if (settings.challengeMode !== "cash" && !settings.challengeReward) {
        showCustomStatusPopup("Enter a non-cash reward, or choose Cash only.", "Prize Customization");
        document.getElementById("prize-challenge-reward").focus();
        return false;
    }
    prizeSettings = settings;
    return true;
}

function restorePrizeSettings(savedSettings) {
    prizeSettings = { ...defaultPrizeSettings, ...savedSettings };
    const controls = {
        currency: "prize-currency",
        grand: "prize-grand",
        runnerUp: "prize-runner-up",
        challenge: "prize-challenge",
        title: "prize-title",
        shared: "prize-shared",
        challengeMode: "prize-challenge-mode",
        challengeReward: "prize-challenge-reward"
    };
    for (const [key, id] of Object.entries(controls)) {
        const input = document.getElementById(id);
        if (input) input.value = String(prizeSettings[key]);
    }
    const enabledControl = document.getElementById("custom-prizes");
    if (enabledControl) {
        enabledControl.checked = prizeSettings.enabled;
        enabledControl.dispatchEvent(new Event("change", { bubbles: true }));
    }
}

function formatPrizeMoney(amount, currency = prizeSettings.currency) {
    return new Intl.NumberFormat("en-US", {
        style: "currency",
        currency,
        minimumFractionDigits: 0,
        maximumFractionDigits: 2
    }).format(amount);
}

function resetContestantPrizes(queen) {
    queen.money = 0;
    queen.prizeAwards = [];
    queen.prizeCurrency = prizeSettings.currency;
    if (queen.QueenA && queen.QueenB) {
        resetContestantPrizes(queen.QueenA);
        resetContestantPrizes(queen.QueenB);
    }
}

function recordPrizeAward(queen, kind, label, amount, reward = "") {
    addMoney(queen, amount);
    queen.prizeCurrency = prizeSettings.currency;
    if (!Array.isArray(queen.prizeAwards)) queen.prizeAwards = [];
    queen.prizeAwards.push({ kind, label, amount, reward, episode: episodeCount });
    if (prizeSettings.enabled && (amount > 0 || reward)) {
        const paragraph = document.createElement("p");
        const cash = amount > 0 ? formatPrizeMoney(amount) : "";
        paragraph.textContent = `${queen.name} receives ${[cash, reward].filter(Boolean).join(" and ")} (${label}).`;
        const main = document.querySelector("div#MainBlock");
        if (main) main.appendChild(paragraph);
    }
}

function awardChallengePrize(queen, winners = [queen], defaultAmount = 5000) {
    let amount = defaultAmount;
    let reward = "";
    if (prizeSettings.enabled) {
        amount = prizeSettings.challengeMode === "reward" ? 0 : prizeSettings.challenge;
        if (prizeSettings.shared === "split") {
            const uniqueWinners = [...new Set(winners)];
            const index = uniqueWinners.indexOf(queen);
            if (index === -1) throw new Error("Challenge prize recipient is not in the shared winners list.");
            const cents = Math.round(amount * 100);
            amount = (Math.floor(cents / uniqueWinners.length) + (index < cents % uniqueWinners.length ? 1 : 0)) / 100;
        }
        if (prizeSettings.challengeMode !== "cash") reward = prizeSettings.challengeReward;
    }
    recordPrizeAward(queen, "challenge", "Challenge win", amount, reward);
}

function awardCustomizedChallengePrizes(winners) {
    if (prizeSettings.enabled) {
        winners.forEach(queen => awardChallengePrize(queen, winners));
    }
}

function awardSeasonPrize(queen) {
    recordPrizeAward(queen, "grand", "Grand prize", prizeSettings.grand);
}

function awardTitlePrize(queen, title) {
    if (!prizeSettings.enabled || prizeSettings.title === 0) return;
    if (queen.prizeAwards?.some(award => award.kind === "title" && award.label === title)) return;
    recordPrizeAward(queen, "title", title, prizeSettings.title);
}

function awardPlacementPrize(queen, placement) {
    if (!prizeSettings.enabled) return;
    if (["RUNNER UP", "LOST 3RD ROUND", "2NDPLACE"].includes(placement)
        && !queen.prizeAwards?.some(award => award.kind === "runnerUp")) {
        recordPrizeAward(queen, "runnerUp", "Runner-up prize", prizeSettings.runnerUp);
    }
    const titles = {
        "GOLDEN BOOT": "Golden Boot",
        "MISS LOST LOOK": "Mx. Lost Look",
        "MISS MAKEUP": "Mx. Makeup",
        "DRAG POP STAR": "Drag Popstar",
        "MISS CON DRAG POP STAR": "Drag Popstar",
        "MISS HUNGRY": "Mx. Hungry",
        "GRANT WINNER": "Grant Winner",
        "MISS BRICK": "Mx. Brick",
        "MISS ROBBED": "Mx. Robbed"
    };
    if (placement === "WINNER ") awardTitlePrize(queen, "Queen of She Done Already Done Had Herses");
    if (titles[placement]) awardTitlePrize(queen, titles[placement]);
}

