// remove any stored custom judges with prohibited name (Lexi Love)
if (allCustomJudges && allCustomJudges.length) {
    const before = allCustomJudges.length;
    allCustomJudges = allCustomJudges.filter(j => !(j && j.name && String(j.name).trim().toLowerCase() === 'lexi love'));
    if (allCustomJudges.length !== before) {
        localStorage.setItem('customJudges', JSON.stringify(allCustomJudges));
    }
}

