function customJudgeSelectList() {
    let select = document.getElementById("custom-judge-remove");
    if (!select) return;
    select.innerHTML = "";
    allCustomJudges.forEach((judge, index) => {
        let option = document.createElement("option");
        option.value = index;
        option.textContent = judge.name;
        select.appendChild(option);
    });
    let previewDiv = document.getElementById("judgeDropdownPreview");
    function updateDropdownPreview() {
        if (!previewDiv) return;
        previewDiv.innerHTML = "";
        let idx = parseInt(select.value);
        if (!isNaN(idx) && allCustomJudges[idx]) {
            let b = document.createElement("b");
            b.innerHTML = "<br>Preview<br>";
            let img = document.createElement("img");
            img.src = resolveTrackedCustomImage(allCustomJudges[idx].imageUrl || "noimage");
            img.setAttribute("style", `border-color: gold; width: 105px; height: 105px;`);
            previewDiv.appendChild(b);
            previewDiv.appendChild(img);
        }
    }
    select.addEventListener('change', updateDropdownPreview);
    if (select.options.length > 0) {
        select.selectedIndex = 0;
        updateDropdownPreview();
    }
}

