function triggerImportJudges() {
    const picker = document.getElementById('judgeFilePicker');
    if (!picker) return;
    picker.onchange = importJudgesFromFile;
    picker.click();
}

function importJudgesFromFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function (ev) {
        try {
            const parsed = JSON.parse(ev.target.result);
            if (!Array.isArray(parsed)) throw new Error('Invalid format');
            const valid = parsed.filter(x => x && typeof x.name === 'string');
            if (valid.length === 0) throw new Error('No valid judges');
            valid.forEach(v => {
                if (!allCustomJudges.some(j => j.name === v.name)) {
                    allCustomJudges.push({ name: v.name, imageUrl: v.imageUrl || 'noimage' });
                }
            });
            localStorage.setItem('customJudges', JSON.stringify(allCustomJudges));
            mergeCustomJudgesToGuests();
            customJudgeSelectList();
            alert('Imported judges successfully');
        } catch (err) {
            alert('Failed to import judges: ' + err.message);
        }
    };
    reader.readAsText(file);
}

function updateJudgePreview(imageUrl) {
    let input = document.getElementById("judgeImageUrl");
    if (!input) return;
    let existingLabel = document.getElementById("judge-bnomasbb");
    let existingImg = document.getElementById("judge-nomasbb");
    if (existingLabel) existingLabel.remove();
    if (existingImg) existingImg.remove();

    let b = document.createElement("b");
    b.innerHTML = "<br>Preview<br>";
    b.setAttribute("id", "judge-bnomasbb");
    let image = document.createElement("img");
    image.src = resolveTrackedCustomImage(imageUrl || "noimage");
    image.setAttribute("style", `border-color: gold; width: 105px; height: 105px;`);
    image.setAttribute("id", "judge-nomasbb");
    input.parentElement.append(b);
    input.parentElement.append(image);
}

