function setupDDLCSystem() {
    const style = document.createElement('style');
    style.innerHTML = `
       .ddlc-overlay {
        display: none;
        position: fixed;
        top: 0; left: 0;
        width: 100%; height: 100%;
        background: rgba(0, 0, 0, 0.7);
        z-index: 10000;
        align-items: center;
        justify-content: center;
        font-family: 'Verdana', sans-serif;
    }

    .ddlc-box {
        background: #ffe6f4;
        border: 4px solid #ffbee1;
        border-radius: 0;          /* remove rounded corners */
        box-shadow: none;          /* remove glow */
        filter: none;              /* ensure no glow effects */
        animation: ddlcPop 0.3s ease-out;
    }

    .ddlc-body {
        padding: 25px;
    }

    .ddlc-text {
        color: #000;
        font-size: 18px;
        margin-bottom: 20px;
    }

    .ddlc-button {
        color: white;
        font-size: 16px;
        padding: 8px 18px;

            text-shadow:
        -1px  0   0 #bd5b9c,
         1px  0   0 #bd5b9c,
         0   -1px 0 #bd5b9c,
         0    1px 0 #bd5b9c,
        -1px -1px 0 #bd5b9c,
         1px -1px 0 #bd5b9c,
        -1px  1px 0 #bd5b9c,
         1px  1px 0 #bd5b9c;

         font-weight: 600;


        background: none;
        border-radius: 0;
        box-shadow: none;

        cursor: pointer;
        transition: background 0.2s, color 0.2s;
    }

    .ddlc-button:hover {
    background: none;
        border-radius: 0;
        box-shadow: none;

    }


    @keyframes ddlcPop {
        from {
            transform: scale(0.9);
            opacity: 0;
        }
        to {
            transform: scale(1);
            opacity: 1;
        }
    }
    `;
    document.head.appendChild(style);
    const modalHtml = `
        <div class="ddlc-box">
            <div class="ddlc-body">
                <p id="ddlc-text" class="ddlc-text"></p>
                <button class="ddlc-button" onclick="closeDDLC()">OK</button>
            </div>
        </div>
    `;
    const container = document.createElement('div');
    container.id = 'ddlc-modal';
    container.className = 'ddlc-overlay';
    container.innerHTML = modalHtml;
    document.body.appendChild(container);
}

