function populateCustomFlagSelect(selectedValue = "") {
    const select = document.getElementById("customCountry");
    if (!select) return;

    select.innerHTML = "";
    CUSTOM_FLAG_OPTIONS.forEach(option => {
        const opt = document.createElement("option");
        opt.value = option.value;
        opt.textContent = option.label;
        select.appendChild(opt);
    });

    if (selectedValue && !CUSTOM_FLAG_OPTIONS.some(o => o.value === selectedValue)) {
        const opt = document.createElement("option");
        opt.value = selectedValue;
        opt.textContent = selectedValue;
        select.appendChild(opt);
    }

    select.value = selectedValue || "";
}

