function updatePremiereTypes(preferredValue = "") {
    const groupSelect = document.getElementById("premiere-group");
    const typeSelect = document.getElementById("premiere-type");

    if (!groupSelect || !typeSelect)
        return;

    const premiereTypes = PREMIERE_TYPES[groupSelect.value] || [];

    typeSelect.innerHTML = "";

    for (const premiereType of premiereTypes) {
        const option = document.createElement("option");
        option.value = premiereType.value;
        option.textContent = premiereType.label;
        if (premiereType.desc) {
            option.title = premiereType.desc;
        }
        typeSelect.appendChild(option);
    }

    if (preferredValue && premiereTypes.some(p => p.value == preferredValue))
        typeSelect.value = preferredValue;

    syncPremiereSelection();
}

function syncPremiereSelection() {
    const groupSelect = document.getElementById("premiere-group");
    const typeSelect = document.getElementById("premiere-type");
    const premiereSelect = document.getElementById("premiere-format");
    const descText = document.getElementById("premiere-desc-text");

    if (!typeSelect || !premiereSelect || !typeSelect.value)
        return;

    const selected = typeSelect.options[typeSelect.selectedIndex];

    premiereSelect.innerHTML = "";

    const option = document.createElement("option");
    option.value = typeSelect.value;
    option.textContent = selected.textContent;

    premiereSelect.appendChild(option);

    premiereSelect.selectedIndex = 0;

    if (descText && groupSelect) {
        const premiereTypes = PREMIERE_TYPES[groupSelect.value] || [];
        const currentItem = premiereTypes.find(p => p.value === typeSelect.value);
        descText.textContent = currentItem && currentItem.desc ? currentItem.desc : "";
    }
    updateSetupSummary();
}

function randomizePremiereSettingReady() {
    const groupSelect = document.getElementById("premiere-group");
    const typeSelect = document.getElementById("premiere-type");

    if (!groupSelect || !typeSelect)
        return;

    const groups = Object.keys(PREMIERE_TYPES);

    groupSelect.value = groups[Math.floor(Math.random() * groups.length)];

    updatePremiereTypes();

    const premiereTypes = PREMIERE_TYPES[groupSelect.value];

    const randomType = premiereTypes[Math.floor(Math.random() * premiereTypes.length)];

    typeSelect.value = randomType.value;

    syncPremiereSelection();

    groupSelect.classList.remove("setting-randomized");
    typeSelect.classList.remove("setting-randomized");

    void groupSelect.offsetWidth;

    groupSelect.classList.add("setting-randomized");
    typeSelect.classList.add("setting-randomized");

    setTimeout(() => {
        groupSelect.classList.remove("setting-randomized");
        typeSelect.classList.remove("setting-randomized");
    }, 600);
}

