function updateFinaleTypes(preferredValue = "") {
    const sizeSelect = document.getElementById("finale-size");
    const typeSelect = document.getElementById("finale-type");
    if (!sizeSelect || !typeSelect) return;

    const finaleTypes = FINALE_TYPES[sizeSelect.value] || [];
    typeSelect.innerHTML = "";

    for (const finaleType of finaleTypes) {
        const option = document.createElement("option");
        option.value = finaleType.value;
        option.textContent = finaleType.label;
        if (finaleType.desc) {
            option.title = finaleType.desc;
        }
        typeSelect.appendChild(option);
    }

    if (preferredValue && finaleTypes.some(finaleType => finaleType.value === preferredValue)) {
        typeSelect.value = preferredValue;
    }

    syncFinaleSelection();
}

function syncFinaleSelection() {
    const sizeSelect = document.getElementById("finale-size");
    const typeSelect = document.getElementById("finale-type");
    const finaleSelect = document.getElementById("finale");
    const descText = document.getElementById("finale-desc-text");
    if (!typeSelect || !finaleSelect || !typeSelect.value) return;

    const selectedType = typeSelect.options[typeSelect.selectedIndex];
    finaleSelect.innerHTML = "";

    const option = document.createElement("option");
    option.value = typeSelect.value;
    option.textContent = selectedType.textContent;
    finaleSelect.appendChild(option);
    finaleSelect.selectedIndex = 0;

    if (descText && sizeSelect) {
        const finaleTypes = FINALE_TYPES[sizeSelect.value] || [];
        const currentItem = finaleTypes.find(f => f.value === typeSelect.value);
        descText.textContent = currentItem && currentItem.desc ? currentItem.desc : "";
    }

    if (typeof updateTargetEpisodeControls === "function") {
        updateTargetEpisodeControls();
    }
}

function randomizeFinaleSettingReady() {
    const sizeSelect = document.getElementById("finale-size");
    const typeSelect = document.getElementById("finale-type");
    if (!sizeSelect || !typeSelect) return;

    const sizes = Object.keys(FINALE_TYPES);
    sizeSelect.value = sizes[Math.floor(Math.random() * sizes.length)];
    updateFinaleTypes();

    const finaleTypes = FINALE_TYPES[sizeSelect.value];
    const randomType = finaleTypes[Math.floor(Math.random() * finaleTypes.length)];
    typeSelect.value = randomType.value;
    syncFinaleSelection();

    sizeSelect.classList.remove("setting-randomized");
    typeSelect.classList.remove("setting-randomized");
    void sizeSelect.offsetWidth;
    sizeSelect.classList.add("setting-randomized");
    typeSelect.classList.add("setting-randomized");

    setTimeout(() => {
        sizeSelect.classList.remove("setting-randomized");
        typeSelect.classList.remove("setting-randomized");
    }, 600);
}

document.addEventListener("DOMContentLoaded", () => {
    document.getElementById("judging-panel")?.addEventListener("change", updateJudgingPanelDescription);
    updateJudgingPanelDescription();
    updateFinaleTypes();
    updatePremiereTypes();
    updateTargetEpisodeControls();
    initializeSettingsQualityOfLife();
});

function randomizeJudgingPanelReady() {
    const sel = document.getElementById("judging-panel");
    if (!sel) return;
    const opts = [...sel.options].filter(o => o.value !== "random");
    sel.value = opts[Math.floor(Math.random() * opts.length)].value;
    sel.classList.remove("setting-randomized");
    void sel.offsetWidth;
    sel.classList.add("setting-randomized");
    setTimeout(() => sel.classList.remove("setting-randomized"), 600);
}

function randomizeSettingReady(selectId) {
    const sel = document.getElementById(selectId);
    if (!sel) return;
    const opts = [...sel.options].filter(o =>
        !SETTINGS_EXCLUDED.has(o.value) && !o.text.includes("(N/A)")
    );
    if (!opts.length) return;
    const pick = opts[Math.floor(Math.random() * opts.length)];
    sel.value = pick.value;
    sel.classList.remove("setting-randomized");
    void sel.offsetWidth;
    sel.classList.add("setting-randomized");
    setTimeout(() => sel.classList.remove("setting-randomized"), 600);
}

const lockedSimulationSettings = new Set();
const simulationSettingIds = ["judging-panel", "premiere-group", "premiere-type", "returning", "format", "finale-size", "finale-type", "target-episodes-mode", "target-episodes"];
let pendingSettingsRandomization = null;

function readSimulationSettings() {
    return Object.fromEntries(simulationSettingIds.map(id => [id, document.getElementById(id)?.value]));
}

function updateSetupSummary() {
    updateJudgingPanelDescription();
    window.DragSetup?.changed();
    const summary = document.getElementById("sim-setup-summary");
    if (!summary) return;
    const label = id => {
        const select = document.getElementById(id);
        return select?.options[select.selectedIndex]?.textContent || "";
    };
    const count = currentCast.length;
    const judges = label("judging-panel");
    const premiere = [label("premiere-group"), label("premiere-type")].filter(Boolean).join(" / ");
    const finale = [label("finale-size"), label("finale-type")].filter(Boolean).join(" / ");
    const episodes = document.getElementById("target-episodes-mode")?.value === "fixed"
        ? `${document.getElementById("target-episodes").value} episodes`
        : "No episode forcing";
    summary.textContent = [`${count} contestant${count === 1 ? "" : "s"}`, judges, premiere, label("format"), finale, episodes].filter(Boolean).join(" · ");
}

function clearSettingsRandomizationUndo() {
    pendingSettingsRandomization = null;
    const button = document.getElementById("sim-settings-undo");
    if (button) button.disabled = true;
}

function runSettingsRandomization(groups) {
    const before = readSimulationSettings();
    const actions = {
        judges: randomizeJudgingPanelReady,
        premiere: randomizePremiereSettingReady,
        returning: () => randomizeSettingReady("returning"),
        format: () => randomizeSettingReady("format"),
        finale: randomizeFinaleSettingReady,
        episodes: randomizeTargetEpisodesReady
    };
    groups.filter(group => !lockedSimulationSettings.has(group)).forEach(group => actions[group]());
    const after = readSimulationSettings();
    if (JSON.stringify(before) !== JSON.stringify(after)) {
        pendingSettingsRandomization = { before, after };
        document.getElementById("sim-settings-undo").disabled = false;
    }
    updateTargetEpisodeControls();
}

function randomizeJudgingPanel() { runSettingsRandomization(["judges"]); }
function randomizePremiereSetting() { runSettingsRandomization(["premiere"]); }
function randomizeFinaleSetting() { runSettingsRandomization(["finale"]); }
function randomizeTargetEpisodes() { runSettingsRandomization(["episodes"]); }
function randomizeSetting(selectId) {
    if (selectId === "returning" || selectId === "format") {
        runSettingsRandomization([selectId]);
    } else {
        randomizeSettingReady(selectId);
    }
}

function randomizeAllSettings() {
    runSettingsRandomization(["judges", "returning", "format", "premiere", "finale"]);
}

function undoSettingsRandomization() {
    if (!pendingSettingsRandomization) return;
    if (JSON.stringify(readSimulationSettings()) !== JSON.stringify(pendingSettingsRandomization.after)) {
        clearSettingsRandomizationUndo();
        window.showInHouseAlert("Settings have changed since the last roll. Undo is no longer available.");
        return;
    }
    const before = pendingSettingsRandomization.before;
    document.getElementById("premiere-group").value = before["premiere-group"];
    updatePremiereTypes(before["premiere-type"]);
    document.getElementById("finale-size").value = before["finale-size"];
    updateFinaleTypes(before["finale-type"]);
    ["judging-panel", "returning", "format", "target-episodes-mode", "target-episodes"].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = before[id];
    });
    clearSettingsRandomizationUndo();
    updateTargetEpisodeControls();
}

function initializeSettingsQualityOfLife() {
    const panel = document.querySelector(".sim-settings-panel");
    if (!panel) return;
    const groups = ["judges", "premiere", "returning", "format", "finale", "episodes"];
    panel.querySelectorAll(".sim-dice-btn").forEach((dice, index) => {
        const group = groups[index];
        const lock = document.createElement("button");
        lock.type = "button";
        lock.className = "sim-setting-lock";
        lock.innerHTML = '<i class="fa-solid fa-lock-open" aria-hidden="true"></i>';
        lock.setAttribute("aria-pressed", "false");
        lock.setAttribute("aria-label", `Lock ${group} for randomization`);
        lock.title = `Lock ${group} for randomization`;
        lock.addEventListener("click", () => {
            const locked = !lockedSimulationSettings.has(group);
            if (locked) lockedSimulationSettings.add(group);
            else lockedSimulationSettings.delete(group);
            lock.setAttribute("aria-pressed", String(locked));
            lock.querySelector("i").className = `fa-solid fa-lock${locked ? "" : "-open"}`;
            lock.title = `${locked ? "Unlock" : "Lock"} ${group} for randomization`;
            lock.setAttribute("aria-label", lock.title);
            dice.disabled = locked;
            window.DragSetup?.changed();
        });
        dice.before(lock);
    });
    panel.addEventListener("change", event => {
        if (!event.target.matches("select, input")) return;
        clearSettingsRandomizationUndo();
        updateSetupSummary();
    });
    panel.addEventListener("input", event => {
        if (!event.target.matches("input")) return;
        clearSettingsRandomizationUndo();
        updateSetupSummary();
    });
    updateSetupSummary();
}
