function syncCastQuickStatsUi() {
    const big = document.getElementById("castBig");
    const nobody = document.querySelector('.nobody');
    const contentImage = document.querySelector('.content-image');
    if (big) {
        if (currentCast.length > 0) {
            big.classList.toggle("hide", false);
            big.innerHTML = "Current Cast: " + currentCast.length;
        } else {
            big.classList.toggle("hide", true);
            big.innerHTML = "Current Cast: <br>";
        }
    }
    if (nobody) nobody.classList.toggle("hide", currentCast.length > 0);
    if (contentImage) contentImage.classList.toggle("hide", currentCast.length > 0);
    updateTargetEpisodeControls();
}

function getAvailableContestantsForRandomAdd(isCustom) {
    const includeValues = getSelectedFranchiseValues("franchise-filter");
    const excludeValues = getSelectedFranchiseValues("franchise-exclude-filter");

    if (includeValues.length > 0 && !includeValues.includes("ALL") && includeValues.length === 1 && includeValues[0] === 'CUSTOM') {
        isCustom = true;
    }

    let queensPool = [];
    try {
        queensPool = Array.isArray(allQueens) ? allQueens : [];
    } catch (_err) {
        queensPool = Array.isArray(window.allQueens) ? window.allQueens : [];
    }

    let basePool = queensPool.filter(q => q.customqueen === isCustom);

    if (includeValues.length > 0 && !includeValues.includes("ALL")) {
        const franchiseNames = buildFranchisePool(includeValues).map(q => q.uid);
        basePool = basePool.filter(q => franchiseNames.includes(q.uid));
    }

    if (excludeValues.length > 0 && !excludeValues.includes("NONE")) {
        const excludedNames = new Set(buildFranchisePool(excludeValues).map(q => q.uid));
        basePool = basePool.filter(q => !excludedNames.has(q.uid));
    }

    return basePool.filter(q => !currentCast.some(c => c.name === q.name));
}

function addRandomContestant(isCustom) {
    let availableQueens = getAvailableContestantsForRandomAdd(isCustom);

    if (availableQueens.length === 0) {
        alert(isCustom ? "No custom queens left!" : "No queens left!");
        return;
    }

    let randomContestant = availableQueens[randomNumber(0, availableQueens.length - 1)];
    currentCast.push(randomContestant);

    updateCast();

    let big = document.getElementById("castBig");
    big.classList.toggle("hide", false);
    big.innerHTML = "Current Cast: " + currentCast.length;

    let txt = document.querySelector('.nobody');
    if (txt) txt.classList.toggle("hide", true);

    let logo = document.querySelector('.content-image');
    if (logo) logo.classList.toggle("hide", true);
}

function addRandomContestantsBatch(amount = 3, isCustom = false) {
    const count = Math.max(1, Number(amount) || 1);
    const availableQueens = shuffledCopy(getAvailableContestantsForRandomAdd(isCustom));
    if (availableQueens.length === 0) {
        alert(isCustom ? "No custom queens left!" : "No queens left!");
        return;
    }
    const picked = availableQueens.slice(0, Math.min(count, availableQueens.length));
    currentCast.push(...picked);
    updateCast();
    syncCastQuickStatsUi();
    showCustomStatusPopup(`${picked.length} contestant${picked.length === 1 ? "" : "s"} added.`, "Cast");
}

function shuffleCurrentCast() {
    if (!Array.isArray(currentCast) || currentCast.length < 2) {
        showCustomStatusPopup("Need at least 2 contestants to shuffle.", "Cast");
        return;
    }
    for (let i = currentCast.length - 1; i > 0; i--) {
        const j = randomNumber(0, i);
        [currentCast[i], currentCast[j]] = [currentCast[j], currentCast[i]];
    }
    updateCast();
    syncCastQuickStatsUi();
    showCustomStatusPopup("Cast order shuffled.", "Cast");
}

function randomizeChaosFranchiseFilters() {
    const includeSelect = document.getElementById("franchise-filter");
    const excludeSelect = document.getElementById("franchise-exclude-filter");
    if (!includeSelect || !excludeSelect) {
        return { includeCount: 0, excludeCount: 0 };
    }

    const includePool = Array.from(includeSelect.options || [])
        .map((opt) => opt.value)
        .filter((value) => value !== "ALL");
    const shuffledIncludePool = shuffledCopy(includePool);

    const includeCount = includePool.length > 0
        ? randomNumber(1, Math.min(7, includePool.length))
        : 0;
    const pickedInclude = new Set(shuffledIncludePool.slice(0, includeCount));

    Array.from(includeSelect.options || []).forEach((option) => {
        option.selected = option.value !== "ALL" && pickedInclude.has(option.value);
    });
    if (pickedInclude.size === 0) {
        setFranchiseSelectToMaster("franchise-filter", "ALL");
    }

    const excludePool = includePool.filter((value) => !pickedInclude.has(value));
    const shuffledExcludePool = shuffledCopy(excludePool);
    const excludeCount = excludePool.length > 0
        ? randomNumber(0, Math.min(4, excludePool.length))
        : 0;
    const pickedExclude = new Set(shuffledExcludePool.slice(0, excludeCount));

    Array.from(excludeSelect.options || []).forEach((option) => {
        option.selected = option.value !== "NONE" && pickedExclude.has(option.value);
    });
    if (pickedExclude.size === 0) {
        setFranchiseSelectToMaster("franchise-exclude-filter", "NONE");
    }

    sanitizeFranchiseSelections();
    updateFranchiseFilterSummary();
    refreshQueenCards();

    return { includeCount: pickedInclude.size, excludeCount: pickedExclude.size };
}

function moreChaosCast() {
    randomizeAllSettings();
    const { includeCount, excludeCount } = randomizeChaosFranchiseFilters();

    const includeCustoms = Math.random() < 0.8;
    const minSize = randomNumber(16, 24);
    const maxSize = randomNumber(Math.max(minSize, 26), allQueens.length);
    const useFixedSize = Math.random() < 0.7;
    const size = useFixedSize ? randomNumber(minSize, maxSize) : "random";

    generateRandomCast({
        size,
        includeCustoms,
        minSize,
        maxSize
    });

    if (currentCast.length === 0) {
        setFranchiseSelectToMaster("franchise-filter", "ALL");
        setFranchiseSelectToMaster("franchise-exclude-filter", "NONE");
        updateFranchiseFilterSummary();
        refreshQueenCards();
        generateRandomCast({ size: "random", includeCustoms: true, minSize: 16, maxSize: 30 });
    }

    if (currentCast.length > 1 && Math.random() < 0.7) {
        for (let i = currentCast.length - 1; i > 0; i--) {
            const j = randomNumber(0, i);
            [currentCast[i], currentCast[j]] = [currentCast[j], currentCast[i]];
        }
        updateCast();
        syncCastQuickStatsUi();
    }

    showCustomStatusPopup(`Chaos cast generated! (${includeCount} include, ${excludeCount} exclude)`, "More");
}

function moreCoinFlip() {
    const result = Math.random() < 0.5 ? "Heads" : "Tails";
    showCustomStatusPopup(`Coin flip: ${result}!`, "More");
}

