function exportCustomQueens() {
    const exportableQueens = allCustomQueens.map(queen => ({
        ...queen,
        images: Array.isArray(queen.images)
            ? queen.images.map(image => resolveTrackedCustomImage(image))
            : [resolveTrackedCustomImage(queen.getCurrentImage())]
    }));
    const dataStr = JSON.stringify(exportableQueens, null, 2);
    const blob = new Blob([dataStr], { type: "text/plain" });
    const url = URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = "customQueens.txt";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    showCustomStatusPopup("The queens were exported.", "Custom Queens");
}

function importCustomQueens() {
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.accept = ".txt,.json";
    fileInput.click();

    fileInput.onchange = () => {
        const file = fileInput.files[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (e) => {
            let content = e.target.result.trim();
            try {
                const imported = JSON.parse(content);
                if (Array.isArray(imported)) {
                    allQueens = allQueens.filter(q => !q.customqueen);
                    
                    allCustomQueens = [];
                    for (let i = 0; i < imported.length; i++) {
                        const q = imported[i];
                        let queen = new Queen(
                            q._name || q.name || '',
                            q._actingStat || 0,
                            q._comedyStat || 0,
                            q._danceStat || 0,
                            q._designStat || 0,
                            q._improvStat || 0,
                            q._runwayStat || 0,
                            q._lipsyncStat || 0,
                            q.images || '',
                            true
                        );
                        allCustomQueens.push(queen);
                        allQueens.push(queen);
                    }
                    allQueens.sort((a, b) => a.name.toLowerCase().localeCompare(b.name.toLowerCase()));
                    
                    saveCustomQueens();
                    showCustomStatusPopup("The queens were imported.", "Custom Queens");
                    
                    const removeSelect = document.getElementById("custom-remove");
                    if (removeSelect) {
                        removeSelect.innerHTML = "";
                        for (let i = 0; i < allCustomQueens.length; i++) {
                            let option = document.createElement("option");
                            option.innerHTML = allCustomQueens[i].name;
                            option.value = i.toString();
                            removeSelect.appendChild(option);
                        }
                        
                        const previewImg = removeSelect.parentElement.querySelector("img");
                        if (previewImg && allCustomQueens.length > 0) {
                            removeSelect.selectedIndex = 0;
                            previewImg.src = allCustomQueens[0].getCurrentImage();
                            previewImg.style.display = "block";
                        }
                    }
                    
                    if (typeof refreshQueenCards === 'function') {
                        refreshQueenCards();
                    }
                } else {
                    throw new Error("File content is not a valid array.");
                }
            } catch (err) {
                alert("Failed to import: invalid file.");
                console.error(err);
            }
        };
        reader.readAsText(file);
    };
}

