async function saveCustomCast() {
    if (!currentCast || currentCast.length === 0) {
        alert("No contestants in the current cast to save!");
        return;
    }

    const castName = await window.showInHousePrompt("Enter a name for this custom cast:", "", "Save Custom Cast");
    if (castName === null || !String(castName).trim()) return;

    let savedCasts = JSON.parse(localStorage.getItem("customCasts")) || [];

    let queenData = currentCast.map(q => ({
        _name: q._name || q.name,
        uid: q.uid,
        _actingStat: q._actingStat,
        _comedyStat: q._comedyStat,
        _danceStat: q._danceStat,
        _designStat: q._designStat,
        _improvStat: q._improvStat,
        _runwayStat: q._runwayStat,
        _lipsyncStat: q._lipsyncStat,
        images: (Array.isArray(q.images) && q.images.length) ? q.images : (typeof q.getCurrentImage === 'function' ? [q.getCurrentImage()] : ["noimage"]),
        country: q.country || "",
        isDuo: q.isDuo || false,
        name1: q.name1 || "",
        name2: q.name2 || ""
    }));

    const options = {
        premiere: document.getElementById("premiere-format")?.value || "",
        returning: document.getElementById("returning")?.value || "",
        format: document.getElementById("format")?.value || "",
        finale: document.getElementById("finale")?.value || ""
    };

    savedCasts.push({
        name: String(castName).trim(),
        cast: queenData,
        options: options
    });

    localStorage.setItem("customCasts", JSON.stringify(savedCasts));
    cleanupUnusedTrackedCustomImages();
    alert(`Custom cast "${castName}" saved successfully!`);
}

