function CheckForReturning() {
    if (smackdown && smackdownSlayoff) {
        if (!returningQueen && !isSplitPremiereInProgress() &&
            currentCast.length >= 3 && currentCast.length <= Math.ceil(totalCastSize / 2) &&
            getSlayoffReturnCandidates().length > 0) {
            returningQueen = true;
            return true;
        }
        return false;
    }
    if ((randomReturn || chooseReturn || chooseDoubleReturn || voteReturn)
        && currentCast.length < totalCastSize - 3
        && returningQueen == false
        && eliminatedCast.length > 0) {

        if (randomNumber(0, 100) < 5 * episodeCount
            || currentCast.length == 5
            || (doubleQueenReturns && currentCast.length == 5)) {

            returningQueen = true;
            return true;
        }

        return false;
    }
    if (smackdown && smackdownFinaleChallenge && returningQueen == false) {
        const finaleTriggerSize = getFinaleCastSize();
        if (currentCast.length == finaleTriggerSize) {
            returningQueen = true;
            return true;
        }
    }
    if (smackdown && !smackdownFinaleChallenge && currentCast.length == 4 && (top4 || lftc || canFinale || allstars3Finale || teamsF) && returningQueen == false || smackdown && !smackdownFinaleChallenge && currentCast.length == 3 && returningQueen == false && top3 || smackdown && !smackdownFinaleChallenge && currentCast.length == 2 && returningQueen == false && top2F || smackdown && !smackdownFinaleChallenge && currentCast.length == 5 && returningQueen == false && top5) {
        returningQueen = true;
        return true;
    }
    if (hbshd && currentCast.length == 3 && top3 && returningQueen == false) {
        returningQueen = true;
        return true;
    }
    if ((!lmd7ReturnTwst && lmdRunwayReturn && eliminatedCast.length == 4 && currentCast.length >= 6 && returningQueen == false) || (lmd7ReturnTwst && lmdRunwayReturn && eliminatedCast.length == 6 && currentCast.length >= 6 && returningQueen == false)) {
        returningQueen = true;
        return true;
    }
    if (lalaparuza && !returningQueen && (currentCast.length - eliminatedCast.length) >= 0 && (currentCast.length - eliminatedCast.length) < 3 && !all_stars || lalaparuza && !returningQueen && (currentCast.length - eliminatedCast.length) >= 1 && (currentCast.length - eliminatedCast.length) < 3 && all_stars) {
        returningQueen = true;
        return true;
    }
    if ((queensOfComedy || reinasDLC) && currentCast.length == Math.round((totalCastSize / 2)) && returningQueen == false && totalCastSize > 8) {
        returningQueen = true;
        return true;
    }
    if ((kittyGirlGroup || attentionGGroup) && currentCast.length == Math.round((totalCastSize / 2)) && returningQueen == false && totalCastSize > 8) {
        returningQueen = true;
        return true;
    }
    if (conjoinedQueens && currentCast.length == Math.round((totalCastSize / 2)) && returningQueen == false && totalCastSize > 8) {
        returningQueen = true;
        return true;
    }
    return false;
}

