function fijarReturningQueen(yes = false) {
    let screen = new Scene();
    let button = document.getElementById("fijar");
    let selectedQueens = [];
    let image1 = document.getElementById("images1")
    let image2 = document.getElementById("images2")
    let select1 = document.getElementById("queenList1");
    let select2 = document.getElementById("queenList2");
    if (select1 && select2) {
        let name1 = select1.options[select1.selectedIndex].text;
        let name2 = select2.options[select2.selectedIndex].text;
        if (name1 && name2 && name1 !== name2) {
            let q1 = eliminatedCast.find(q => q.name === name1);
            let q2 = eliminatedCast.find(q => q.name === name2);
            if (q1) selectedQueens.push(q1);
            if (q2) selectedQueens.push(q2);
        }
        if (button) button.remove();
        select1.remove();
        select2.remove();
        if (image1) image1.remove();
        if (image2) image2.remove();
    } else {
        let image = document.getElementById("images1")
        let select = document.getElementById("queenList");
        if (select) {
            let opt = select.options[select.selectedIndex];
            if (opt) {
                let queen = eliminatedCast.find(q => q.name === opt.text);
                if (queen) selectedQueens.push(queen);
            }
            if (image) image1.remove();
            if (button) button.remove();
            if (select) select.remove();
        }
    }
    for (let queen of selectedQueens) {
        screen.createImage(queen.getCurrentImage(), "aquamarine");
        screen.createBold(queen.name);
        insOgPla(queen);
        currentCast.push(queen);
        eliminatedCast.splice(eliminatedCast.indexOf(queen), 1);
        
        if (yes) {
            queen.trackRecord.pop();
            appendRetEp(queen, episodeCount);
        } else {
            appendRetEp(queen, episodeCount + 1);
        }
        quitarDoubleElim(queen);
    }
    if (!yes) {
        screen.createButton("Proceed", "newEpisode()");
    }
}
function quitarDoubleElim(queen) {
    if (queen.rankP === "PREMIERE_JOINT") {
        queen.rankP = 0;
        queen.premiereJointRank = 0;
        queen.premiereJointRankEnd = 0;
        queen.premiereGroupIndex = 0;
        return;
    }
    let otherTie;
    if (queen.rankP == "tie1") {
        otherTie = eliminatedCast.find(elimQ => {
            return elimQ.rankP == "tie2"
        });
        otherTie.rankP = 0;
    }
    if (queen.rankP == "tie2") {
        otherTie = eliminatedCast.find(elimQ => {
            return elimQ.rankP == "tie1"
        });
        otherTie.rankP = 0;
    }
    queen.rankP = 0;
}
function getRetEpEntries(queen) {
    if (!queen) {
        return [];
    }
    if (Array.isArray(queen.retEp)) {
        return queen.retEp.filter((value) => Number.isFinite(Number(value)) && Number(value) > 0);
    }
    const legacy = [];
    if (Number(queen.retEp) > 0) {
        legacy.push(Number(queen.retEp));
    }
    if (Number(queen.retEp2) > 0) {
        legacy.push(Number(queen.retEp2));
    }
    return legacy;
}
function appendRetEp(queen, episode) {
    if (!queen) {
        return;
    }
    const entries = getRetEpEntries(queen);
    entries.push(Number(episode));
    queen.retEp = entries;
    queen.retEp2 = entries.length > 1 ? entries[1] : 0;
}

function queensMatchByIdentityOrName(queenA, queenB) {
    if (!queenA || !queenB) {
        return false;
    }
    if (queenA === queenB) {
        return true;
    }
    if (queenA.name && queenB.name) {
        return queenA.name === queenB.name;
    }
    return false;
}

function removeQueenFromList(list, queen) {
    if (!Array.isArray(list) || !queen) {
        return;
    }
    for (let i = list.length - 1; i >= 0; i--) {
        if (queensMatchByIdentityOrName(list[i], queen)) {
            list.splice(i, 1);
        }
    }
}

function addQueenToCurrentCastUnique(queen, toFront = false) {
    if (!queen) {
        return;
    }
    removeQueenFromList(eliminatedCast, queen);
    removeQueenFromList(currentCast, queen);
    if (toFront) {
        currentCast.unshift(queen);
    } else {
        currentCast.push(queen);
    }
}

function addQueenToEliminatedCastUnique(queen, toFront = true) {
    if (!queen) {
        return;
    }
    if (isSplitPremiereInProgress()) {
        if (firstCast.includes(queen)) queen.premiereGroupIndex = 1;
        else if (secondCast.includes(queen)) queen.premiereGroupIndex = 2;
        else if (thirdCast.includes(queen)) queen.premiereGroupIndex = 3;
    }
    // Prevent split-premiere pool restores from bringing back eliminated queens.
    if (Array.isArray(firstCast)) {
        removeQueenFromList(firstCast, queen);
    }
    if (Array.isArray(secondCast)) {
        removeQueenFromList(secondCast, queen);
    }
    if (Array.isArray(thirdCast)) {
        removeQueenFromList(thirdCast, queen);
    }
    removeQueenFromList(currentCast, queen);
    removeQueenFromList(eliminatedCast, queen);
    if (toFront) {
        eliminatedCast.unshift(queen);
    } else {
        eliminatedCast.push(queen);
    }
    if (typeof onClaimedQueenEliminated === "function") {
        onClaimedQueenEliminated(queen);
    }
}

function isRetEpCell(queen, cellEpisode) {
    const entries = getRetEpEntries(queen);
    for (let i = 0; i < entries.length; i++) {
        const retEpisode = Number(entries[i]);
        if (retEpisode === Number(cellEpisode) && retEpisode - queen.trackRecord.length <= 0) {
            return true;
        }
    }
    return false;
}
function getOgPlaceEntries(queen) {
    if (!queen) {
        return [];
    }
    if (Array.isArray(queen.ogPlace)) {
        return queen.ogPlace.filter((value) => value !== 0 && value !== undefined && value !== null && value !== "");
    }
    let legacyEntries = [];
    if (queen.ogPlace !== 0 && queen.ogPlace !== undefined && queen.ogPlace !== null && queen.ogPlace !== "") {
        legacyEntries.push(queen.ogPlace);
    }
    if (queen.ogPlace2 !== undefined && queen.ogPlace2 !== null && queen.ogPlace2 !== "") {
        legacyEntries.push(queen.ogPlace2);
    }
    return legacyEntries;
}
function appendOgPlace(queen, placement) {
    if (!queen) {
        return;
    }
    const entries = getOgPlaceEntries(queen);
    entries.push(placement);
    queen.ogPlace = entries;
    queen.ogPlace2 = entries.length > 1 ? entries[1] : undefined;
}
function formatOrdinalLabel(value) {
    const n = Math.abs(Number(value)) || 0;
    const mod100 = n % 100;
    if (mod100 >= 11 && mod100 <= 13) return n + "th";
    const mod10 = n % 10;
    if (mod10 === 1) return n + "st";
    if (mod10 === 2) return n + "nd";
    if (mod10 === 3) return n + "rd";
    return n + "th";
}
function normalizeOrdinalSuffixesInHtml(html) {
    return String(html || "").replace(/\b(\d+)(st|nd|rd|th)\b/gi, (_match, digits) => {
        return formatOrdinalLabel(digits);
    });
}
function normalizeTrackRecordRankOrdinals() {
    const table = document.getElementById("trackRecord");
    if (!table) return;
    const rows = table.querySelectorAll("tr");
    for (let i = 1; i < rows.length; i++) {
        const rankCell = rows[i].querySelector("th, td");
        if (!rankCell) continue;
        const normalized = normalizeOrdinalSuffixesInHtml(rankCell.innerHTML);
        if (normalized !== rankCell.innerHTML) {
            rankCell.innerHTML = normalized;
        }
    }
}
if (!window.__ssTrackRecordOrdinalObserver) {
    let trackRecordOrdinalRefreshQueued = false;
    const queueTrackRecordOrdinalRefresh = () => {
        if (trackRecordOrdinalRefreshQueued) return;
        trackRecordOrdinalRefreshQueued = true;
        requestAnimationFrame(() => {
            trackRecordOrdinalRefreshQueued = false;
            normalizeTrackRecordRankOrdinals();
        });
    };

    window.__ssTrackRecordOrdinalObserver = new MutationObserver(() => {
        queueTrackRecordOrdinalRefresh();
    });
    const observerRoot = document.getElementById("MainBlock") || document.body;
    if (observerRoot) {
        window.__ssTrackRecordOrdinalObserver.observe(observerRoot, {
            childList: true,
            subtree: true,
            characterData: false,
            attributes: false
        });
    }
    setTimeout(queueTrackRecordOrdinalRefresh, 0);
}
function formatOgPlaceValue(value) {
    if (value === undefined || value === null) {
        return "";
    }
    const text = String(value).trim();
    if (text === "") {
        return "";
    }
    if (/^\d+$/.test(text)) {
        return formatOrdinalLabel(text);
    }
    return text;
}
function appendOrigPlaceLabels(rankCell, queen) {
    const entries = getOgPlaceEntries(queen);
    for (let i = 0; i < entries.length; i++) {
        const formatted = formatOgPlaceValue(entries[i]);
        if (formatted !== "") {
            rankCell.innerHTML += "<br><small>(Orig. " + formatted + ")</small>";
        }
    }
}
function insOgPla(queen) {
    if (s14Premiere && episodeCount == 3) {
        if (eliminatedCast.length > 1) {
            appendOgPlace(queen, formatOrdinalLabel(totalCastSize - bandcatorce) + "/" + totalCastSize);
        } else {
            appendOgPlace(queen, totalCastSize - bandcatorce);
        }
    } else {
        appendOgPlace(queen, currentCast.length + 1 + eliminatedCast.findIndex((contestant) => {
            return queen == contestant
        }));
    }
}
