let pairQOF = [];
let qofcomedy = [];
let flagQoC = false;
function queensofComedy(pord = "") {
    if (pord) {
        pairQOF = [];
        qofcomedy = [];
        episodeCount++;
        for (var i = 0; i < currentCast.length; i++) {
            currentCast[i].episodesOn++;
        }
        top2 = [];
        bottomQueens = [];
        let screen = new Scene();
        screen.clean();
        if (!solidbk) {
            document.body.style.backgroundImage = "url('image/queensofcomedy.webp')";
        }
        qofcomedy = currentCast.slice();
        let allofthem = [...currentCast, ...eliminatedCast];
        if (reinasDLC) {
            episodeChallenges.push("Stand Up");
            screen.createHeader("Reinas de la Comedia!!");
            screen.createParagraph("All of the eliminated contestants get a chance to return to the competition. There will be one contestant returning and 3 will face off in a lipsync for your life, where only 1 will survive!!");
        } else {
            episodeChallenges.push("Stand Up");
            screen.createHeader("Queens of Comedy!!");
            screen.createParagraph("All of the eliminated All Stars get a chance to return to the competition. The contestants must perform a live stand-up comedy act in front of an audience of judgmental drag queens!!");
        }
        screen.createHorizontalLine();
        screen.createBold("The returning queens get to choose their partner... Starting with the last eliminated queen...");
        for (let i = 0; i < eliminatedCast.length; i++) {
            if (eliminatedCast[i].queenDisqOrDept == true) {
                eliminatedCast[i].addToTrackRecord("");
                allofthem.splice(allofthem.indexOf(eliminatedCast[i]), 1);
            } else {
                screen.createImage(eliminatedCast[i].getCurrentImage());
                let queen = bestSister(eliminatedCast[i], qofcomedy);
                if (qofcomedy.find(q => { return q.name == queen.name }) == undefined) {
                    queen = qofcomedy[randomNumber(0, qofcomedy.length - 1)];
                }
                screen.createImage(queen.getCurrentImage());
                screen.createBold(eliminatedCast[i].name + " chose " + queen.name);
                eliminatedCast[i].getComedy();
                queen.getComedy();
                let sumComedy = eliminatedCast[i].performanceScore + queen.performanceScore;
                let team = new Team(eliminatedCast[i], queen);
                team.performanceScore = sumComedy;
                pairQOF.push(team);
                const chosenIndex = qofcomedy.indexOf(queen);
                if (chosenIndex !== -1) {
                    qofcomedy.splice(chosenIndex, 1);
                }
            }
            if (eliminatedCast.length - i == 1 && qofcomedy.length > 1) {
                flagQoC = true;
            }
        }
        if (qofcomedy.length == 2 && flagQoC) {
            screen.createImage(qofcomedy[0].getCurrentImage());
            screen.createImage(qofcomedy[1].getCurrentImage());
            screen.createBold(qofcomedy[0].name + " and " + qofcomedy[1].name + " will work together!");
            qofcomedy[0].getComedy();
            qofcomedy[1].getComedy();
            let sumComedy = qofcomedy[0].performanceScore + qofcomedy[1].performanceScore;
            let team = new Team(qofcomedy[0], qofcomedy[1]);
            team.performanceScore = sumComedy;
            team._name = "no";
            qofcomedy.splice(0, 2);
            pairQOF.push(team);
        }
        if (qofcomedy.length == 1) {
            screen.createImage(qofcomedy[0].getCurrentImage());
            screen.createBold("That means " + qofcomedy[0].name + " will work solo as the emcee of the show.");
            qofcomedy[0].getComedy();
        }
        screen.createHorizontalLine();
        sortPerformances(pairQOF);
        screen.createBigText("Contestants' performances...");
        let slay = allofthem.filter(function (queen) { return queen.performanceScore < 6; });
        let great = allofthem.filter(function (queen) { return queen.performanceScore >= 6 && queen.performanceScore < 16; });
        let good = allofthem.filter(function (queen) { return queen.performanceScore >= 16 && queen.performanceScore < 26; });
        let bad = allofthem.filter(function (queen) { return queen.performanceScore >= 26 && queen.performanceScore < 31; });
        let flop = allofthem.filter(function (queen) { return queen.performanceScore >= 31 && queen.performanceScore < 50; });
        createPerformanceDesc(slay, great, good, bad, flop);
        comedyChallengeCounter++;
        screen.createHorizontalLine();
        screen.createButton("Proceed", "queensofComedyProceed()");
    }
}
function queensofComedyProceed() {
    if (rigEPOutcome) {
        renderQueensOfComedyRigPicker();
        return;
    }
    queensofComedyJudging(pairQOF, qofcomedy);
}
let rigQofcWinnerIndex = null;
function renderQueensOfComedyRigPicker() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Make your decision...");
    screen.createBold("Ladies, I've made some decisions...");
    if (!solidbk) setBackgroundToStage();

    screen.createBold("Pairs - Toggle winner:");
    screen.createParagraph("", "rigQofcContainer");
    const rigQofcContainer = document.getElementById("rigQofcContainer");
    pairQOF.forEach((pair, index) => {
        const selected = rigQofcWinnerIndex === index;
        const pairLabel = pair._name === "no"
            ? `${pair.QueenA.name.split(' ')[0]} & ${pair.QueenB.name.split(' ')[0]} (no return)`
            : `${pair.QueenA.name.split(' ')[0]} & ${pair.QueenB.name.split(' ')[0]}`;
        const trackA = pair.QueenA.trackRecord.join(' - ') || 'No track record yet';
        const trackB = pair.QueenB.trackRecord.join(' - ') || 'No track record yet';
        rigQofcContainer.innerHTML += `<div class="rigItem" style="display:inline-block;text-align:center;margin:6px;">
            <img src="${pair.QueenA.getCurrentImage()}" style="width:96px;height:auto;display:inline-block;margin:0 2px 6px;border-radius:50%;object-fit:cover;" title="${trackA}"/><img src="${pair.QueenB.getCurrentImage()}" style="width:96px;height:auto;display:inline-block;margin:0 2px 6px;border-radius:50%;object-fit:cover;" title="${trackB}"/>
            <button data-pair-index="${index}" class="rigToggleBtn" style="min-width:220px;display:block;margin:0 auto;">${pairLabel} ${selected ? "★" : "☆"}</button>
        </div>`;
    });

    setTimeout(() => {
        rigQofcContainer.querySelectorAll('[data-pair-index]').forEach(btn => {
            btn.onclick = () => toggleQueensOfComedyWinner(parseInt(btn.getAttribute('data-pair-index'), 10));
        });
    }, 0);

    screen.createHorizontalLine();
    screen.createButton("Finish Rigging", "finishQueensOfComedyRigging()");
}
function toggleQueensOfComedyWinner(index) {
    rigQofcWinnerIndex = rigQofcWinnerIndex === index ? null : index;
    renderQueensOfComedyRigPicker();
}
function finishQueensOfComedyRigging() {
    if (rigQofcWinnerIndex !== null && rigQofcWinnerIndex >= 0 && rigQofcWinnerIndex < pairQOF.length) {
        const winner = pairQOF.splice(rigQofcWinnerIndex, 1)[0];
        pairQOF.unshift(winner);
    }
    rigQofcWinnerIndex = null;
    queensofComedyJudging(pairQOF, qofcomedy);
}
