let bracketTextColorPalette = Array(8).fill("#ffffff");
document.addEventListener("input", updateBracketTextColorDisplay);
document.addEventListener("change", updateBracketTextColorDisplay);

function updateBracketTextColorDisplay(event) {
    const match = /^bracketTextColor([1-8])$/.exec(event.target?.id || "");
    if (!match) return;
    const group = Number(match[1]);
    const color = normalizeHexColor(event.target.value);
    if (!color) {
        console.warn("Invalid bracket text color.", event.target.value);
        return;
    }
    bracketTextColorPalette[group - 1] = color;
    document.querySelectorAll("[data-bracket-text-group]").forEach(element => {
        const number = Number(element.dataset.bracketTextGroup);
        if ((number - 1) % 8 !== group - 1) return;
        element.style.color = color;
        const row = element.parentElement;
        if (row?.classList.contains("bracket-name-chip-row") && element === row.lastElementChild &&
            !row.parentElement.dataset.premiereNameGroup) {
            row.parentElement.style.color = color;
        }
    });
}
let bracketReturnAtMergeCount = 1;
let bracketReturnAtFinaleCount = 1;
let bracketWildcardEntrantsPerBracket = 6;
let bracketWildcardSelectableEntrants = false;
