function toggleBracketRigTop2(name) {
    const i = bracketRigTop2.indexOf(name);
    if (i > -1) {
        bracketRigTop2.splice(i, 1);
    } else if (bracketRigTop2.length < 2) {
        bracketRigTop2.push(name);
    }
    bracketJudgingScreen();
}

function confirmBracketTop2Pick() {
    const confirmBtn = document.getElementById("bracketTop2ConfirmBtn");

    const selectedQueens = currentCast.filter((queen) => bracketRigTop2.includes(queen.name));

    if (selectedQueens.length !== 2) {
        alert("Please select exactly 2 queens for the Top 2.");
        return;
    }

    topQueens = [...selectedQueens].sort((a, b) => a.performanceScore - b.performanceScore);
    const topQueenNames = new Set(topQueens.map(q => q.name));

    if (bracketFanonJudging) {
        bracketHighQueen = currentCast.find(q => !topQueenNames.has(q.name)) || null;
        safeQueens = currentCast.filter(q => !topQueenNames.has(q.name) && (!bracketHighQueen || q.name !== bracketHighQueen.name));
        bottomQueens = [];
    } else {
        bottomQueens = currentCast.filter(q => !topQueenNames.has(q.name));
        safeQueens = [];
        bracketHighQueen = null;
    }

    bracketRigTop2 = [];
    if (confirmBtn) confirmBtn.remove();

    bracketJudgingResults();
}

