function bracketTop2LipsyncResult() {
    let screen = new Scene();
    screen.clean();
    let isTie = false;
    if (forcedBracketOutcome && forcedBracketOutcome.type === "tie") {
        isTie = true;
    } else if (forcedBracketOutcome && forcedBracketOutcome.type === "win") {
        const forcedWinnerName = forcedBracketOutcome.queens[0];
        const forcedWinnerIndex = topQueens.findIndex(q => q.name === forcedWinnerName);
        if (forcedWinnerIndex > 0) {
            const forcedWinner = topQueens[forcedWinnerIndex];
            topQueens.splice(forcedWinnerIndex, 1);
            topQueens.unshift(forcedWinner);
        }
    } else {
        topQueens.sort((a, b) => b.lipsyncScore - a.lipsyncScore);
        if (topQueens.length >= 2) {
            isTie = topQueens[0].lipsyncScore === topQueens[1].lipsyncScore;
        }
    }
    forcedBracketOutcome = null;
    if (isTie) {
        toAlots(topQueens, [], alotsSong);
        screen.createHeader("I've made my decision.");
        screen.createImage(topQueens[0].getCurrentImage(), "darkblue");
        screen.createImage(topQueens[1].getCurrentImage(), "darkblue");
        screen.createBold(topQueens[0].name + " and " + topQueens[1].name + ", you're both winners, baby!");
        screen.createBold("This lip sync is a tie, so you will split the point.");
        topQueens.forEach((queen) => {
            queen.addToTrackRecord(" WIN");
            queen.favoritism += 4;
            queen.ppe += 5;
            awardChallengePrize(queen, topQueens, 2500);
            bracketPoints[queen.name] = (bracketPoints[queen.name] || 0) + BRACKET_TIE_SPLIT_PTS;
            recordMvqPointsWon(queen, BRACKET_TIE_SPLIT_PTS);
        });
    } else {
        toAlots([topQueens[0]], [topQueens[1]], alotsSong);

        const bWinner = topQueens[0];
        const bRunner = topQueens[1];

        screen.createHeader("I've made my decision.");
        screen.createImage(bWinner.getCurrentImage(), "royalblue");
        screen.createBold(bWinner.name + ", you're a winner baby!");
        bWinner.addToTrackRecord("WIN");
        bWinner.favoritism += 5;
        bWinner.ppe += 5;
        awardChallengePrize(bWinner);
        bracketPoints[bWinner.name] = (bracketPoints[bWinner.name] || 0) + BRACKET_WIN_PTS;
        recordMvqPointsWon(bWinner, BRACKET_WIN_PTS);

        screen.createImage(bRunner.getCurrentImage(), "deepskyblue");
        screen.createBold(bRunner.name + ", you are safe.");
        bRunner.addToTrackRecord("WIN ");
        bRunner.favoritism += 2;
        bRunner.ppe += 5;
        bracketPoints[bRunner.name] = (bracketPoints[bRunner.name] || 0) + BRACKET_TOP2_PTS;
        recordMvqPointsWon(bRunner, BRACKET_TOP2_PTS);
    }

    if (bracketFanonJudging) {
        if (bracketHighQueen) {
            bracketHighQueen.addToTrackRecord("HIGH");
            bracketHighQueen.ppe += 4;
        }
        if (safeQueens.length > 0) {
            safeQueens.forEach(q => {
                q.addToTrackRecord("SAFE");
                q.ppe += 3;
            });
        }
        screen.createHorizontalLine();
        screen.createButton("Proceed", "bracketBottomPointExchange()");
    } else {
        bottomQueens.forEach(q => {
            q.addToTrackRecord("BTM");
            q.ppe += 3;
        });
        screen.createHorizontalLine();
        screen.createButton("Proceed", "bracketBottomPointExchange()");
    }
}

async function bracketBottomPointExchange() {
    let screen = new Scene();
    screen.clean();
    const highExchangers = bracketFanonJudging && bracketHighQueen ? [bracketHighQueen] : [];
    const fanonExchangers = [...safeQueens, ...highExchangers];
    const isCurrentlyFanon = bracketFanonJudging && fanonExchangers.length > 0;
    const exchangers = isCurrentlyFanon ? fanonExchangers : bottomQueens;
    const exchangeLabel = isCurrentlyFanon ? "non-top queens" : "bottom queens";
    screen.createHeader("The " + exchangeLabel + " exchange points");
    screen.createBold("Each " + (isCurrentlyFanon ? "non-top queen" : "bottom queen") + " gives their MVQ point to another queen.");
    if (!solidbk) {
        setBackgroundToStage();
    }

    const voteGain = {};
    [...exchangers, ...topQueens].forEach(q => {
        voteGain[q.name] = 0;
    });
    for (const giver of exchangers) {
        const options = [...exchangers.filter(q => q !== giver)];
        const includeTopQueens = randomNumber(0, 99) < 35 || options.length === 0;
        if (includeTopQueens) {
            options.push(...topQueens);
        }
        if (options.length === 0) {
            continue;
        }
        const receiver = await chooseClaimedQueenTarget(
            giver,
            options,
            "give your bracket point to",
            () => bestSister(giver, options) || options[randomNumber(0, options.length - 1)]
        );
        if (!receiver) {
            continue;
        }
        voteGain[receiver.name] = (voteGain[receiver.name] || 0) + 1;
        bracketPoints[receiver.name] = (bracketPoints[receiver.name] || 0) + 1;
        recordMvqPointsGifted(receiver, 1);
        screen.createImage(giver.getCurrentImage(), isCurrentlyFanon ? "gray" : "tomato");
        screen.createImage(receiver.getCurrentImage(), "gold");
        screen.createBold(giver.name + " gives 1 point to " + receiver.name + ".");
    }

    screen.createHorizontalLine();
    if (runwayJudgingEnabled) {
        screen.createButton("Proceed", "showEpisodeMvqSheet(\"postBracketFPR\")");
    } else {
        screen.createButton("Proceed", "showEpisodeMvqSheet(\"bracketContestantProgressBridge\")");
    }
}

