function bracketCutoff() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Bracket Round " + bracketRound + " \u2014 Bracket " + (currentBracket + 1) + " Final Results");
    if (!solidbk) {
        setBackgroundToStage();
    }

    const bracketPassCount = getBracketPassCount();
    currentCast = currentCast.filter(q => !q.queenDisqOrDept);
    currentCast.forEach((queen) => {
        queen.bracketTotalPoints = (queen.bracketTotalPoints || 0) + (bracketPoints[queen.name] || 0);
    });

    const bSorted = [...currentCast].sort((a, b) =>
        (bracketPoints[b.name] || 0) - (bracketPoints[a.name] || 0)
    );
    let bAdvancing = bSorted.slice(0, bracketPassCount);
    let bEliminated = bSorted.slice(bracketPassCount);

    // RuPaul mode: let the user pick who advances from the tied queens
    if (rigEPOutcome && bAdvancing.length && bEliminated.length) {
        const cutoffPoints = bracketPoints[bAdvancing[bAdvancing.length - 1].name] || 0;
        const tieCandidates = bEliminated.filter(q => (bracketPoints[q.name] || 0) === cutoffPoints);
        if (tieCandidates.length) {
            const guaranteedAdvancing = bAdvancing.filter(q => (bracketPoints[q.name] || 0) > cutoffPoints);
            const tiePool = [
                ...bAdvancing.filter(q => (bracketPoints[q.name] || 0) === cutoffPoints),
                ...tieCandidates
            ];

            screen.createHorizontalLine();
            screen.createBold(`It's a tie at ${cutoffPoints} point${cutoffPoints === 1 ? "" : "s"}! Choose which of these queens advance:`);

            let main = document.querySelector("div#MainBlock");
            let castSelection = createRigQueenCards(tiePool, null, {
                containerID: "bracketTieSelection",
                buttonText: (queen) => `${queen.name.split(' ')[0]} (${bracketPoints[queen.name] || 0}pts)`,
                toggleable: true,
                minWidth: "180px"
            });
            main.appendChild(castSelection);

            screen.createButton("Confirm", `confirmBracketTiePick(${JSON.stringify(guaranteedAdvancing.map(q => q.name))}, ${JSON.stringify(tiePool.map(q => q.name))}, ${JSON.stringify(bSorted.map(q => q.name))})`, "bracketTieConfirmBtn");
            window._bracketTieScreen = screen;
            return;
        }
    }

    if (bracketLipSyncTieBreaker && bAdvancing.length && bEliminated.length) {
        const cutoffPoints = bracketPoints[bAdvancing[bAdvancing.length - 1].name] || 0;
        const tieCandidates = bEliminated.filter(q => (bracketPoints[q.name] || 0) === cutoffPoints);
        if (tieCandidates.length) {
            const tiePool = [
                ...bAdvancing.filter(q => (bracketPoints[q.name] || 0) === cutoffPoints),
                ...tieCandidates
            ];
            const guaranteedAdvancing = bAdvancing.filter(q => (bracketPoints[q.name] || 0) > cutoffPoints);
            const slotsFromTie = bracketPassCount - guaranteedAdvancing.length;
            let winnersFromTie = [];

            screen.createHorizontalLine();
            screen.createBold("The passers will be decided by a lip sync tie-breaker.");


            const tieSlay = tiePool.filter((q) => q.lipsyncScore > 11);
            const tieGreat = tiePool.filter((q) => q.lipsyncScore >= 8 && q.lipsyncScore < 12);
            const tieGood = tiePool.filter((q) => q.lipsyncScore >= 4 && q.lipsyncScore < 8);
            const tieBad = tiePool.filter((q) => q.lipsyncScore >= 2 && q.lipsyncScore < 4);
            const tieFlop = tiePool.filter((q) => q.lipsyncScore >= -10 && q.lipsyncScore < 2);
            createLipsyncDesc(tieSlay, tieGreat, tieGood, tieBad, tieFlop);

            const rankedTiePool = [...tiePool].sort((a, b) => b.lipsyncScore - a.lipsyncScore);
            while (winnersFromTie.length < slotsFromTie && rankedTiePool.length) {
                const bestScore = rankedTiePool[0].lipsyncScore;
                const sameScore = rankedTiePool.filter((q) => q.lipsyncScore === bestScore);
                const slotsLeft = slotsFromTie - winnersFromTie.length;

                if (sameScore.length <= slotsLeft) {
                    winnersFromTie.push(...sameScore);
                    for (let i = rankedTiePool.length - 1; i >= 0; i--) {
                        if (rankedTiePool[i].lipsyncScore === bestScore) {
                            rankedTiePool.splice(i, 1);
                        }
                    }
                } else {
                    const pool = [...sameScore];
                    while (winnersFromTie.length < slotsFromTie && pool.length) {
                        const pickIndex = randomNumber(0, pool.length - 1);
                        winnersFromTie.push(pool[pickIndex]);
                        pool.splice(pickIndex, 1);
                    }
                    screen.createBold("The tie-breaker was still tied, so the final passer spot was decided at random.");
                    break;
                }
            }

            bAdvancing = [...guaranteedAdvancing, ...winnersFromTie];
            bEliminated = bSorted.filter(q => !bAdvancing.includes(q));
        }
    }

    if (bracketTieSave && !bracketTieSaveUsed && bAdvancing.length && bEliminated.length) {
        const cutoffPoints = bracketPoints[bAdvancing[bAdvancing.length - 1].name] || 0;
        const tieCandidates = bEliminated.filter(q => (bracketPoints[q.name] || 0) === cutoffPoints);
        if (tieCandidates.length) {
            const saved = tieCandidates[randomNumber(0, tieCandidates.length - 1)];
            bAdvancing.push(saved);
            bEliminated = bEliminated.filter(q => q !== saved);
            bracketTieSaveUsed = true;
            screen.createHorizontalLine();
            screen.createImage(saved.getCurrentImage(), "gold");
            screen.createBold(saved.name + " ties at the cutoff and also advances!");
        }
    }

    bracketCutoffFinalize(bAdvancing, bEliminated);
}

function confirmBracketTiePick(guaranteedAdvancingNames, tiePoolNames, bSortedNames) {
    const sel = document.getElementById("bracketTieSelection");
    const confirmBtn = document.getElementById("bracketTieConfirmBtn");

    const selectedNames = tiePoolNames.filter((name, i) => {
        const btn = document.getElementById("bracketTieSelection_btn_" + i);
        return btn && btn.dataset.selected === "true";
    });

    if (selectedNames.length === 0) {
        alert("Please select at least one queen to advance.");
        return;
    }

    if (sel) sel.remove();
    if (confirmBtn) confirmBtn.remove();

    const allQueens = [...currentCast, ...eliminatedCast];
    const findQ = name => allQueens.find(q => q.name === name);

    const bAdvancing = [...guaranteedAdvancingNames, ...selectedNames].map(findQ).filter(Boolean);
    const advancingNames = new Set(bAdvancing.map(q => q.name));
    const bEliminated = bSortedNames.map(findQ).filter(q => q && !advancingNames.has(q.name));

    let screen = new Scene();
    screen.createBold(`You have chosen ${selectedNames.join(" and ")} to advance!`);

    bracketCutoffFinalize(bAdvancing, bEliminated, screen);
    window._bracketTieScreen = null;
}

function bracketCutoffFinalize(bAdvancing, bEliminated, existingScreen) {
    let screen = existingScreen || new Scene();

    screen.createBold("After " + getBracketEpisodesCount() + " episodes, the results are in\u2026");
    screen.createHorizontalLine();
    screen.createBigText("The advancing queens are...");
    bAdvancing.forEach(q => {
        screen.createImage(q.getCurrentImage(), "gold");
        screen.createBold(q.name + " advances with " + (bracketPoints[q.name] || 0) + " points!");
    });

    screen.createHorizontalLine();
    screen.createBigText("The eliminated queens are..");
    bEliminated.forEach(q => {
        screen.createImage(q.getCurrentImage(), "sienna");
        screen.createBold(q.name + " is eliminated with " + (bracketPoints[q.name] || 0) + " points!");
        q.editTrackRecord("ELIM");
        elimQueenWithTwists({
            screen,
            queen: q,
            eliminationRecord: null,
            eliminationUnfavoritism: 0,
            eliminationPpe: 0,
            eliminationText: q.name + " is eliminated with " + (bracketPoints[q.name] || 0) + " points!",
            skipImage: true,
            skipChocolate: true,
            skipDunkTank: true,
            skipLuckyCow: true,
        });
        q.bracketEliminated = true;
        q.bracketElimBracket = currentBracket + 1;
        q.bracketElimPoints = bracketPoints[q.name] || 0;
        q.rankP = "BRACKET_JOINT";
        q.elimEp = episodeCount;
        const elimIdx = eliminatedCast.indexOf(q);
        if (elimIdx !== -1) {
            eliminatedCast.splice(elimIdx, 1);
        }
        eliminatedCast.unshift(q);
        const idx = bracketSavedFullCast.indexOf(q);
        if (idx !== -1) bracketSavedFullCast.splice(idx, 1);
    });
    updateBracketJointPlacementRank(bracketSavedFullCast.length);

    screen.createHorizontalLine();
    currentBracket++;
    if (currentBracket < getBracketCount()) {
        claimContinueAfterElimAction = renderBracketPhaseIntro;
        screen.createButton("Proceed to Bracket " + (currentBracket + 1), "renderBracketPhaseIntro()");
    } else if (hasAnotherBracketRound()) {
        claimContinueAfterElimAction = startNextBracketRound;
        screen.createButton("Proceed to Round " + (bracketRound + 1), "startNextBracketRound()");
    } else {
        claimContinueAfterElimAction = startMainSeasonAfterBrackets;
        screen.createButton("Begin Main Season", "startMainSeasonAfterBrackets()");
    }
}

function hasAnotherBracketRound() {
    if (hasCustomBracketRoundPlan()) {
        return bracketRoundConfigIndex < bracketRoundConfigs.length - 1;
    }
    return false;
}

function startNextBracketRound() {
    if (!hasAnotherBracketRound()) {
        startMainSeasonAfterBrackets();
        return;
    }

    const survivors = [...bracketSavedFullCast];
    if (survivors.length < 2) {
        startMainSeasonAfterBrackets();
        return;
    }

    const nextRoundNumber = bracketRound + 1;
    let roundBracketCount = 1;
    let roundPassers = 1;

    bracketRoundConfigIndex = Math.min(bracketRoundConfigs.length - 1, bracketRoundConfigIndex + 1);
    const activeRound = getActiveBracketRoundConfig();
    applyBracketRoundConfig(activeRound, nextRoundNumber);
    roundBracketCount = Math.floor(Number(activeRound && activeRound.count));
    if (!Number.isFinite(roundBracketCount) || roundBracketCount < 1) {
        roundBracketCount = 1;
    }
    roundBracketCount = Math.min(roundBracketCount, survivors.length);
    bracketCount = roundBracketCount;
    if (activeRound) {
        activeRound.count = roundBracketCount;
    }

    bracketGroups = Array.from({ length: roundBracketCount }, () => []);
    const shuffled = [...survivors].sort(() => Math.random() - 0.5);
    shuffled.forEach((queen, index) => {
        const groupIndex = index % roundBracketCount;
        const globalBracketGroup = getGlobalBracketGroupNumber(groupIndex + 1, bracketRound);
        recordQueenBracketGroup(queen, globalBracketGroup || (groupIndex + 1));
        bracketGroups[groupIndex].push(queen);
    });

    const nonEmptyGroupSizes = bracketGroups.map((group) => group.length).filter((size) => size > 0);
    const smallestGroupSize = nonEmptyGroupSizes.length ? Math.min(...nonEmptyGroupSizes) : 1;
    const passRound = getActiveBracketRoundConfig();
    const configuredPassers = Math.floor(Number(passRound && passRound.passers));
    roundPassers = Number.isFinite(configuredPassers) && configuredPassers > 0 ? configuredPassers : 1;
    roundPassers = Math.max(1, Math.min(roundPassers, smallestGroupSize));
    bracketPassersPerBracket = roundPassers;
    if (passRound) {
        passRound.passers = roundPassers;
    }

    currentBracket = 0;

    let screen = new Scene();
    screen.clean();
    screen.createHeader("Round " + bracketRound + " Brackets");
    screen.createBold("The surviving queens are shuffled into the next bracket round before the merge.");
    screen.createBold("Round " + bracketRound + " brackets: " + roundBracketCount + " | episodes per bracket: " + getBracketEpisodesCount() + " | passers per bracket: " + roundPassers + ".");
    screen.createHorizontalLine();
    screen.createButton("Start Round " + bracketRound, "renderBracketPhaseIntro()", "nwEp");
}

function applyBracketPointsToStarsAtMerge() {
    if (!bracketPointsToStars || bracketPointsStarsApplied) return;
    if (!(all_winners || as9FormatMod)) return;

    const divisor = Math.max(1, Number(bracketPointsPerStar) || 1);
    currentCast.forEach((queen) => {
        const points = Number(queen.bracketTotalPoints || 0);
        if (!Number.isFinite(points) || points <= 0) return;
        const bonus = Math.floor(points / divisor);
        if (bonus > 0) {
            queen.stars = Number(queen.stars || 0) + bonus;
        }
    });

    bracketPointsStarsApplied = true;
}

function startMainSeasonAfterBrackets() {
    if (wildcardBracketPhaseActive) {
        finishWildcardBracketPhase();
        return;
    }

    const bracketPassersAtMerge = [...bracketSavedFullCast];
    const mergeReturnCount = getWildcardReturnCount(false);

    bracketPhaseActive = false;
    bracketUsingCustomPlan = false;
    bracketRoundConfigIndex = 0;
    currentCast = [...bracketPassersAtMerge];
    applyBracketPostFormatSelection();
    applyBracketPointsToStarsAtMerge();
    slmEpisodeOffset = slmFormat ? episodeCount : 0;

    let mergeReturningQueens = [];

    if (bracketReturnAtMerge && !bracketMergeReturnUsed) {
        const candidates = getBracketReturnCandidates();
        if (candidates.length) {
            if (bracketWildcardBracket) {
                const selectionLimit = getWildcardEntrantLimit(mergeReturnCount);
                const autoCandidates = getSortedBracketReturnCandidates().slice(0, selectionLimit);
                if (bracketWildcardSelectableEntrants) {
                    showWildcardSelectionScreen(
                        candidates,
                        selectionLimit,
                        "merge",
                        "The Main Season Begins!",
                        `Choose the queens who will enter the merge wildcard bracket. You may pick up to ${selectionLimit}.`,
                        "Start Merge Wildcard Bracket",
                        (selectedQueens) => startWildcardBracketPhase(selectedQueens, mergeReturnCount, "merge"),
                        {
                            containerID: "wildcardMergeSelection",
                            buttonTextPrefix: "Enter"
                        }
                    );
                    return;
                }

                if (startWildcardBracketPhase(autoCandidates, mergeReturnCount, "merge")) {
                    return;
                }
            } else if (bracketWildcardSelectableEntrants) {
                showWildcardSelectionScreen(
                    candidates,
                    Math.min(mergeReturnCount, candidates.length),
                    "merge",
                    "The Main Season Begins!",
                    `Choose ${Math.min(mergeReturnCount, candidates.length)} queen${Math.min(mergeReturnCount, candidates.length) === 1 ? "" : "s"} to return for the merge.`,
                    "Return Selected Queens",
                    (selectedQueens) => {
                        mergeReturningQueens = Array.isArray(selectedQueens) ? selectedQueens : [];
                        finalizeDirectWildcardReturns(selectedQueens, "merge");
                    },
                    {
                        containerID: "wildcardMergeSelection",
                        buttonTextPrefix: "Pick"
                    }
                );
                return;
            } else {
                const mergeReturnQueens = pickBracketReturnQueens(mergeReturnCount);
                if (mergeReturnQueens.length) {
                    mergeReturningQueens = mergeReturnQueens;
                    finalizeDirectWildcardReturns(mergeReturnQueens, "merge");
                    return;
                }
            }
        }
    }

    updateBracketJointPlacementRank();
    totalCastSize = currentCast.length;
    ensurePostBracketMergeHasNonFinaleEpisode();

    let screen = new Scene();
    screen.clean();
    screen.createHeader("The Main Season Begins!");
    screen.createBold(
        currentCast.length + " queens survived the bracket phase and will now compete for the crown!"
    );
    if (mergeReturningQueens.length) {
        screen.createHorizontalLine();
        if (mergeReturningQueens.length === 1) {
            const mergeReturnQueen = mergeReturningQueens[0];
            screen.createImage(mergeReturnQueen.getCurrentImage(), "gold");
            screen.createBold("The wildcard is..." + mergeReturnQueen.name + "! They will now return for the merge!");
        } else {
            mergeReturningQueens.forEach((queen) => {
                screen.createImage(queen.getCurrentImage(), "gold");
                screen.createBold(queen.name + " returns for the merge!");
            });
        }
    }
    screen.createHorizontalLine();
    currentCast.forEach(q => {
        screen.createImage(q.getCurrentImage(), "gold");
        screen.createBold(q.name);
    });
    screen.createHorizontalLine();
    screen.createButton("Begin!", "newEpisode()");
}

function confirmMergeWildcard() {
    return confirmWildcardSelection();
}

function configureBrackets() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Select your brackets");
    screen.createBold("Place your queens in the brackets you think they belong in. You can change this at any time before the season starts.");

    let main = document.querySelector("div#MainBlock");
    if (!main) return;

    ensureBracketGroupsSize();
    const currentBracketCount = getBracketCount();
    const existingByBracket = bracketGroups.map((group) => group.map(q => q.name));

    let bracketContainer = document.createElement("div");
    bracketContainer.id = "preseasonBracketContainer";
    bracketContainer.style.display = "flex";
    bracketContainer.style.flexDirection = "column";
    bracketContainer.style.gap = "14px";
    bracketContainer.style.maxWidth = "1180px";
    bracketContainer.style.margin = "12px auto";

    for (let bracketIndex = 0; bracketIndex < currentBracketCount; bracketIndex++) {
        const row = document.createElement("div");
        row.style.display = "grid";
        row.style.gridTemplateColumns = "repeat(auto-fit, minmax(130px, 1fr))";
        row.style.gap = "10px";
        row.style.padding = "12px";
        const rowColor = getBracketColor(bracketIndex + 1);
        row.style.border = "2px solid " + rowColor;
        row.style.borderRadius = "12px";
        row.style.background = "rgba(255, 255, 255, 0.08)";

        const rowTitle = document.createElement("p");
        rowTitle.style.gridColumn = "1 / -1";
        rowTitle.style.margin = "0";
        rowTitle.style.fontWeight = "700";
        rowTitle.style.backgroundColor = rowColor;
        rowTitle.style.color = getBracketTextColor(bracketIndex + 1);
        rowTitle.dataset.bracketTextGroup = String(bracketIndex + 1);
        rowTitle.textContent = "Bracket " + (bracketIndex + 1);
        row.appendChild(rowTitle);

        for (let slotIndex = 0; slotIndex < queenPerBracket; slotIndex++) {
            const slot = document.createElement("div");
            slot.style.display = "flex";
            slot.style.flexDirection = "column";
            slot.style.alignItems = "center";
            slot.style.gap = "8px";

            const image = document.createElement("img");
            const imageId = "bracket-image-" + bracketIndex + "-" + slotIndex;
            image.id = imageId;
            image.src = "image/queens/noimage.jpg";
            image.alt = "Bracket slot image";
            image.style.width = "92px";
            image.style.height = "92px";
            image.style.objectFit = "cover";
            image.style.borderRadius = "50%";
            image.style.display = "block";
            image.style.margin = "0 auto";

            const select = document.createElement("select");
            select.dataset.bracketSlot = "true";
            select.dataset.bracketIndex = String(bracketIndex);
            select.dataset.slotIndex = String(slotIndex);
            select.dataset.imageId = imageId;
            select.dataset.previousValue = "";

            const emptyOption = document.createElement("option");
            emptyOption.value = "";
            emptyOption.textContent = "Choose queen";
            select.add(emptyOption);

            currentCast.forEach((queen) => {
                const option = document.createElement("option");
                option.value = queen.name;
                option.textContent = queen.name;
                select.add(option);
            });

            const existingName = existingByBracket[bracketIndex][slotIndex] || "";
            if (existingName && currentCast.some(q => q.name === existingName)) {
                select.value = existingName;
                select.dataset.previousValue = existingName;
            }

            select.addEventListener("change", () => {
                validateBracketUniqueness(select);
            });

            slot.appendChild(image);
            slot.appendChild(select);
            row.appendChild(slot);
            updateBracketSlotImage(select);
        }

        bracketContainer.appendChild(row);
    }

    const actionWrap = document.createElement("div");
    actionWrap.style.display = "flex";
    actionWrap.style.justifyContent = "center";
    actionWrap.style.gap = "12px";
    actionWrap.style.margin = "8px auto 0";

    const randomizeButton = document.createElement("button");
    randomizeButton.type = "button";
    randomizeButton.textContent = "Randomize Brackets";
    randomizeButton.addEventListener("click", randomizeBracketSelection);

    const finalizeButton = document.createElement("button");
    finalizeButton.type = "button";
    finalizeButton.textContent = "Finalize Brackets";
    finalizeButton.addEventListener("click", finalizeBrackets);

    actionWrap.appendChild(randomizeButton);
    actionWrap.appendChild(finalizeButton);

    main.appendChild(bracketContainer);
    main.appendChild(actionWrap);
}

function runPreSeasonChoices(options = {}) {
    preSeasonFlowState.allowSpConf = options.allowSpConf ?? preSeasonFlowState.allowSpConf;
    preSeasonFlowState.skipSpConf = options.skipSpConf ?? preSeasonFlowState.skipSpConf;

    if (brackets_format) {
        configureBrackets();
        return;
    }

    const pending = getPendingPreSeasonChoices();
    if (pending.length > 1) {
        renderPreSeasonChoicesMenu(pending);
        return;
    }
    if (pending.length === 1) {
        const fn = window[pending[0].action];
        if (typeof fn === "function") fn();
        return;
    }

    if (chocolateBarTwist && !chocolateBarTwistChoosable && !hasGoldenBarAssigned()) {
        giveChocolate();
        return;
    }
    if (luckydoll && !luckydollchooseable && !hasLuckyDollAssigned()) {
        giveDoll();
        return;
    }
    if (dunkTank && !dunkTankChoose && !hasDunkTankLevers()) {
        assignRandomDunkTankLevers();
        return;
    }
    if (s9Premiere && !hasLateQueenChosen()) {
        chooseLateQueen();
        return;
    }
    if (bbd4Premiere && !hasLateQueenChosen()) {
        chooseLateQueen();
        return;
    }
    if (lmd5Premiere && !hasLateQueenChosen()) {
        chooseLateQueen();
        return;
    }
    if (lmd4Premiere && !hasLateQueensChosen()) {
        chooseLateQueens();
        return;
    }
    if (triplePremiereFlag) {
        triplePremiereChoose();
        return;
    }
    if (s6Premiere || s12Premiere || s14Premiere || ph2Premiere || newImmTwst || globalPremiere || squirrelPremiere) {
        doublePremiere();
        return;
    }
    newEpisode();
}

function resumePreSeasonChoices() {
    runPreSeasonChoices();
}

