let saveHistoryButtonAccessCache = null;

async function canRenderSaveHistoryButton() {
    const now = Date.now();
    if (saveHistoryButtonAccessCache && saveHistoryButtonAccessCache.expiresAt > now) {
        return saveHistoryButtonAccessCache.allowed;
    }

    const user = typeof window.getCurrentUser === "function" ? window.getCurrentUser() : null;
    const isStaff = typeof window.getIsStaff === "function" && window.getIsStaff();
    const isOwner = !!(user && typeof window.isOwnerEmail === "function" && window.isOwnerEmail(user.email));

    if (isStaff || isOwner) {
        saveHistoryButtonAccessCache = { allowed: true, expiresAt: now + 15000 };
        return true;
    }

    if (typeof window.getUserHistoryAccess !== "function") {
        saveHistoryButtonAccessCache = { allowed: false, expiresAt: now + 3000 };
        return false;
    }

    try {
        const access = await window.getUserHistoryAccess();
        const allowed = !access.blocked;
        saveHistoryButtonAccessCache = { allowed, expiresAt: now + 10000 };
        return allowed;
    } catch (_err) {
        saveHistoryButtonAccessCache = { allowed: false, expiresAt: now + 5000 };
        return false;
    }
}

const SKIP_TO_NEXT_EPISODE_BUTTON_ID = "skipToNextEpisodeBtn";
let skipToNextEpisodeState = null;

function endSkipToNextEpisode(message = "") {
    skipToNextEpisodeState = null;
    if (message && typeof showFloatingNotice === "function") {
        showFloatingNotice(message, 1800);
    }
}

function canShowSkipToNextEpisodeButton(text, method) {
    text = String(text || "").trim();
    method = String(method || "");
    if (text !== "Proceed" && text !== "Begin!" && text !== "Show result" && text !== "Choose Assassin") {
        return false;
    }
    if (method === "") {
        return false;
    }
    if (method.includes("episodeStartPhase()") || method.includes("newEpisode()") || method.includes("preReunion()") || method.includes("contestantProgress()")) {
        return false;
    }
    return episodeCount >= 1;
}

function getSkipToNextEpisodeButton() {
    let buttons = document.querySelectorAll("div#MainBlock button");
    let labels = ["Proceed", "Begin!", "Show result", "Choose Assassin"];
    for (let l = 0; l < labels.length; l++) {
        for (let i = 0; i < buttons.length; i++) {
            let button = buttons[i];
            if (!button || button.disabled || button.id === SKIP_TO_NEXT_EPISODE_BUTTON_ID) {
                continue;
            }
            if (String(button.textContent || "").trim() === labels[l]) {
                return button;
            }
        }
    }
    return null;
}

function continueSkipToNextEpisode() {
    if (!skipToNextEpisodeState) {
        return;
    }

    skipToNextEpisodeState.steps++;
    if (skipToNextEpisodeState.steps > 250) {
        endSkipToNextEpisode("Skip stopped before finishing.");
        return;
    }

    let currentEpisode = Number(episodeCount || 0);
    let nextEpisodeReached = currentEpisode > skipToNextEpisodeState.startEpisode;
    let nextEpisodeButton = document.getElementById("nwEp");

    if (nextEpisodeReached && !skipToNextEpisodeState.enteredNextEpisodeStart) {
        let nextAction = String(nextEpisodeButton && nextEpisodeButton.getAttribute("onclick") || "");
        if (nextEpisodeButton && (nextAction.includes("episodeStartPhase()") || nextAction.includes("renderBracketPhaseIntro()"))) {
            skipToNextEpisodeState.enteredNextEpisodeStart = true;
            nextEpisodeButton.click();
            setTimeout(continueSkipToNextEpisode, 0);
            return;
        }

        endSkipToNextEpisode("Skipped to next episode.");
        return;
    }

    if (skipToNextEpisodeState.enteredNextEpisodeStart) {
        endSkipToNextEpisode("Skipped to next episode.");
        return;
    }

    let button = getSkipToNextEpisodeButton();
    if (!button) {
        endSkipToNextEpisode(nextEpisodeReached ? "Skipped to next episode." : "Couldn't skip this screen.");
        return;
    }

    button.click();
    setTimeout(continueSkipToNextEpisode, 0);
}

function skipToNextEpisode() {
    if (skipToNextEpisodeState) {
        return;
    }

    skipToNextEpisodeState = {
        startEpisode: Number(episodeCount || 0),
        enteredNextEpisodeStart: false,
        steps: 0
    };

    if (typeof showFloatingNotice === "function") {
        showFloatingNotice("Skipping to next episode...", 1200);
    }

    setTimeout(continueSkipToNextEpisode, 0);
}

class Scene {
    constructor(div = undefined) {
        if (div == undefined) {
            this._MainBlock = document.querySelector("div#MainBlock");
        } else {
            this._MainBlock = div;
            let main = document.querySelector("div#MainBlock");
            main.appendChild(this._MainBlock);
        }
    }
    clean() {
        this._MainBlock.innerHTML = '';
        window.DragUi.reveal(this._MainBlock, false);
        this.createRightClick();
        const scrollToTopNow = () => {
            window.scrollTo({ top: 0, behavior: "auto" });
            document.documentElement.scrollTop = 0;
            document.body.scrollTop = 0;
        };
        scrollToTopNow();
        requestAnimationFrame(scrollToTopNow);
        let scrollup = document.querySelector(".toTop");
        if (scrollup) {
            window.addEventListener("scroll", e => {
                if (window.scrollY > 100) {
                    scrollup.classList.add("active");
                } else {
                    scrollup.classList.remove("active");
                }
            }, { passive: true });
        }
    }
    createRightClick() {
        if (document.getElementById("inputRightKey") == undefined) {
            let text = document.createElement("input");
            text.setAttribute("class", "textRightClick");
            text.setAttribute("id", "inputRightKey");
            text.setAttribute("type", "text");
            text.setAttribute("readonly", "readonly");
            this._MainBlock.parentElement.appendChild(text);
        }
    }
    createHeader(text) {
        let title = document.getElementById("MainTitle");
        title.innerHTML = text;
    }
    createBigText(text) {
        let big = document.createElement("big");
        let p = document.createElement("p");
        big.innerHTML = text;
        p.appendChild(big);
        this._MainBlock.appendChild(p);
    }
    createParagraph(text, id = '') {
        let p = document.createElement("p");
        p.innerHTML = text;
        p.setAttribute("id", id);
        this._MainBlock.appendChild(p);
    }
    createBold(text, id = '', id1 = '') {
        let p = document.createElement("p");
        let bold = document.createElement("b");
        bold.innerHTML = text;
        bold.setAttribute("id", id);
        p.setAttribute("id", id1);
        p.appendChild(bold);
        this._MainBlock.appendChild(p);
    }
    createButton(text, method, id = '') {
        let button = document.createElement("button");
        button.innerHTML = text;
        button.setAttribute("onclick", method);
        button.setAttribute("id", id);

        const isSaveHistoryButton =
            text === "Save to History"
            || (typeof method === "string" && method.includes("saveSeasonToHistory"));

        if (isSaveHistoryButton) {
            const target = this._MainBlock;
            canRenderSaveHistoryButton().then((allowed) => {
                if (!allowed || !target || !button || button.isConnected) return;
                target.appendChild(button);
            });
            return;
        }

        this._MainBlock.appendChild(button);

        if (showSkipToNextEpisodeButton && !skipToNextEpisodeState && canShowSkipToNextEpisodeButton(text, method) && !document.getElementById(SKIP_TO_NEXT_EPISODE_BUTTON_ID)) {
            let skipButton = document.createElement("button");
            skipButton.innerHTML = "Skip to Next Episode";
            skipButton.setAttribute("onclick", "skipToNextEpisode()");
            skipButton.setAttribute("id", SKIP_TO_NEXT_EPISODE_BUTTON_ID);
            this._MainBlock.appendChild(skipButton);
        }

        const isTrackRecordDownloadButton =
            id === "downloadTR"
            || (text === "Download" && typeof method === "string" && method.includes("downloadTR()"));

        if (isTrackRecordDownloadButton) {
            const hasCopySettingsButton = this._MainBlock.querySelector("button[data-season-settings-copy='true']");
            if (!hasCopySettingsButton) {
                let copySettingsButton = document.createElement("button");
                copySettingsButton.innerHTML = "Copy Settings";
                copySettingsButton.setAttribute("onclick", "copyCurrentSeasonSettings()");
                copySettingsButton.setAttribute("data-season-settings-copy", "true");
                this._MainBlock.appendChild(copySettingsButton);
            }
        }

        if ((id === "nwEp" || text === "Proceed" || text === "Begin!") && typeof method === "string" && method && !method.includes("reSimulate") && !method.includes("location.reload") && !method.includes("contestantProgress")) {
            lastMidSeasonProceedMethod = method;
            lastMidSeasonProceedText = text || "Proceed";
        }

        if (text == "Proceed" || text == "Show result" || text == "Choose Assassin") {
            let teamhead = document.getElementById("MainTitle");
            if (team && teamhead && teamhead.innerHTML == "Pair time!") {
                // no-op
            } else {
                let textField = document.getElementById("inputRightKey");
                if (textField) {
                    try { textField.focus({ preventScroll: true }); } catch (e) {}
                    textField.addEventListener("keydown", (e) => {
                        let key = e.key;
                        if (key === "ArrowRight" && document.querySelector("button[onclick='" + method + "']") == button) {
                            e.target.remove();
                            button.click();
                            this.goToTop();
                        }
                    }, { once: true });
                    document.addEventListener("click", e => {
                        if (e.target.matches('div#MainBlock') == false && e.target.matches('select') == false) {
                            try { textField.focus({ preventScroll: true }); } catch (e) { }
                        }
                    });
                }
            }
        }
    }
    createHorizontalLine() {
        let hr = document.createElement("hr");
        this._MainBlock.appendChild(hr);
    }
    /*
    createImage(source, color = "black") {
        let image = document.createElement("img");
        image.src = source;
        image.setAttribute("style", `border-color: ${color}; width: 105px; height: 105px;`);
        this._MainBlock.appendChild(image);
    }*/
    createImage(source, color = "black", id = '') {
        const wrapper = document.createElement("div");
        wrapper.style.position = "relative";
        wrapper.style.display = "inline-block";
        wrapper.style.margin = "4px";
        wrapper.style.width = "105px";
        wrapper.style.height = "105px";

        const image = document.createElement("img");
        image.src = source;
        image.style.border = `2px solid ${color}`;
        image.style.width = "100%";
        image.style.height = "100%";
        image.style.objectFit = "cover";
        image.style.borderRadius = "100%";
        image.style.display = "block";

        if (id) image.id = id;

        const styleModeEl = document.getElementById("style-mode");
        const partyStyleSelected = partyMode || (styleModeEl && styleModeEl.value === "party");
        // Shown only while the anniversary theme is active (see anniversary.css).
        const anniversaryHat = !spookyMode && !jollyMode && !partyStyleSelected && !valentinesMode;
        if (spookyMode || jollyMode || partyStyleSelected || anniversaryHat) {
            const isPartyHat = partyStyleSelected && !spookyMode && !jollyMode;
            const hat = document.createElement(isPartyHat ? "span" : "img");
            if (spookyMode) {
                hat.src = "image/witch_hat.webp";
            } else if (jollyMode) {
                hat.src = "image/santa_hat.webp";
            } else if (anniversaryHat) {
                hat.src = "image/party_hat.svg";
                hat.alt = "";
                hat.className = "anniversary-hat";
                hat.style.display = "none";
            } else {
                hat.textContent = "";
                hat.style.fontSize = "44px";
                hat.style.lineHeight = "1";
                hat.style.filter = "drop-shadow(0 3px 2px rgba(0, 0, 0, 0.35))";
            }
            hat.style.position = "absolute";
            hat.style.borderRadius = "0%";
            hat.style.border = "none";
            hat.style.top = anniversaryHat ? "-44px" : "-35px";
            hat.style.left = "50%";
            hat.style.transform = "translateX(-50%) rotate(-6deg)";
            hat.style.width = isPartyHat ? "auto" : anniversaryHat ? "52px" : "70px";
            hat.style.pointerEvents = "auto";
            hat.style.transition = "all 0.3s ease";
            hat.style.animation = "floatingHat 2s ease-in-out infinite";

            if (!document.querySelector('#hatAnimation')) {
                const style = document.createElement('style');
                style.id = 'hatAnimation';
                style.textContent = `
                @keyframes floatingHat {
                    0%, 100% { transform: translateX(-50%) rotate(-6deg) translateY(0); }
                    50% { transform: translateX(-50%) rotate(-6deg) translateY(-5px); }
                }
            `;
                document.head.appendChild(style);
            }

            hat.addEventListener("click", () => {
                hat.style.pointerEvents = "none";
                hat.style.animation = "none";
                hat.style.transform = "translateX(-50%) rotate(60deg) translateY(120px)";
                hat.style.top = "30px";
                hat.style.opacity = "0";

                setTimeout(() => {
                    if (hat && hat.parentNode) hat.remove();
                }, 800);
            });
            wrapper.appendChild(hat);
        } else if (valentinesMode) {
            const frame = document.createElement("img");
            frame.src = "image/HeartFrame.gif";
            frame.style.position = "absolute";
            frame.style.top = "50%";
            frame.style.left = "50%";
            frame.style.transform = "translate(-50%, -50%)";
            frame.style.width = "130px";
            frame.style.height = "130px";
            frame.style.pointerEvents = "none";
            frame.style.zIndex = "10";
            frame.style.border = "none";
            frame.style.outline = "none";
            wrapper.appendChild(frame);
        }

        wrapper.appendChild(image);
        this._MainBlock.appendChild(wrapper);
    }

    createBWImage(source, color = "black", id = '') {
        this.createImage(source, color, id);
        const wrapper = this._MainBlock.lastElementChild;
        const image = wrapper && wrapper.lastElementChild && wrapper.lastElementChild.tagName === "IMG"
            ? wrapper.lastElementChild
            : null;

        if (image) {
            image.style.webkitFilter = "grayscale(100%)";
            image.style.filter = "grayscale(100%)";
        }
    }
    goToTop() {
        window.scrollTo({ top: 0, behavior: "auto" });
    }
}
