let allLsSongs = [];
function loadSongs() {
    const status = document.getElementById("sim-loading-status");
    if (status) status.textContent = "Loading lip-sync music...";
    fetch('textFiles/songs.txt')
        .then((response) => {
            if (!response.ok) throw new Error(`Failed to load music: ${response.status}`);
            return response.text()
        })
        .then((data) => {
            let songs = parseTextFileList(data);
            allLsSongs = songs;
            lsSongs = [...allLsSongs]
            markAllMusicLoaded();
        })
        .catch((error) => {
            console.error("Could not load lip-sync music:", error);
            if (status) status.textContent = "Music could not load. Reload the page to try again.";
        });
}
loadSongs()
