function getTalentStatProfile(talent) {
    for (const [stats, talents] of Object.entries(TALENT_STAT_GROUPS)) {
        if (talents.includes(talent)) {
            return stats.split(",");
        }
    }
    return ["acting", "comedy", "dance", "design", "improv", "runway", "lipsync"];
}

