    const tagsTitle = document.createElement("span");
    tagsTitle.textContent = "Tags";
    const tagsGrid = document.createElement("div");
    tagsGrid.className = "tr-mode-tag-grid";
    const customTagRow = document.createElement("div");
    customTagRow.className = "tr-mode-inline-row tr-mode-inline-row--tag";
    const customTagInput = document.createElement("input");
