function checkLiveAuditionRunwayEvent(queen, runwayTheme, screen) {
    if (randomNumber(0, 1000) >= 900) {
        const event = liveAuditionRunwayEventsBad[randomNumber(0, liveAuditionRunwayEventsBad.length - 1)];

        queen.performanceScore += event.points;

        screen.createImage(queen.getCurrentImage(), "red");
        screen.createBold(`${queen.name} presents a ${runwayTheme} look. ${event.event}`);

        return true;
    } else if (randomNumber(0, 1000) >= 900) {
        const event = liveAuditionRunwayEventsGood[randomNumber(0, liveAuditionRunwayEventsGood.length - 1)];

        queen.performanceScore += event.points;

        screen.createImage(queen.getCurrentImage(), "green");
        screen.createBold(`${queen.name} presents a ${runwayTheme} look. ${event.event}`);

        return true;
    }

    screen.createImage(queen.getCurrentImage(), "silver");
    screen.createBold(`${queen.name} presents a ${runwayTheme} look.`);

    return false;
}
function toBlots(lipsyncers, song, auto = 0) {
    let totalLipsync = 0;
    let lipsyncQueens = "";
    for (let i = 0; i < lipsyncers.length; i++) {
        totalLipsync += lipsyncers[i].lipsyncScore;
        if (team && onFinale) {
            lipsyncQueens += "<b>" + lipsyncers[i].lipsyncQueen.name + "</b>";
        } else {
            lipsyncQueens += "<b>" + lipsyncers[i].name + "</b>";
        }
        if (i != lipsyncers.length - 1) {
            lipsyncQueens += "<br><small> vs </small><br>";
        }
    }
    let songBy = song.slice(song.indexOf(" by "));
    let songName = song.slice(0, song.indexOf(" by "));
    if (totalLipsync / lipsyncers.length >= 8 || totalLipsync / lipsyncers.length <= 1 || auto == 17) {
        blots.push({ queens: lipsyncQueens, lsSong: songName + "<br><small>" + songBy + "</small>", score: totalLipsync / lipsyncers.length, episode: "<b>" + episodeCount + "</b>" });
    }
}
function toAlots(lWin, lLos, song, auto = 0, options = {}) {
    lWin = Array.isArray(lWin) ? lWin.filter(queen => queen && queen.name) : [];
    lLos = Array.isArray(lLos) ? lLos.filter(queen => queen && queen.name) : [];

    if (lWin.length === 0 && lLos.length === 0) {
        console.warn("toAlots called without valid queens.", { song, auto });
        return;
    }

    let queenW = "";
    let queenL = "";
    let winnerNames = [];
    let loserNames = [];
    for (let i = 0; i < lWin.length; i++) {
        let winnerName = team && onFinale && lWin[i].lipsyncQueen ? lWin[i].lipsyncQueen.name : lWin[i].name;
        winnerNames.push(winnerName);
        queenW += "<b>" + winnerName + "</b>";
        if (i != lWin.length - 1 && lWin.length > 1) {
            queenW += "<br><small> & </small><br>";
        }
    }
    for (let i = 0; i < lLos.length; i++) {
        let loserName = team && onFinale && lLos[i].lipsyncQueen ? lLos[i].lipsyncQueen.name : lLos[i].name;
        loserNames.push(loserName);
        queenL += "<b>" + loserName + "</b>";
        if (i != lLos.length - 1 && lLos.length > 1) {
            queenL += "<br><small> & </small><br>";
        }
    }

    let songStr = String(song || "");
    let byIdx = songStr.indexOf(" by ");
    let songName = byIdx !== -1 ? songStr.slice(0, byIdx).trim() : songStr.trim();
    let songBy = byIdx !== -1 ? songStr.slice(byIdx) : "";
    let songArtist = byIdx !== -1 ? songStr.slice(byIdx + 4).trim() : "";

    const epNum = options.audition ? 0 : Number(auto) > 0 ? Number(auto) : Number(episodeCount || 1);

    const matchups = options.audition ? liveAuditionMatchups : alots;
    matchups.push({
        isAudition: Boolean(options.audition),
        winner: queenW,
        loser: queenL,
        winnerNames: winnerNames,
        loserNames: loserNames,
        winnerQueens: [...lWin],
        loserQueens: [...lLos],
        rawSong: songStr,
        songName: songName,
        songArtist: songArtist,
        lsSong: songName + "<br><small>" + songBy + "</small>",
        episode: "<b>" + epNum + "</b>",
        epNum: epNum,
        isFinale: Boolean(onFinale || onTop4Finale),
        isSmackdown: Boolean(smackdown || smackdownFinaleChallenge || lalaparuza)
    });
}

