let rigbtm2QuitLs = false;

async function lipsyncDesc() {
    let screen = new Scene();
    screen.clean();
    if (riggoryLipsync) {
        for (let i = 0; i < bottomQueens.length; i++) {
            bottomQueens[i].getASLipsync();
        }
    } else {
        for (let i = 0; i < bottomQueens.length; i++) {
            bottomQueens[i].getLipsync();
            bottomQueens[i].lipsyncScore = (bottomQueens[i].lipsyncScore - bottomQueens[i].favoritism) + bottomQueens[i].unfavoritism;
        }
    }
    screen.createHeader("The time has come...");
    screen.createBold("For you to lip-sync... for your lives! Good luck, and don't fuck it up.");

    let song = lsSong().toString();
    getLSConfessionals(bottomQueens, screen);
    if (rigbtm2QuitLs || (randomNumber(0, 1000) >= 999 && !disqOrDept && bottomQueens.length == 2 && !squirrelPremiere)) {
        let quitterQueen = bottomQueens[randomNumber(0, bottomQueens.length - 1)];
        screen.createImage(quitterQueen.getCurrentImage(), "red");
        screen.createBold(quitterQueen.name + ", shockingly has left the runway, they decided that they won't lipsync.");
        if (quitterQueen.name == bottomQueens[0].name) {
            toAlots([bottomQueens[1]], [], alotsSong);
            bottomQueens[0].addToTrackRecord("BTM2+QUIT");
            bottomQueens[0].unfavoritism += 5;
            bottomQueens[0].queenDisqOrDept = true;
            bottomQueens[0].minqdd = "<small>(Quit)</small>";
            bottomQueens[1].addToTrackRecord("BTM2");
            bottomQueens[1].unfavoritism += 3;
            bottomQueens[1].ppe += 1;
            for (let i = 0; i < bottomQueens.length; i++) {
                if (bottomQueens[i].maxiT == true) {
                    bottomQueens[i].trackRecord[bottomQueens[i].trackRecord.length - 2] += bottomQueens[i].trackRecord[bottomQueens[i].trackRecord.length - 1];
                    bottomQueens[i].trackRecord.splice([bottomQueens[i].trackRecord.length - 1], 1);
                    bottomQueens[i].maxiT = false;
                }
            }
            bottomQueens.splice(bottomQueens.indexOf(bottomQueens[0]), 1);
        } else {
            toAlots([bottomQueens[0]], [], alotsSong);
            bottomQueens[0].addToTrackRecord("BTM2");
            bottomQueens[0].unfavoritism += 3;
            bottomQueens[0].ppe += 1;
            bottomQueens[1].addToTrackRecord("BTM2+QUIT");
            bottomQueens[1].unfavoritism += 5;
            bottomQueens[1].queenDisqOrDept = true;
            bottomQueens[1].minqdd = "<small>(Quit)</small>";
            for (let i = 0; i < bottomQueens.length; i++) {
                if (bottomQueens[i].maxiT == true) {
                    bottomQueens[i].trackRecord[bottomQueens[i].trackRecord.length - 2] += bottomQueens[i].trackRecord[bottomQueens[i].trackRecord.length - 1];
                    bottomQueens[i].trackRecord.splice([bottomQueens[i].trackRecord.length - 1], 1);
                    bottomQueens[i].maxiT = false;
                }
            }
            bottomQueens.splice(bottomQueens.indexOf(bottomQueens[1]), 1);
        }
        if (randomNumber(0, 10 < 5) || rigbtm2QuitLs) {
            screen.createHorizontalLine();
            screen.createParagraph("The other bottom queen goes on and continues lipsyncing");
            let slay = bottomQueens.filter(function (queen) { return queen.lipsyncScore > 11; });
            let great = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 8 && queen.lipsyncScore < 12; });
            let good = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 4 && queen.lipsyncScore < 8; });
            let bad = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 2 && queen.lipsyncScore < 4; });
            let flop = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= -10 && queen.lipsyncScore < 2; });
            createLipsyncDesc(slay, great, good, bad, flop);
            screen.createHorizontalLine();
        }
        eliminatedCast.unshift(quitterQueen);
        currentCast.splice(currentCast.indexOf(quitterQueen), 1);
        disqOrDept = true;
        if (chocolateBarTwist && !chocolateBarTwistCheck) {
            if (chocolateBarCheck(quitterQueen) == true) {
                chocolateBarTwistCheck = true;
            }
        }
        createPostLSBtn();
    } else {
        let lowQueen = currentCast.find(q => q.trackRecord[q.trackRecord.length - 1] === "LOW") || currentCast.find(q => q.trackRecord[q.trackRecord.length - 1] === "SAVED");

        if (luckydoll && !luckydollused && lowQueen !== undefined && currentCast.length >= 6) {
            let dollHolder = bottomQueens.find(q => q.luckydoll === true);

            if (dollHolder) {
                luckydollused = true;

                let saveCandidates = bottomQueens.slice();
                recordSaveTwist({name: "Lucky Doll"}, dollHolder, saveCandidates);
                if (dollHolder.maxiT == true) {
                    dollHolder.editTrackRecord("SAVED");
                } else {
                    dollHolder.addToTrackRecord("SAVED");
                }
                dollHolder.ppe += 2;

                screen.createImage(dollHolder.getCurrentImage(), "pink");
                screen.createImage("image/Queen.png", "gold");
                screen.createBold(`${dollHolder.name} you hold the lucky doll! This means you are now safe!`);

                lowQueen.trackRecord.pop();
                screen.createImage(lowQueen.getCurrentImage(), "tomato")
                screen.createBold(`${lowQueen.name}... I'm sorry my dear, but that means you are no longer safe, and up for elimination...`);
                bottomQueens.splice(bottomQueens.indexOf(dollHolder), 1, lowQueen);

                screen.createHorizontalLine();
            }
        }

        let event = checkForLipsyncEvent(bottomQueens);
        if (event != false) {
            let eventQueen = bottomQueens.find((q) => {
                return q.name == event.queen.name
            });
            eventQueen.lipsyncScore += event.points;
        }
        let slay = bottomQueens.filter(function (queen) { return queen.lipsyncScore > 11; });
        let great = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 8 && queen.lipsyncScore < 12; });
        let good = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 4 && queen.lipsyncScore < 8; });
        let bad = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= 2 && queen.lipsyncScore < 4; });
        let flop = bottomQueens.filter(function (queen) { return queen.lipsyncScore >= -10 && queen.lipsyncScore < 2; });
        toBlots(bottomQueens, song);
        if (!riggoryLipsync) {
            for (let i = 0; i < bottomQueens.length; i++) {
                bottomQueens[i].lipsyncScore = (bottomQueens[i].lipsyncScore + bottomQueens[i].favoritism) - bottomQueens[i].unfavoritism;
            }
        }
        createLipsyncDesc(slay, great, good, bad, flop);
        screen.createButton("Show result", "lipSync()"); 
    }
    if (rigLSOutcome && bottomQueens.length >= 1) {
        screen.createHorizontalLine();
        screen.createBold("Production Panel...");

        screen.createParagraph("", "rigLSContainer");
        renderRigLSPanel("rigLSContainer");
    }
}

function bindRigLongPressTrackRecord(container) {
    if (!container) return;
    const items = container.querySelectorAll('.rigItem, [data-track-record]');
    items.forEach(item => {
        const queenName = item.getAttribute('data-queen-name') || item.querySelector('.rigQueenNameLabel')?.textContent || item.textContent?.trim() || 'Contestant';
        const trackRecord = item.getAttribute('data-track-record') || item.getAttribute('title');
        if (!trackRecord) return;

        let timer = null;
        let startX = 0;
        let startY = 0;
        let isLongPress = false;

        const startTimer = (e) => {
            isLongPress = false;
            const touch = e.touches ? e.touches[0] : e;
            startX = touch ? touch.clientX : 0;
            startY = touch ? touch.clientY : 0;

            clearTimeout(timer);
            timer = setTimeout(() => {
                isLongPress = true;
                if (typeof navigator !== 'undefined' && navigator.vibrate) {
                    try { navigator.vibrate(40); } catch (_) {}
                }
                const msg = `${queenName}: ${trackRecord}`;
                if (typeof showFloatingNotice === 'function') {
                    showFloatingNotice(msg, 2500);
                } else if (typeof showCustomStatusPopup === 'function') {
                    showCustomStatusPopup(trackRecord, queenName, { duration: 2500 });
                } else {
                    alert(msg);
                }
            }, 350);
        };

        const cancelTimer = (e) => {
            if (e.type === 'touchmove' && e.touches && e.touches[0]) {
                const moveX = Math.abs(e.touches[0].clientX - startX);
                const moveY = Math.abs(e.touches[0].clientY - startY);
                if (moveX > 10 || moveY > 10) {
                    clearTimeout(timer);
                }
            } else {
                clearTimeout(timer);
            }
        };

        item.addEventListener('touchstart', startTimer, { passive: true });
        item.addEventListener('touchmove', cancelTimer, { passive: true });
        item.addEventListener('touchend', cancelTimer, { passive: true });
        item.addEventListener('touchcancel', cancelTimer, { passive: true });

        item.addEventListener('mousedown', startTimer);
        item.addEventListener('mousemove', cancelTimer);
        item.addEventListener('mouseup', cancelTimer);
        item.addEventListener('mouseleave', cancelTimer);

        item.addEventListener('contextmenu', (e) => {
            if (isLongPress) {
                e.preventDefault();
            }
        });
    });
}

function renderRigLSPanel(containerId, queensPool = bottomQueens, options = {}) {
    const container = document.getElementById(containerId);
    const queens = (queensPool && queensPool.length > 0) ? queensPool : bottomQueens;
    if (!container || !queens || queens.length < 1) return;

    const mode = options.mode || "bottom";
    const actionLabel = (mode === "bottom") ? "Stay" : "Win";
    const N = queens.length;
    let html = `<div style="width:100%;margin-top:12px;text-align:center;">`;

    html += `<div style="margin-bottom:12px;">
        <button id="${containerId}_rigSelectAllBtn" class="rigForceBtn" style="min-width:130px;margin:4px;">Select All</button>
        <button id="${containerId}_rigDeselectAllBtn" class="rigForceBtn" style="min-width:130px;margin:4px;">Deselect All</button>
    </div>`;

    queens.forEach((queen) => {
        const qNameEscaped = queen.name.replace(/"/g, '&quot;');
        const trackRecordStr = queen.trackRecord.join(' - ') || 'No track record yet';
        const trackEscaped = trackRecordStr.replace(/"/g, '&quot;');

        html += `<div class="rigItem" data-queen-name="${qNameEscaped}" data-track-record="${trackEscaped}" style="display:inline-block;text-align:center;margin:6px;" title="${trackRecordStr}">
            <img src="${queen.getCurrentImage()}" style="width:96px;height:auto;display:block;margin:0 auto 6px;border-radius:50%;object-fit:cover;"/>
            <label style="cursor:pointer;display:block;margin-top:4px;">
                <input type="checkbox" class="rigLSQueenCheck" data-queen-name="${qNameEscaped}" checked style="cursor:pointer;margin-right:4px;"/>
                <span class="rigQueenNameLabel">${queen.name.split(' ')[0]}</span>
            </label>
        </div>`;
    });

    html += `<div style="margin-top:12px;">
        <button id="${containerId}_rigApplyCustomSelectionBtn" class="rigForceBtn" style="min-width:240px;margin:4px;">
            Confirm Lip Sync Outcome (<span id="${containerId}_rigCheckedCount">${N}</span> / ${N} ${actionLabel})
        </button>
    </div>`;

    html += `</div>`;
    container.innerHTML = html;

    setTimeout(() => {
        bindRigLongPressTrackRecord(container);

        const updateCheckedCount = () => {
            const checked = container.querySelectorAll('.rigLSQueenCheck:checked');
            const countSpan = container.querySelector(`#${containerId}_rigCheckedCount`);
            if (countSpan) countSpan.innerText = checked.length;
        };

        container.querySelectorAll('.rigLSQueenCheck').forEach(chk => {
            chk.onchange = updateCheckedCount;
        });

        const selectAllBtn = container.querySelector(`#${containerId}_rigSelectAllBtn`);
        if (selectAllBtn) {
            selectAllBtn.onclick = () => {
                container.querySelectorAll('.rigLSQueenCheck').forEach(chk => chk.checked = true);
                updateCheckedCount();
            };
        }

        const deselectAllBtn = container.querySelector(`#${containerId}_rigDeselectAllBtn`);
        if (deselectAllBtn) {
            deselectAllBtn.onclick = () => {
                container.querySelectorAll('.rigLSQueenCheck').forEach(chk => chk.checked = false);
                updateCheckedCount();
            };
        }

        const applyBtn = container.querySelector(`#${containerId}_rigApplyCustomSelectionBtn`);
        if (applyBtn) {
            applyBtn.onclick = () => {
                const checkedBoxes = container.querySelectorAll('.rigLSQueenCheck:checked');
                const checkedNames = Array.from(checkedBoxes).map(cb => cb.getAttribute('data-queen-name'));

                if (typeof options.onApply === "function") {
                    let type = "single";
                    if (mode === "bottom") {
                        if (checkedNames.length === 0) {
                            type = "doubleSashay";
                        } else if (checkedNames.length === N) {
                            type = "doubleShantay";
                        }
                    } else if ((mode === "as" || mode === "slayers") && checkedNames.length > 1) {
                        type = "doubleWin";
                    }
                    options.onApply({ type, checkedNames, queens, mode });
                    return;
                }

                if (mode === "bottom") {
                    if (checkedNames.length === 0) {
                        forceNobodyStays();
                    } else if (checkedNames.length === 1) {
                        forceShantay(checkedNames[0]);
                    } else if (checkedNames.length === N) {
                        forceEverybodyStays();
                    } else {
                        forceDoubleShantay(checkedNames);
                    }
                } else if (mode === "as") {
                    if (checkedNames.length === 0) {
                        forceASWin(queens[0] ? queens[0].name : "");
                    } else if (checkedNames.length === 1) {
                        forceASWin(checkedNames[0]);
                    } else {
                        forceASDoubleWin(checkedNames);
                    }
                } else if (mode === "slayers") {
                    if (checkedNames.length === 0) {
                        forceSlayersPremiereWin(queens[0] ? queens[0].name : "");
                    } else if (checkedNames.length === 1) {
                        forceSlayersPremiereWin(checkedNames[0]);
                    } else {
                        forceSlayersPremiereDoubleWin(checkedNames);
                    }
                } else if (mode === "bracket") {
                    if (checkedNames.length === 1) {
                        forceBracketWin(checkedNames[0]);
                    } else {
                        forceBracketTie();
                    }
                }
            };
        }
    }, 0);
}

function getPairs(arr) {
    let pairs = [];
    for (let i = 0; i < arr.length; i++) {
        for (let j = i + 1; j < arr.length; j++) {
            pairs.push([arr[i], arr[j]]);
        }
    }
    return pairs;
}

function getTriples(arr) {
    let triples = [];
    for (let i = 0; i < arr.length; i++) {
        for (let j = i + 1; j < arr.length; j++) {
            for (let k = j + 1; k < arr.length; k++) {
                triples.push([arr[i], arr[j], arr[k]]);
            }
        }
    }
    return triples;
}

function getCombos(arr, size) {
    let results = [];
    function walk(start, combo) {
        if (combo.length === size) {
            results.push(combo.slice());
            return;
        }
        for (let i = start; i < arr.length; i++) {
            combo.push(arr[i]);
            walk(i + 1, combo);
            combo.pop();
        }
    }
    walk(0, []);
    return results;
}

