// FAN RECEPTION //
function getQueenMomentumScore(queen, asOfIndex) {
    const track = Array.isArray(queen.trackRecord) ? queen.trackRecord : [];
    const endIndex = Number.isInteger(asOfIndex) ? Math.min(asOfIndex, track.length) : track.length;
    const recent = track.slice(Math.max(0, endIndex - 3), endIndex);
    let score = 0;
    for (const entry of recent) {
        if (/WIN/.test(entry)) score += 2;
        else if (/HIGH|TOP/.test(entry)) score += 1;
        else if (/LOW|BTM/.test(entry)) score -= 1;
    }
    return score;
}

function getPopularityDeltaForPlacement(placement) {
    const p = String(placement || "").toUpperCase();
    if (/WIN|TOP2|MAXI/.test(p)) return 14;
    if (/HIGH|TOP/.test(p)) return 7;
    if (/SAVED|CHOC|IMM/.test(p)) return 4;
    if (/ELIM|DISQ|DEPT|QUIT|MOLE/.test(p)) return -18;
    if (/BTM/.test(p)) return -14;
    if (/LOW/.test(p)) return -8;
    if (/SAFE|GUEST|^IN$/.test(p)) return -1;
    return 0;
}

const POPULARITY_COLORS = [
    "#c2185b", "#1976d2", "#7b1fa2", "#2e7d32", "#ef6c00",
    "#0097a7", "#d84315", "#3949ab", "#00796b", "#c62828",
    "#5e35b1", "#558b2f", "#ad1457", "#0288d1", "#8e24aa",
    "#388e3c", "#f57c00", "#4527a0", "#00897b", "#b71c1c"
];

function getQueenInitialPopularity(queen) {
    let nameHash = 0;
    const nameStr = String(queen.name || "");
    for (let i = 0; i < nameStr.length; i++) {
        nameHash = ((nameHash << 5) - nameHash + nameStr.charCodeAt(i)) | 0;
    }
    const statSum = (queen._actingStat || 0) + (queen._comedyStat || 0) + (queen._danceStat || 0) +
                    (queen._designStat || 0) + (queen._improvStat || 0) + (queen._runwayStat || 0) + (queen._lipsyncStat || 0);
    const hashMod = Math.abs(nameHash) % 41;
    const statMod = Math.min(15, Math.max(-15, Math.round((statSum - 60) / 2)));
    const favMod = ((queen.favoritism || 0) - (queen.unfavoritism || 0)) * 4;
    let initial = 25 + hashMod + statMod + favMod;
    return Math.max(15, Math.min(85, initial));
}

function getQueenPopularityHistory(queen) {
    const initial = getQueenInitialPopularity(queen);
    const history = [initial];
    let value = initial;
    const track = Array.isArray(queen.trackRecord) ? queen.trackRecord : [];
    for (const placement of track) {
        value = Math.max(0, Math.min(100, value + getPopularityDeltaForPlacement(placement)));
        history.push(value);
    }
    return history;
}

// Renders the full multi-line popularity chart with axes, gridlines, points, and an interactive queen legend.
function createPopularityMultiLineChart(histories) {
    const container = document.createElement("div");
    container.className = "popularity-chart-container";

    const totalEpisodes = histories.reduce((max, h) => Math.max(max, h.history.length - 1), 0);
    const numColumns = Math.max(2, totalEpisodes + 1);

    const svgWidth = 940;
    const svgHeight = 430;
    const leftPad = 48;
    const rightPad = 32;
    const topPad = 25;
    const bottomPad = 45;
    const plotWidth = svgWidth - leftPad - rightPad;
    const plotHeight = svgHeight - topPad - bottomPad;

    const ns = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(ns, "svg");
    svg.setAttribute("viewBox", `0 0 ${svgWidth} ${svgHeight}`);
    svg.setAttribute("class", "popularity-chart-svg");
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", "Popularity trend chart");

    const yPos = (val) => topPad + ((100 - Math.max(0, Math.min(100, val))) / 100) * plotHeight;
    const xStep = numColumns > 1 ? plotWidth / (numColumns - 1) : plotWidth;
    const xPos = (col) => leftPad + col * xStep;

    // Horizontal gridlines & Y-axis labels (100, 75, 50, 25, 0)
    [100, 75, 50, 25, 0].forEach((val) => {
        const y = yPos(val);

        const line = document.createElementNS(ns, "line");
        line.setAttribute("x1", leftPad);
        line.setAttribute("y1", y);
        line.setAttribute("x2", leftPad + plotWidth);
        line.setAttribute("y2", y);
        line.setAttribute("stroke", "#e5dae5");
        line.setAttribute("stroke-width", "1");
        svg.appendChild(line);

        const label = document.createElementNS(ns, "text");
        label.setAttribute("x", leftPad - 10);
        label.setAttribute("y", y + 4);
        label.setAttribute("text-anchor", "end");
        label.setAttribute("fill", "#202122");
        label.setAttribute("font-size", "11");
        label.setAttribute("font-family", "'Rubik', sans-serif");
        label.setAttribute("font-weight", "500");
        label.textContent = String(val);
        svg.appendChild(label);
    });

    // X-axis episode labels (Preseason, Ep 1, Ep 2, ...)
    for (let c = 0; c < numColumns; c++) {
        const x = xPos(c);
        const text = document.createElementNS(ns, "text");
        text.setAttribute("x", x);
        text.setAttribute("y", topPad + plotHeight + 25);
        text.setAttribute("text-anchor", "middle");
        text.setAttribute("fill", "#202122");
        text.setAttribute("font-size", "11");
        text.setAttribute("font-family", "'Rubik', sans-serif");
        text.setAttribute("font-weight", "500");
        text.textContent = c === 0 ? "Preseason" : `Ep ${c}`;
        svg.appendChild(text);
    }

    const legend = document.createElement("div");
    legend.className = "popularity-chart-legend";

    const queenGroups = [];

    histories.forEach(({ queen, history }, idx) => {
        const color = POPULARITY_COLORS[idx % POPULARITY_COLORS.length];
        const g = document.createElementNS(ns, "g");
        g.setAttribute("class", `queen-chart-group group-${idx}`);
        g.style.transition = "opacity 0.2s ease";

        const points = history.map((val, col) => `${xPos(col)},${yPos(val)}`).join(" ");

        const polyline = document.createElementNS(ns, "polyline");
        polyline.setAttribute("points", points);
        polyline.setAttribute("fill", "none");
        polyline.setAttribute("stroke", color);
        polyline.setAttribute("stroke-width", "2.2");
        polyline.setAttribute("stroke-linecap", "round");
        polyline.setAttribute("stroke-linejoin", "round");
        polyline.style.transition = "stroke-width 0.15s ease";
        g.appendChild(polyline);

        history.forEach((val, col) => {
            const circle = document.createElementNS(ns, "circle");
            circle.setAttribute("cx", xPos(col));
            circle.setAttribute("cy", yPos(val));
            circle.setAttribute("r", "3.5");
            circle.setAttribute("fill", "#ffffff");
            circle.setAttribute("stroke", color);
            circle.setAttribute("stroke-width", "2");
            g.appendChild(circle);
        });

        svg.appendChild(g);

        // Legend item below chart
        const legendItem = document.createElement("div");
        legendItem.className = "popularity-legend-item";
        legendItem.setAttribute("data-queen-idx", String(idx));

        const avatar = document.createElement("img");
        avatar.className = "popularity-legend-avatar";
        avatar.src = queen.getCurrentImage ? queen.getCurrentImage() : (queen.image || "");
        avatar.alt = queen.name;
        avatar.style.border = `2px solid ${color}`;

        const nameSpan = document.createElement("span");
        nameSpan.className = "popularity-legend-name";
        nameSpan.textContent = queen.name;

        legendItem.appendChild(avatar);
        legendItem.appendChild(nameSpan);
        legend.appendChild(legendItem);

        queenGroups.push({ group: g, polyline, legendItem, idx });
    });

    // Hover interactions between legend items and line chart
    const highlightQueen = (activeIdx) => {
        queenGroups.forEach(({ group, polyline, legendItem, idx }) => {
            if (activeIdx === null || activeIdx === idx) {
                group.style.opacity = "1";
                polyline.setAttribute("stroke-width", activeIdx === idx ? "3.8" : "2.2");
                legendItem.style.opacity = "1";
            } else {
                group.style.opacity = "0.15";
                polyline.setAttribute("stroke-width", "2.2");
                legendItem.style.opacity = "0.35";
            }
        });
    };

    queenGroups.forEach(({ group, legendItem, idx }) => {
        const onEnter = () => highlightQueen(idx);
        const onLeave = () => highlightQueen(null);

        legendItem.addEventListener("mouseenter", onEnter);
        legendItem.addEventListener("mouseleave", onLeave);
        group.addEventListener("mouseenter", onEnter);
        group.addEventListener("mouseleave", onLeave);
    });

    container.appendChild(svg);
    container.appendChild(legend);
    return container;
}

