function createLipsyncDesc(slay, great, good, bad, flop) {
    const screen = new Scene();
    const word = (currentCast.length == 5 && top5) ? "final performance" : "lipsync";

    const nameOf = q => (team && !teamFlagF && q.lipsyncQueen) ? q.lipsyncQueen.name : q.name;
    const imageOf = q => (team && !teamFlagF && q.lipsyncQueen) ? q.lipsyncQueen.getCurrentImage() : q.getCurrentImage();

    function renderBucket(arr, suffix) {
        if (!arr || arr.length === 0) return;
        arr.forEach(q => screen.createImage(imageOf(q)));
        screen.createBold(`${arr.map(nameOf).join(', ')}${suffix}`);
    }

    renderBucket(slay, ` slayed the ${word}!!`);
    renderBucket(great, ` had a great ${word}!`);
    renderBucket(good, ` had a good ${word}.`);
    renderBucket(bad, ` had a bad ${word}...`);
    renderBucket(flop, ` flopped the ${word}...`);
}

function createExtDesc(slay, great, good, bad, flop) {
    let screen = new Scene();
    let word = "extermination";

    if (slay.length !== 0) {
        slay.forEach(q => screen.createImage(team && !teamFlagF ? q.lipsyncQueen.getCurrentImage() : q.getCurrentImage()));
        screen.createBold("", "slay");
        let slayText = document.getElementById("slay");
        slay.forEach(q => slayText.innerHTML += `${team && !teamFlagF ? q.lipsyncQueen.name : q.name}, `);
        slayText.innerHTML += "absolutely dominated the " + word + "!!";
    }

    if (great.length !== 0) {
        great.forEach(q => screen.createImage(team && !teamFlagF ? q.lipsyncQueen.getCurrentImage() : q.getCurrentImage()));
        screen.createBold("", "great");
        let greatText = document.getElementById("great");
        great.forEach(q => greatText.innerHTML += `${team && !teamFlagF ? q.lipsyncQueen.name : q.name}, `);
        greatText.innerHTML += "performed amazingly in the " + word + "!";
    }

    if (good.length !== 0) {
        good.forEach(q => screen.createImage(team && !teamFlagF ? q.lipsyncQueen.getCurrentImage() : q.getCurrentImage()));
        screen.createBold("", "good");
        let goodText = document.getElementById("good");
        good.forEach(q => goodText.innerHTML += `${team && !teamFlagF ? q.lipsyncQueen.name : q.name}, `);
        goodText.innerHTML += "handled the " + word + " decently.";
    }

    if (bad.length !== 0) {
        bad.forEach(q => screen.createImage(team && !teamFlagF ? q.lipsyncQueen.getCurrentImage() : q.getCurrentImage()));
        screen.createBold("", "bad");
        let badText = document.getElementById("bad");
        bad.forEach(q => badText.innerHTML += `${team && !teamFlagF ? q.lipsyncQueen.name : q.name}, `);
        badText.innerHTML += "struggled during the " + word + "...";
    }

    if (flop.length !== 0) {
        flop.forEach(q => screen.createImage(team && !teamFlagF ? q.lipsyncQueen.getCurrentImage() : q.getCurrentImage()));
        screen.createBold("", "flop");
        let flopText = document.getElementById("flop");
        flop.forEach(q => flopText.innerHTML += `${team && !teamFlagF ? q.lipsyncQueen.name : q.name}, `);
        flopText.innerHTML += "completely bombed the " + word + "...";
    }
}
let teamFlagF = false;

function checkDGULAElims() {
    if ((dragula_format || extElim) && bottomQueens.length > 0) {
        let eliminatedQueens = [];

        bottomQueens.sort((a, b) => a.runwayScore - b.runwayScore);
        let btmCount = bottomQueens.length;

        bottomQueens.forEach(q => {
            if (q.trackRecord[q.trackRecord.length - 1] == "TBA") {
                q.trackRecord.pop();
            }
        });

        if (btmCount === 2) {
            eliminatedQueens = [bottomQueens[1]];
        }
        else if (btmCount === 3) {
            eliminatedQueens = [bottomQueens[2]];
        }
        else if (btmCount === 4) {
            eliminatedQueens = [bottomQueens[3]];
        }

        const stayingQueens = bottomQueens.filter(q => !eliminatedQueens.includes(q));
        if (btmCount > 1) {
            stayingQueens.forEach(q => {
                q.addToTrackRecord("BTM" + btmCount);
                q.ppe += 1;
            });
        }
        eliminatedQueens.forEach(q => {
            q.addToTrackRecord("EXT");
            eliminatedCast.unshift(q);
            currentCast.splice(currentCast.indexOf(q), 1);
            q.ppe += 0;
        });
        dragulaElm = eliminatedQueens;
        dragulaStay = stayingQueens;
    }
    bottomQueens = [];
}
function preReunion() {

    if (typeof applyCheckboxTwists === "function") {
        if (applyCheckboxTwists() === false) return;
    }

    checkDGULAElims();

    if (rumixFiller && !rumixFillerUsed) {
        rumixFillerEp();
        return;
    }

    if (mvEp && !mvEpUsed) {
        musicVideoFillerEp();
        return;
    }

    if (recapEp && !recapEpUsed) {
        recapEpisode();
        return;
    }

    if (reuls && !reulsUsed) {
        shdareu();
        return;
    }

    if (reunionEnabled && !reunionAfterFinale) {
        reunion();
        return;
    }

    if (maybeTriggerBracketFinaleReturn()) {
        return;
    }

    if (finaleMaxi && !finaleMaxiUsed) {
        finaleMaxiEp();
        return;
    }
    if (top3LSF && currentCast.length > 3) {
        episodeStartPhase();
    } else if (dres4finale) {
        if (currentCast.length == 4) {
            dres4FakeFinale();
        } else {
            finale();
        }    
    } else if (currentCast.length == 4 && (lmd3Semis || lmd4Semis || lmd5Semis || lmd6Semis)) {
        lmdFinaleTop4();

    } else if (currentCast.length == 4 && canFinale) {
        canadaS2Finale();
    } else if (currentCast.length == 5 && (top5 || top5ls)) {
        if (top5ls) {
            top5LS();
        } else {
            finaleT5();
        }
    } else if (currentCast.length == 6 && (top6reg || top6ls || top6as11 || top6lsSudden)) {
        if (top6ls || top6lsSudden) {
            top6LS();
        } else if (top6as11) {
            top6AS11();
        } else {
            top6();
        }
    } else if (currentCast.length == 7 && (top7reg || top7ls)) {
        if (top7ls) {
            top7LS();
        } else {
            top7();
        }
    } else if (currentCast.length == 4 && teamsF) {
        const hasTeamPairShape = !!(currentCast[0]?.QueenA && currentCast[0]?.QueenB && currentCast[1]?.QueenA && currentCast[1]?.QueenB);
        if (hasTeamPairShape) {
            finaleTeam();
        } else {
            finaleTeam();
        }
    } else if (currentCast.length == 4 && lftc) {
        finaleLS();
    } else if (currentCast.length == 8 && (top8reg || top8ls)) {
        if (top8reg) {
            top8();
        } else {
            top8LS();
        }
    } else if (currentCast.length == 4 && maxiLFTC) {
        finaleRumix();
    } else if (currentCast.length == 4 && top4) {
        finaleTop4();
    } else if (currentCast.length == 3 && top3LSF) {
        top3LS();     
    } else if (currentCast.length == 4 && allstars3Finale) {
        finaleAS();
    } else {
        finale();
    }
}

// ---- Finale Maxi: an extra maxi challenge right before the finale (after the reunion), one winner and everyone else safe ----
function finaleMaxiEp() {
    const select = document.getElementById("finaleMaxiChallenge");
    const option = FIRST_EPISODE_CHALLENGE_OPTIONS.find(entry => entry.value === (select ? select.value : "rumix")) || FIRST_EPISODE_CHALLENGE_OPTIONS.find(entry => entry.value === "rumix");
    finaleMaxiActive = true;
    finaleMaxiEpIndex = episodeChallenges.length;
    isTeamChallenge = false;
    topQueens = [];
    bottomQueens = [];
    for (let i = 0; i < currentCast.length; i++) {
        currentCast[i].performanceScore = 0;
        currentCast[i].runwayScore = 0;
    }
    eval(option.command);
}

function finaleMaxiResults() {
    finaleMaxiActive = false;
    if (episodeChallenges.length === finaleMaxiEpIndex) episodeChallenges.push("Maxi");
    for (let i = 0; i < eliminatedCast.length; i++) {
        eliminatedCast[i].addToTrackRecord("");
    }

    let screen = new Scene();
    screen.clean();
    screen.createHeader("Bring back my girls!");
    screen.createBold("Ladies, I've made some decisions...");
    if (!solidbk) {
        setBackgroundToStage();
    }
    topQueens = [...currentCast];
    for (let i = 0; i < topQueens.length; i++) {
        if (riggory) topQueens[i].performanceScore -= topQueens[i].runwayScore;
        else topQueens[i].performanceScore -= (topQueens[i].runwayScore - topQueens[i].favoritism);
    }
    topQueens.sort((a, b) => (a.performanceScore - b.performanceScore));
    if (topQueens.length > 1 && topQueens[0].performanceScore == topQueens[1].performanceScore && randomNumber(0, 100) < 60) {
        const winners = topQueens.slice(0, 2);
        winners.forEach(queen => {
            queen.addToTrackRecord(" WIN");
            queen.favoritism += 5;
            queen.ppe += 5;
            awardChallengePrize(queen, winners);
            screen.createImage(queen.getCurrentImage(), "darkblue");
        });
        screen.createBold(winners[0].name + ", " + winners[1].name + ", condragulations, you're the winners of today's challenge!");
        topQueens.splice(0, 2);
    } else {
        topQueens[0].addToTrackRecord("WIN");
        awardChallengePrize(topQueens[0]);
        screen.createImage(topQueens[0].getCurrentImage(), "royalblue");
        screen.createBold(topQueens[0].name + ", condragulations, you're the winner of today's challenge!");
        topQueens.splice(0, 1);
    }

    for (let i = 0; i < topQueens.length; i++) {
        screen.createImage(topQueens[i].getCurrentImage(), "black");
        topQueens[i].addToTrackRecord("SAFE");
    }
    if (topQueens.length) {
        screen.createParagraph(topQueens.map(queen => queen.name).join(", ") + ", good job this week, you're safe.");
    }

    topQueens = [];
    bottomQueens = [];
    screen.createButton("Proceed", "continueFinaleMaxi()");
}

function continueFinaleMaxi() {
    finaleMaxiUsed = true;
    preReunion();
}

function continuePreReunion() {

    if (typeof applyCheckboxTwists === "function") {
        if (applyCheckboxTwists() === false) return;
    }

    if (rumixFiller && !rumixFillerUsed) {
        rumixFillerUsed = true;
    }

    else if (mvEp && !mvEpUsed) {
        mvEpUsed = true;
    }

    else if (recapEp && !recapEpUsed) {
        recapEpUsed = true;
    }

    preReunion();
}

// Shared by the Rumix / Music Video special episodes (they behave like a normal challenge screen).
function replaceFillerProceedWithRunwayButton(buttonsBefore, runwayCall) {
    const main = document.querySelector("div#MainBlock");
    if (!main) return;
    Array.from(main.querySelectorAll("button")).forEach((button) => {
        if (!buttonsBefore.has(button)) button.remove();
    });
    new Scene().createButton("Proceed", runwayCall, "button2");
}

function showFillerRunway(nextCall) {
    const main = document.querySelector("div#MainBlock");
    const buttonsBefore = new Set(main ? main.querySelectorAll("button") : []);
    runway();
    // runway() adds its own Proceed for the regular judging screens; the special episode goes to its lip sync instead
    if (main) {
        Array.from(main.querySelectorAll("button")).forEach((button) => {
            if (!buttonsBefore.has(button)) button.remove();
        });
    }
    new Scene().createButton("Proceed", nextCall);
}

// Results screen after the special episode's lip sync: everyone moves on, or (Cut contestant) the worst one is eliminated.
function fillerLipsyncResults(cutContestant, everyoneMovesOnText) {
    let screen = new Scene();
    screen.clean();

    screen.createHeader("After the lipsync...");

    const worst = cutContestant && Array.isArray(bottomQueens) && bottomQueens.length
        ? bottomQueens[bottomQueens.length - 1]
        : null;

    if (worst && currentCast.includes(worst)) {
        screen.createBold("Ladies, I've made my decision... One of you will not be moving on to the next episode.");
        screen.createImage(worst.getCurrentImage(), "red");
        screen.createBold(`${worst.name}, you were the worst performing contestant. You will not be moving on to the next episode... Sashay away.`);

        worst.trackRecord.pop();
        worst.addToTrackRecord("ELIMF");
        worst.unfavoritism += 5;
        currentCast.splice(currentCast.indexOf(worst), 1);
        addQueenToEliminatedCastUnique(worst);
    } else {
        screen.createBold(everyoneMovesOnText);
        currentCast.forEach(q => {
            screen.createImage(q.getCurrentImage(), "silver");
        });
    }

    screen.createHorizontalLine();
    screen.createButton("Proceed", "continuePreReunion()");
}

