function rumixFillerLipSync() {

    let screen = new Scene();
    screen.clean();

    screen.createHeader("Bring back my girls!");
    screen.createBold("Ladies... I still haven't made my decision, I need to see ALL of you lip sync one more time!");

    bottomQueens = [...currentCast];

    for (let i = 0; i < bottomQueens.length; i++) {
        bottomQueens[i].getLipsync();
        bottomQueens[i].lipsyncScore =
            (bottomQueens[i].lipsyncScore - bottomQueens[i].favoritism)
            + bottomQueens[i].unfavoritism;
    }

    bottomQueens.sort((a, b) => b.lipsyncScore - a.lipsyncScore);

    let song = lsSong().toString();

    let slay = [];
    let great = [];
    let good = [];
    let bad = [];
    let flop = [];

    for (let i = 0; i < bottomQueens.length; i++) {

        if (i == 0 || i == 1) {
            slay.push(bottomQueens[i]);
        } else if (i < Math.ceil(bottomQueens.length / 2)) {
            great.push(bottomQueens[i]);
        } else if (i == Math.floor(bottomQueens.length / 2)) {
            good.push(bottomQueens[i]);
        } else if (i >= bottomQueens.length - 2) {
            flop.push(bottomQueens[i]);
        } else {
            bad.push(bottomQueens[i]);
        }
    }

    createLipsyncDesc(slay, great, good, bad, flop);

    screen.createButton("Proceed", "rumixFillerResults()");
}

