function checkForReuEvents() {

}

function getSlmReunionRematches() {
    if (!slmFormat || !slmReunionRematches || !Array.isArray(alots) || alots.length === 0) {
        return [];
    }

    const seasonQueens = [...currentCast, ...eliminatedCast];
    return alots.reduce((rematches, record) => {
        const winnerNames = Array.isArray(record?.winnerNames) ? record.winnerNames.filter(Boolean) : [];
        const loserNames = Array.isArray(record?.loserNames) ? record.loserNames.filter(Boolean) : [];

        if (winnerNames.length !== 1 || loserNames.length !== 1) {
            return rematches;
        }

        const firstQueen = seasonQueens.find(q => q && q.name === winnerNames[0]);
        const secondQueen = seasonQueens.find(q => q && q.name === loserNames[0]);

        if (!firstQueen || !secondQueen || firstQueen === secondQueen) {
            return rematches;
        }

        rematches.push({
            firstQueen,
            secondQueen,
            episode: String(record.episode || "").replace(/<[^>]+>/g, "").trim(),
        });
        return rematches;
    }, []);
}

function getSlmReunionRematchPlacement(wins, total) {
    return (wins > 0 ? "WIN REMATCH " : "LOSS REMATCH ") + wins + "/" + total;
}

function resolveSlmReunionRematch(screen, firstQueen, secondQueen, rematchNumber, totalRematches, originalEpisode) {
    const rematchQueens = [firstQueen, secondQueen];
    for (let i = 0; i < rematchQueens.length; i++) {
        rematchQueens[i].getASLipsync();
    }

    screen.createHorizontalLine();
    screen.createBold("Rematch " + rematchNumber + " of " + totalRematches + "!");
    if (originalEpisode) {
        screen.createParagraph("Originally lip synced in episode " + originalEpisode + ".");
    }
    screen.createImage(firstQueen.getCurrentImage());
    screen.createImage(secondQueen.getCurrentImage());
    screen.createBold(firstQueen.name + " and " + secondQueen.name + " will lip sync again...");
    screen.createBold("The time has come for you to lip-sync... one more time! Good luck, and don't fuck it up.");

    const score1 = firstQueen.lipsyncScore;
    const score2 = secondQueen.lipsyncScore;

    if (score1 > 7 && score2 > 7 && !noDouble) {
        screen.createImage(firstQueen.getCurrentImage(), "magenta");
        screen.createImage(secondQueen.getCurrentImage(), "magenta");
        screen.createBold(firstQueen.name + " and " + secondQueen.name + ", condragulations. You both won this rematch.");
        return { winners: [firstQueen, secondQueen], losers: [] };
    }

    if (score1 < 2 && score2 < 2 && !noDouble) {
        screen.createImage(firstQueen.getCurrentImage(), "darkred");
        screen.createImage(secondQueen.getCurrentImage(), "darkred");
        screen.createBold(firstQueen.name + " and " + secondQueen.name + ", neither one of you won this rematch.");
        return { winners: [], losers: [firstQueen, secondQueen] };
    }

    const tieBreaker = Math.random() - 0.5;
    rematchQueens.sort((a, b) => {
        if (b.lipsyncScore === a.lipsyncScore) {
            return tieBreaker;
        }
        return b.lipsyncScore - a.lipsyncScore;
    });

    const winner = rematchQueens[0];
    const loser = rematchQueens[1];

    screen.createImage(winner.getCurrentImage(), "royalblue");
    screen.createBold(winner.name + ", condragulations. You won this rematch.");
    screen.createImage(loser.getCurrentImage(), "darkred");
    screen.createBold(loser.name + ", you have lost this rematch...");

    return { winners: [winner], losers: [loser] };
}

function runSlmReunionLipSyncRematches(screen, rematches) {
    const reunionCast = [...currentCast, ...eliminatedCast];
    const rematchStats = new Map(reunionCast.map(queen => [queen, { wins: 0, total: 0 }]));

    screen.createBigText("Lip Sync Rematches!");
    screen.createBold("Tonight, the queens will redo every one-on-one lip sync they had during the season.");

    for (let i = 0; i < rematches.length; i++) {
        const rematch = rematches[i];
        const result = resolveSlmReunionRematch(
            screen,
            rematch.firstQueen,
            rematch.secondQueen,
            i + 1,
            rematches.length,
            rematch.episode
        );

        for (let j = 0; j < result.winners.length; j++) {
            const winnerStats = rematchStats.get(result.winners[j]);
            if (winnerStats) {
                winnerStats.wins += 1;
                winnerStats.total += 1;
            }
        }
        for (let j = 0; j < result.losers.length; j++) {
            const loserStats = rematchStats.get(result.losers[j]);
            if (loserStats) {
                loserStats.total += 1;
            }
        }
    }

    for (let i = 0; i < currentCast.length; i++) {
        const stats = rematchStats.get(currentCast[i]);
        if (stats && stats.total > 0) {
            currentCast[i].addToTrackRecord(getSlmReunionRematchPlacement(stats.wins, stats.total));
        } else {
            currentCast[i].addToTrackRecord("RUN ");
        }
    }

    for (let i = 0; i < eliminatedCast.length; i++) {
        const stats = rematchStats.get(eliminatedCast[i]);
        if (stats && stats.total > 0) {
            eliminatedCast[i].addToTrackRecord(getSlmReunionRematchPlacement(stats.wins, stats.total));
        } else {
            eliminatedCast[i].addToTrackRecord("GUEST");
        }
    }
}

function getReulsLossLabel(roundNumber) {
    const labels = ["1ST", "2ND", "3RD", "4TH"];
    const label = labels[Math.max(0, Math.min(labels.length - 1, roundNumber - 1))];
    return "LOST " + label + " ROUND ";
}

function resolveReulsDuel(screen, q1, q2, roundNumber, finalRound = false) {
    const currLip = [q1, q2];
    for (let i = 0; i < currLip.length; i++) {
        currLip[i].getASLipsync();
    }

    screen.createImage(q1.getCurrentImage());
    screen.createImage(q2.getCurrentImage());
    screen.createBold(q1.name + " and " + q2.name + " will lipsync...");
    screen.createBold("The time has come for you to lip-sync... for your life! Good luck, and don't fuck it up.");

    let song = lsSong().toString();
    screen.createHorizontalLine();
    let event = checkForLipsyncEvent(currLip);
    if (event != false) {
        let eventQueen = currLip.find((q) => {
            return q.name == event.queen.name;
        });
        eventQueen.lipsyncScore += event.points;
    }

    currLip.sort(function (a, b) { return (b.lipsyncScore - a.lipsyncScore); });
    toBlots(currLip, song);
    toAlots([currLip[0]], [currLip[1]], alotsSong);

    screen.createBold("I've made my decision.");
    if (finalRound) {
        screen.createBold("", "typeF");
        let txt = "The Queen of She Done Already Done Had Herses is...";
        typeWriter(txt, 0);
    }

    screen.createImage(currLip[0].getCurrentImage(), "royalblue");
    screen.createBold(currLip[0].name + ", condragulations. You are a winner, baby!");
    screen.createImage(currLip[1].getCurrentImage(), "darkred");
    screen.createBold(currLip[1].name + ", thank you for an unforgettable season.");
    currLip[1].addToTrackRecord(getReulsLossLabel(roundNumber));

    return currLip[0];
}

function resolveReulsThreeWay(screen, q1, q2, q3, roundNumber, finalRound = false) {
    const currLip = [q1, q2, q3].filter(Boolean);
    for (let i = 0; i < currLip.length; i++) {
        currLip[i].getASLipsync();
    }

    screen.createImage(q1.getCurrentImage());
    screen.createImage(q2.getCurrentImage());
    screen.createImage(q3.getCurrentImage());
    screen.createBold(q1.name + ", " + q2.name + " and " + q3.name + " will lipsync...");
    screen.createBold("The time has come for you to lip-sync... for your life! Good luck, and don't fuck it up.");

    let song = lsSong().toString();
    screen.createHorizontalLine();
    let event = checkForLipsyncEvent(currLip);
    if (event != false) {
        let eventQueen = currLip.find((q) => {
            return q.name == event.queen.name;
        });
        eventQueen.lipsyncScore += event.points;
    }

    currLip.sort(function (a, b) { return (b.lipsyncScore - a.lipsyncScore); });
    toBlots(currLip, song);
    toAlots([currLip[0]], [currLip[1], currLip[2]], alotsSong);

    screen.createBold("I've made my decision.");
    if (finalRound) {
        screen.createBold("", "typeF");
        let txt = "The Queen of She Done Already Done Had Herses is...";
        typeWriter(txt, 0);
    }

    screen.createImage(currLip[0].getCurrentImage(), "royalblue");
    screen.createBold(currLip[0].name + ", condragulations. You are a winner, baby!");
    for (let i = 1; i < currLip.length; i++) {
        screen.createImage(currLip[i].getCurrentImage(), "darkred");
        screen.createBold(currLip[i].name + ", thank you for an unforgettable season.");
        currLip[i].addToTrackRecord(getReulsLossLabel(roundNumber));
    }

    return currLip[0];
}

function runReulsBracketRound(screen, contestants, roundNumber, targetWinners) {
    let pool = contestants.filter(Boolean);
    if (pool.length === 0) return [];

    while (pool.length > targetWinners) {
        let nextPool = [];

        screen.createHorizontalLine();
        screen.createBold("Round " + roundNumber + "!");

        if (pool.length % 2 !== 0 && pool.length >= 3) {
            for (let i = 0; i < pool.length - 3; i += 2) {
                let winner = resolveReulsDuel(screen, pool[i], pool[i + 1], roundNumber, false);
                nextPool.push(winner);
            }

            let tripleWinner = resolveReulsThreeWay(screen, pool[pool.length - 3], pool[pool.length - 2], pool[pool.length - 1], roundNumber, false);
            nextPool.push(tripleWinner);
        } else {
            for (let i = 0; i < pool.length; i += 2) {
                let winner = resolveReulsDuel(screen, pool[i], pool[i + 1], roundNumber, false);
                nextPool.push(winner);
            }
        }

        pool = nextPool;
    }

    return pool;
}

function runReulsEliminationOrderFormat(screen) {
    screen.createHeader("Lip Sync Smackdown!!");

    let fullEliminationOrder = [...eliminatedCast].reverse();
    if (fullEliminationOrder.length < 5) {
        return false;
    }

    for (let i = 0; i < currentCast.length; i++) {
        currentCast[i].addToTrackRecord("RUN ");
    }

    let preFinaleElimQueen = fullEliminationOrder[fullEliminationOrder.length - 1];
    let eligibleForEarlyRounds = fullEliminationOrder.slice(0, fullEliminationOrder.length - 1);
    let splitPoint = Math.ceil(eligibleForEarlyRounds.length / 2);
    let round1Pool = eligibleForEarlyRounds.slice(0, splitPoint);
    let round2Pool = eligibleForEarlyRounds.slice(splitPoint);
    let round1Winners = runReulsBracketRound(screen, round1Pool, 1, Math.ceil(round1Pool.length / 2));
    let round2Entrants = [...round1Winners, ...round2Pool];
    let round2Winners = runReulsBracketRound(screen, round2Entrants, 2, 3);

    if (round2Winners.length < 2) {
        return false;
    }

    let champion;
    if (round2Winners.length === 2) {
        screen.createHorizontalLine();
        screen.createBold("Round 3!");
        champion = resolveReulsThreeWay(screen, round2Winners[0], round2Winners[1], preFinaleElimQueen, 3, true);
    } else {
        screen.createHorizontalLine();
        screen.createBold("Round 3!");
        let round3Winners = [];

        let semi1Winner = resolveReulsDuel(screen, round2Winners[0], preFinaleElimQueen, 3, false);
        round3Winners.push(semi1Winner);

        let semi2Winner = resolveReulsDuel(screen, round2Winners[1], round2Winners[2], 3, false);
        round3Winners.push(semi2Winner);

        if (round3Winners.length < 2) {
            return false;
        }

        screen.createHorizontalLine();
        screen.createBold("Round 4!");
        champion = resolveReulsDuel(screen, round3Winners[0], round3Winners[1], 4, true);
    }

    champion.addToTrackRecord("WINNER ");
    if (champion.minqdd != 0) {
        champion.minqdd += "<br><small>(Queen of<br>SDADHH)</small>";
    } else {
        champion.minqdd = "<small>(Queen of<br>SDADHH)</small>";
    }

    return true;
}

function runReulsS16Format(screen) {
    screen.createHeader("Lip Sync Smackdown!!");

    let roundCast = [...eliminatedCast];
    if (roundCast.length < 11) {
        return false;
    }
    if (roundCast.length % 2 === 0) {
        return false;
    }

    for (let i = 0; i < currentCast.length; i++) {
        currentCast[i].addToTrackRecord("RUN ");
    }

    screen.createHorizontalLine();
    screen.createBold("Round 1!");
    let duelWinners = [];
    let tripleStart = roundCast.length - 3;
    for (let i = 0; i < tripleStart; i += 2) {
        let winner = resolveReulsDuel(screen, roundCast[i], roundCast[i + 1], 1, false);
        duelWinners.push(winner);
    }
    let semifinalByeWinner = resolveReulsThreeWay(screen, roundCast[tripleStart], roundCast[tripleStart + 1], roundCast[tripleStart + 2], 1, false);
    screen.createBold(semifinalByeWinner.name + " advances directly to the semifinal lipsync.");

    screen.createHorizontalLine();
    screen.createBold("Round 2!");
    let round2Pool = [...duelWinners];
    while (round2Pool.length > 4) {
        let playInA = round2Pool.pop();
        let playInB = round2Pool.pop();
        let playInWinner = resolveReulsDuel(screen, playInA, playInB, 2, false);
        screen.createBold(playInWinner.name + " advances from the Round 2 play-in.");
        round2Pool.unshift(playInWinner);
    }

    let finalist = resolveReulsDuel(screen, round2Pool[0], round2Pool[1], 2, false);
    screen.createBold(finalist.name + " advances directly to the final lipsync.");
    let semifinalist = resolveReulsDuel(screen, round2Pool[2], round2Pool[3], 2, false);
    screen.createBold(semifinalist.name + " advances to the semifinal lipsync.");

    screen.createHorizontalLine();
    screen.createBold("Round 3! Semifinal");
    let finalOpponent = resolveReulsDuel(screen, semifinalByeWinner, semifinalist, 3, false);

    screen.createHorizontalLine();
    screen.createBold("Final Round!");
    let champion = resolveReulsDuel(screen, finalist, finalOpponent, 4, true);

    champion.addToTrackRecord("WINNER ");
    if (champion.minqdd != 0) {
        champion.minqdd += "<br><small>(Queen of<br>SDADHH)</small>";
    } else {
        champion.minqdd = "<small>(Queen of<br>SDADHH)</small>";
    }

    return true;
}

