function toggleFranchiseFilter() {
    const modal = document.getElementById("franchise-filter-modal");
    const legacyPanel = document.getElementById("franchiseContainer");
    const filterBtn = document.querySelector(".search-filter-button");
    if (!modal && !legacyPanel) return;

    if (!modal && legacyPanel) {
        const isOpen = legacyPanel.style.display !== "none";
        legacyPanel.style.display = isOpen ? "none" : "block";
        legacyPanel.classList.toggle("active", !isOpen);
        if (filterBtn) filterBtn.setAttribute("aria-expanded", isOpen ? "false" : "true");
        if (!isOpen) {
            document.addEventListener("keydown", closeFranchiseFilterOnEscape);
        } else {
            document.removeEventListener("keydown", closeFranchiseFilterOnEscape);
        }
        return;
    }

    const isOpen = modal.classList.contains("active") || modal.getAttribute("aria-hidden") === "false";
    if (!isOpen) {
        if (filterBtn) filterBtn.setAttribute("aria-expanded", "true");
        activateCenteredPopup(modal);
        if (!modal.dataset.backdropBound) {
            modal.addEventListener("click", (event) => {
                if (event.target === modal) toggleFranchiseFilter();
            });
            document.addEventListener("keydown", closeFranchiseFilterOnEscape);
            modal.dataset.backdropBound = "true";
        }
    } else {
        if (filterBtn) filterBtn.setAttribute("aria-expanded", "false");
        deactivateCenteredPopup(modal);
    }
}

function closeFranchiseFilterOnEscape(event) {
    if (event.key === "Escape") {
        const modal = document.getElementById("franchise-filter-modal");
        const legacyPanel = document.getElementById("franchiseContainer");
        if (modal && modal.classList.contains("active")) {
            toggleFranchiseFilter();
        } else if (legacyPanel && legacyPanel.style.display !== "none") {
            toggleFranchiseFilter();
        }
    }
}

function getSelectedFranchiseValues(selectId) {
    const select = document.getElementById(selectId);
    if (!select) return [];
    return Array.from(select.selectedOptions).map(opt => opt.value);
}

function setFranchiseSelectToMaster(selectId, masterValue) {
    const select = document.getElementById(selectId);
    if (!select) return;
    Array.from(select.options || []).forEach((option) => {
        option.selected = option.value === masterValue;
    });
}

function clearFranchiseSelectValues(selectId, masterValue) {
    setFranchiseSelectToMaster(selectId, masterValue);
}

function sanitizeFranchiseSelections() {
    const includeSelect = document.getElementById("franchise-filter");
    const excludeSelect = document.getElementById("franchise-exclude-filter");
    if (!includeSelect || !excludeSelect) return;

    const includeValues = new Set(getSelectedFranchiseValues("franchise-filter").filter((value) => value !== "ALL"));
    const excludeValues = new Set(getSelectedFranchiseValues("franchise-exclude-filter").filter((value) => value !== "NONE"));

    if (includeValues.size === 0) {
        setFranchiseSelectToMaster("franchise-filter", "ALL");
    }

    if (excludeValues.size === 0) {
        setFranchiseSelectToMaster("franchise-exclude-filter", "NONE");
    }

    if (includeValues.size > 0 && excludeValues.size > 0) {
        let changed = false;
        Array.from(excludeSelect.options || []).forEach((option) => {
            if (option.value !== "NONE" && option.selected && includeValues.has(option.value)) {
                option.selected = false;
                changed = true;
            }
        });
        if (changed) {
            const remaining = Array.from(excludeSelect.selectedOptions || []).map((opt) => opt.value).filter((value) => value !== "NONE");
            if (remaining.length === 0) {
                setFranchiseSelectToMaster("franchise-exclude-filter", "NONE");
            }
        }
    }
}

function updateFranchiseFilterSummary() {
    const includeSelect = document.getElementById("franchise-filter");
    const excludeSelect = document.getElementById("franchise-exclude-filter");
    const summaryEl = document.getElementById("franchise-filter-summary");
    const filterBtn = document.querySelector(".search-filter-button");

    if (!includeSelect || !excludeSelect) return;

    const includeValues = getSelectedFranchiseValues("franchise-filter").filter((value) => value !== "ALL");
    const excludeValues = getSelectedFranchiseValues("franchise-exclude-filter").filter((value) => value !== "NONE");
    const includeLabels = includeValues.map((value) => includeSelect.querySelector(`option[value="${value}"]`)?.textContent || value);
    const excludeLabels = excludeValues.map((value) => excludeSelect.querySelector(`option[value="${value}"]`)?.textContent || value);
    const activeCount = includeLabels.length + excludeLabels.length;

    if (summaryEl) {
        if (activeCount === 0) {
            summaryEl.textContent = "Filters: all franchises";
        } else {
            const includeText = includeLabels.length ? `Include ${includeLabels.join(", ")}` : "Include all";
            const excludeText = excludeLabels.length ? `Exclude ${excludeLabels.join(", ")}` : "Exclude none";
            summaryEl.textContent = `Filters: ${includeText} • ${excludeText}`;
        }
    }

    if (filterBtn) {
        filterBtn.classList.toggle("filter-active", activeCount > 0);
        filterBtn.setAttribute("aria-label", activeCount > 0 ? `Franchise filters active (${activeCount})` : "Franchise filters");
        filterBtn.title = activeCount > 0 ? `Franchise filters (${activeCount} active)` : "Franchise filters";
    }
}

function bindFranchiseFilterPanelActions() {
    const resetBtn = document.getElementById("franchise-reset-btn");
    const clearIncludeBtn = document.getElementById("franchise-clear-include-btn");
    const clearExcludeBtn = document.getElementById("franchise-clear-exclude-btn");
    const closeBtn = document.getElementById("franchise-close-btn");

    if (resetBtn && !resetBtn.dataset.bound) {
        resetBtn.addEventListener("click", () => {
            setFranchiseSelectToMaster("franchise-filter", "ALL");
            setFranchiseSelectToMaster("franchise-exclude-filter", "NONE");
            updateFranchiseFilterSummary();
            refreshQueenCards();
        });
        resetBtn.dataset.bound = "true";
    }

    if (clearIncludeBtn && !clearIncludeBtn.dataset.bound) {
        clearIncludeBtn.addEventListener("click", () => {
            clearFranchiseSelectValues("franchise-filter", "ALL");
            sanitizeFranchiseSelections();
            updateFranchiseFilterSummary();
            refreshQueenCards();
        });
        clearIncludeBtn.dataset.bound = "true";
    }

    if (clearExcludeBtn && !clearExcludeBtn.dataset.bound) {
        clearExcludeBtn.addEventListener("click", () => {
            clearFranchiseSelectValues("franchise-exclude-filter", "NONE");
            sanitizeFranchiseSelections();
            updateFranchiseFilterSummary();
            refreshQueenCards();
        });
        clearExcludeBtn.dataset.bound = "true";
    }

    if (closeBtn && !closeBtn.dataset.bound) {
        closeBtn.addEventListener("click", () => {
            const modal = document.getElementById("franchise-filter-modal");
            if (modal && modal.classList.contains("active")) {
                toggleFranchiseFilter();
            }
        });
        closeBtn.dataset.bound = "true";
    }
}

function buildFranchisePool(selectedValues) {
    let franchisePool = [];
    if (selectedValues.includes("NORTHAMERICA")) franchisePool.push(...usQueens, ...canQueens, ...mxQueens);
    if (selectedValues.includes("EUROPE")) franchisePool.push(...ukQueens, ...esQueens, ...frQueens, ...itQueens, ...holQueens, ...belQueens, ...svQueens, ...gerQueens);
    if (selectedValues.includes("LATAM")) franchisePool.push(...mxQueens, ...brQueens, ...switchQueens, ...lmdQueens);
    if (selectedValues.includes("ASIAPAC")) franchisePool.push(...phQueens, ...thQueens, ...duQueens, ...chQueens, ...krQueens, indQueens, ...nzQueens);
    if (selectedValues.includes("US")) franchisePool.push(...usQueens);
    if (selectedValues.includes("UK")) franchisePool.push(...ukQueens);
    if (selectedValues.includes("CANADA")) franchisePool.push(...canQueens);
    if (selectedValues.includes("ESPANA")) franchisePool.push(...esQueens);
    if (selectedValues.includes("DOWNUNDER")) franchisePool.push(...duQueens);
    if (selectedValues.includes("FRANCE")) franchisePool.push(...frQueens);
    if (selectedValues.includes("ITALIA")) franchisePool.push(...itQueens);
    if (selectedValues.includes("PHILIPPINES")) franchisePool.push(...phQueens);
    if (selectedValues.includes("THAILAND")) franchisePool.push(...thQueens);
    if (selectedValues.includes("HOLLAND")) franchisePool.push(...holQueens);
    if (selectedValues.includes("BELGIQUE")) franchisePool.push(...belQueens);
    if (selectedValues.includes("MEXICO")) franchisePool.push(...mxQueens);
    if (selectedValues.includes("BRASIL")) franchisePool.push(...brQueens);
    if (selectedValues.includes("SVERIGE")) franchisePool.push(...svQueens);
    if (selectedValues.includes("GERMANY")) franchisePool.push(...gerQueens);
    if (selectedValues.includes("THESWITCH")) franchisePool.push(...switchQueens);
    if (selectedValues.includes("LAMASDRAGA")) franchisePool.push(...lmdQueens);
    if (selectedValues.includes("DRAGULA")) franchisePool.push(...bbdQueens);
    if (selectedValues.includes("MISC")) franchisePool.push(...miscQueens);
    if (selectedValues.includes("CUSTOM")) franchisePool.push(...allCustomQueens);
    return franchisePool;
}

