function removeDuplicateQueensByName(queens) {
    const seen = new Set();
    return queens.filter((queen) => {
        if (!queen || !queen.name || seen.has(queen.name)) return false;
        seen.add(queen.name);
        return true;
    });
}

function shuffledCopy(array) {
    const copy = [...array];
    for (let i = copy.length - 1; i > 0; i--) {
        const j = randomNumber(0, i);
        [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy;
}

function getDragRaceFranchiseMap(includeCustoms = false, candidatePool = null) {
    const candidateNames = Array.isArray(candidatePool)
        ? new Set(candidatePool.map((queen) => normalizeHistoryName(queen && queen.name)).filter(Boolean))
        : null;
    const map = {};
    DRAG_RACE_FRANCHISE_CONFIG.forEach(({ code, source }) => {
        let pool = source().filter((queen) => includeCustoms || !queen.customqueen);
        if (candidateNames) {
            pool = pool.filter((queen) => candidateNames.has(normalizeHistoryName(queen && queen.name)));
        }
        map[code] = removeDuplicateQueensByName(pool);
    });
    return map;
}

function getGenerateCastSelectedFranchiseCode() {
    const franchiseSelect = document.getElementById("generate-cast-franchise");
    return franchiseSelect && franchiseSelect.value ? franchiseSelect.value : "__all__";
}

function getGenerateCastLayoutPreset() {
    const layoutSelect = document.getElementById("generate-cast-layout");
    if (layoutSelect && layoutSelect.value) {
        return layoutSelect.value;
    }
    return "STANDARD";
}

function getAllStarsHistoryBuilderOptions() {
    const presetSelect = document.getElementById("generate-cast-preset");
    const asReturnersSelect = document.getElementById("generate-cast-as-returners");
    const asMaxSelect = document.getElementById("generate-cast-as-max");
    const excludeWinnersEl = document.getElementById("generate-cast-exclude-winners");
    const preset = presetSelect ? presetSelect.value : "random";
    const allowAllStarsReturners = asReturnersSelect ? asReturnersSelect.value !== "exclude" : true;
    const maxAllStarsParticipations = allowAllStarsReturners
        ? (Number.isFinite(Number(asMaxSelect && asMaxSelect.value))
            ? Math.max(0, Math.floor(Number(asMaxSelect.value)))
            : Number.POSITIVE_INFINITY)
        : 0;
    const excludeWinners = excludeWinnersEl ? excludeWinnersEl.checked : false;

    return { preset, allowAllStarsReturners, maxAllStarsParticipations, excludeWinners };
}

function getGenerateCastSourcePool(mode, options = {}) {
    const {
        includeCustoms = true,
        franchiseCode = "__all__",
        allStarsOptions = getAllStarsHistoryBuilderOptions(),
        desiredStats = getDreamCastStatTargets()
    } = options;

    if (mode === "REGULAR_HISTORY") {
        return getRegularHistoryCandidates(includeCustoms, franchiseCode);
    }

    if (mode === "ALL_STARS_HISTORY") {
        return shuffledCopy(getAllStarsHistoryCandidates(includeCustoms, allStarsOptions.preset, {
            allowAllStarsReturners: allStarsOptions.allowAllStarsReturners,
            maxAllStarsParticipations: allStarsOptions.maxAllStarsParticipations,
            excludeWinners: allStarsOptions.excludeWinners,
            franchiseCode
        }))
            .sort((a, b) => b.score - a.score || a.queen.name.localeCompare(b.queen.name))
            .map((entry) => entry.queen);
    }

    if (mode === "DREAM") {
        return shuffledCopy(getFilteredGenerateCastPool(includeCustoms, franchiseCode))
            .map((queen) => ({
                queen,
                score: calculateDreamCastScore(queen, desiredStats),
                average: getQueenAverageStat(queen)
            }))
            .sort((a, b) => b.score - a.score || b.average - a.average || a.queen.name.localeCompare(b.queen.name))
            .map((entry) => entry.queen);
    }

    return getFilteredGenerateCastPool(includeCustoms, franchiseCode);
}

function getAvailableGlobalFranchises(franchiseMap) {
    return DRAG_RACE_FRANCHISE_CONFIG.filter((franchise) => {
        const pool = franchiseMap[franchise.code] || [];
        return pool.length > 0;
    });
}

const DREAM_CAST_STAT_CONFIG = [
    { key: "acting", property: "_actingStat" },
    { key: "comedy", property: "_comedyStat" },
    { key: "dance", property: "_danceStat" },
    { key: "design", property: "_designStat" },
    { key: "improv", property: "_improvStat" },
    { key: "runway", property: "_runwayStat" },
    { key: "lipsync", property: "_lipsyncStat" }
];

function getFilteredGenerateCastPool(includeCustoms = true, franchiseCode = "__all__") {
    let pool = allQueens.filter((queen) => includeCustoms || !queen.customqueen);

    const includeValues = getSelectedFranchiseValues("franchise-filter");
    const excludeValues = getSelectedFranchiseValues("franchise-exclude-filter");

    if (includeValues.length > 0 && !includeValues.includes("ALL")) {
        const franchiseNames = new Set(buildFranchisePool(includeValues).map((queen) => queen.uid));
        pool = pool.filter((queen) => franchiseNames.has(queen.uid));
    }

    if (excludeValues.length > 0 && !excludeValues.includes("NONE")) {
        const excludedNames = new Set(buildFranchisePool(excludeValues).map((queen) => queen.uid));
        pool = pool.filter((queen) => !excludedNames.has(queen.uid));
    }

    return removeDuplicateQueensByName(pool);
}

function updateDreamCastStatValue(input) {
    if (!input) return;
    const output = document.querySelector(`[data-dream-stat-value="${input.id}"]`);
    if (output) {
        output.textContent = input.value;
    }

    const min = Number(input.min || 0);
    const max = Number(input.max || 100);
    const value = Number(input.value || 0);
    const progress = max === min ? 0 : ((value - min) / (max - min)) * 100;

    input.style.setProperty("--dream-slider-progress", `${progress}%`);
}

function initDreamCastStatControls() {
    const statInputs = document.querySelectorAll("[data-dream-stat]");
    statInputs.forEach((input) => {
        if (!input.dataset.bound) {
            input.addEventListener("input", () => updateDreamCastStatValue(input));
            input.dataset.bound = "true";
        }
        updateDreamCastStatValue(input);
    });
}

function getDreamCastStatTargets() {
    const targets = {};
    DREAM_CAST_STAT_CONFIG.forEach(({ key }) => {
        const input = document.querySelector(`[data-dream-stat="${key}"]`);
        targets[key] = input ? parseInt(input.value, 10) || 0 : 10;
    });
    return targets;
}

function getQueenAverageStat(queen) {
    let total = 0;
    for (let i = 0; i < DREAM_CAST_STAT_CONFIG.length; i++) {
        total += Number(queen[DREAM_CAST_STAT_CONFIG[i].property]) || 0;
    }
    return total / DREAM_CAST_STAT_CONFIG.length;
}

function calculateDreamCastScore(queen, desiredStats) {
    let score = 0;

    DREAM_CAST_STAT_CONFIG.forEach(({ key, property }) => {
        const target = Number(desiredStats[key]) || 0;
        const value = Number(queen[property]) || 0;
        const closeness = 15 - Math.abs(value - target);
        const ambitionBonus = (target / 15) * value;

        score += closeness * 3 + ambitionBonus;
    });

    return score + getQueenAverageStat(queen);
}

function generateDreamCast(options = {}) {
    const {
        size = "random",
        includeCustoms = true,
        franchiseCode = "__all__",
        minSize = 8,
        maxSize = 16,
        desiredStats = getDreamCastStatTargets()
    } = options;

    const pool = getFilteredGenerateCastPool(includeCustoms, franchiseCode);
    if (pool.length === 0) {
        alert("No queens available for this dream cast.");
        return;
    }

    const maxAllowedSize = Math.min(maxSize, pool.length);
    const castSize = size === "random"
        ? randomNumber(Math.min(minSize, maxAllowedSize), maxAllowedSize)
        : Math.min(size, pool.length);

    const rankedPool = shuffledCopy(pool)
        .map((queen) => ({
            queen,
            score: calculateDreamCastScore(queen, desiredStats),
            average: getQueenAverageStat(queen)
        }))
        .sort((a, b) => b.score - a.score || b.average - a.average || a.queen.name.localeCompare(b.queen.name));

    applyGeneratedCast(rankedPool.slice(0, castSize).map((entry) => entry.queen));
}

function pickUniqueQueensFromPool(pool, amount, selectedNames) {
    const picked = [];
    const shuffledPool = shuffledCopy(pool);
    for (let i = 0; i < shuffledPool.length && picked.length < amount; i++) {
        const queen = shuffledPool[i];
        if (!selectedNames.has(queen.name)) {
            picked.push(queen);
            selectedNames.add(queen.name);
        }
    }
    return picked;
}

function applyGeneratedCast(cast) {
    currentCast = cast;
    updateCast();

    let big = document.getElementById("castBig");
    big.classList.toggle("hide", false);
    big.innerHTML = "Current Cast: " + currentCast.length;

    let txt = document.querySelector('.nobody');
    if (txt) txt.classList.toggle("hide", true);

    let logo = document.querySelector('.content-image');
    if (logo) logo.classList.toggle("hide", true);
}

function enforceFranchiseCap(cast, maxQueens, franchiseNameSet, replacementPool) {
    const cappedCast = [];
    const selectedNames = new Set();
    let franchiseCount = 0;

    for (let i = 0; i < cast.length; i++) {
        const queen = cast[i];
        const isInFranchise = franchiseNameSet.has(queen.name);
        if (!isInFranchise || franchiseCount < maxQueens) {
            cappedCast.push(queen);
            selectedNames.add(queen.name);
            if (isInFranchise) franchiseCount++;
        }
    }

    if (cappedCast.length < cast.length) {
        const fillers = pickUniqueQueensFromPool(
            replacementPool.filter((queen) => !franchiseNameSet.has(queen.name)),
            cast.length - cappedCast.length,
            selectedNames
        );
        cappedCast.push(...fillers);
    }

    return cappedCast;
}

function generateCountryVSTWCast(options = {}) {
    const {
        hostCode,
        size = "random",
        minSize = 10,
        maxSize = 16,
        maxHostQueens = 5,
        candidatePool = null
    } = options;

    const { includeCustoms = true } = options;

    const franchiseMap = getDragRaceFranchiseMap(includeCustoms, candidatePool);
    const validHosts = DRAG_RACE_FRANCHISE_CONFIG.map((franchise) => franchise.code);
    if (!hostCode || !validHosts.includes(hostCode)) {
        alert("Invalid host country for Country VSTW.");
        return;
    }

    const hostPool = franchiseMap[hostCode] || [];
    const worldPools = DRAG_RACE_FRANCHISE_CONFIG
        .filter((franchise) => franchise.code !== hostCode)
        .map((franchise) => ({ code: franchise.code, pool: franchiseMap[franchise.code] || [] }));

    const fullPool = removeDuplicateQueensByName([
        ...hostPool,
        ...worldPools.flatMap((franchise) => franchise.pool)
    ]);

    if (fullPool.length === 0 || hostPool.length === 0) {
        alert("Not enough Drag Race queens available for Country VSTW.");
        return;
    }

    const maxAllowedSize = Math.min(maxSize, fullPool.length);
    const castSize = size === "random"
        ? randomNumber(Math.min(minSize, maxAllowedSize), maxAllowedSize)
        : Math.min(size, fullPool.length);

    const hostTargetRaw = Math.max(3, Math.floor(castSize / 3));
    const hostTarget = Math.min(hostTargetRaw, maxHostQueens);
    const hostCount = Math.min(hostTarget, hostPool.length, Math.max(1, castSize - 1));
    const worldCount = castSize - hostCount;

    const selectedNames = new Set();
    const selected = [];

    selected.push(...pickUniqueQueensFromPool(hostPool, hostCount, selectedNames));

    const shuffledWorldFranchises = shuffledCopy(worldPools);
    for (let i = 0; i < shuffledWorldFranchises.length && selected.length < castSize; i++) {
        const franchisePool = shuffledWorldFranchises[i].pool;
        const onePick = pickUniqueQueensFromPool(franchisePool, 1, selectedNames);
        selected.push(...onePick);
    }

    if (selected.length < castSize) {
        const remainingWorldPool = worldPools.flatMap((franchise) => franchise.pool);
        selected.push(...pickUniqueQueensFromPool(remainingWorldPool, worldCount - (selected.length - hostCount), selectedNames));
    }

    let finalCast = selected.slice(0, castSize);
    const hostNameSet = new Set(hostPool.map((queen) => queen.name));
    finalCast = enforceFranchiseCap(finalCast, maxHostQueens, hostNameSet, fullPool);
    finalCast = shuffledCopy(finalCast).slice(0, castSize);

    applyGeneratedCast(finalCast);
}

function generateGlobalCast(options = {}) {
    const {
        size = "random",
        minSize = 10,
        candidatePool = null
    } = options;

    const { includeCustoms = true } = options;

    const franchiseMap = getDragRaceFranchiseMap(includeCustoms, candidatePool);
    const availableFranchises = getAvailableGlobalFranchises(franchiseMap);
    const franchisePools = availableFranchises.map((franchise) => ({
        code: franchise.code,
        pool: franchiseMap[franchise.code] || []
    }));

    if (franchisePools.length === 0) {
        alert("No Drag Race queens available for Global cast.");
        return;
    }

    const maxAllowedSize = franchisePools.length;
    const castSize = size === "random"
        ? randomNumber(Math.min(minSize, maxAllowedSize), maxAllowedSize)
        : Math.min(size, franchisePools.length);

    const shuffledFranchises = shuffledCopy(franchisePools);
    const selectedFranchises = shuffledFranchises.slice(0, castSize);

    const finalCast = [];
    for (let i = 0; i < selectedFranchises.length; i++) {
        const franchisePool = selectedFranchises[i].pool;
        if (franchisePool.length === 0) continue;
        const queen = franchisePool[randomNumber(0, franchisePool.length - 1)];
        finalCast.push(queen);
    }

    applyGeneratedCast(finalCast);
}

const SEASON_HISTORY_FRANCHISES_KEY = "seasonHistoryFranchises";
const SEASON_HISTORY_ACTIVE_FRANCHISE_KEY = "seasonHistoryActiveFranchise";
const DEFAULT_SEASON_HISTORY_FRANCHISE = "Main";
let seasonHistoryFranchiseStoreCache = null;

function normalizeSeasonHistoryFranchiseName(value) {
    const cleaned = String(value || "").replace(/\s+/g, " ").trim();
    return cleaned || DEFAULT_SEASON_HISTORY_FRANCHISE;
}

function getCurrentSeasonHistoryFranchise() {
    return normalizeSeasonHistoryFranchiseName(localStorage.getItem(SEASON_HISTORY_ACTIVE_FRANCHISE_KEY));
}

function setCurrentSeasonHistoryFranchise(name) {
    const normalized = normalizeSeasonHistoryFranchiseName(name);
    localStorage.setItem(SEASON_HISTORY_ACTIVE_FRANCHISE_KEY, normalized);
    return normalized;
}

function getSeasonHistoryFranchiseStore() {
    if (seasonHistoryFranchiseStoreCache) {
        return seasonHistoryFranchiseStoreCache;
    }

    let parsed = null;
    try {
        parsed = JSON.parse(localStorage.getItem(SEASON_HISTORY_FRANCHISES_KEY) || "{}");
    } catch (_err) {
        parsed = {};
    }

    const store = {};
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        Object.keys(parsed).forEach((franchiseName) => {
            const normalized = normalizeSeasonHistoryFranchiseName(franchiseName);
            const records = parsed[franchiseName];
            store[normalized] = Array.isArray(records) ? records : [];
        });
    }

    if (Object.keys(store).length === 0) {
        let legacy = [];
        try {
            const oldStored = JSON.parse(localStorage.getItem("seasonHistory") || "[]");
            legacy = Array.isArray(oldStored) ? oldStored : [];
        } catch (_err) {
            legacy = [];
        }

        if (legacy.length > 0) {
            store[DEFAULT_SEASON_HISTORY_FRANCHISE] = legacy.map((record) => {
                const clone = { ...record };
                clone.historyFranchise = DEFAULT_SEASON_HISTORY_FRANCHISE;
                return clone;
            });
        }
    }

    const active = getCurrentSeasonHistoryFranchise();
    if (!store[active]) {
        if (Object.keys(store).length === 0) {
            store[active] = [];
        } else {
            const firstKey = Object.keys(store)[0];
            setCurrentSeasonHistoryFranchise(firstKey);
        }
    }

    seasonHistoryFranchiseStoreCache = store;
    return store;
}

function buildMergedSeasonHistoryRecords(store) {
    return Object.values(store || {}).reduce((allRecords, records) => {
        if (!Array.isArray(records)) {
            return allRecords;
        }
        records.forEach((record) => allRecords.push(record));
        return allRecords;
    }, []);
}

function minifyHistoryMarkup(markup = "") {
    const html = String(markup || "");
    if (!html) return "";
    return html
        .replace(/>\s+</g, "><")
        .replace(/\s{2,}/g, " ")
        .trim();
}

function compactHistoryFlagMap(flags) {
    if (!flags || typeof flags !== "object") {
        return {};
    }

    const compactFlags = {};
    Object.keys(flags).forEach((key) => {
        if (flags[key] === true) {
            compactFlags[key] = true;
        }
    });
    return compactFlags;
}

function compactHistoryCastEntry(entry = {}) {
    if (!entry || typeof entry !== "object") {
        return null;
    }

    const compact = {
        name: entry.name
    };

    ["image", "name1", "name2", "country", "prizeCurrency"].forEach((field) => {
        if (entry[field]) compact[field] = entry[field];
    });

    ["images", "trackRecord", "lipsyncHistory", "voteHerstory", "mvqWonHistory", "mvqGiftedHistory", "laMasScoreHistory", "sealEpisodes", "retEp", "ogPlace", "miniEpisode", "tCaptain", "grantEpisode", "miniLoser", "redLSEp", "heartEpisode", "gftdS", "immuneEp", "redSealEp", "curseEp", "friends", "allies", "enemies", "sisters", "prizeAwards"].forEach((field) => {
        if (Array.isArray(entry[field]) && entry[field].length > 0) {
            compact[field] = entry[field];
        }
    });

    ["currentImageIndex", "money", "rankP", "acting", "comedy", "dance", "design", "improv", "runway", "lipsync", "ppe", "stars", "luckycowvotes", "redSeals", "episodesOn", "votes", "retEp2", "ogPlace2", "minqdd"].forEach((field) => {
        if (Number(entry[field]) !== 0) {
            compact[field] = entry[field];
        }
    });

    if (Number(entry.hearts) !== 1) {
        compact.hearts = entry.hearts;
    }

    ["custom", "isDuo", "luckydoll", "goldSeal", "purpleSeal"].forEach((field) => {
        if (entry[field] === true) {
            compact[field] = true;
        }
    });

    return compact;
}

function compactHistoryRecordForStorage(record = {}) {
    const compact = { ...record };

    compact.trackRecordHTML = minifyHistoryMarkup(compact.trackRecordHTML || "");
    compact.formatFlags = compactHistoryFlagMap(compact.formatFlags);
    compact.premiereFlags = compactHistoryFlagMap(compact.premiereFlags);
    compact.returningFlags = compactHistoryFlagMap(compact.returningFlags);
    compact.twists = compactHistoryFlagMap(compact.twists);
    if (record.twists && (record.twists.immunity || record.twists.immunityPotions)) {
        compact.twists.immunityAwardTiming = record.twists.immunityAwardTiming;
        compact.twists.immunityPotionExpiry = record.twists.immunityPotionExpiry;
    }

    if (Array.isArray(compact.cast)) {
        compact.cast = compact.cast
            .map((entry) => compactHistoryCastEntry(entry))
            .filter(Boolean);
    }

    ["challenges", "alots", "saveTwist4Chart", "decidingVote4Chart", "elimKween4Chart", "safetyDecidingVote4Chart", "safetyResult4Chart", "winnerNames", "winnerImgs"].forEach((field) => {
        if (Array.isArray(compact[field]) && compact[field].length === 0) {
            delete compact[field];
        }
    });

    ["liveShare", "trackRecordRankCache"].forEach((field) => {
        if (compact[field] && typeof compact[field] === "object" && Object.keys(compact[field]).length === 0) {
            delete compact[field];
        }
    });

    return compact;
}

function compactSeasonHistoryStoreForQuota(store = {}) {
    const compactStore = {};
    Object.keys(store || {}).forEach((franchiseName) => {
        const records = Array.isArray(store[franchiseName]) ? store[franchiseName] : [];
        compactStore[franchiseName] = records.map((record) => compactHistoryRecordForStorage(record));
    });
    return compactStore;
}

function trimOldestSeasonHistoryRecord(store = {}) {
    const nextStore = {};
    let targetFranchise = null;
    let longestLength = 0;

    Object.keys(store || {}).forEach((franchiseName) => {
        const records = Array.isArray(store[franchiseName]) ? store[franchiseName] : [];
        nextStore[franchiseName] = records.slice();
        if (records.length > longestLength) {
            longestLength = records.length;
            targetFranchise = franchiseName;
        }
    });

    if (!targetFranchise || !Array.isArray(nextStore[targetFranchise]) || nextStore[targetFranchise].length === 0) {
        return null;
    }

    nextStore[targetFranchise] = nextStore[targetFranchise].slice(0, -1);
    return nextStore;
}

function saveSeasonHistoryFranchiseStore(store, options = {}) {
    const { skipCompaction = false } = options;
    const compactStore = skipCompaction ? store : compactSeasonHistoryStoreForQuota(store);

    seasonHistoryFranchiseStoreCache = compactStore;

    try {
        localStorage.setItem(SEASON_HISTORY_FRANCHISES_KEY, JSON.stringify(compactStore));
    } catch (error) {
        if (!error || error.name !== "QuotaExceededError") {
            return false;
        }
        return false;
    }

    // Legacy mirror key is best-effort only.
    try {
        localStorage.setItem("seasonHistory", JSON.stringify(buildMergedSeasonHistoryRecords(compactStore)));
    } catch (_err) {}

    return true;
}

function getSeasonHistoryFranchiseNames(store = getSeasonHistoryFranchiseStore()) {
    const names = Object.keys(store || {}).map(normalizeSeasonHistoryFranchiseName);
    if (names.length === 0) {
        return [getCurrentSeasonHistoryFranchise()];
    }
    return names;
}

function getStoredSeasonHistoryRecords(franchiseName = null) {
    if (franchiseName) {
        return getLocalSeasonHistoryRecords(franchiseName);
    }

    if (Array.isArray(window.historyCloudMergedSeasons) && window.historyCloudMergedSeasons.length > 0) {
        return window.historyCloudMergedSeasons;
    }

    const store = getSeasonHistoryFranchiseStore();
    return buildMergedSeasonHistoryRecords(store);
}

function getLocalSeasonHistoryRecords(franchiseName = null) {
    const store = getSeasonHistoryFranchiseStore();
    const targetFranchise = normalizeSeasonHistoryFranchiseName(franchiseName || getCurrentSeasonHistoryFranchise());
    return Array.isArray(store[targetFranchise]) ? store[targetFranchise] : [];
}

function setLocalSeasonHistoryRecords(franchiseName, records) {
    const targetFranchise = normalizeSeasonHistoryFranchiseName(franchiseName || getCurrentSeasonHistoryFranchise());
    const store = getSeasonHistoryFranchiseStore();
    store[targetFranchise] = Array.isArray(records) ? records : [];
    seasonHistoryFranchiseStoreCache = store;
    return saveSeasonHistoryFranchiseStore(store);
}

function buildSeasonHistoryStorageKey(record = {}) {
    if (record && record.id !== undefined && record.id !== null && record.id !== "") {
        return "id:" + String(record.id);
    }

    const liveShare = record && record.liveShare ? record.liveShare : {};
    return [
        String(liveShare.roomId || ""),
        String(record.name || "").trim().toLowerCase(),
        String(record.date || ""),
        String(record.winner || "").trim().toLowerCase(),
        Number(record.episodes || 0),
        String(record.savedAt || "")
    ].join("|");
}

function addSeasonRecordToHistory(record, options = {}) {
    if (!record || typeof record !== "object") {
        return false;
    }

    let normalizedRecord = null;
    try {
        normalizedRecord = JSON.parse(JSON.stringify(record));
    } catch (_err) {
        return false;
    }

    if (!normalizedRecord) {
        return false;
    }

    if (options.source) {
        normalizedRecord.historySource = options.source;
    }
    normalizedRecord = compactHistoryRecordForStorage(normalizedRecord);
    if (normalizedRecord.id === undefined || normalizedRecord.id === null || normalizedRecord.id === "") {
        normalizedRecord.id = "season-" + Date.now() + "-" + Math.floor(Math.random() * 1000000);
    }
    const targetFranchise = normalizeSeasonHistoryFranchiseName(options.franchise || normalizedRecord.historyFranchise || getCurrentSeasonHistoryFranchise());
    normalizedRecord.historyFranchise = targetFranchise;
    if (options.archivedFromLive) {
        normalizedRecord.archivedFromLive = true;
    }
    normalizedRecord.savedAt = normalizedRecord.savedAt || new Date().toISOString();

    if (normalizedRecord.liveShare && normalizedRecord.liveShare.roomId) {
        normalizedRecord.liveShare.watchUrl = getLiveSeasonWatchUrl(normalizedRecord.liveShare.roomId);
    }

    const localHistory = getLocalSeasonHistoryRecords(targetFranchise);
    const recordKey = buildSeasonHistoryStorageKey(normalizedRecord);
    const existingIndex = localHistory.findIndex((item) => buildSeasonHistoryStorageKey(item) === recordKey);

    if (existingIndex >= 0) {
        localHistory[existingIndex] = { ...localHistory[existingIndex], ...normalizedRecord };
    } else {
        localHistory.unshift(normalizedRecord);
    }

    const stored = setLocalSeasonHistoryRecords(targetFranchise, localHistory);
    if (!stored) {
        window.pendingCloudOnlyHistoryRecord = normalizedRecord;
        return false;
    }

    window.pendingCloudOnlyHistoryRecord = null;

    if (Array.isArray(window.historyCloudMergedSeasons)) {
        const mergedHistory = [...window.historyCloudMergedSeasons];
        const mergedIndex = mergedHistory.findIndex((item) => buildSeasonHistoryStorageKey(item) === recordKey);
        if (mergedIndex >= 0) {
            mergedHistory[mergedIndex] = { ...mergedHistory[mergedIndex], ...normalizedRecord };
        } else {
            mergedHistory.unshift(normalizedRecord);
        }
        window.historyCloudMergedSeasons = mergedHistory;
    }

    if (options.notice && typeof showFloatingNotice === "function") {
        showFloatingNotice(options.notice, 2200);
    }

    return true;
}

function getAllStarsHistoryCandidates(includeCustoms = true, preset = "random", options = {}) {
    const {
        allowAllStarsReturners = true,
        maxAllStarsParticipations = Number.POSITIVE_INFINITY,
        excludeWinners = false,
        franchiseCode = "__all__"
    } = options;
    const selectedHistoryFranchise = franchiseCode && franchiseCode !== "__all__" ? franchiseCode : null;
    const history = getStoredSeasonHistoryRecords(selectedHistoryFranchise);
    const pool = getFilteredGenerateCastPool(includeCustoms);
    const poolByName = new Map();
    const presetKey = normalizeHistoryMetaKey(preset);
    const normalizedMaxAllStarsParticipations = Number.isFinite(Number(maxAllStarsParticipations))
        ? Math.max(0, Math.floor(Number(maxAllStarsParticipations)))
        : Number.POSITIVE_INFINITY;

    pool.forEach((queen) => {
        poolByName.set(normalizeHistoryName(queen.name), queen);
    });

    function isBracketAllStarsSeason(season) {
        if (!season || typeof season !== "object") {
            return false;
        }

        const formatKey = normalizeHistoryMetaKey(season.format);
        if (formatKey === "brackets-format" || formatKey === "bracketsformat") {
            return true;
        }

        const flags = season.formatFlags || {};
        return !!(flags.top6ls || flags.top6lsSudden || flags.top6as11 || flags.top7ls || flags.top8ls);
    }

    function isAllStarsHistorySeason(season) {
        if (!season || typeof season !== "object") {
            return false;
        }

        const flags = season.formatFlags || {};
        const inferredType = flags.all_winners
            ? "all-winners"
            : (flags.all_stars || flags.lipsync_assassin || flags.og_lsa || flags.top2LFTWFormat || flags.safetyFormat)
                ? "all-stars"
                : "regular";
        const seasonType = normalizeHistorySeasonType(season.seasonType || inferredType);
        if (seasonType === "all-stars") {
            return true;
        }

        const formatKey = normalizeHistoryMetaKey(season.format);
        return formatKey === "all-stars"
            || formatKey === "lipsync-assassin"
            || formatKey === "og-lipsync-assassin"
            || formatKey === "top2lftw"
            || formatKey === "safety";
    }

    function hasWinnerTrackRecord(trackRecord, entryName = "", season = null) {
        const hasWinnerPlacement = Array.isArray(trackRecord)
            ? trackRecord.some((placement) => typeof placement === "string" && placement.toUpperCase() === "WINNER")
            : (typeof trackRecord === "string" && trackRecord.toUpperCase() === "WINNER");
        if (!hasWinnerPlacement) {
            return false;
        }

        const seasonWinnerStatus = isHistoryEntrySeasonWinner(entryName, season);
        return seasonWinnerStatus !== false;
    }

    function isBadTrackRecord(entry) {
        const wins = countHistoryWins(entry.trackRecord);
        const tops = countHistoryTopPlacements(entry.trackRecord);
        const bottoms = countHistoryBottomTwos(entry.trackRecord);
        const rank = resolveHistoryEntryRank(entry);
        return (bottoms > (tops + wins)) || rank > 6;
    }

    function isGoodTrackRecord(entry) {
        const wins = countHistoryWins(entry.trackRecord);
        const tops = countHistoryTopPlacements(entry.trackRecord);
        const bottoms = countHistoryBottomTwos(entry.trackRecord);
        const rank = resolveHistoryEntryRank(entry);
        return ((tops + wins) > bottoms) && rank <= 4;
    }

    const filteredHistory = presetKey === "bracket-allstars"
        ? history.filter(isBracketAllStarsSeason)
        : history;

    const statsByName = new Map();
    filteredHistory.forEach((season, seasonIndex) => {
        const seasonIsAllStars = isAllStarsHistorySeason(season);
        const cast = Array.isArray(season.cast) ? season.cast : [];
        cast.forEach((entry) => {
            const normalizedName = normalizeHistoryName(entry && entry.name);
            if (!normalizedName || !poolByName.has(normalizedName)) {
                return;
            }

            const rankValue = resolveHistoryEntryRank(entry, season);
            const existing = statsByName.get(normalizedName) || {
                name: entry.name,
                appearances: 0,
                crowns: 0,
                wins: 0,
                tops: 0,
                bottoms: 0,
                ppeTotal: 0,
                ppeCount: 0,
                bestRank: Number.POSITIVE_INFINITY,
                recencyScore: 0,
                hasWinnerTrackRecord: false,
                allStarsParticipations: 0,
                lastEntry: null
            };

            existing.appearances += 1;
            existing.crowns += rankValue === 1 ? 1 : 0;
            existing.wins += countHistoryWins(entry.trackRecord);
            existing.tops += countHistoryTopPlacements(entry.trackRecord);
            existing.bottoms += countHistoryBottomTwos(entry.trackRecord);
            existing.hasWinnerTrackRecord = existing.hasWinnerTrackRecord || hasWinnerTrackRecord(entry.trackRecord, entry.name, season) || rankValue === 1;
            if (seasonIsAllStars) {
                existing.allStarsParticipations += 1;
            }

            const ppeValue = Number(entry.ppe);
            if (Number.isFinite(ppeValue)) {
                existing.ppeTotal += ppeValue;
                existing.ppeCount += 1;
            }

            if (Number.isFinite(rankValue)) {
                existing.bestRank = Math.min(existing.bestRank, rankValue);
            }

            existing.recencyScore += Math.max(0, filteredHistory.length - seasonIndex);
            existing.lastEntry = entry;
            statsByName.set(normalizedName, existing);
        });
    });

    let entries = Array.from(statsByName.entries()).map(([normalizedName, stats]) => {
        const queen = poolByName.get(normalizedName);
        const averagePPE = stats.ppeCount > 0 ? stats.ppeTotal / stats.ppeCount : 0;
        const bestRankBonus = Number.isFinite(stats.bestRank)
            ? Math.max(0, 12 - Math.min(stats.bestRank, 12))
            : 0;

        const score =
            (stats.crowns * 25)
            + (stats.wins * 7)
            + (stats.tops * 3)
            - (stats.bottoms * 2)
            + (averagePPE * 4)
            + (bestRankBonus * 2)
            + (stats.appearances * 1.5)
            + (stats.recencyScore * 0.35);

        return {
            queen,
            score,
            stats
        };
    }).filter((entry) => entry.queen);

    if (presetKey === "all-winners") {
        entries = entries.filter((entry) => entry.stats.hasWinnerTrackRecord || entry.stats.crowns > 0);
    } else if (excludeWinners) {
        entries = entries.filter((entry) => !entry.stats.hasWinnerTrackRecord && entry.stats.crowns === 0);
    }

    if (presetKey === "redemption") {
        entries = entries.filter((entry) => entry.stats.lastEntry && isBadTrackRecord(entry.stats.lastEntry));
    } else if (presetKey === "good") {
        entries = entries.filter((entry) => entry.stats.lastEntry && isGoodTrackRecord(entry.stats.lastEntry));
    } else if (presetKey === "mixed") {
        const bad = entries.filter((entry) => entry.stats.lastEntry && isBadTrackRecord(entry.stats.lastEntry));
        const good = entries.filter((entry) => entry.stats.lastEntry && isGoodTrackRecord(entry.stats.lastEntry));
        const mixed = [];
        let i = 0;
        while (i < bad.length || i < good.length) {
            if (i < bad.length) mixed.push(bad[i]);
            if (i < good.length) mixed.push(good[i]);
            i++;
        }
        entries = mixed;
    }

    if (!allowAllStarsReturners || normalizedMaxAllStarsParticipations === 0) {
        entries = entries.filter((entry) => entry.stats.allStarsParticipations === 0);
    } else if (normalizedMaxAllStarsParticipations < Number.POSITIVE_INFINITY) {
        entries = entries.filter((entry) => entry.stats.allStarsParticipations <= normalizedMaxAllStarsParticipations);
    }

    return entries;
}

function getRegularHistoryCandidates(includeCustoms = true, franchiseCode = "__all__") {
    const selectedHistoryFranchise = franchiseCode && franchiseCode !== "__all__" ? franchiseCode : null;
    const history = getStoredSeasonHistoryRecords(selectedHistoryFranchise);
    const pool = getFilteredGenerateCastPool(includeCustoms);

    if (!Array.isArray(history) || history.length === 0) {
        return [...pool];
    }

    const usedNames = new Set();

    history.forEach((season) => {
        const cast = Array.isArray(season && season.cast) ? season.cast : [];
        cast.forEach((entry) => {
            const rawName = entry && (entry.name || entry._name || entry);
            const normalizedName = normalizeHistoryName(rawName);
            if (normalizedName) {
                usedNames.add(normalizedName);
            }
        });
    });

    return pool.filter((queen) => !usedNames.has(normalizeHistoryName(queen && queen.name)));
}

function selectDiverseAllStarsCandidates(candidates, castSize, options = {}) {
    const source = Array.isArray(candidates) ? candidates : [];
    const targetSize = Math.max(0, Math.min(Number(castSize) || 0, source.length));
    if (options.preserveRanking || targetSize === 0) {
        return source.slice(0, targetSize);
    }

    const buckets = [[], [], []];
    source.forEach((entry) => {
        const bestRank = entry && entry.stats ? Number(entry.stats.bestRank) : Number.POSITIVE_INFINITY;
        const bucketIndex = bestRank <= 4 ? 0 : bestRank <= 8 ? 1 : 2;
        buckets[bucketIndex].push(entry);
    });

    const bucketTargets = [
        Math.round(targetSize * 0.4),
        Math.round(targetSize * 0.3),
        targetSize - Math.round(targetSize * 0.4) - Math.round(targetSize * 0.3)
    ];
    const selected = [];
    const remaining = buckets.map((bucket) => shuffledCopy(bucket));

    for (let bucketIndex = 0; bucketIndex < remaining.length; bucketIndex += 1) {
        const target = Math.min(bucketTargets[bucketIndex], remaining[bucketIndex].length);
        selected.push(...remaining[bucketIndex].splice(0, target));
    }

    const leftovers = remaining.flat();
    while (selected.length < targetSize && leftovers.length > 0) {
        selected.push(leftovers.shift());
    }

    return shuffledCopy(selected);
}

function generateHistoryAllStarsCast(options = {}) {
    const {
        size = "random",
        includeCustoms = true,
        franchiseCode = "__all__",
        preset = "random",
        allowAllStarsReturners = true,
        maxAllStarsParticipations = Number.POSITIVE_INFINITY,
        excludeWinners = false,
        minSize = 10,
        maxSize = 16
    } = options;

    const rankedCandidates = shuffledCopy(getAllStarsHistoryCandidates(includeCustoms, preset, {
        allowAllStarsReturners,
        maxAllStarsParticipations,
        excludeWinners,
        franchiseCode
    }))
        .sort((a, b) => b.score - a.score || a.queen.name.localeCompare(b.queen.name));

    const isBracketAllStarsPreset = normalizeHistoryMetaKey(preset) === "bracket-allstars";

    if (rankedCandidates.length === 0) {
        alert(isBracketAllStarsPreset
            ? "No eligible queens found. Save at least one Tournament of All Stars season to Season History first."
            : "No eligible queens found in saved Season History for this preset.");
        return;
    }

    if (isBracketAllStarsPreset && rankedCandidates.length < 18) {
        alert(`Tournament of All Stars needs 18 eligible queens (found ${rankedCandidates.length}).`);
        return;
    }

    const maxAllowedSize = Math.min(maxSize, rankedCandidates.length);
    const castSize = isBracketAllStarsPreset
        ? 18
        : size === "random"
            ? randomNumber(Math.min(minSize, maxAllowedSize), maxAllowedSize)
            : Math.min(size, rankedCandidates.length);

    const finalCast = selectDiverseAllStarsCandidates(rankedCandidates, castSize, {
        preserveRanking: ["all-winners", "redemption", "good"].includes(normalizeHistoryMetaKey(preset))
    }).map((entry) => entry.queen);
    applyGeneratedCast(shuffledCopy(finalCast));
}

function generateRegularHistoryCast(options = {}) {
    const {
        size = "random",
        includeCustoms = true,
        franchiseCode = "__all__",
        minSize = 8,
        maxSize = 16
    } = options;

    const availableQueens = shuffledCopy(getRegularHistoryCandidates(includeCustoms, franchiseCode));

    if (availableQueens.length === 0) {
        alert("No eligible queens found. Every available queen appears in your saved Season History.");
        return;
    }

    const maxAllowedSize = Math.min(maxSize, availableQueens.length);
    const castSize = size === "random"
        ? randomNumber(Math.min(minSize, maxAllowedSize), maxAllowedSize)
        : Math.min(size, availableQueens.length);

    applyGeneratedCast(availableQueens.slice(0, castSize));
}

function randomCastPopup() {
    initGenerateCastUI();
    openGenerateCastModal();
}

function initGenerateCastUI() {
    const modal = document.getElementById("generate-cast-modal");
    const hostSelect = document.getElementById("generate-cast-host");
    const franchiseSelect = document.getElementById("generate-cast-franchise");
    const modeSelect = document.getElementById("generate-cast-mode");
    const layoutSelect = document.getElementById("generate-cast-layout");
    const sizeModeSelect = document.getElementById("generate-cast-size-mode");
    const sizeInput = document.getElementById("generate-cast-size");

    if (!modal || !hostSelect || !franchiseSelect || !modeSelect || !layoutSelect || !sizeModeSelect || !sizeInput) return;

    if (!hostSelect.dataset.initialized) {
        hostSelect.innerHTML = "";
        DRAG_RACE_FRANCHISE_CONFIG.forEach((franchise) => {
            const option = document.createElement("option");
            option.value = franchise.code;
            option.textContent = franchise.label;
            hostSelect.appendChild(option);
        });
        hostSelect.dataset.initialized = "true";
    }

    const activeHistoryFranchise = getCurrentSeasonHistoryFranchise();
    const historyFranchiseNames = getSeasonHistoryFranchiseNames(getSeasonHistoryFranchiseStore());
    const selectedHistoryFranchise = franchiseSelect.value;
    franchiseSelect.innerHTML = '<option value="__all__">All History Franchises</option>';
    historyFranchiseNames.forEach((franchiseName) => {
        const option = document.createElement("option");
        option.value = franchiseName;
        option.textContent = franchiseName;
        franchiseSelect.appendChild(option);
    });
    if (selectedHistoryFranchise && (selectedHistoryFranchise === "__all__" || historyFranchiseNames.includes(selectedHistoryFranchise))) {
        franchiseSelect.value = selectedHistoryFranchise;
    } else if (historyFranchiseNames.includes(activeHistoryFranchise)) {
        franchiseSelect.value = activeHistoryFranchise;
    } else {
        franchiseSelect.value = "__all__";
    }

    if (!modeSelect.dataset.bound) {
        modeSelect.addEventListener("change", updateGenerateCastUIVisibility);
        layoutSelect.addEventListener("change", updateGenerateCastUIVisibility);
        sizeModeSelect.addEventListener("change", updateGenerateCastUIVisibility);
        franchiseSelect.addEventListener("change", updateGenerateCastUIVisibility);
        const includeCustomsEl = document.getElementById("generate-include-customs");
        if (includeCustomsEl) {
            includeCustomsEl.addEventListener("change", updateGenerateCastUIVisibility);
        }
            if (hostSelect && !hostSelect.dataset.hostBound) {
                hostSelect.addEventListener('change', () => {
                    const includeCustomsEl2 = document.getElementById('generate-include-customs');
                    const includeCustoms2 = includeCustomsEl2 ? includeCustomsEl2.checked : true;
                    const hide = hostSelect.value === 'CUSTOM' && getGenerateCastLayoutPreset() === 'COUNTRY_VSTW';
                    let selectionCleared = false;
                    ['franchise-filter','franchise-exclude-filter'].forEach(id => {
                        const sel = document.getElementById(id);
                        if (!sel) return;
                        const opt = Array.from(sel.options || []).find(o => o.value === 'CUSTOM');
                        if (!opt) return;
                        opt.hidden = hide;
                        opt.disabled = hide;
                        if (hide && opt.selected) {
                            opt.selected = false;
                            selectionCleared = true;
                        }
                    });
                    // hide/show the generate-include-customs checkbox wrapper as well
                    const checkboxEl2 = document.getElementById('generate-include-customs');
                    if (checkboxEl2) {
                        const wrapper2 = checkboxEl2.closest('div');
                        if (wrapper2) wrapper2.style.display = hide ? 'none' : 'block';
                        else checkboxEl2.style.display = hide ? 'none' : 'inline-block';
                    }
                    if (selectionCleared) {
                        try { if (typeof refreshQueenCards === 'function') refreshQueenCards(); } catch (e) {}
                    }
                    updateGenerateCastUIVisibility();
                });
                hostSelect.dataset.hostBound = 'true';
            }
        document.addEventListener("keydown", closeGenerateCastModalOnEscape);
        modal.addEventListener("click", (event) => {
            if (event.target === modal) {
                closeGenerateCastModal();
            }
        });
        modeSelect.dataset.bound = "true";
    }

    if (!modal.dataset.previewBound) {
        modal.addEventListener("change", updateGenerateCastPreview);
        modal.addEventListener("input", (event) => {
            const target = event.target;
            if (!target) return;
            if (target.id === "generate-cast-size" || target.hasAttribute("data-dream-stat")) {
                updateGenerateCastPreview();
            }
        });
        modal.dataset.previewBound = "true";
    }

    if (!modal.dataset.submitBound) {
        modal.addEventListener("keydown", (event) => {
            if (event.key !== "Enter") return;
            const target = event.target;
            if (target && (target.tagName === "TEXTAREA" || target.classList.contains("generate-cast-close"))) {
                return;
            }
            event.preventDefault();
            applyGenerateCastFromUI();
        });
        modal.dataset.submitBound = "true";
    }

    initDreamCastStatControls();
    const presetSelect = document.getElementById("generate-cast-preset");
    if (presetSelect && !presetSelect.dataset.bound) {
        presetSelect.addEventListener("change", updateGenerateCastUIVisibility);
        presetSelect.dataset.bound = "true";
    }
    const asReturnersSelect = document.getElementById("generate-cast-as-returners");
    const asMaxSelect = document.getElementById("generate-cast-as-max");
    if (asReturnersSelect && !asReturnersSelect.dataset.bound) {
        asReturnersSelect.addEventListener("change", updateGenerateCastUIVisibility);
        asReturnersSelect.dataset.bound = "true";
    }
    if (asMaxSelect && !asMaxSelect.dataset.bound) {
        asMaxSelect.addEventListener("change", updateGenerateCastUIVisibility);
        asMaxSelect.dataset.bound = "true";
    }
    const excludeWinnersCheckboxInit = document.getElementById("generate-cast-exclude-winners");
    if (excludeWinnersCheckboxInit && !excludeWinnersCheckboxInit.dataset.bound) {
        excludeWinnersCheckboxInit.addEventListener("change", updateGenerateCastUIVisibility);
        excludeWinnersCheckboxInit.dataset.bound = "true";
    }
    updateGenerateCastUIVisibility();
    updateGenerateCastPreview();
    {
        const includeCustomsEl = document.getElementById('generate-include-customs');
        const includeCustoms = includeCustomsEl ? includeCustomsEl.checked : true;
        const hideInitial = hostSelect && hostSelect.value === 'CUSTOM' && getGenerateCastLayoutPreset() === 'COUNTRY_VSTW';
        let selectionClearedInit = false;
        ['franchise-filter','franchise-exclude-filter'].forEach(id => {
            const sel = document.getElementById(id);
            if (!sel) return;
            const opt = Array.from(sel.options || []).find(o => o.value === 'CUSTOM');
            if (!opt) return;
            opt.hidden = hideInitial;
            opt.disabled = hideInitial;
            if (hideInitial && opt.selected) {
                opt.selected = false;
                selectionClearedInit = true;
            }
        });
        const checkboxEl3 = document.getElementById('generate-include-customs');
        if (checkboxEl3) {
            const wrapper3 = checkboxEl3.closest('div');
            if (wrapper3) wrapper3.style.display = hideInitial ? 'none' : 'block';
            else checkboxEl3.style.display = hideInitial ? 'none' : 'inline-block';
        }
        try { if (selectionClearedInit && typeof refreshQueenCards === 'function') refreshQueenCards(); } catch (e) {}
    }
}

function resetGenerateCastForm() {
    const modeSelect = document.getElementById("generate-cast-mode");
    const layoutSelect = document.getElementById("generate-cast-layout");
    const sizeModeSelect = document.getElementById("generate-cast-size-mode");
    const sizeInput = document.getElementById("generate-cast-size");
    const hostSelect = document.getElementById("generate-cast-host");
    const franchiseSelect = document.getElementById("generate-cast-franchise");
    const presetSelect = document.getElementById("generate-cast-preset");
    const asReturnersSelect = document.getElementById("generate-cast-as-returners");
    const asMaxSelect = document.getElementById("generate-cast-as-max");
    const excludeWinners = document.getElementById("generate-cast-exclude-winners");
    const includeCustoms = document.getElementById("generate-include-customs");

    if (modeSelect) modeSelect.value = "RANDOM";
    if (layoutSelect) layoutSelect.value = "STANDARD";
    if (sizeModeSelect) sizeModeSelect.value = "random";
    if (sizeInput) sizeInput.value = "12";
    if (hostSelect && hostSelect.options.length > 0) hostSelect.selectedIndex = 0;
    if (franchiseSelect) franchiseSelect.value = "__all__";
    if (presetSelect) presetSelect.value = "random";
    if (asReturnersSelect) asReturnersSelect.value = "allow";
    if (asMaxSelect) asMaxSelect.value = "2";
    if (excludeWinners) excludeWinners.checked = true;
    if (includeCustoms) includeCustoms.checked = true;

    document.querySelectorAll("[data-dream-stat]").forEach((input) => {
        input.value = "10";
        updateDreamCastStatValue(input);
    });

    updateGenerateCastUIVisibility();
    updateGenerateCastPreview();
}

function updateGenerateCastPreview() {
    const preview = document.getElementById("generate-cast-preview");
    const modeSelect = document.getElementById("generate-cast-mode");
    const hostSelect = document.getElementById("generate-cast-host");
    const includeCustomsEl = document.getElementById("generate-include-customs");
    const sizeModeSelect = document.getElementById("generate-cast-size-mode");
    const sizeInput = document.getElementById("generate-cast-size");
    if (!preview || !modeSelect) return;

    let includeCustoms = includeCustomsEl ? includeCustomsEl.checked : true;
    const franchiseCode = getGenerateCastSelectedFranchiseCode();
    const mode = modeSelect.value;
    const layoutPreset = getGenerateCastLayoutPreset();
    if (layoutPreset === "COUNTRY_VSTW" && hostSelect && hostSelect.value === "CUSTOM") {
        includeCustoms = true;
    }
    const sizeMode = sizeModeSelect ? sizeModeSelect.value : "random";
    const requestedSize = sizeMode === "custom" ? Math.max(1, parseInt(sizeInput?.value || "1", 10) || 1) : null;
    const allStarsOptions = getAllStarsHistoryBuilderOptions();
    const sourcePool = getGenerateCastSourcePool(mode, { includeCustoms, franchiseCode, allStarsOptions });

    let eligibleCount = 0;
    let helperText = "";

    if (layoutPreset === "COUNTRY_VSTW") {
        const hostCode = hostSelect ? hostSelect.value : "";
        if (!hostCode) {
            preview.textContent = "Pick a host country to preview eligibility.";
            return;
        }
        const franchiseMap = getDragRaceFranchiseMap(includeCustoms, sourcePool);
        const hostPool = (franchiseMap[hostCode] || []).filter(Boolean);
        const guestsPool = removeDuplicateQueensByName(Object.entries(franchiseMap)
            .filter(([code]) => code !== hostCode)
            .flatMap(([, queens]) => queens || []));
        eligibleCount = hostPool.length + guestsPool.length;
        helperText = `eligible from ${sourcePool.length} source queens, shaped as VSTW with host ${hostCode}.`;
    } else if (layoutPreset === "GLOBAL") {
        const franchiseMap = getDragRaceFranchiseMap(includeCustoms, sourcePool);
        eligibleCount = getAvailableGlobalFranchises(franchiseMap).length;
        helperText = `max cast size from ${sourcePool.length} source queens because Global uses one queen per franchise.`;
    } else if (mode === "REGULAR_HISTORY") {
        eligibleCount = sourcePool.length;
        helperText = "eligible based on queens not in saved Season History.";
    } else if (mode === "ALL_STARS_HISTORY") {
        eligibleCount = sourcePool.length;
        helperText = "eligible from saved All Stars history rules.";
    } else {
        eligibleCount = sourcePool.length;
        helperText = "eligible from your current franchise filter pool.";
    }

    if (requestedSize !== null) {
        preview.textContent = `Eligible: ${eligibleCount}. Requested size: ${requestedSize}. ${helperText}`;
    } else {
        preview.textContent = `Eligible: ${eligibleCount}. ${helperText}`;
    }
}

function updateGenerateCastUIVisibility() {
    const modeSelect = document.getElementById("generate-cast-mode");
    const layoutWrap = document.getElementById("generate-cast-layout-wrap");
    const layoutSelect = document.getElementById("generate-cast-layout");
    const hostWrap = document.getElementById("generate-cast-host-wrap");
    const franchiseWrap = document.getElementById("generate-cast-franchise-wrap");
    const sizeWrap = document.getElementById("generate-cast-size-wrap");
    const dreamWrap = document.getElementById("generate-cast-dream-wrap");
    const presetWrap = document.getElementById("generate-cast-preset-wrap");
    const asReturnersWrap = document.getElementById("generate-cast-as-returners-wrap");
    const asMaxWrap = document.getElementById("generate-cast-as-max-wrap");
    const excludeWinnersWrap = document.getElementById("generate-cast-exclude-winners-wrap");
    const asReturnersSelect = document.getElementById("generate-cast-as-returners");
    const asMaxSelect = document.getElementById("generate-cast-as-max");
    const excludeWinnersCheckbox = document.getElementById("generate-cast-exclude-winners");
    const sizeModeSelect = document.getElementById("generate-cast-size-mode");
    const sizeInput = document.getElementById("generate-cast-size");
    const sizeNote = document.getElementById("generate-cast-size-note");

    if (!modeSelect || !layoutWrap || !layoutSelect || !hostWrap || !franchiseWrap || !sizeWrap || !dreamWrap || !sizeModeSelect || !sizeInput || !sizeNote || !presetWrap || !asReturnersWrap || !asMaxWrap || !asReturnersSelect || !asMaxSelect) return;

    const layoutPreset = getGenerateCastLayoutPreset();
    const isCountry = layoutPreset === "COUNTRY_VSTW";
    const isGlobalPreset = layoutPreset === "GLOBAL";
    const isDream = modeSelect.value === "DREAM";
    const isRegularHistory = modeSelect.value === "REGULAR_HISTORY";
    const isCustomSize = sizeModeSelect.value === "custom";
    const isAllStarsHistory = modeSelect.value === "ALL_STARS_HISTORY";
    const franchiseCode = getGenerateCastSelectedFranchiseCode();
    const allowAllStarsReturners = asReturnersSelect.value !== "exclude";
    const maxAllStarsParticipations = Number.isFinite(Number(asMaxSelect.value))
        ? Math.max(0, Math.floor(Number(asMaxSelect.value)))
        : Number.POSITIVE_INFINITY;

    const presetSelectEl = document.getElementById("generate-cast-preset");
    const currentPreset = presetSelectEl ? presetSelectEl.value : "random";
    const excludeWinners = isAllStarsHistory && excludeWinnersCheckbox ? excludeWinnersCheckbox.checked : false;
    let includeCustoms = document.getElementById("generate-include-customs")?.checked ?? true;
    if (isCountry && document.getElementById("generate-cast-host")?.value === "CUSTOM") {
        includeCustoms = true;
    }
    const allStarsOptions = getAllStarsHistoryBuilderOptions();
    const sourcePool = getGenerateCastSourcePool(modeSelect.value, { includeCustoms, franchiseCode, allStarsOptions });

    layoutWrap.classList.toggle("hide", false);
    hostWrap.classList.toggle("hide", !isCountry);
    franchiseWrap.classList.toggle("hide", !(isRegularHistory || isAllStarsHistory));
    dreamWrap.classList.toggle("hide", !isDream);
    sizeWrap.classList.toggle("hide", false);
    sizeInput.classList.toggle("hide", !isCustomSize);
    presetWrap.classList.toggle("hide", !isAllStarsHistory);
    asReturnersWrap.classList.toggle("hide", !isAllStarsHistory);
    asMaxWrap.classList.toggle("hide", !isAllStarsHistory || !allowAllStarsReturners);
    if (excludeWinnersWrap) excludeWinnersWrap.classList.toggle("hide", !isAllStarsHistory);

    if (isGlobalPreset) {
        const franchiseMap = getDragRaceFranchiseMap(includeCustoms, sourcePool);
        const availableCount = getAvailableGlobalFranchises(franchiseMap).length;
        sizeInput.max = String(availableCount);
        if (parseInt(sizeInput.value, 10) > availableCount) {
            sizeInput.value = String(availableCount);
        }
        sizeNote.textContent = `Global uses max 1 queen per franchise from the selected mode (max cast size: ${availableCount}).`;
    } else if (isCountry) {
        const franchiseMap = getDragRaceFranchiseMap(includeCustoms, sourcePool);
        const hostCode = document.getElementById("generate-cast-host")?.value || "";
        const hostPool = franchiseMap[hostCode] || [];
        const availableCount = removeDuplicateQueensByName(Object.values(franchiseMap).flat()).length;
        sizeInput.max = String(Math.max(1, availableCount));
        if (availableCount > 0 && parseInt(sizeInput.value, 10) > availableCount) {
            sizeInput.value = String(availableCount);
        }
        sizeNote.textContent = hostPool.length > 0
            ? `VSTW uses the selected mode pool with max 5 host queens (eligible queens: ${availableCount}).`
            : "VSTW needs at least one eligible queen from the host country.";
    } else if (isRegularHistory) {
        const availableCount = sourcePool.length;
        sizeInput.max = String(Math.max(1, availableCount));
        if (availableCount > 0 && parseInt(sizeInput.value, 10) > availableCount) {
            sizeInput.value = String(availableCount);
        }
        sizeNote.textContent = availableCount > 0
            ? `Regular uses queens that are not present in your saved Season History (eligible queens: ${availableCount}).`
            : "Regular uses queens not present in your saved Season History. Save fewer repeated queens or add more queens first.";
    } else if (isAllStarsHistory) {
        const presetSelect = document.getElementById("generate-cast-preset");
        const preset = presetSelect ? presetSelect.value : "random";
        const isBracketAllStarsPreset = normalizeHistoryMetaKey(preset) === "bracket-allstars";
        const availableCount = sourcePool.length;
        sizeInput.max = String(Math.max(1, availableCount));
        if (availableCount > 0 && parseInt(sizeInput.value, 10) > availableCount) {
            sizeInput.value = String(availableCount);
        }
        const returnerFilterLabel = !allowAllStarsReturners
            ? "first-timers only"
            : maxAllStarsParticipations < Number.POSITIVE_INFINITY
                ? `max ${maxAllStarsParticipations} All Stars participation${maxAllStarsParticipations === 1 ? "" : "s"}`
                : "all returners allowed";
        const winnersLabel = excludeWinners ? ", excluding winners" : "";
        if (isBracketAllStarsPreset) {
                sizeNote.textContent = availableCount > 0
                ? `Tournament of All Stars draws from saved tournament seasons (${returnerFilterLabel}${winnersLabel}; eligible queens: ${availableCount}, required: 18).`
                : "Tournament of All Stars needs saved tournament seasons in Season History.";  
        } else {
            sizeNote.textContent = availableCount > 0
                ? `All Stars uses your saved Season History (${excludeWinners ? "excluding winners, " : ""}${returnerFilterLabel}; eligible queens: ${availableCount}).`
                : "All Stars uses your saved Season History. Save a season first.";
        }
    } else if (isDream) {
        sizeInput.max = "50";
        sizeNote.textContent = "Dream Cast Builder scores queens against your stat sliders and picks the closest matches.";
    } else {
        sizeInput.max = "50";
        sizeNote.textContent = "Random picks a size in the mode's normal range.";
    }
}

if (typeof window.showInHouseAlert !== "function") {
    const nativeAlert = typeof window.alert === "function" ? window.alert.bind(window) : () => {};
    const nativeConfirm = typeof window.confirm === "function" ? window.confirm.bind(window) : () => false;
    const nativePrompt = typeof window.prompt === "function" ? window.prompt.bind(window) : () => null;

    function escapeInHouseDialogText(value) {
        return String(value ?? "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#39;");
    }

    function openInHouseDialog(options = {}) {
        const mode = options.mode || "alert";
        const title = options.title || (mode === "confirm" ? "Confirm" : mode === "prompt" ? "Enter a value" : "Notice");
        const message = String(options.message ?? "");
        const confirmText = options.confirmText || (mode === "prompt" ? "Save" : "OK");
        const cancelText = options.cancelText || "Cancel";
        const defaultValue = String(options.defaultValue ?? "");

        if (!document?.body) {
            if (mode === "confirm") return Promise.resolve(nativeConfirm(message));
            if (mode === "prompt") return Promise.resolve(nativePrompt(message, defaultValue));
            nativeAlert(message);
            return Promise.resolve(undefined);
        }

        return new Promise((resolve) => {
            const modal = document.createElement("div");
            modal.className = "history-save-modal active";
            modal.setAttribute("aria-hidden", "false");
            modal.innerHTML = `
                <div class="history-save-modal-card generate-cast-card" role="dialog" aria-modal="true" aria-label="${escapeInHouseDialogText(title)}">
                    <button type="button" class="generate-cast-close" aria-label="Close dialog">
                        <i class="fa-solid fa-xmark"></i>
                    </button>
                    <h3>${escapeInHouseDialogText(title)}</h3>
                    <p class="generate-cast-subtitle" style="white-space: pre-wrap;">${escapeInHouseDialogText(message)}</p>
                    ${mode === "prompt" ? `<input type="text" data-dialog-input maxlength="160" value="${escapeInHouseDialogText(defaultValue)}">` : ""}
                    <div class="generate-cast-actions">
                        ${mode !== "alert" ? `<button type="button" data-action="cancel">${escapeInHouseDialogText(cancelText)}</button>` : ""}
                        <button type="button" data-action="confirm">${escapeInHouseDialogText(confirmText)}</button>
                    </div>
                </div>
            `;

            const card = modal.querySelector(".history-save-modal-card");
            const closeBtn = modal.querySelector(".generate-cast-close");
            const cancelBtn = modal.querySelector('[data-action="cancel"]');
            const confirmBtn = modal.querySelector('[data-action="confirm"]');
            const input = modal.querySelector("[data-dialog-input]");

            const finish = (result) => {
                if (modal._closing) return;
                modal._closing = true;
                if (typeof deactivateCenteredPopup === "function") {
                    deactivateCenteredPopup(modal);
                }
                modal.remove();
                resolve(result);
            };

            if (card) {
                card.style.margin = "auto";
                card.style.alignSelf = "center";
            }

            if (typeof activateCenteredPopup === "function") {
                document.body.appendChild(modal);
                activateCenteredPopup(modal);
            } else {
                modal.style.display = "flex";
                modal.style.position = "fixed";
                modal.style.inset = "0";
                modal.style.zIndex = "2147483647";
                modal.style.pointerEvents = "auto";
                modal.style.justifyContent = "center";
                modal.style.alignItems = "center";
                document.body.appendChild(modal);
            }

            if (closeBtn) {
                closeBtn.addEventListener("click", () => finish(mode === "confirm" ? false : mode === "prompt" ? null : undefined));
            }
            if (cancelBtn) {
                cancelBtn.addEventListener("click", () => finish(mode === "prompt" ? null : false));
            }
            if (confirmBtn) {
                confirmBtn.addEventListener("click", () => finish(mode === "prompt" ? input?.value ?? "" : true));
            }

            modal.addEventListener("click", (event) => {
                if (event.target === modal) {
                    finish(mode === "confirm" ? false : mode === "prompt" ? null : undefined);
                }
            });

            modal.addEventListener("keydown", (event) => {
                if (event.key === "Escape") {
                    finish(mode === "confirm" ? false : mode === "prompt" ? null : undefined);
                } else if (event.key === "Enter") {
                    if (mode === "prompt") {
                        finish(input?.value ?? "");
                    } else {
                        finish(true);
                    }
                }
            });

            requestAnimationFrame(() => {
                if (input) {
                    input.focus();
                    input.select();
                } else if (confirmBtn) {
                    confirmBtn.focus();
                }
            });
        });
    }

    window.showInHouseAlert = function(message, title = "Notice") {
        return openInHouseDialog({ mode: "alert", title, message });
    };

    window.showInHouseConfirm = function(message, title = "Confirm") {
        return openInHouseDialog({ mode: "confirm", title, message, confirmText: "OK", cancelText: "Cancel" });
    };

    window.showInHousePrompt = function(message, defaultValue = "", title = "Enter a value") {
        return openInHouseDialog({ mode: "prompt", title, message, defaultValue, confirmText: "Save", cancelText: "Cancel" });
    };

    window.alert = function(message) {
        void window.showInHouseAlert(message);
    };
}

function centerOverlayBox(box) {
    if (!box) return;

    box.style.position = "absolute";
    box.style.left = "50%";
    box.style.top = "50%";
    box.style.transform = "translate(-50%, -50%)";
    box.style.pointerEvents = "auto";
    box.style.willChange = "auto";
}

function getCenteredPopupBox(modal) {
    if (!modal) return null;
    return modal.querySelector(".generate-cast-card, .history-save-modal-card, .ddlc-box, .account-card, .profile-card, .custom-image-crop-card") || modal.firstElementChild;
}

function ensurePopupRoot() {
    let popupRoot = document.getElementById("top-layer-popup-root");
    if (!popupRoot) {
        popupRoot = document.createElement("div");
        popupRoot.id = "top-layer-popup-root";
    }
    // Body accessibility filters make fixed descendants relative to the page.
    if (popupRoot.parentElement !== document.documentElement) {
        document.documentElement.appendChild(popupRoot);
    }
    const bodyStyle = window.getComputedStyle(document.body);
    popupRoot.style.fontFamily = bodyStyle.fontFamily;
    popupRoot.style.fontSize = bodyStyle.fontSize;
    popupRoot.style.lineHeight = bodyStyle.lineHeight;
    popupRoot.style.color = bodyStyle.color;

    popupRoot.style.position = "fixed";
    popupRoot.style.left = "0";
    popupRoot.style.top = "0";
    popupRoot.style.width = "100%";
    popupRoot.style.height = "100%";
    popupRoot.style.inset = "0";
    popupRoot.style.zIndex = "2147483646";
    popupRoot.style.pointerEvents = "none";
    popupRoot.style.isolation = "isolate";
    popupRoot.style.overflow = "visible";

    return popupRoot;
}

function syncOverlayBackdrop(modal) {
    if (!modal) return;

    modal.style.position = "fixed";
    modal.style.inset = "0";
    modal.style.left = "0";
    modal.style.top = "0";
    modal.style.width = "100%";
    modal.style.height = "100%";
    modal.style.pointerEvents = "auto";
    modal.style.overflow = "visible";
}

function movePopupToTopLayer(modal) {
    if (!modal) return;
    const popupRoot = ensurePopupRoot();
    if (modal.parentElement !== popupRoot) {
        popupRoot.appendChild(modal);
    }
    modal.style.zIndex = "2147483647";
    modal.style.isolation = "isolate";
}

function getPopupScrollableAncestor(target, boundary) {
    let node = target instanceof Element ? target : null;

    while (node) {
        const style = window.getComputedStyle(node);
        const overflowY = `${style.overflowY || ""} ${style.overflow || ""}`;
        const overflowX = `${style.overflowX || ""} ${style.overflow || ""}`;
        const canScrollY = /(auto|scroll|overlay)/i.test(overflowY) && node.scrollHeight > node.clientHeight + 1;
        const canScrollX = /(auto|scroll|overlay)/i.test(overflowX) && node.scrollWidth > node.clientWidth + 1;

        if (canScrollY || canScrollX) {
            return node;
        }

        if (node === boundary) {
            break;
        }
        node = node.parentElement;
    }

    return null;
}

function canPopupContainerScroll(node, deltaX, deltaY) {
    if (!node) return false;

    if (deltaY < 0 && node.scrollTop > 0) return true;
    if (deltaY > 0 && node.scrollTop + node.clientHeight < node.scrollHeight - 1) return true;
    if (deltaX < 0 && node.scrollLeft > 0) return true;
    if (deltaX > 0 && node.scrollLeft + node.clientWidth < node.scrollWidth - 1) return true;

    return false;
}

function enablePopupScrollPassthrough(modal) {
    if (!modal || modal._popupWheelHandler) return;

    const box = getCenteredPopupBox(modal);
    const forwardWheel = (event) => {
        if (event.target.closest("input, textarea, select")) return;

        const scrollableNode = getPopupScrollableAncestor(event.target, box);
        if (scrollableNode && canPopupContainerScroll(scrollableNode, event.deltaX, event.deltaY)) {
            return;
        }

        event.preventDefault();
        window.scrollBy({
            left: event.deltaX,
            top: event.deltaY,
            behavior: "auto"
        });
    };

    modal.addEventListener("wheel", forwardWheel, { passive: false });
    modal._popupWheelHandler = forwardWheel;
}

function disablePopupScrollPassthrough(modal) {
    if (!modal?._popupWheelHandler) return;
    modal.removeEventListener("wheel", modal._popupWheelHandler);
    modal._popupWheelHandler = null;
}

function hasVisibleCenteredPopup(exceptModal = null) {
    const activePopups = document.querySelectorAll('[data-centered-popup="1"].active[aria-hidden="false"]');
    for (const popup of activePopups) {
        if (popup !== exceptModal) {
            return true;
        }
    }
    return false;
}

function activateCenteredPopup(modal) {
    if (!modal) return;
    const box = getCenteredPopupBox(modal);

    modal.setAttribute("data-centered-popup", "1");
    movePopupToTopLayer(modal);
    document.documentElement.classList.add("popup-open");
    document.body.classList.add("popup-open");
    modal.classList.add("active");
    modal.setAttribute("aria-hidden", "false");
    modal.style.display = "block";
    modal.style.opacity = "0";
    modal.style.transition = "none";

    if (box) {
        box.style.zIndex = "2147483647";
        box.style.pointerEvents = "auto";
    }

    syncOverlayBackdrop(modal);
    centerOverlayBox(box);

    if (box) {
        box.style.opacity = "0";
        box.style.transition = "none";
    }

    enablePopupScrollPassthrough(modal);
    if (box && modal.getAttribute("role") !== "status") {
        window.DragUi.activateDialog(box, () => {
            const close = box.querySelector(".generate-cast-close, .account-close, .custom-image-crop-cancel, [data-dialog-close]");
            if (close) close.click();
            else deactivateCenteredPopup(modal);
        });
    }
    if (modal._popupRevealFrame != null) {
        cancelAnimationFrame(modal._popupRevealFrame);
    }
    modal._popupRevealFrame = requestAnimationFrame(() => {
        modal._popupRevealFrame = null;
        if (!modal.isConnected || !modal.classList.contains("active")) return;
        modal.style.transition = "opacity 0.14s ease-out";
        modal.style.opacity = "1";
        if (box) {
            box.style.transition = "none";
            box.style.opacity = "1";
        }
    });
}

function deactivateCenteredPopup(modal) {
    if (!modal) return;
    const box = getCenteredPopupBox(modal);

    if (box) window.DragUi.deactivateDialog(box);
    if (modal._popupRevealFrame != null) {
        cancelAnimationFrame(modal._popupRevealFrame);
        modal._popupRevealFrame = null;
    }
    disablePopupScrollPassthrough(modal);
    modal.classList.remove("active");
    modal.setAttribute("aria-hidden", "true");
    modal.style.removeProperty("position");
    modal.style.removeProperty("left");
    modal.style.removeProperty("top");
    modal.style.removeProperty("width");
    modal.style.removeProperty("height");
    modal.style.removeProperty("inset");
    modal.style.removeProperty("display");
    modal.style.removeProperty("z-index");
    modal.style.removeProperty("isolation");
    modal.style.removeProperty("pointer-events");
    modal.style.removeProperty("opacity");
    modal.style.removeProperty("transition");
    modal.style.removeProperty("overflow");
    if (!hasVisibleCenteredPopup()) {
        document.documentElement.classList.remove("popup-open");
        document.body.classList.remove("popup-open");
    }

    if (box) {
        box.style.removeProperty("z-index");
        box.style.removeProperty("pointer-events");
        box.style.removeProperty("position");
        box.style.removeProperty("left");
        box.style.removeProperty("top");
        box.style.removeProperty("opacity");
        box.style.removeProperty("transition");
        box.style.removeProperty("transform");
        box.style.removeProperty("will-change");
        delete box._smoothLeft;
        delete box._smoothTop;
    }
}

function showFloatingNotice(message, duration = 1600) {
    const notice = document.createElement("div");
    notice.className = "history-save-modal active";
    notice.setAttribute("aria-hidden", "false");
    notice.setAttribute("role", "status");
    notice.setAttribute("aria-live", "polite");
    notice.innerHTML = '<div class="history-save-modal-card generate-cast-card" style="width:min(90vw, 320px); text-align:center;"><p style="margin:0; font-weight:700;">' + message + '</p></div>';
    document.body.appendChild(notice);
    activateCenteredPopup(notice);
    window.setTimeout(() => {
        deactivateCenteredPopup(notice);
        notice.remove();
    }, duration);
}

function showCustomStatusPopup(message, title = "Notice", options = {}) {
    const text = String(message ?? "").trim();
    if (!text) return;

    const useModal = !!options.modal;
    const duration = typeof options.duration === "number" ? options.duration : 1800;

    if (!useModal && typeof showFloatingNotice === "function") {
        showFloatingNotice(text, duration);
        return;
    }
    if (typeof window.showInHouseAlert === "function") {
        void window.showInHouseAlert(text, title);
        return;
    }
    if (typeof showFloatingNotice === "function") {
        showFloatingNotice(text, duration);
        return;
    }
    if (typeof window.alert === "function") {
        window.alert(text);
    }
}

function openGenerateCastModal() {
    const modal = document.getElementById("generate-cast-modal");
    if (!modal) return;
    activateCenteredPopup(modal);
}

function closeGenerateCastModal() {
    const modal = document.getElementById("generate-cast-modal");
    if (!modal) return;
    deactivateCenteredPopup(modal);
}

function closeGenerateCastModalOnEscape(event) {
    if (event.key === "Escape") {
        closeGenerateCastModal();
        closeSaveSeasonHistoryModal();
        closeMoreActionsModal();
    }
}

function openMoreActionsModal() {
    const modal = document.getElementById("more-actions-modal");
    if (!modal) return;
    if (!modal.dataset.bound) {
        modal.addEventListener("click", (event) => {
            if (event.target === modal) {
                closeMoreActionsModal();
            }
        });
        modal.dataset.bound = "true";
    }
    document.addEventListener("keydown", closeMoreActionsModalOnEscape);
    activateCenteredPopup(modal);
}

function closeMoreActionsModal() {
    const modal = document.getElementById("more-actions-modal");
    if (!modal) return;
    deactivateCenteredPopup(modal);
    document.removeEventListener("keydown", closeMoreActionsModalOnEscape);
}

function closeMoreActionsModalOnEscape(event) {
    if (event.key === "Escape") {
        closeMoreActionsModal();
    }
}

const DRAG_RACE_WIKI_BASE_URL = "https://rupaulsdragrace.fandom.com/wiki/";

// The contestant search lives on its own page (contestants.html); every function below renders into that page's root.
function getContestantSearchModal() {
    return document.getElementById("contestant-search-page");
}

function getContestantSearchQueens() {
    const seen = new Set();
    return (Array.isArray(allQueens) ? allQueens : [])
        .filter((queen) => queen && queen.name && !queen.customqueen)
        .sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), undefined, { sensitivity: "base" }))
        .filter((queen) => {
            const key = String(queen.name || "").trim().toLowerCase();
            if (!key || seen.has(key)) return false;
            seen.add(key);
            return true;
        });
}

function getContestantWikiUrl(queenName) {
    const normalizedName = String(queenName || "").trim().replace(/\s+/g, " ");
    if (!normalizedName) return DRAG_RACE_WIKI_BASE_URL;
    return DRAG_RACE_WIKI_BASE_URL + encodeURIComponent(normalizedName).replace(/%20/g, "_");
}

function getContestantSearchImage(queen) {
    if (queen && typeof queen.getCurrentImage === "function") {
        return queen.getCurrentImage();
    }
    if (queen && Array.isArray(queen.image) && queen.image[0]) {
        return queen.image[0];
    }
    if (queen && queen.image) {
        return queen.image;
    }
    return "image/queens/noimage.jpg";
}

function getContestantStatsSummary(queen) {
    const acting = Number(queen?._actingStat || 0);
    const comedy = Number(queen?._comedyStat || 0);
    const dance = Number(queen?._danceStat || 0);
    const design = Number(queen?._designStat || 0);
    const improv = Number(queen?._improvStat || 0);
    const runway = Number(queen?._runwayStat || 0);
    const lipsync = Number(queen?._lipsyncStat || 0);
    const total = acting + comedy + dance + design + improv + runway + lipsync;
    return { acting, comedy, dance, design, improv, runway, lipsync, total };
}

function getContestantSearchRankMap(contestants) {
    const ranked = contestants
        .map((queen) => ({ queen, total: getContestantStatsSummary(queen).total }))
        .sort((a, b) => b.total - a.total || String(a.queen.name || "").localeCompare(String(b.queen.name || ""), undefined, { sensitivity: "base" }));
    const ranks = new Map();
    for (let index = 0; index < ranked.length;) {
        const tieStart = index;
        const tiedTotal = ranked[index].total;
        while (index < ranked.length && ranked[index].total === tiedTotal) {
            index += 1;
        }

        const tieEnd = index;
        const ordinal = (value) => {
            const suffix = value % 100 >= 11 && value % 100 <= 13
                ? "TH"
                : ({ 1: "ST", 2: "ND", 3: "RD" }[value % 10] || "TH");
            return value + suffix;
        };
        const rankLabel = tieEnd - tieStart > 1
            ? ordinal(tieStart + 1) + "-" + ordinal(tieEnd)
            : ordinal(tieStart + 1);

        for (let tiedIndex = tieStart; tiedIndex < tieEnd; tiedIndex += 1) {
            ranks.set(ranked[tiedIndex].queen, rankLabel);
        }
    }

    return ranks;
}

function renderContestantSearchResults() {
    const modal = getContestantSearchModal();
    if (!modal) return;

    const input = modal.querySelector("#contestant-search-input");
    const statFilter = modal.querySelector("#contestant-search-stat-filter");
    const minimum = modal.querySelector("#contestant-search-min");
    const maximum = modal.querySelector("#contestant-search-max");
    const sort = modal.querySelector("#contestant-search-sort");
    const results = modal.querySelector("#contestant-search-results");
    const summary = modal.querySelector("#contestant-search-summary");
    if (!results) return;

    const allContestants = getContestantSearchQueens();
    const searchTerm = String(input && input.value ? input.value : "").trim().toLowerCase();
    const statKey = statFilter?.value || "all";
    const minimumValue = minimum?.value === "" ? null : Number(minimum?.value);
    const maximumValue = maximum?.value === "" ? null : Number(maximum?.value);
    const rankMap = getContestantSearchRankMap(allContestants);
    const queens = allContestants.filter((queen) => {
        if (searchTerm && !String(queen.name || "").toLowerCase().includes(searchTerm)) return false;
        if (statKey === "all" && minimumValue === null && maximumValue === null) return true;
        const stats = getContestantStatsSummary(queen);
        const value = stats[statKey === "all" ? "total" : statKey];
        return (minimumValue === null || value >= minimumValue) && (maximumValue === null || value <= maximumValue);
    }).sort((a, b) => {
        const sortKey = sort?.value || "name-asc";
        if (sortKey === "name-desc") return String(b.name || "").localeCompare(String(a.name || ""), undefined, { sensitivity: "base" });
        if (sortKey === "name-asc") return String(a.name || "").localeCompare(String(b.name || ""), undefined, { sensitivity: "base" });
        if (sortKey === "total-desc") return getContestantStatsSummary(b).total - getContestantStatsSummary(a).total || String(a.name || "").localeCompare(String(b.name || ""));
        if (sortKey === "total-asc") return getContestantStatsSummary(a).total - getContestantStatsSummary(b).total || String(a.name || "").localeCompare(String(b.name || ""));
        if (sortKey.endsWith("-desc")) return getContestantStatsSummary(b)[sortKey.slice(0, -5)] - getContestantStatsSummary(a)[sortKey.slice(0, -5)] || String(a.name || "").localeCompare(String(b.name || ""));
        if (sortKey.endsWith("-asc")) return getContestantStatsSummary(a)[sortKey.slice(0, -4)] - getContestantStatsSummary(b)[sortKey.slice(0, -4)] || String(a.name || "").localeCompare(String(b.name || ""));
        return String(a.name || "").localeCompare(String(b.name || ""), undefined, { sensitivity: "base" });
    });

    if (summary) {
        summary.textContent = searchTerm
            ? queens.length + " contestant" + (queens.length === 1 ? "" : "s") + " found"
            : allContestants.length + " contestants available";
    }

    if (queens.length === 0) {
        results.innerHTML = '<p class="contestant-search-empty">No contestants matched that search.</p>';
        return;
    }

    results.innerHTML = queens.map((queen) => {
        const name = String(queen.name || "").replace(/"/g, "&quot;");
        const image = String(getContestantSearchImage(queen) || "").replace(/"/g, "&quot;");
        const wikiUrl = getContestantWikiUrl(queen.name).replace(/"/g, "&quot;");
        const stats = getContestantStatsSummary(queen);
        const rank = rankMap.get(queen) || "-";
        const statRows = [
            [["Acting", stats.acting], ["Comedy", stats.comedy], ["Dance", stats.dance], ["Design", stats.design]],
            [["Improv", stats.improv], ["Runway", stats.runway], ["Lipsync", stats.lipsync], ["Total", stats.total]],
        ];
        const statsHtml = statRows.map((row, rowIndex) => {
            const rowHtml = row.map(([label, value]) => {
                const pairClass = label === "Total"
                    ? "contestant-stat-pair contestant-stat-pair-total"
                    : "contestant-stat-pair";
                return '<span class="' + pairClass + '"><span class="contestant-stat-label">' + label + '</span><strong>' + value + '</strong></span>';
            }).join("");
            const rowClass = rowIndex === 0
                ? "contestant-search-stats-row"
                : "contestant-search-stats-row contestant-search-stats-row-secondary";
            return '<div class="' + rowClass + '">' + rowHtml + '</div>';
        }).join("");
        return ''
            + '<article class="contestant-search-row">'
            + '<img class="contestant-search-avatar" src="' + image + '" alt="' + name + '">'
            + '<div class="contestant-search-copy">'
            + '<h4><span class="contestant-search-rank">#' + rank + '</span>' + name + '</h4>'
            + '<div class="contestant-search-stats">'
            + statsHtml
            + '</div>'
            + '</div>'
            + '<div class="contestant-search-actions">'
            + '<a class="contestant-search-wiki" href="' + wikiUrl + '" target="_blank" rel="noopener noreferrer">Visit Wiki</a>'
            + '</div>'
            + '</article>';
    }).join("");
}

