function moneyChart() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Money Tracker");
    setBackgroundToNormal();
    let main = document.querySelector("div#MainBlock");

    const allContestants = [...currentCast, ...eliminatedCast].filter((q, idx, arr) => q && arr.findIndex(item => item.name === q.name) === idx);

    if (allContestants.length === 0) {
        screen.createBold("No contestants found.");
    } else {
        const parseMoney = (val) => {
            if (typeof val === "number") return val;
            const parsed = Number(String(val || 0).replace(/[^0-9.-]+/g, ""));
            return Number.isFinite(parsed) ? parsed : 0;
        };

        const sorted = [...allContestants].sort((a, b) => {
            const diff = parseMoney(b.money) - parseMoney(a.money);
            if (diff !== 0) return diff;
            return a.name.localeCompare(b.name);
        });

        const topAmount = parseMoney(sorted[0]?.money);

        const centering = document.createElement("center");
        centering.style.maxWidth = "100%";
        centering.style.overflowX = "auto";
        const table = document.createElement("table");
        table.setAttribute("id", "trackRecord");
        table.setAttribute("class", "trtable money-tracker-table");
        table.setAttribute("border", "2");

        const header = document.createElement("tr");
        header.innerHTML = `
            <th class="nameTR" style="text-align: left; padding-left: 0.85rem;">Contestant</th>
            <th class="nameTR" style="width: 140px; text-align: right; padding-right: 1rem;">Prize Money</th>
            <th class="nameTR">Non-cash Rewards</th>
        `;
        table.appendChild(header);

        sorted.forEach((queen) => {
            const tr = document.createElement("tr");
            const rawMoney = queen.money ?? 0;
            const numericMoney = parseMoney(rawMoney);
            const isTop = topAmount > 0 && numericMoney === topAmount;
            const hasMoney = numericMoney > 0;

            const tdName = document.createElement("td");
            tdName.className = "money-queen-cell";
            const imgUrl = queen.getCurrentImage ? queen.getCurrentImage() : (queen.image || "");
            tdName.innerHTML = `
                <div class="money-queen-wrap">
                    <img src="${imgUrl}" alt="${queen.name}">
                    <span class="money-queen-name">${queen.name}</span>
                </div>
            `;
            tr.appendChild(tdName);

            // Money Amount
            const tdMoney = document.createElement("td");
            tdMoney.className = "money-amount-cell" + (isTop ? " top-earner" : (hasMoney ? " has-money" : ""));
            if (typeof rawMoney === "string" && isNaN(Number(rawMoney.replace(/[^0-9.-]+/g, "")))) {
                tdMoney.innerHTML = rawMoney;
            } else {
                tdMoney.textContent = formatPrizeMoney(numericMoney, queen.prizeCurrency || "USD");
            }
            tr.appendChild(tdMoney);

            const tdRewards = document.createElement("td");
            tdRewards.style.overflowWrap = "anywhere";
            tdRewards.style.maxWidth = "300px";
            const rewards = (queen.prizeAwards || []).filter(award => award.reward);
            tdRewards.textContent = rewards.length > 0
                ? rewards.map(award => `${award.reward} (Ep. ${award.episode})`).join("; ")
                : "-";
            tr.appendChild(tdRewards);

            table.appendChild(tr);
        });

        centering.appendChild(table);
        if (main) {
            main.appendChild(centering);
        }
    }

    addStatsTabs(screen, "Money Tracker");
    addStatsFooter(screen);
}

