let fanReactionWeekViewIndex = -1;
function weeklyFanReactionsScreen(weekIndex) {
    const contestants = [...currentCast, ...eliminatedCast];
    const totalWeeks = contestants.reduce((max, q) => Math.max(max, Array.isArray(q.trackRecord) ? q.trackRecord.length : 0), 0);

    if (!Number.isInteger(weekIndex)) {
        weekIndex = fanReactionWeekViewIndex >= 0 ? fanReactionWeekViewIndex : totalWeeks - 1;
    }
    weekIndex = Math.max(0, Math.min(weekIndex, Math.max(0, totalWeeks - 1)));
    fanReactionWeekViewIndex = weekIndex;

    let screen = new Scene();
    screen.clean();
    screen.createHeader("Fan Reactions");
    setBackgroundToNormal();

    if (totalWeeks === 0) {
        screen.createBold("No episodes have aired yet, so there's nothing to react to.");
    } else {
        const { challengeLabel, threads } = getWeeklyFanReactions(weekIndex);
        const main = document.querySelector("div#MainBlock");

        const banner = document.createElement("div");
        banner.className = "fan-reaction-episode-banner";
        banner.innerHTML = `<b>Episode ${weekIndex + 1}: ${challengeLabel}</b>`;
        main.appendChild(banner);

        for (const thread of threads) {
            const card = document.createElement("div");
            card.className = "fan-reaction-thread";

            if (thread.queens.length > 0) {
                const imagesWrap = document.createElement("div");
                imagesWrap.className = "fan-reaction-thread-images";
                for (const queen of thread.queens) {
                    const img = document.createElement("img");
                    img.src = queen.getCurrentImage();
                    img.alt = queen.name;
                    imagesWrap.appendChild(img);
                }
                card.appendChild(imagesWrap);
            }

            for (const line of thread.lines) {
                const p = document.createElement("p");
                p.innerHTML = line;
                card.appendChild(p);
            }

            main.appendChild(card);
        }
    }

    if (totalWeeks > 1) {
        const navContainer = document.createElement("div");
        navContainer.className = "fan-reaction-nav";

        const prevBtn = document.createElement("button");
        prevBtn.innerHTML = '<i class="fa-solid fa-chevron-left"></i>';
        prevBtn.setAttribute("title", "Previous Week");
        prevBtn.setAttribute("aria-label", "Previous Week");
        if (weekIndex > 0) {
            prevBtn.setAttribute("onclick", `weeklyFanReactionsScreen(${weekIndex - 1})`);
        } else {
            prevBtn.disabled = true;
        }
        navContainer.appendChild(prevBtn);

        const nextBtn = document.createElement("button");
        nextBtn.innerHTML = '<i class="fa-solid fa-chevron-right"></i>';
        nextBtn.setAttribute("title", "Next Week");
        nextBtn.setAttribute("aria-label", "Next Week");
        if (weekIndex < totalWeeks - 1) {
            nextBtn.setAttribute("onclick", `weeklyFanReactionsScreen(${weekIndex + 1})`);
        } else {
            nextBtn.disabled = true;
        }
        navContainer.appendChild(nextBtn);

        const main = document.querySelector("div#MainBlock");
        if (main) {
            main.appendChild(navContainer);
        }
    }

    addStatsTabs(screen, "Fan Reactions");
    addStatsFooter(screen);
}

let userEpisodeRatings = {};
let selectedRatingsEpisodeIndex = 0;

function getImdbRatingTextColor(score) {
    if (score >= 8.0) return "#2e7d32";
    if (score >= 7.0) return "#558b2f";
    if (score >= 6.0) return "#c47d00";
    if (score >= 5.0) return "#d84315";
    return "#c62828";
}

function computeEpisodeViewership(epIndex, totalEpisodes, challengeLabel, rating) {
    let base = 0.810;
    const cat = getChallengeFlavorCategory(challengeLabel);
    if (epIndex === 0) base += 0.095;
    if (epIndex === totalEpisodes - 1) base += 0.075;
    if (/snatch/i.test(challengeLabel)) base += 0.090;
    else if (/ball|make ?over/i.test(challengeLabel)) base += 0.055;
    else if (cat === "performance") base += 0.040;

    if (rating >= 8.0) base += 0.045;
    else if (rating <= 5.5) base -= 0.035;

    const hash = Math.sin((epIndex + 1) * 9301 + 49297) * 233280;
    const rng = (hash - Math.floor(hash)) * 0.08 - 0.04;
    const finalViewers = Math.max(0.550, Math.min(1.350, base + rng));
    return Number(finalViewers.toFixed(3));
}

function computeEpisodeRatingData(epIndex, totalEpisodes) {
    const contestants = [...currentCast, ...eliminatedCast];
    const rawChallenge = episodeChallenges[epIndex] || `Episode ${epIndex + 1}`;
    const challengeLabel = String(rawChallenge).replace(/<nl>/g, " / ");
    const activeThisWeek = contestants.filter(q => q && Array.isArray(q.trackRecord) && q.trackRecord.length > epIndex);

    const getTag = (q) => String(q.trackRecord[epIndex] || "");
    const winners = activeThisWeek.filter(q => /WIN/.test(getTag(q)));
    const tops = activeThisWeek.filter(q => /HIGH|TOP/.test(getTag(q)));
    const bottoms = activeThisWeek.filter(q => /BTM/.test(getTag(q)));
    const eliminated = activeThisWeek.filter(q => /ELIM|DISQ|DEPT|QUIT|MOLE/.test(getTag(q)));
    const saved = activeThisWeek.filter(q => /SAVED|CHOC/.test(getTag(q)));

    let score = 7.6;

    // Challenge type weight
    const cat = getChallengeFlavorCategory(challengeLabel);
    if (cat === "comedy") score += 0.4;
    else if (cat === "performance") score += 0.3;
    else if (cat === "design") score += 0.2;
    if (/finale|rumix/i.test(challengeLabel)) score += 0.4;

    // Lipsync performance impact from recorded blots
    const blot = blots.find(b => resolveEpisodeNumber(b.episode) === (epIndex + 1));
    if (blot) {
        if (blot.score >= 8) score += 0.9;
        else if (blot.score >= 6) score += 0.4;
        else if (blot.score <= 3) score -= 0.8;
    }

    // Winner satisfaction
    if (winners.length >= 2) {
        score += 0.3;
    } else if (winners.length === 1) {
        const momentum = getQueenMomentumScore(winners[0], epIndex + 1);
        if (momentum >= 2) score += 0.4;
        else if (momentum < 0) score -= 0.2;
    }

    // Elimination fairness & drama
    for (const elim of eliminated) {
        const momentum = getQueenMomentumScore(elim, epIndex + 1);
        if (momentum >= 2) score -= 0.9;
        else if (momentum >= 0) score += 0.1;
        else score += 0.3;
    }
    if (eliminated.length >= 2) score -= 0.4;
    if (saved.length > 0) score += 0.3;

    // Deterministic subtle variance
    const seed = ((epIndex * 37 + challengeLabel.length * 13) % 9 - 4) * 0.08;
    score = Math.max(4.5, Math.min(9.8, score + seed));
    const finalRating = Number(score.toFixed(1));
    const viewers = computeEpisodeViewership(epIndex, totalEpisodes, challengeLabel, finalRating);

    // Pick Winner (or top queen if no explicit win)
    let winner = null;
    if (winners.length > 0) {
        winner = winners[0];
    } else if (tops.length > 0) {
        winner = tops[0];
    } else if (activeThisWeek.length > 0) {
        winner = activeThisWeek[0];
    }

    // Dynamic IMDb episode synopsis
    let synopsis;
    if (epIndex === 0) {
        synopsis = `The season kicks off in grand fashion as the queens arrive to face ${challengeLabel}. ${winner ? winner.name + ' makes a strong opening statement to snatch the first challenge win of the season.' : ''} ${eliminated.length > 0 ? eliminated.map(e => e.name).join(' and ') + ' faces a heartbreaking premiere exit.' : ''}`;
    } else if (epIndex === totalEpisodes - 1 || /finale/i.test(challengeLabel)) {
        synopsis = `The finalists battle it out in ${challengeLabel} for the coveted crown, delivering showstopping performances and exquisite final runways before the reigning superstar is chosen.`;
    } else if (/snatch/i.test(challengeLabel)) {
        synopsis = `It's time for the ultimate test of celebrity impersonation in Snatch Game! ${winner ? winner.name + ' steals the show with quick wit and comedy,' : ''} while the bottom queens fight for survival in a dramatic lip sync.`;
    } else if (cat === "design") {
        synopsis = `The werkroom transforms into a fashion atelier as the queens create original couture for ${challengeLabel}. ${winner ? winner.name + ' wows the judges with structural mastery on the main stage.' : ''}`;
    } else if (cat === "performance") {
        synopsis = `High-energy choreography and vocals take center stage in ${challengeLabel}. ${winner ? winner.name + ' stands out with impeccable stage presence and star power.' : ''}`;
    } else {
        synopsis = `The competition heats up as the contestants tackle ${challengeLabel}. ${winner ? winner.name + ' delivers the standout performance of the night,' : ''} while high stakes lead into an unforgettable lip sync showdown.`;
    }

    const voteCount = Math.round(280 + ((epIndex * 97 + 131) % 400) + (finalRating * 45));

    return {
        episodeNumber: epIndex + 1,
        challengeLabel,
        rating: finalRating,
        voteCount,
        viewers,
        winner,
        synopsis,
        winners,
        bottoms,
        eliminated,
        saved
    };
}

function renderImdbEpisodeSpotlight(ep, episodeData) {
    const spotlightWrap = document.getElementById("imdbEpisodeSpotlight");
    if (!spotlightWrap || !ep) return;

    spotlightWrap.innerHTML = "";

    const card = document.createElement("div");
    card.className = "imdb-spotlight-card";

    const imgDiv = document.createElement("div");
    imgDiv.className = "imdb-spotlight-thumb-wrap";
    const thumbImg = document.createElement("img");
    const queenImg = ep.winner && ep.winner.getCurrentImage ? ep.winner.getCurrentImage() : (ep.winner ? ep.winner.image : "");
    thumbImg.src = queenImg || "data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==";
    thumbImg.alt = ep.challengeLabel;
    thumbImg.className = "imdb-spotlight-thumb";
    imgDiv.appendChild(thumbImg);

    if (ep.winner) {
        const winnerTag = document.createElement("div");
        winnerTag.className = "imdb-spotlight-badge";
        const winnerLabel = ep.winners && ep.winners.length > 1 ? `Winners: ${ep.winners.map(w => w.name).join(", ")}` : `Winner: ${ep.winner.name}`;
        winnerTag.innerHTML = winnerLabel;
        imgDiv.appendChild(winnerTag);
    }
    card.appendChild(imgDiv);

    const details = document.createElement("div");
    details.className = "imdb-spotlight-details";

    const epKicker = document.createElement("div");
    epKicker.className = "imdb-spotlight-kicker";
    epKicker.innerHTML = `Episode ${ep.episodeNumber} · ${ep.viewers.toFixed(3)}M viewers`;
    details.appendChild(epKicker);

    const epTitle = document.createElement("h3");
    epTitle.className = "imdb-spotlight-title";
    epTitle.innerHTML = `${ep.challengeLabel} <i class="fa-solid fa-chevron-right" style="font-size:0.8rem;opacity:0.6;"></i>`;
    details.appendChild(epTitle);

    const epRatingRow = document.createElement("div");
    epRatingRow.className = "imdb-spotlight-rating-row";
    epRatingRow.innerHTML = `
        <span class="imdb-spotlight-star"><i class="fa-solid fa-star"></i></span>
        <span class="imdb-spotlight-score">${ep.rating.toFixed(1)}</span>
        <span class="imdb-spotlight-votes">(${ep.voteCount} fan ratings)</span>
    `;
    details.appendChild(epRatingRow);

    const epSynopsis = document.createElement("p");
    epSynopsis.className = "imdb-spotlight-synopsis";
    epSynopsis.innerHTML = ep.synopsis;
    details.appendChild(epSynopsis);

    // Queen outcomes row
    const outcomesRow = document.createElement("div");
    outcomesRow.className = "imdb-spotlight-outcomes";
    if (ep.winners.length > 0) {
        outcomesRow.innerHTML += `<span class="imdb-outcome-tag win"><b>WIN:</b> ${ep.winners.map(w => w.name).join(", ")}</span>`;
    }
    if (ep.eliminated.length > 0) {
        outcomesRow.innerHTML += `<span class="imdb-outcome-tag elim"><b>ELIM:</b> ${ep.eliminated.map(e => e.name).join(", ")}</span>`;
    } else if (ep.saved.length > 0) {
        outcomesRow.innerHTML += `<span class="imdb-outcome-tag save"><b>SAVED:</b> ${ep.saved.map(s => s.name).join(", ")}</span>`;
    }
    if (outcomesRow.children.length > 0) {
        details.appendChild(outcomesRow);
    }

    // User Interactive Rating Row (10 stars)
    const ratingWidget = document.createElement("div");
    ratingWidget.className = "imdb-spotlight-user-rating";
    const currentRating = userEpisodeRatings[ep.episodeNumber] || 0;
    
    let starsHtml = "";
    for (let s = 1; s <= 10; s++) {
        const isFilled = s <= currentRating;
        starsHtml += `<span class="imdb-user-star ${isFilled ? 'filled' : ''}" data-score="${s}"><i class="fa-${isFilled ? 'solid' : 'regular'} fa-star"></i></span>`;
    }

    ratingWidget.innerHTML = `
        <span class="imdb-user-rating-label">Your rating:</span>
        <div class="imdb-user-stars-wrap">${starsHtml}</div>
        <span class="imdb-user-rating-value">${currentRating > 0 ? `${currentRating} / 10` : 'Rate'}</span>
    `;

    ratingWidget.querySelectorAll(".imdb-user-star").forEach(starEl => {
        starEl.addEventListener("click", () => {
            const score = Number(starEl.getAttribute("data-score"));
            userEpisodeRatings[ep.episodeNumber] = score;
            renderImdbEpisodeSpotlight(ep, episodeData);
        });
    });

    details.appendChild(ratingWidget);
    card.appendChild(details);
    spotlightWrap.appendChild(card);
}

function episodeRatingsChart() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Episodes & Ratings");
    setBackgroundToNormal();

    let main = document.querySelector("div#MainBlock");
    const contestants = [...currentCast, ...eliminatedCast];
    const totalEpisodes = contestants.reduce((max, q) => Math.max(max, Array.isArray(q.trackRecord) ? q.trackRecord.length : 0), 0);

    if (totalEpisodes === 0) {
        screen.createBold("No episodes have aired yet, so there are no episode ratings.");
    } else {
        const episodeData = [];
        for (let ep = 0; ep < totalEpisodes; ep++) {
            episodeData.push(computeEpisodeRatingData(ep, totalEpisodes));
        }

        const avgScore = Number((episodeData.reduce((sum, ep) => sum + ep.rating, 0) / episodeData.length).toFixed(1));
        const totalVotes = episodeData.reduce((sum, ep) => sum + ep.voteCount, 0);

        if (selectedRatingsEpisodeIndex >= totalEpisodes) {
            selectedRatingsEpisodeIndex = 0;
        }

        // IMDb-Style Season Header Banner
        const headerDiv = document.createElement("div");
        headerDiv.className = "imdb-guide-header";
        headerDiv.innerHTML = `
            <div class="imdb-guide-title-row">
                <h2>Episodes <i class="fa-solid fa-chevron-right" style="font-size:1.1rem;opacity:0.7;"></i></h2>
                <div class="imdb-guide-season-pill">Season 1</div>
            </div>
            <div class="imdb-guide-sub">
                <span><b>${totalEpisodes} Episodes</b></span> · 
                <span style="color:#e67e22;font-weight:700;"><i class="fa-solid fa-star"></i> ${avgScore.toFixed(1)} Average</span> · 
                <span>from ${totalVotes.toLocaleString()} fan ratings</span>
            </div>
        `;
        main.appendChild(headerDiv);

        // IMDb-Style Episode Histogram / Bar Chart
        const barChartContainer = document.createElement("div");
        barChartContainer.className = "imdb-histogram-container";

        // Calculate heights dynamically: 0 to 10 scale, max height = 110px, min base = 18px
        const minRating = 4.0;
        const maxRating = 10.0;
        const calcBarHeight = (r) => Math.max(22, Math.min(108, Math.round(((r - minRating) / (maxRating - minRating)) * 82 + 22)));

        const avgBarHeight = calcBarHeight(avgScore);

        // Average dotted/dashed horizontal reference line across the chart
        const avgLine = document.createElement("div");
        avgLine.className = "imdb-histogram-avg-line";
        avgLine.style.bottom = `${avgBarHeight + 30}px`;
        avgLine.setAttribute("title", `Season Average: ${avgScore.toFixed(1)}`);
        barChartContainer.appendChild(avgLine);

        episodeData.forEach((ep, idx) => {
            const isSelected = idx === selectedRatingsEpisodeIndex;
            const barItem = document.createElement("div");
            barItem.className = `imdb-histogram-item ${isSelected ? 'active' : ''}`;
            barItem.setAttribute("data-ep-idx", String(idx));

            const barHeight = calcBarHeight(ep.rating);

            barItem.innerHTML = `
                <div class="imdb-histogram-bar-wrap">
                    <div class="imdb-histogram-bar ${isSelected ? 'active' : ''}" style="height: ${barHeight}px;">
                        <span class="imdb-histogram-bar-score">${ep.rating.toFixed(1)}</span>
                    </div>
                </div>
                <span class="imdb-histogram-ep-label">E${ep.episodeNumber}</span>
            `;

            barItem.addEventListener("click", () => {
                selectedRatingsEpisodeIndex = idx;
                barChartContainer.querySelectorAll(".imdb-histogram-item").forEach(item => item.classList.remove("active"));
                barChartContainer.querySelectorAll(".imdb-histogram-bar").forEach(bar => bar.classList.remove("active"));
                barItem.classList.add("active");
                barItem.querySelector(".imdb-histogram-bar").classList.add("active");
                renderImdbEpisodeSpotlight(episodeData[idx], episodeData);
            });

            barChartContainer.appendChild(barItem);
        });

        main.appendChild(barChartContainer);

        // Featured Episode Spotlight Card Slot
        const spotlightContainer = document.createElement("div");
        spotlightContainer.id = "imdbEpisodeSpotlight";
        main.appendChild(spotlightContainer);

        // Initial render of currently selected episode
        renderImdbEpisodeSpotlight(episodeData[selectedRatingsEpisodeIndex], episodeData);
    }

    addStatsTabs(screen, "Episode Ratings");
    addStatsFooter(screen);
}

function pointsTrackRecord() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("MVQ Points Track Record");
    setBackgroundToNormal();

    let main = document.querySelector("div#MainBlock");
    const contestants = [...currentCast, ...eliminatedCast];
    const maxHistoryLength = contestants.reduce((maxLen, q) => {
        const wonLen = Array.isArray(q.mvqWonHistory) ? q.mvqWonHistory.length : 0;
        const giftedLen = Array.isArray(q.mvqGiftedHistory) ? q.mvqGiftedHistory.length : 0;
        return Math.max(maxLen, wonLen, giftedLen);
    }, 0);
    const totalEpisodes = Math.max(1, Math.max(episodeChallenges.length, maxHistoryLength));

    const explicitBracketCount = contestants.reduce((maxValue, q) => {
        const groups = getQueenBracketGroups(q);
        const queenMax = groups.reduce((groupMax, groupNumber) => Math.max(groupMax, groupNumber), 0);
        return Math.max(maxValue, queenMax);
    }, 0);
    const bracketCount = Math.max(1, explicitBracketCount || (typeof getBracketCount === "function" ? getBracketCount() : 1));
    const configuredEpisodesPerBracket = Math.floor(Number(bracketEpisodesPerBracket));
    const episodesPerBracket = configuredEpisodesPerBracket > 0
        ? configuredEpisodesPerBracket
        : Math.max(1, Math.ceil(totalEpisodes / bracketCount));

    const formatPoints = (value) => {
        const numericValue = Number(value || 0);
        if (!Number.isFinite(numericValue)) return "0";
        return Number.isInteger(numericValue)
            ? String(numericValue)
            : numericValue.toFixed(1).replace(/\.0$/, "");
    };

    const getCellStyle = (won, gifted, type) => {
        const tiePts = typeof BRACKET_TIE_SPLIT_PTS === "number" ? BRACKET_TIE_SPLIT_PTS : 2.5;
        const winPts = typeof BRACKET_WIN_PTS === "number" ? BRACKET_WIN_PTS : 3;
        const top2Pts = typeof BRACKET_TOP2_PTS === "number" ? BRACKET_TOP2_PTS : 2;
        const epsilon = 0.001;

        if (type === "earned") {
            if (won > 0 && Math.abs(won - tiePts) <= epsilon) {
                return { background: "#0d0ca8", color: "#ffffff" };
            }
            if (won >= (winPts - epsilon)) {
                return { background: "royalblue", color: "#ffffff" };
            }
            if (won >= (top2Pts - epsilon)) {
                return { background: "deepskyblue", color: "#000000" };
            }
        }

        if (type === "gifted" && gifted > 0) {
            return { background: "#b8dbe8", color: "#000000" };
        }

        return { background: "var(--ss-cell)", color: "var(--text)" };
    };

    const board = document.createElement("div");
    board.style.maxWidth = "1320px";
    board.style.width = "100%";
    board.style.margin = "10px auto 0";
    board.style.padding = "0 10px";
    board.style.boxSizing = "border-box";
    board.style.overflowX = "auto";

    const sectionsWrap = document.createElement("div");
    sectionsWrap.style.display = "flex";
    sectionsWrap.style.flexDirection = "column";
    sectionsWrap.style.alignItems = "center";
    sectionsWrap.style.gap = "12px";
    sectionsWrap.style.marginTop = "8px";
    sectionsWrap.style.width = "100%";

    for (let bracketIndex = 0; bracketIndex < bracketCount; bracketIndex++) {
        const groupNumber = bracketIndex + 1;
        const groupContestants = contestants.filter((q) => {
            const contestantGroups = getQueenBracketGroups(q);
            if (contestantGroups.length > 0) {
                return contestantGroups.includes(groupNumber);
            }
            return bracketCount === 1;
        });

        if (groupContestants.length === 0) {
            continue;
        }

        const startEpisode = bracketIndex * episodesPerBracket;
        const endEpisode = Math.min(totalEpisodes, startEpisode + episodesPerBracket);
        const episodeIndexes = [];
        for (let ep = startEpisode; ep < endEpisode; ep++) {
            episodeIndexes.push(ep);
        }

        const rankedContestants = [...groupContestants].sort((a, b) => {
            const totalA = episodeIndexes.reduce((sum, ep) => {
                const won = Array.isArray(a.mvqWonHistory) ? Number(a.mvqWonHistory[ep] || 0) : 0;
                const gifted = Array.isArray(a.mvqGiftedHistory) ? Number(a.mvqGiftedHistory[ep] || 0) : 0;
                return sum + won + gifted;
            }, 0);
            const totalB = episodeIndexes.reduce((sum, ep) => {
                const won = Array.isArray(b.mvqWonHistory) ? Number(b.mvqWonHistory[ep] || 0) : 0;
                const gifted = Array.isArray(b.mvqGiftedHistory) ? Number(b.mvqGiftedHistory[ep] || 0) : 0;
                return sum + won + gifted;
            }, 0);
            return totalB - totalA;
        });

        const section = document.createElement("div");
        section.style.border = "none";
        section.style.background = "transparent";
        section.style.width = "fit-content";
        section.style.maxWidth = "100%";
        section.style.margin = "0 auto";
        section.style.overflowX = "auto";
        section.style.overflowY = "visible";

        const table = document.createElement("table");
        table.setAttribute("class", "trtable stats-track-table stats-points-track-table");
        table.style.display = "inline-table";
        table.style.width = "max-content";
        table.style.borderCollapse = "collapse";
        table.style.minWidth = "760px";

        const bracketTitleRow = document.createElement("tr");
        const bracketTitleCell = document.createElement("th");
        bracketTitleCell.textContent = "Bracket " + groupNumber;
        bracketTitleCell.setAttribute("colspan", String((episodeIndexes.length * 2) + 2));
        bracketTitleCell.style.background = typeof getBracketColor === "function"
            ? getBracketColor(groupNumber)
            : "#ff8a00";
        bracketTitleCell.style.color = getBracketTextColor(groupNumber);
        bracketTitleCell.dataset.bracketTextGroup = String(groupNumber);
        bracketTitleCell.style.textAlign = "center";
        bracketTitleCell.style.fontWeight = "800";
        bracketTitleCell.style.fontSize = "1.55rem";
        bracketTitleCell.style.padding = "10px 8px";
        bracketTitleCell.style.border = "1px solid var(--border-strong)";
        bracketTitleRow.appendChild(bracketTitleCell);
        table.appendChild(bracketTitleRow);

        const header = document.createElement("tr");
        const nameHeader = document.createElement("th");
        nameHeader.textContent = "Contestant";
        nameHeader.style.padding = "8px";
        nameHeader.style.border = "1px solid var(--border-strong)";
        nameHeader.style.background = "var(--ss-head)";
        nameHeader.style.fontSize = "1.15rem";
        header.appendChild(nameHeader);

        episodeIndexes.forEach((ep) => {
            const epHeader = document.createElement("th");
            epHeader.textContent = "Ep. " + (ep + 1);
            epHeader.style.padding = "8px";
            epHeader.style.border = "1px solid var(--border-strong)";
            epHeader.style.background = "var(--ss-head)";
            epHeader.style.fontSize = "1.1rem";
            epHeader.setAttribute("colspan", "2");
            header.appendChild(epHeader);
        });

        const totalHeader = document.createElement("th");
        totalHeader.textContent = "Total Points";
        totalHeader.style.padding = "8px";
        totalHeader.style.border = "1px solid var(--border-strong)";
        totalHeader.style.background = "var(--ss-head)";
        totalHeader.style.fontSize = "1.1rem";
        header.appendChild(totalHeader);

        table.appendChild(header);

        rankedContestants.forEach((queen) => {
            const row = document.createElement("tr");

            row.appendChild(createStatsContestantCell(queen, queen.name));

            let totalPoints = 0;
            episodeIndexes.forEach((ep) => {
                const won = Array.isArray(queen.mvqWonHistory) ? Number(queen.mvqWonHistory[ep] || 0) : 0;
                const gifted = Array.isArray(queen.mvqGiftedHistory) ? Number(queen.mvqGiftedHistory[ep] || 0) : 0;
                totalPoints += won + gifted;

                const earnedCell = document.createElement("td");
                const earnedStyle = getCellStyle(won, gifted, "earned");
                earnedCell.style.padding = "7px 8px";
                earnedCell.style.border = "1px solid var(--border-strong)";
                earnedCell.style.background = earnedStyle.background;
                earnedCell.style.color = earnedStyle.color;
                earnedCell.style.textAlign = "center";
                earnedCell.style.fontWeight = "800";
                earnedCell.style.fontSize = "0.98rem";
                earnedCell.textContent = won > 0 ? ("+" + formatPoints(won)) : "-";
                row.appendChild(earnedCell);

                const giftedCell = document.createElement("td");
                const giftedStyle = getCellStyle(won, gifted, "gifted");
                giftedCell.style.padding = "7px 8px";
                giftedCell.style.border = "1px solid var(--border-strong)";
                giftedCell.style.background = giftedStyle.background;
                giftedCell.style.color = giftedStyle.color;
                giftedCell.style.textAlign = "center";
                giftedCell.style.fontWeight = "800";
                giftedCell.style.fontSize = "0.98rem";
                giftedCell.textContent = gifted > 0 ? ("+" + formatPoints(gifted)) : "-";
                row.appendChild(giftedCell);
            });

            const totalCell = document.createElement("td");
            totalCell.style.padding = "7px 8px";
            totalCell.style.border = "1px solid var(--border-strong)";
            totalCell.style.background = "var(--ss-cell)";
            totalCell.style.textAlign = "center";
            totalCell.style.fontWeight = "800";
            totalCell.style.fontSize = "1rem";
            totalCell.textContent = formatPoints(totalPoints);
            row.appendChild(totalCell);

            table.appendChild(row);
        });

        section.appendChild(table);
        sectionsWrap.appendChild(section);
    }

    board.appendChild(sectionsWrap);
    main.appendChild(board);
    addStatsTabs(screen, "MVQ Points Track Record");
    addStatsFooter(screen);
}

function laMasPointsTrackRecord() {
    let screen = new Scene();
    screen.clean();
    screen.createHeader("Points Track Record");
    setBackgroundToNormal();

    let main = document.querySelector("div#MainBlock");
    const contestants = [...currentCast, ...eliminatedCast];
    const withScores = contestants.filter((queen) => Array.isArray(queen.laMasScoreHistory));
    const totalEpisodes = Math.max(1, withScores.reduce((maxLen, queen) => Math.max(maxLen, queen.laMasScoreHistory.length), 0));

    const formatPoints = (value) => {
        const numericValue = Number(value || 0);
        if (!Number.isFinite(numericValue)) return "-";
        return Number.isInteger(numericValue)
            ? String(numericValue)
            : numericValue.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
    };

    const getCellStyleByPlacement = (rankIndex, validCount) => {
        if (rankIndex < 0 || validCount <= 0) return { background: "#a9a9a9", color: "#000000" };
        const maxIndex = Math.max(validCount - 1, 1);
        const normalized = rankIndex / maxIndex;
        const hue = 210 * (1 - normalized);
        const saturation = 75;
        const lightness = 58 - (normalized * 14);
        return {
            background: `hsl(${hue}, ${saturation}%, ${lightness}%)`,
            color: normalized > 0.62 ? "#ffffff" : "#000000"
        };
    };

    const rankedContestants = [...withScores].sort((a, b) => {
        const aScores = Array.isArray(a.laMasScoreHistory) ? a.laMasScoreHistory : [];
        const bScores = Array.isArray(b.laMasScoreHistory) ? b.laMasScoreHistory : [];
        const aTotal = aScores.reduce((sum, value) => sum + (Number.isFinite(Number(value)) ? Number(value) : 0), 0);
        const bTotal = bScores.reduce((sum, value) => sum + (Number.isFinite(Number(value)) ? Number(value) : 0), 0);
        return bTotal - aTotal;
    });

    let centering = document.createElement("center");
    let table = document.createElement("table");
    table.setAttribute("id", "trackRecord");
    table.setAttribute("class", "trtable stats-track-table stats-points-track-table");
    table.setAttribute("border", "2");

    let header = document.createElement("tr");
    let nameHeader = document.createElement("th");
    nameHeader.textContent = "Contestant";
    header.appendChild(nameHeader);

    for (let ep = 0; ep < totalEpisodes; ep++) {
        let epHeader = document.createElement("th");
        epHeader.textContent = String(ep + 1);
        header.appendChild(epHeader);
    }

    let totalHeader = document.createElement("th");
    totalHeader.textContent = "Total";
    header.appendChild(totalHeader);

    let avgHeader = document.createElement("th");
    avgHeader.textContent = "Average";
    header.appendChild(avgHeader);

    table.appendChild(header);

    const episodeRankMaps = Array.from({ length: totalEpisodes }, (_, ep) => {
        const scored = rankedContestants
            .map((queen) => {
                const raw = Array.isArray(queen.laMasScoreHistory) ? queen.laMasScoreHistory[ep] : undefined;
                const score = Number(raw);
                return { queen, score: Number.isFinite(score) ? score : null };
            })
            .filter((entry) => entry.score !== null)
            .sort((a, b) => b.score - a.score);

        const rankMap = new Map();
        let previousScore = null;
        let currentRank = -1;

        scored.forEach((entry, idx) => {
            if (entry.score !== previousScore) {
                currentRank = idx;
                previousScore = entry.score;
            }
            rankMap.set(entry.queen, currentRank);
        });

        return {
            rankMap,
            validCount: scored.length
        };
    });

    rankedContestants.forEach((queen) => {
        let row = document.createElement("tr");

        row.appendChild(createStatsContestantCell(queen, queen.name));

        let total = 0;
        let judgedEpisodes = 0;

        for (let ep = 0; ep < totalEpisodes; ep++) {
            const raw = Array.isArray(queen.laMasScoreHistory) ? queen.laMasScoreHistory[ep] : undefined;
            const score = Number(raw);
            const validScore = Number.isFinite(score) ? score : null;

            if (validScore !== null) {
                total += validScore;
                judgedEpisodes++;
            }

            let scoreCell = document.createElement("td");
            const epRanks = episodeRankMaps[ep];
            const rankIndex = validScore === null ? -1 : (epRanks.rankMap.has(queen) ? epRanks.rankMap.get(queen) : -1);
            const style = getCellStyleByPlacement(rankIndex, epRanks.validCount);
            scoreCell.style.backgroundColor = style.background;
            scoreCell.style.color = style.color;
            scoreCell.style.textAlign = "center";
            scoreCell.style.fontWeight = "800";
            scoreCell.textContent = validScore === null ? "" : formatPoints(validScore);
            row.appendChild(scoreCell);
        }

        let totalCell = document.createElement("td");
        totalCell.style.fontWeight = "800";
        totalCell.style.textAlign = "center";
        totalCell.textContent = formatPoints(total);
        row.appendChild(totalCell);

        let avgCell = document.createElement("td");
        avgCell.style.fontWeight = "800";
        avgCell.style.textAlign = "center";
        const avg = judgedEpisodes > 0 ? (total / judgedEpisodes) : 0;
        avgCell.textContent = avg.toFixed(2);
        row.appendChild(avgCell);

        table.appendChild(row);
    });

    centering.appendChild(table);
    main.appendChild(centering);
    addStatsTabs(screen, "Points TR");
    addStatsFooter(screen);
}

function loadCodesPage() {
    displayUnlockedQueens();
    displayUnlockedTwists();
}

function redeemCode() {
    let code = document.getElementById("codeInput").value.toUpperCase();

    if (redeemedCodes.includes(code)) {
        showCustomStatusPopup("Code already redeemed!", "Codes", { modal: true });
        return;
    }

    let codeData = codes[code];
    if (!codeData) {
        showCustomStatusPopup("Invalid code!", "Codes", { modal: true });
        return;
    }

    if (codeData.type === CODE_TYPES.QUEEN) {
        let queen = secretQueens[codeData.queenIndex];
        allCustomQueens.push(queen);
        saveCustomQueens();
        showCustomStatusPopup("Unlocked Queen: " + queen.name, "Codes");
    }

    if (codeData.type === CODE_TYPES.TWIST) {
        unlockedTwists.push(codeData.twistId);
        localStorage.setItem(
            "unlockedTwists",
            JSON.stringify(unlockedTwists)
        );
        showCustomStatusPopup("Unlocked Twist!", "Codes");
    }

    if (codeData.type === CODE_TYPES.EVENT) {
        if (typeof codeData.void === "function") {
            codeData.void();
        }
        return;
    }

    if (codeData.type === CODE_TYPES.BADGE) {
        let unlockedBadges = JSON.parse(localStorage.getItem("unlockedBadges") || "[]");
        if (!unlockedBadges.includes(codeData.badgeId)) {
            unlockedBadges.push(codeData.badgeId);
            localStorage.setItem("unlockedBadges", JSON.stringify(unlockedBadges));
            if (window.accountDb && window.currentUserUid) {
                window.accountDb.ref(`users/${window.currentUserUid}/profile/badges`).set(unlockedBadges);
            }
        }
        showCustomStatusPopup("Badge unlocked: " + codeData.badgeId.charAt(0).toUpperCase() + codeData.badgeId.slice(1) + "!", "Codes");
    }

    redeemedCodes.push(code);
    localStorage.setItem("redeemedCodes", JSON.stringify(redeemedCodes));
    displayUnlockedQueens();
    displayUnlockedTwists();
}

function displayUnlockedQueens() {
    let unlockedDiv = document.getElementById("unlockedQueens");
    if (!unlockedDiv) return;
    unlockedDiv.innerHTML = "";

    redeemedCodes.forEach(code => {
        let codeData = codes[code];
        if (!codeData || codeData.type !== CODE_TYPES.QUEEN) return;

        let queen = secretQueens[codeData.queenIndex];
        if (!queen) return;

        let div = document.createElement("div");
        div.classList.add("card");

        let divImg = document.createElement("div");
        divImg.classList.add("data-image");

        let img = document.createElement("img");
        img.src = queen.getCurrentImage();
        img.style.borderColor = "black";
        img.style.width = "80px";
        img.style.height = "80px";

        divImg.appendChild(img);
        div.appendChild(divImg);

        let nameDiv = document.createElement("div");
        nameDiv.classList.add("data-header");
        nameDiv.textContent = queen.name;

        div.appendChild(nameDiv);
        unlockedDiv.appendChild(div);
    });
}

function displayUnlockedTwists() {
    let twistDiv = document.getElementById("unlockedTwists");
    if (!twistDiv) return;
    twistDiv.innerHTML = "";

    unlockedTwists.forEach(twistId => {
        let twist = twists[twistId];

        let div = document.createElement("div");
        div.classList.add("card");
        div.textContent = twist.name;
        twistDiv.appendChild(div);
    });
}

