function sanitizePublicSharePayload(payload) {
    if (!payload || typeof payload !== "object") {
        return null;
    }

    try {
        return JSON.parse(JSON.stringify(payload));
    } catch (_err) {
        return null;
    }
}

function createPublicShareId(prefix = "share") {
    return prefix + Math.random().toString(36).slice(2, 10);
}

function stableStringify(value) {
    if (value === null || typeof value !== "object") {
        return JSON.stringify(value);
    }

    if (Array.isArray(value)) {
        return "[" + value.map((entry) => stableStringify(entry)).join(",") + "]";
    }

    const keys = Object.keys(value).sort();
    return "{" + keys.map((key) => JSON.stringify(key) + ":" + stableStringify(value[key])).join(",") + "}";
}

function hashStringToBase36(input) {
    const text = String(input || "");
    let hash = 2166136261;

    for (let i = 0; i < text.length; i++) {
        hash ^= text.charCodeAt(i);
        hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
    }

    return (hash >>> 0).toString(36).padStart(7, "0");
}

function buildPublicShareStableKey(kind, payload) {
    if (kind === "history-season") {
        const seasonId = payload && payload.id;
        if (seasonId !== undefined && seasonId !== null && String(seasonId).trim() !== "") {
            return "history-season:id:" + String(seasonId).trim();
        }
    }

    if (kind === "custom-queen") {
        const name = String((payload && (payload._name || payload.name)) || "").trim().toLowerCase();
        const stats = [
            Number(payload && payload._actingStat) || 0,
            Number(payload && payload._comedyStat) || 0,
            Number(payload && payload._danceStat) || 0,
            Number(payload && payload._designStat) || 0,
            Number(payload && payload._improvStat) || 0,
            Number(payload && payload._runwayStat) || 0,
            Number(payload && payload._lipsyncStat) || 0
        ].join("|");
        const duoMeta = [
            payload && payload.isDuo ? "1" : "0",
            String((payload && payload.name1) || "").trim().toLowerCase(),
            String((payload && payload.name2) || "").trim().toLowerCase()
        ].join("|");
        return "custom-queen:" + name + ":" + stats + ":" + duoMeta;
    }

    return kind + ":" + stableStringify(payload);
}

function createPublicShareIdFromStableKey(kind, stableKey) {
    const prefix = kind === "history-season" ? "hs" : (kind === "custom-queen" ? "cq" : "sh");
    return prefix + "-" + hashStringToBase36(stableKey);
}

function isPublicShareExpired(record) {
    if (!record || typeof record !== "object") {
        return false;
    }

    const expiresAt = Date.parse(record.expiresAt || "");
    return Number.isFinite(expiresAt) ? Date.now() >= expiresAt : false;
}

async function publishPublicShare(kind, payload, title = "Shared item") {
    const db = getLiveShareDb();
    if (!db) {
        throw new Error("Sharing is unavailable right now.");
    }

    const sanitizedPayload = sanitizePublicSharePayload(payload);
    if (!sanitizedPayload) {
        throw new Error("This item could not be prepared for sharing.");
    }

    const now = new Date();
    const auth = window.accountAuth || (window.firebase && typeof window.firebase.auth === "function" ? window.firebase.auth() : null);
    const user = auth && auth.currentUser;
    const ownerUid = user && !user.isAnonymous ? user.uid : null;
    const stableKey = buildPublicShareStableKey(kind, sanitizedPayload) + (ownerUid ? ":" + ownerUid : "");
    const shareId = createPublicShareIdFromStableKey(kind, stableKey);
    const existingSnapshot = await db.ref(PUBLIC_SHARE_DB_PATH + "/" + shareId).once("value");
    const existingRecord = existingSnapshot.val();
    const createdAt = existingRecord && !isPublicShareExpired(existingRecord)
        ? String(existingRecord.createdAt || now.toISOString())
        : now.toISOString();
    const record = {
        kind,
        title: String(title || "Shared item"),
        createdAt,
        updatedAt: now.toISOString(),
        expiresAt: new Date(now.getTime() + PUBLIC_SHARE_MAX_AGE_MS).toISOString(),
        payload: sanitizedPayload
    };

    if (ownerUid) record.ownerUid = ownerUid;
    await db.ref(PUBLIC_SHARE_DB_PATH + "/" + shareId).set(record);
    return { shareId, record };
}

async function readPublicShare(shareId) {
    const db = getLiveShareDb();
    if (!db || !shareId) {
        return null;
    }

    const snapshot = await db.ref(PUBLIC_SHARE_DB_PATH + "/" + shareId).once("value");
    const record = snapshot.val();
    if (record && isPublicShareExpired(record)) {
        db.ref(PUBLIC_SHARE_DB_PATH + "/" + shareId).remove().catch(() => {});
        return null;
    }
    return record;
}

