function resolveAbsoluteShareAsset(value, fallbackPath = "image/favicon.ico") {
    const rawValue = String(value || "").trim() || fallbackPath;
    const currentUrl = new URL(window.location.href);
    const baseUrl = currentUrl.origin + "/sponsors/drag/";

    try {
        return new URL(rawValue, baseUrl).href;
    } catch (_err) {
        return new URL(fallbackPath, baseUrl).href;
    }
}

function ensureSocialMetaTag(attributeName, attributeValue) {
    if (!attributeName || !attributeValue || !document || !document.head) {
        return null;
    }

    let tag = document.head.querySelector('meta[' + attributeName + '="' + attributeValue + '"]');
    if (!tag) {
        tag = document.createElement("meta");
        tag.setAttribute(attributeName, attributeValue);
        document.head.appendChild(tag);
    }
    return tag;
}

function updateSocialPreviewMeta(options = {}) {
    const title = String(options.title || "Simulator Superstars");
    const description = String(options.description || "Create, share, and watch seasons on Simulator Superstars.");
    const url = String(options.url || window.location.href || "");
    const image = resolveAbsoluteShareAsset(options.image || "image/favicon.ico");
    const type = String(options.type || "website");

    document.title = title;

    const metaEntries = [
        ["name", "description", description],
        ["property", "og:title", title],
        ["property", "og:description", description],
        ["property", "og:url", url],
        ["property", "og:type", type],
        ["property", "og:image", image],
        ["name", "twitter:card", image ? "summary_large_image" : "summary"],
        ["name", "twitter:title", title],
        ["name", "twitter:description", description],
        ["name", "twitter:image", image]
    ];

    metaEntries.forEach(([attrName, attrValue, content]) => {
        const tag = ensureSocialMetaTag(attrName, attrValue);
        if (tag) {
            tag.setAttribute("content", String(content || ""));
        }
    });
}

function hasLiveSeasonData() {
    const activeQueens = Array.isArray(currentCast) ? currentCast.filter(Boolean) : [];
    const outQueens = Array.isArray(eliminatedCast) ? eliminatedCast.filter(Boolean) : [];
    return activeQueens.length + outQueens.length > 0;
}

function getSharedSeasonRoomIdFromUrl() {
    const params = new URLSearchParams(window.location.search || "");
    const rawHash = String(window.location.hash || "").replace(/^#/, "").trim();
    const hashParams = new URLSearchParams(rawHash);
    const bareHashRoomId = rawHash && !rawHash.includes("=") && !["contestants"].includes(rawHash.toLowerCase()) ? rawHash : "";
    const pathMatch = String(window.location.pathname || "").match(/\/(?:w|watch)\/([^/?#]+)/i);
    const pathRoomId = pathMatch ? pathMatch[1] : "";

    return String(params.get("w") || hashParams.get("w") || params.get("watch") || hashParams.get("watch") || bareHashRoomId || pathRoomId || "")
        .replace(/[^a-z0-9_-]/gi, "")
        .trim();
}

function getSharedSeasonAccessKeyFromUrl() {
    const params = new URLSearchParams(window.location.search || "");
    const hashParams = new URLSearchParams(String(window.location.hash || "").replace(/^#/, ""));
    return String(params.get("a") || hashParams.get("a") || params.get("access") || hashParams.get("access") || "")
        .replace(/[^a-z0-9_-]/gi, "")
        .trim();
}

function isLiveShareWatchPage() {
    return /(^|\/)watch\.html$/i.test(String(document.location.pathname || ""));
}

function getLiveSeasonSimulatorUrl() {
    return window.location.origin + "/sponsors/drag/index.html";
}

function getInviteParamValue(...keys) {
    const params = new URLSearchParams(window.location.search || "");
    const hashParams = new URLSearchParams(String(window.location.hash || "").replace(/^#/, ""));
    for (let i = 0; i < keys.length; i++) {
        const key = String(keys[i] || "").trim();
        if (!key) continue;
        const fromSearch = String(params.get(key) || "").trim();
        if (fromSearch) return fromSearch;
        const fromHash = String(hashParams.get(key) || "").trim();
        if (fromHash) return fromHash;
    }
    return "";
}

function getInvitePlayerFromUrl() {
    return getInviteParamValue("player", "p", "invitePlayer");
}

function getInviteQueenFromUrl() {
    return getInviteParamValue("queen", "q", "inviteQueen");
}

function isInviteModeFromUrl() {
    return false;
}

function resolveInviteCastQueen(entry) {
    if (!entry || typeof entry !== "object") {
        return null;
    }

    const name = String(entry.name || entry._name || "").trim();
    if (!name) {
        return null;
    }

    const existing = (Array.isArray(allQueens) ? allQueens : []).find((queen) => String(queen._name || queen.name || "").trim() === name);
    if (existing) {
        return existing;
    }

    const images = Array.isArray(entry.images) && entry.images.length > 0
        ? entry.images
        : (entry.image ? [entry.image] : ["noimage"]);

    const generated = new Queen(
        name,
        Number(entry.acting || entry._actingStat || 0),
        Number(entry.comedy || entry._comedyStat || 0),
        Number(entry.dance || entry._danceStat || 0),
        Number(entry.design || entry._designStat || 0),
        Number(entry.improv || entry._improvStat || 0),
        Number(entry.runway || entry._runwayStat || 0),
        Number(entry.lipsync || entry._lipsyncStat || 0),
        images,
        true,
        !!entry.isDuo,
        entry.name1 || "",
        entry.name2 || ""
    );
    generated.customqueen = true;
    generated.country = entry.country || null;

    if (Array.isArray(allCustomQueens)) {
        allCustomQueens.push(generated);
    }
    if (Array.isArray(allQueens)) {
        allQueens.push(generated);
    }
    return generated;
}

function applyInviteCastSnapshot(seasonSnapshot) {
    if (!seasonSnapshot || !Array.isArray(seasonSnapshot.cast) || seasonSnapshot.cast.length === 0) {
        return false;
    }

    const resolved = [];
    seasonSnapshot.cast.forEach((entry) => {
        const queen = resolveInviteCastQueen(entry);
        if (queen && !resolved.some((picked) => queensMatchByIdentityOrName(picked, queen))) {
            resolved.push(queen);
        }
    });

    if (resolved.length === 0) {
        return false;
    }

    currentCast = [];
    eliminatedCast = [];
    resolved.forEach((queen) => addQueenToCurrentCastUnique(queen));
    updateCast();
    if (typeof syncCastQuickStatsUi === "function") {
        syncCastQuickStatsUi();
    }
    return true;
}

function applyInviteClaimFromUrl() {
    if (!isInviteModeFromUrl()) {
        return;
    }

    if (isLiveShareWatchPage()) {
        const inviteQueen = getInviteQueenFromUrl();
        if (inviteQueen) {
            promptAndToggleClaimedQueenName(inviteQueen);
        }
        return;
    }

    const inviteSnapshot = getSharedSeasonSnapshotFromUrl();

    const loadedCast = applyInviteCastSnapshot(inviteSnapshot);
    if (loadedCast && typeof refreshQueenCards === "function") {
        refreshQueenCards();
    }

    resolveInviteeAccountNameAsync().then((accountName) => {
        if (!accountName) {
            return;
        }
        if (typeof showCustomStatusPopup === "function") {
            showCustomStatusPopup(accountName + " joined. Pick your queen from the cast.", "Multiplayer");
        }
    }).catch(() => {});

    if (typeof refreshQueenCards === "function") {
        refreshQueenCards();
    }
    updateCast();
}

async function resolveInviteeAccountNameAsync() {
    try {
        const authApi = window.firebase && typeof window.firebase.auth === "function" ? window.firebase.auth() : null;
        if (!authApi) {
            return null;
        }

        return await new Promise((resolve) => {
            let settled = false;
            let unsubscribe = null;
            const finish = (value) => {
                if (settled) return;
                settled = true;
                if (typeof unsubscribe === "function") {
                    try {
                        unsubscribe();
                    } catch (_err) {}
                }
                resolve(String(value || "").trim() || null);
            };

            const timer = setTimeout(() => finish(null), 2000);
            unsubscribe = authApi.onAuthStateChanged(
                async (user) => {
                    clearTimeout(timer);
                    const cachedUsername = String(window.currentUsername || "").trim();
                    if (cachedUsername) {
                        finish(cachedUsername);
                        return;
                    }
                    if (user && user.uid && window.accountDb && typeof window.accountDb.ref === "function") {
                        try {
                            const usernameSnapshot = await window.accountDb.ref(`users/${user.uid}/username`).once("value");
                            const username = String(usernameSnapshot.val() || "").trim();
                            if (username) {
                                finish(username);
                                return;
                            }
                        } catch (_err) {}
                    }
                    if (user && user.displayName) {
                        finish(user.displayName);
                    } else if (user && user.email) {
                        finish(user.email.split("@")[0]);
                    } else {
                        finish(null);
                    }
                },
                () => {
                    clearTimeout(timer);
                    finish(null);
                }
            );
        });
    } catch (_err) {
        return null;
    }
}

async function copyLiveSeasonPlayerInviteLink() {
    showCustomStatusPopup("Multiplayer Be A Queen mode has been removed.", "Multiplayer Invite", { modal: true });
    return false;
}

function createLiveShareAccessKey() {
    return Math.random().toString(36).slice(2, 8);
}

function getStoredLiveShareRoomMeta() {
    try {
        const parsed = JSON.parse(localStorage.getItem(LIVE_SHARE_ROOM_META_KEY) || "null");
        return parsed && typeof parsed === "object" ? parsed : null;
    } catch (_err) {
        return null;
    }
}

function isLiveShareExpired(liveShare) {
    if (!liveShare || typeof liveShare !== "object") {
        return false;
    }

    const expiresAt = Date.parse(liveShare.expiresAt || "");
    if (Number.isFinite(expiresAt)) {
        return Date.now() >= expiresAt;
    }

    const createdAt = Date.parse(liveShare.createdAt || liveShare.updatedAt || "");
    return Number.isFinite(createdAt)
        ? (Date.now() - createdAt) >= LIVE_SHARE_MAX_AGE_MS
        : false;
}

function getLiveShareSnapshotStorageKey(roomId = currentLiveShareRoomId) {
    return LIVE_SHARE_SNAPSHOT_KEY_PREFIX + String(roomId || "");
}

function clearStoredLiveShareRoomId() {
    try {
        const storedRoomId = currentLiveShareRoomId || localStorage.getItem(LIVE_SHARE_ROOM_STORAGE_KEY) || "";
        if (storedRoomId) {
            localStorage.removeItem(getLiveShareSnapshotStorageKey(storedRoomId));
        }
        localStorage.removeItem(LIVE_SHARE_ROOM_STORAGE_KEY);
        localStorage.removeItem(LIVE_SHARE_ROOM_META_KEY);
    } catch (_err) {}
}

function persistLiveShareSnapshot(record) {
    if (!record || !record.liveShare || !record.liveShare.roomId) {
        return;
    }

    try {
        localStorage.setItem(getLiveShareSnapshotStorageKey(record.liveShare.roomId), JSON.stringify(record));
    } catch (_err) {}
}

function readStoredLiveShareSnapshot(roomId = currentLiveShareRoomId) {
    if (!roomId) {
        return null;
    }

    try {
        const parsed = JSON.parse(localStorage.getItem(getLiveShareSnapshotStorageKey(roomId)) || "null");
        if (!parsed || typeof parsed !== "object") {
            return null;
        }
        if (parsed.liveShare && isLiveShareExpired(parsed.liveShare)) {
            localStorage.removeItem(getLiveShareSnapshotStorageKey(roomId));
            return null;
        }
        return parsed;
    } catch (_err) {
        return null;
    }
}

function persistLiveShareRoomMeta(options = {}) {
    if (!currentLiveShareRoomId) {
        return;
    }

    try {
        const existing = getStoredLiveShareRoomMeta();
        const createdAt = existing && existing.roomId === currentLiveShareRoomId && existing.createdAt
            ? existing.createdAt
            : new Date().toISOString();
        const createdTime = Date.parse(createdAt);
        const expiresAt = new Date((Number.isFinite(createdTime) ? createdTime : Date.now()) + LIVE_SHARE_MAX_AGE_MS).toISOString();
        const refreshSignal = Object.prototype.hasOwnProperty.call(options, "refreshSignal")
            ? String(options.refreshSignal || "")
            : String((existing && existing.roomId === currentLiveShareRoomId && existing.refreshSignal) || "");
        const accessKey = Object.prototype.hasOwnProperty.call(options, "accessKey")
            ? String(options.accessKey || "")
            : String((existing && existing.roomId === currentLiveShareRoomId && existing.accessKey) || createLiveShareAccessKey());
        localStorage.setItem(LIVE_SHARE_ROOM_STORAGE_KEY, currentLiveShareRoomId);
        localStorage.setItem(LIVE_SHARE_ROOM_META_KEY, JSON.stringify({
            roomId: currentLiveShareRoomId,
            createdAt,
            updatedAt: new Date().toISOString(),
            expiresAt,
            fallbackMode: !!liveShareFallbackMode,
            refreshSignal,
            accessKey,
            mode: normalizeLiveShareMode(options.mode || (existing && existing.roomId === currentLiveShareRoomId ? existing.mode : getLiveSeasonShareMode()))
        }));
    } catch (_err) {}
}

function restoreLiveShareRoomIdFromStorage() {
    if (currentLiveShareRoomId) {
        return currentLiveShareRoomId;
    }

    try {
        const storedRoomId = String(localStorage.getItem(LIVE_SHARE_ROOM_STORAGE_KEY) || "")
            .replace(/[^a-z0-9_-]/gi, "")
            .trim();
        const meta = getStoredLiveShareRoomMeta();

        if (!storedRoomId) {
            if (meta) clearStoredLiveShareRoomId();
            return "";
        }

        if (meta && isLiveShareExpired(meta)) {
            clearStoredLiveShareRoomId();
            return "";
        }

        currentLiveShareRoomId = storedRoomId;
        liveShareFallbackMode = !!(meta && meta.fallbackMode);
        return currentLiveShareRoomId;
    } catch (_err) {
        return "";
    }
}

function getCurrentLiveSeasonName() {
    const titleEl = document.getElementById("MainTitle");
    const rawTitle = titleEl ? titleEl.textContent.replace(/\s+/g, " ").trim() : "";
    if (rawTitle && !/simulator superstars|season history/i.test(rawTitle)) {
        return rawTitle;
    }

    const queenCount = (Number(totalCastSize) || 0)
        || ((Array.isArray(currentCast) ? currentCast.length : 0) + (Array.isArray(eliminatedCast) ? eliminatedCast.length : 0));
    const currentEpisodeLabel = Array.isArray(episodeChallenges) && episodeChallenges.length > 0
        ? "Ep " + episodeChallenges.length
        : "Live";

    if (queenCount > 0) {
        return "Hosted Season • " + queenCount + " queens • " + currentEpisodeLabel;
    }

    return "Hosted Season";
}

function resolveCurrentEliminationFormatLabel() {
    if (dragula_format || titans_format) {
        return "Extermination";
    }

    if (beaverCastVote || voteReturn || (!all_stars && !lipsync_assassin && !og_lsa && !all_winners && !top2LFTWFormat && !safetyFormat)) {
        return "Vote to Eliminate";
    }

    return "Lipstick Elimination";
}

function getLiveSeasonWatchUrl(roomId = currentLiveShareRoomId) {
    if (!roomId) {
        return "";
    }

    const currentUrl = new URL(window.location.href);
    return currentUrl.origin + "/watch.html?w=" + encodeURIComponent(String(roomId || ""));
}

function getLiveShareMainTitleSnapshot() {
    const titleEl = document.getElementById("MainTitle");
    return titleEl ? String(titleEl.innerHTML || "").trim() : "";
}

function getLiveShareMainBlockSnapshot() {
    const mainBlock = document.getElementById("MainBlock");
    if (!mainBlock) {
        return "";
    }
    const html = String(mainBlock.innerHTML || "")
        .replace(/>\s+</g, "><")
        .replace(/\s{2,}/g, " ")
        .trim();
    // Keep payload bounded for Firebase and URL fallbacks.
    return html.length > 60000 ? html.slice(0, 60000) : html;
}

async function copyTextToClipboardWithFallback(text, successMessage = "Copied to clipboard.", promptLabel = "Copy this link:") {
    const copyValue = String(text || "");

    try {
        if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
            await navigator.clipboard.writeText(copyValue);
        } else {
            const temp = document.createElement("textarea");
            temp.value = copyValue;
            temp.setAttribute("readonly", "readonly");
            temp.style.position = "fixed";
            temp.style.opacity = "0";
            document.body.appendChild(temp);
            temp.focus();
            temp.select();
            document.execCommand("copy");
            temp.remove();
        }

        if (typeof showCustomStatusPopup === "function") {
            showCustomStatusPopup(successMessage, "Sharing");
        } else if (typeof showFloatingNotice === "function") {
            showFloatingNotice(successMessage, 1800);
        }
        return true;
    } catch (_err) {
        if (typeof window.showInHousePrompt === "function") {
            await window.showInHousePrompt(promptLabel, copyValue, "Auto-copy blocked");
        } else {
            window.prompt(promptLabel, copyValue);
        }
        return false;
    }
}

