        episodesCompleted: Array.isArray(episodeChallenges) ? episodeChallenges.length : 0,
        challenges: Array.isArray(episodeChallenges) ? [...episodeChallenges] : [],
        formatFlags: record.formatFlags || {},
        premiereFlags: record.premiereFlags || {},
        returningFlags: record.returningFlags || {},
        twists: record.twists || {},
        prizeSettings: record.prizeSettings,
        bracket: {
            enabled: !!brackets_format,
            phaseActive: !!bracketPhaseActive,
            round: Number(bracketRound) || 1,
            bracketCount: Number(bracketCount) || 0,
            queensPerBracket: Number(queenPerBracket) || 0,
            passersPerBracket: Number(bracketPassersPerBracket) || 0,
            episodesPerBracket: Number(bracketEpisodesPerBracket) || 0,
            postFormat: bracketPostFormat || "regular",
            roundPlan: String(bracketRoundPlanText || "").trim(),
            returnAtMerge: !!bracketReturnAtMerge,
            returnAtMergeCount: Number(bracketReturnAtMergeCount) || 0,
            returnAtFinale: !!bracketReturnAtFinale,
            returnAtFinaleCount: Number(bracketReturnAtFinaleCount) || 0,
            wildcardBracket: !!bracketWildcardBracket,
            wildcardEntrantsPerReturnee: Number(bracketWildcardEntrantsPerBracket) || 0,
            wildcardSelectableEntrants: !!bracketWildcardSelectableEntrants,
            pointsToStars: !!bracketPointsToStars,
            pointsPerStar: Number(bracketPointsPerStar) || 0,
            tieSave: !!bracketTieSave,
            lipSyncTieBreaker: !!bracketLipSyncTieBreaker
        },
        liveShare: {
            enabled: !!currentLiveShareRoomId,
            roomId: String(currentLiveShareRoomId || ""),
            mode: getLiveSeasonShareMode(),
            screenShareActive: !!liveShareScreenStream,
            eliminationFormat: resolveCurrentEliminationFormatLabel()
        },
