function handleLiveShareSyncError(error) {
    console.error("Failed syncing the live season:", error);
    if (!liveShareFallbackMode && typeof showFloatingNotice === "function") {
        showFloatingNotice("Live updates could not be sent. Retrying automatically.", 3200);
    }
    liveShareFallbackMode = true;
}

async function syncCurrentSeasonToLiveShare(force = false) {
    if (liveSeasonSpectatorMode || !currentLiveShareRoomId || !hasLiveSeasonData()) {
        return null;
    }

    if (!force && typeof navigator !== "undefined" && navigator.onLine === false) {
        return null;
    }

    const db = getLiveShareDb();
    if (!db) {
        throw new Error("Live sharing is unavailable right now.");
    }

    const compactRecord = sanitizeLiveShareRecordForFirebase(buildCompactLiveShareRecord(currentLiveShareRoomId));
    const record = compactRecord;

    if (!record) {
        return null;
    }
    const fingerprint = JSON.stringify({
        name: record.name,
        winner: record.winner,
        episodes: record.episodes,
        challenges: record.challenges,
        trackRecordHTML: record.trackRecordHTML,
        liveShare: {
            mode: record.liveShare.mode,
            status: record.liveShare.status,
            refreshSignal: record.liveShare.refreshSignal,
            accessKey: record.liveShare.accessKey
        },
        cast: Array.isArray(record.cast) ? record.cast.map(queen => ({
            name: queen.name,
            rankP: queen.rankP,
            trackRecord: queen.trackRecord
        })) : []
    });

    persistLiveShareSnapshot(record);

    if (!force && fingerprint === liveShareLastFingerprint) {
        persistLiveShareRoomMeta();
        return record;
    }

    if (!force && liveShareLastSyncAt > 0 && (Date.now() - liveShareLastSyncAt) < LIVE_SHARE_MIN_SYNC_GAP_MS) {
        scheduleLiveShareSync(false);
        return record;
    }

    await db.ref(LIVE_SHARE_DB_PATH + "/" + currentLiveShareRoomId).set(record);

    liveShareLastFingerprint = fingerprint;
    liveShareLastSyncAt = Date.now();
    liveShareFallbackMode = false;
    persistLiveShareRoomMeta();
    persistLiveShareSnapshot(record);
    updateLiveSharePanel();

    if (record.liveShare && String(record.liveShare.status || "").toLowerCase() === "ended") {
        const historyRecord = buildCurrentSeasonHistoryRecord({
            seasonName: getCurrentLiveSeasonName(),
            savedSeasonType: inferSeasonTypeKeyFromState(),
            liveShareRoomId: currentLiveShareRoomId,
            liveShareStatus: "ended"
        }) || record;
        addSeasonRecordToHistory(historyRecord, { source: "live-share", archivedFromLive: true });
    }

    return record;
}

function startLiveShareAutoSync() {
    if (isLiveSeasonScreenShareMode()) {
        return;
    }

    if (liveShareSyncTimer) {
        window.clearInterval(liveShareSyncTimer);
    }

    ensureLiveShareDomObserver();
    if (!liveShareVisibilitySyncInstalled && typeof document !== "undefined") {
        liveShareVisibilitySyncInstalled = true;

        document.addEventListener("visibilitychange", () => {
            if (!document.hidden && isLiveSeasonStreamingEnabled() && !isLiveSeasonScreenShareMode()) {
                scheduleLiveShareSync(true);
            }
        });

        if (typeof window !== "undefined") {
            window.addEventListener("online", () => {
                if (isLiveSeasonStreamingEnabled() && !isLiveSeasonScreenShareMode()) {
                    scheduleLiveShareSync(true);
                }
            });
        }
    }
    scheduleLiveShareSync(true);
    liveShareSyncTimer = window.setInterval(() => {
        if (document.hidden) {
            return;
        }
        syncCurrentSeasonToLiveShare().catch(handleLiveShareSyncError);
    }, 12000);
}

async function copyLiveSeasonLink() {
    if (!currentLiveShareRoomId && isLiveSeasonStreamingEnabled()) {
        await ensureLiveShareRoomReady(true);
    }
    if (!currentLiveShareRoomId) {
        return false;
    }
    return copyTextToClipboardWithFallback(
        getLiveSeasonWatchUrl(currentLiveShareRoomId),
        "Watch link copied!",
        "Copy this watch link:"
    );
}

async function shareCurrentSeasonLive() {
    if (!isLiveSeasonStreamingEnabled()) {
        setLiveSeasonStreamingEnabled(true);
        syncLiveShareControlState();
        updateLiveSharePanel();
    }

    if (isLiveSeasonScreenShareMode()) {
        try {
            await startLiveScreenShareSession();
            await copyLiveSeasonLink();
            if (typeof showFloatingNotice === "function") {
                showFloatingNotice("Screen sharing is live. Viewers can open the watch link to connect in real time.", 3200);
            }
        } catch (err) {
            const message = err && err.message ? err.message : "Could not start screen sharing right now.";
            if (typeof showCustomStatusPopup === "function") {
                showCustomStatusPopup(message, "Live Streaming", { modal: true });
            } else {
                alert(message);
            }
        }
        return;
    }

    if (!currentLiveShareRoomId) {
        try {
            currentLiveShareRoomId = await reserveLiveShareRoomId();
        } catch (err) {
            alert(err && err.message ? err.message : "Only 10 live seasons can run at once right now. Try again soon.");
            return;
        }
    }

    if (!hasLiveSeasonData()) {
        await ensureLiveShareRoomReady(true);
        await copyLiveSeasonLink();
        if (typeof showFloatingNotice === "function") {
            showFloatingNotice("Watch link copied. The room is now live in Firebase and viewers will see a waiting screen until the season starts.", 3200);
        }
        return;
    }

    persistLiveShareRoomMeta({ refreshSignal: Date.now().toString() });

    try {
        await syncCurrentSeasonToLiveShare(true);
        startLiveShareAutoSync();
        await copyLiveSeasonLink();
    } catch (err) {
        handleLiveShareSyncError(err);
        startLiveShareAutoSync();
        const fallbackRecord = buildCompactLiveShareRecord(currentLiveShareRoomId);
        persistLiveShareRoomMeta();
        persistLiveShareSnapshot(fallbackRecord);
        updateLiveSharePanel();
        await copyLiveSeasonLink();
        if (typeof showFloatingNotice === "function") {
            showFloatingNotice("Watch link copied, but live updates are unavailable. Retrying automatically.", 3200);
        }
    }
}

async function stopLiveSeasonSharing() {
    await stopLiveScreenShareSession({ silent: true });

    if (!currentLiveShareRoomId) {
        setLiveSeasonStreamingEnabled(false);
        syncLiveShareControlState();
        updateLiveSharePanel();
        return;
    }

    const roomId = currentLiveShareRoomId;
    const finalStatus = hasLiveSeasonData() && currentCast.length <= 1 ? "ended" : "abandoned";
    const finalRecord = buildArchivedLiveShareRecord(roomId, finalStatus);

    if (finalRecord) {
        addSeasonRecordToHistory(finalRecord, { source: "live-share", archivedFromLive: true });
    }

    try {
        const db = getLiveShareDb();
        if (db) {
            await db.ref(LIVE_SHARE_DB_PATH + "/" + roomId).remove();
        }
    } catch (_err) {}

    setLiveSeasonStreamingEnabled(false);
    syncLiveShareControlState();
    currentLiveShareRoomId = "";
    liveShareLastFingerprint = "";
    liveShareLastWaitingFingerprint = "";
    liveShareAutoRestoreAttempted = true;
    clearLiveShareDomObserver();

    if (liveShareSyncTimer) {
        window.clearInterval(liveShareSyncTimer);
        liveShareSyncTimer = null;
    }

    clearStoredLiveShareRoomId();

    updateLiveSharePanel();
    if (typeof showFloatingNotice === "function") {
        showFloatingNotice("Live season sharing ended, the room was deleted, and the season was saved to Season History.", 2800);
    }
}

function renderLiveShareWaitingState(roomId, message, isError = false) {
    updateSocialPreviewMeta({
        title: isError ? "Live Watch Unavailable - Simulator Superstars" : "Watching Live Season - Simulator Superstars",
        description: String(message || "Watch a live season on Simulator Superstars."),
        url: window.location.href
    });

    const mainBlock = document.getElementById("MainBlock");
    if (!mainBlock) return;

    const titleEl = document.getElementById("MainTitle");
    if (titleEl) {
        titleEl.innerHTML = isError ? "Live Watch Unavailable" : "Watching Live Season";
    }

    const actionMarkup = ''
        + (!isStandaloneSharedView() ? '<button onclick="window.location.href=\'' + getLiveSeasonSimulatorUrl() + '\'">Back to simulator</button>' : '')
        + (currentLiveShareRoomId ? '<button onclick="copyLiveSeasonLink()">Copy watch link</button>' : '');

    mainBlock.innerHTML = ""
        + '<div style="max-width:760px;margin:30px auto;padding:24px;border-radius:24px;background:rgba(255,255,255,0.92);box-shadow:0 18px 40px rgba(61,10,31,0.12);text-align:center;">'
        + '<h2 style="margin-top:0;color:#3D0A1F;">' + (isError ? 'Could not open this watch room' : 'Watching room ' + roomId) + '</h2>'
        + '<p style="color:#5a3a4f;line-height:1.6;">' + message + '</p>'
        + '<div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;">'
        + actionMarkup
        + '</div>'
        + '</div>';
}

function renderSharedSeasonSnapshot(season) {
    clearLiveShareVoteWaitTimers();
    liveSharePendingSeason = null;

    if (!season || !Array.isArray(season.cast) || season.cast.length === 0) {
        const shareStatus = season && season.liveShare ? String(season.liveShare.status || "") : "";
        if (shareStatus === "ended") {
            renderLiveShareWaitingState(currentLiveShareRoomId || "live", "This live stream has ended and will stay viewable until it expires.", false);
        } else if (shareStatus === "abandoned") {
            renderLiveShareWaitingState(currentLiveShareRoomId || "live", "This live stream was closed before the season finished, and the final page will stay up until it expires.", false);
        } else {
            renderLiveShareWaitingState(currentLiveShareRoomId || "live", "The host has not synced the season yet.", false);
        }
        return;
    }

    const liveShareData = season && season.liveShare && typeof season.liveShare === "object"
        ? season.liveShare
        : null;
    const mirroredMainHtml = liveShareData ? String(liveShareData.mainBlockHtml || "") : "";
    if (mirroredMainHtml && getLiveShareModeFromRecord(season) === LIVE_SHARE_MODE_SCREEN) {
        const mainBlock = document.getElementById("MainBlock");
        const titleEl = document.getElementById("MainTitle");
        if (mainBlock) {
            mainBlock.innerHTML = mirroredMainHtml;
            renderWatchClaimPanel(season);
        }
        if (titleEl) {
            titleEl.innerHTML = String(liveShareData.mainTitleHtml || season.name || "Watching Live Season");
        }
        return;
    }

    updateSocialPreviewMeta({
        title: (season.name || "Live Season") + " - Simulator Superstars",
        description: season.winner
            ? ("Winner: " + season.winner + ". Watch this shared season on Simulator Superstars.")
            : "Watch this shared season on Simulator Superstars.",
        image: season.winnerImg || (season.cast && season.cast[0] && season.cast[0].image) || "image/favicon.ico",
        url: window.location.href
    });

    const hasSavedTR = typeof season.trackRecordHTML === "string"
        && season.trackRecordHTML.includes('id="trackRecord"')
        && /Rank/i.test(season.trackRecordHTML)
        && /Contestant/i.test(season.trackRecordHTML);

    if (hasSavedTR) {
        const mainBlock = document.getElementById("MainBlock");
        if (!mainBlock) return;
        mainBlock.innerHTML = "";
        setBackgroundToNormal();

        const titleEl = document.getElementById("MainTitle");
        if (titleEl) {
            titleEl.innerHTML = season.name || "Watching Live Season";
        }

        const center = document.createElement("center");
        const temp = document.createElement("div");
        temp.innerHTML = season.trackRecordHTML;
        const table = temp.querySelector("table#trackRecord") || temp.querySelector("table");
        if (table) {
            table.id = "trackRecord";
            table.classList.add("trtable");
            table.removeAttribute("border");

            const tableWrap = document.createElement("div");
            tableWrap.className = "history-trackrecord-wrap";
            tableWrap.appendChild(table);

            center.appendChild(tableWrap);
            mainBlock.appendChild(center);
            insertHistorySeasonRecap(season, null);
            renderWatchClaimPanel(season);
            return;
        }
    }

    renderHistorySeasonProgress(season, null);
    renderWatchClaimPanel(season);
}

function renderWatchClaimPanel(season) {
    const existing = document.getElementById("ss-watch-claim-panel");
    if (existing) existing.remove();
}

function watchSharedSeasonRoom(roomId) {
    liveSeasonSpectatorMode = true;
    currentLiveShareRoomId = roomId;
    liveShareLastAppliedSignal = "";
    clearLiveShareVoteWaitTimers();
    liveSharePendingSeason = null;

    const sharedSnapshot = getBestAvailableSharedSnapshot(roomId);
    if (sharedSnapshot && !hasAccessToSharedSeason(sharedSnapshot)) {
        renderLiveShareWaitingState(roomId, "This viewer link is private or invalid.", true);
    } else if (sharedSnapshot && getLiveShareModeFromRecord(sharedSnapshot) === LIVE_SHARE_MODE_SCREEN) {
        renderLiveScreenShareState(
            roomId,
            sharedSnapshot.liveShare && sharedSnapshot.liveShare.screenShareActive
                ? "Connecting to the host screen…"
                : "The host has not started the screen share yet.",
            false
        );
        ensureLiveScreenShareViewerConnection(roomId).catch(() => {
            renderLiveScreenShareState(roomId, "Could not connect to the host screen right now.", true);
        });
    } else if (sharedSnapshot && shouldApplyLiveShareRefresh(sharedSnapshot, true)) {
        if (shouldShowLiveShareVoteWait(sharedSnapshot)) {
            renderLiveShareVoteWaitState(roomId, sharedSnapshot);
        } else {
            renderSharedSeasonSnapshot(sharedSnapshot);
        }
    } else {
        renderLiveShareWaitingState(roomId, "Waiting for live updates from the host…", false);
    }

    if (liveShareLocalWatchTimer) {
        window.clearInterval(liveShareLocalWatchTimer);
    }
    liveShareLocalWatchTimer = window.setInterval(() => {
        if (document.hidden) {
            return;
        }
        const latestLocalSnapshot = readStoredLiveShareSnapshot(roomId);
        if (latestLocalSnapshot && !hasAccessToSharedSeason(latestLocalSnapshot)) {
            return;
        }
        if (latestLocalSnapshot && getLiveShareModeFromRecord(latestLocalSnapshot) === LIVE_SHARE_MODE_SCREEN) {
            renderLiveScreenShareState(
                roomId,
                latestLocalSnapshot.liveShare && latestLocalSnapshot.liveShare.screenShareActive
                    ? "Connecting to the host screen…"
                    : "The host has not started the screen share yet.",
                false
            );
            ensureLiveScreenShareViewerConnection(roomId).catch(() => {
                renderLiveScreenShareState(roomId, "Could not connect to the host screen right now.", true);
            });
            return;
        }
        if (latestLocalSnapshot && shouldApplyLiveShareRefresh(latestLocalSnapshot)) {
            if (shouldShowLiveShareVoteWait(latestLocalSnapshot)) {
                renderLiveShareVoteWaitState(roomId, latestLocalSnapshot);
            } else {
                renderSharedSeasonSnapshot(latestLocalSnapshot);
            }
        }
    }, 4000);

    const db = getLiveShareDb();
    if (!db) {
        if (!sharedSnapshot) {
            renderLiveShareWaitingState(roomId, "Live season sharing is unavailable right now.", true);
        }
        return;
    }

    if (liveShareWatcherRef) {
        liveShareWatcherRef.off("value");
    }

    liveShareWatcherRef = db.ref(LIVE_SHARE_DB_PATH + "/" + roomId);
    liveShareWatcherRef.on("value", (snapshot) => {
        const season = snapshot.val();
        if (!season) {
            cleanupLiveScreenShareViewerConnection(true);
            window.clearInterval(liveShareLocalWatchTimer);
            liveShareLocalWatchTimer = null;
            renderLiveShareWaitingState(roomId, "This live stream link is no longer valid.", true);
            return;
        }
        if (!hasAccessToSharedSeason(season)) {
            renderLiveShareWaitingState(roomId, "This viewer link is private or invalid.", true);
            return;
        }
        if (season.liveShare && isLiveShareExpired(season.liveShare)) {
            liveShareWatcherRef.remove().catch(() => {});
            renderLiveShareWaitingState(roomId, "This shared sim expired after 30 days and was cleaned up.", true);
            return;
        }
        liveShareFallbackMode = false;
        if (getLiveShareModeFromRecord(season) === LIVE_SHARE_MODE_SCREEN) {
            renderLiveScreenShareState(
                roomId,
                season.liveShare && season.liveShare.screenShareActive
                    ? "Connecting to the host screen…"
                    : "The host has not started the screen share yet.",
                false
            );
            ensureLiveScreenShareViewerConnection(roomId).catch(() => {
                renderLiveScreenShareState(roomId, "Could not connect to the host screen right now.", true);
            });
            return;
        }
        cleanupLiveScreenShareViewerConnection(true);
        if (!shouldApplyLiveShareRefresh(season)) {
            return;
        }
        persistLiveShareSnapshot(season);
        if (shouldShowLiveShareVoteWait(season)) {
            renderLiveShareVoteWaitState(roomId, season);
            return;
        }
        renderSharedSeasonSnapshot(season);
    }, (error) => {
        console.error("Failed loading live season updates:", error);
        liveShareFallbackMode = true;
        const latestSnapshot = getBestAvailableSharedSnapshot(roomId);
        if (latestSnapshot) {
            if (shouldApplyLiveShareRefresh(latestSnapshot)) {
                renderSharedSeasonSnapshot(latestSnapshot);
            }
            if (typeof showFloatingNotice === "function") {
                showFloatingNotice("Viewing the shared snapshot. Live auto-refresh is unavailable.", 2600);
            }
            return;
        }
        renderLiveShareWaitingState(roomId, "Something went wrong while loading the live season.", true);
    });
}

function ensureLiveSharePanel() {
    const existingPanel = document.getElementById("ss-live-share-panel");
    if (existingPanel) {
        existingPanel.remove();
    }

    if (liveSharePanelRefreshTimer) {
        window.clearInterval(liveSharePanelRefreshTimer);
        liveSharePanelRefreshTimer = null;
    }
}

async function ensureLiveShareRoomReady(force = false) {
    if (liveSeasonSpectatorMode || !isLiveSeasonStreamingEnabled()) {
        return null;
    }

    if (!currentLiveShareRoomId) {
        currentLiveShareRoomId = await reserveLiveShareRoomId();
    }

    persistLiveShareRoomMeta({ refreshSignal: Date.now().toString() });

    if (isLiveSeasonScreenShareMode()) {
        const waitingRecord = buildLiveShareWaitingRecord(currentLiveShareRoomId, "live");
        const waitingFingerprint = getLiveShareWaitingFingerprint(waitingRecord);
        const db = getLiveShareDb();

        if (db && (force || waitingFingerprint !== liveShareLastWaitingFingerprint)) {
            await db.ref(LIVE_SHARE_DB_PATH + "/" + currentLiveShareRoomId).update(waitingRecord);
        }

        liveShareLastWaitingFingerprint = waitingFingerprint;
        liveShareFallbackMode = !db;
        persistLiveShareRoomMeta({ mode: LIVE_SHARE_MODE_SCREEN });
        persistLiveShareSnapshot(waitingRecord);
        updateLiveSharePanel();

        if (liveShareScreenStream) {
            await ensureLiveScreenShareHostListeners(currentLiveShareRoomId);
        }

        return waitingRecord;
    }

    if (!hasLiveSeasonData()) {
        const waitingRecord = buildLiveShareWaitingRecord(currentLiveShareRoomId, "live");
        const waitingFingerprint = getLiveShareWaitingFingerprint(waitingRecord);
        const db = getLiveShareDb();

        if (db && (force || waitingFingerprint !== liveShareLastWaitingFingerprint)) {
            await db.ref(LIVE_SHARE_DB_PATH + "/" + currentLiveShareRoomId).set(waitingRecord);
        }

        liveShareLastWaitingFingerprint = waitingFingerprint;
        liveShareFallbackMode = !db;
        persistLiveShareRoomMeta();
        persistLiveShareSnapshot(waitingRecord);
        updateLiveSharePanel();
        return waitingRecord;
    }

    try {
        const record = await syncCurrentSeasonToLiveShare(force);
        startLiveShareAutoSync();
        return record;
    } catch (err) {
        handleLiveShareSyncError(err);
        startLiveShareAutoSync();
        const fallbackRecord = buildCompactLiveShareRecord(currentLiveShareRoomId);
        persistLiveShareRoomMeta();
        persistLiveShareSnapshot(fallbackRecord);
        updateLiveSharePanel();
        return fallbackRecord;
    }
}

function maybeEnableAutomaticLiveShare() {
    if (liveSeasonSpectatorMode || document.location.pathname.includes("history.html") || !isLiveSeasonStreamingEnabled()) {
        return;
    }

    if (!isLiveSeasonScreenShareMode()) {
        ensureLiveShareDomObserver();
    }

    if (liveShareAutoRestoreAttempted || !hasLiveSeasonData()) {
        return;
    }

    liveShareAutoRestoreAttempted = true;
    ensureLiveShareRoomReady(true).catch(() => {});
}

function updateLiveSharePanel() {
    maybeEnableAutomaticLiveShare();

    const panel = document.getElementById("ss-live-share-panel");

    const status = panel ? panel.querySelector("#ss-live-share-status") : null;
    const copyBtn = panel ? panel.querySelector("#ss-live-share-copy") : null;
    const stopBtn = panel ? panel.querySelector("#ss-live-share-stop") : null;
    const shareBtn = panel ? panel.querySelector("button") : null;
    const toggle = panel ? panel.querySelector("#ss-live-share-enabled") : null;
    const twistToggle = document.getElementById("liveStreamingToggle");
    const voteWaitSelect = panel ? panel.querySelector("#ss-live-share-vote-wait") : null;
    const twistVoteWaitSelect = document.getElementById("liveShareVoteWaitMenu");
    const menuStatus = document.getElementById("liveShareStatusMenu");
    const menuShareBtn = document.getElementById("liveShareRefreshBtn");
    const menuCopyBtn = document.getElementById("liveShareCopyBtn");
    const menuStopBtn = document.getElementById("liveShareStopBtn");
    const streamingEnabled = isLiveSeasonStreamingEnabled();
    const shareMode = getLiveSeasonShareMode();
    const shouldShow = !liveSeasonSpectatorMode && (hasLiveSeasonData() || !!currentLiveShareRoomId);

    if (panel) {
        panel.style.display = shouldShow ? "block" : "none";
    }

    if (toggle) toggle.checked = streamingEnabled;
    if (twistToggle) twistToggle.checked = streamingEnabled;
    if (voteWaitSelect) voteWaitSelect.value = String(getLiveShareVoteWaitSeconds());
    if (twistVoteWaitSelect) twistVoteWaitSelect.value = String(getLiveShareVoteWaitSeconds());
    const twistMode = document.getElementById("liveShareModeMenu");
    if (twistMode) twistMode.value = shareMode;

    if (!streamingEnabled) {
        const offMessage = shareMode === LIVE_SHARE_MODE_SCREEN
            ? "Streaming is off. Press Start Streaming when you want spectators to connect to your live screen."
            : "Streaming is off. Press Start Streaming when you want spectators. Live voting is disabled for now.";
        if (status) {
            status.textContent = offMessage;
        }
        if (menuStatus) {
            menuStatus.textContent = offMessage;
        }
        if (copyBtn) copyBtn.style.display = "none";
        if (stopBtn) stopBtn.style.display = "none";
        if (menuCopyBtn) menuCopyBtn.style.display = "none";
        if (menuStopBtn) menuStopBtn.style.display = "none";
        if (shareBtn) {
            shareBtn.textContent = shareMode === LIVE_SHARE_MODE_SCREEN ? "Start screen share" : "Start streaming";
            shareBtn.disabled = false;
            shareBtn.style.opacity = "1";
            shareBtn.style.cursor = "pointer";
        }
        if (menuShareBtn) {
            menuShareBtn.textContent = shareMode === LIVE_SHARE_MODE_SCREEN ? "Start Screen Share" : "Start Streaming";
            menuShareBtn.disabled = false;
            menuShareBtn.style.opacity = "1";
            menuShareBtn.style.cursor = "pointer";
        }
        return;
    }

    if (shareBtn) {
        shareBtn.disabled = false;
        shareBtn.style.opacity = "1";
        shareBtn.style.cursor = "pointer";
    }
    if (menuShareBtn) {
        menuShareBtn.disabled = false;
        menuShareBtn.style.opacity = "1";
        menuShareBtn.style.cursor = "pointer";
    }

    if (currentLiveShareRoomId) {
        const liveMessage = shareMode === LIVE_SHARE_MODE_SCREEN
            ? (liveShareScreenStream
                ? "Screen sharing is live now. Viewers can open the watch link and connect in real time."
                : "Watch link is ready. Viewers will see a waiting screen until you start screen sharing.")
            : (!hasLiveSeasonData()
                ? "Watch link is ready. Viewers will see a waiting screen until the season begins."
                : liveShareFallbackMode
                    ? "Live updates are unavailable. Retrying automatically; viewers may see an older track record."
                    : "Sharing is live now and updates automatically for viewers.");
        if (status) {
            status.textContent = liveMessage;
        }
        if (menuStatus) {
            menuStatus.textContent = liveMessage;
        }
        if (copyBtn) copyBtn.style.display = "inline-flex";
        if (stopBtn) stopBtn.style.display = "inline-flex";
        if (menuCopyBtn) menuCopyBtn.style.display = "inline-flex";
        if (menuStopBtn) menuStopBtn.style.display = "inline-flex";
        if (shareBtn) {
            shareBtn.textContent = shareMode === LIVE_SHARE_MODE_SCREEN
                ? (liveShareScreenStream ? "Restart screen share" : "Start screen share")
                : (liveShareFallbackMode ? "Copy updated link" : "Refresh viewers");
        }
        if (menuShareBtn) {
            menuShareBtn.textContent = shareMode === LIVE_SHARE_MODE_SCREEN
                ? (liveShareScreenStream ? "Restart Screen Share" : "Start Screen Share")
                : (liveShareFallbackMode ? "Copy Updated Link" : "Refresh Viewers");
        }
    } else {
        const readyMessage = shareMode === LIVE_SHARE_MODE_SCREEN
            ? "Press Start Screen Share when you want spectators to connect to your live screen."
            : "Press Start Streaming when you want spectators.";
        if (status) {
            status.textContent = readyMessage;
        }
        if (menuStatus) {
            menuStatus.textContent = readyMessage;
        }
        if (copyBtn) copyBtn.style.display = "none";
        if (stopBtn) stopBtn.style.display = "none";
        if (menuCopyBtn) menuCopyBtn.style.display = "none";
        if (menuStopBtn) menuStopBtn.style.display = "none";
        if (shareBtn) shareBtn.textContent = shareMode === LIVE_SHARE_MODE_SCREEN ? "Start screen share" : "Start streaming";
        if (menuShareBtn) menuShareBtn.textContent = shareMode === LIVE_SHARE_MODE_SCREEN ? "Start Screen Share" : "Start Streaming";
    }
}

function initLiveSeasonShareExperience() {
    if (window.__ssLiveSeasonShareInitialized) {
        return;
    }
    window.__ssLiveSeasonShareInitialized = true;
    installLiveShareQuitGuard();

    const roomId = getSharedSeasonRoomIdFromUrl();

    if (roomId && !isLiveShareWatchPage()) {
        window.location.replace(getLiveSeasonWatchUrl(roomId));
        return;
    }

    if (isLiveShareWatchPage()) {
        if (roomId) {
            watchSharedSeasonRoom(roomId);
            applyInviteClaimFromUrl();
        } else if (getSharedPublicIdFromUrl()) {
            openSharedCustomQueenFromUrl()
                .then((openedSharedQueen) => {
                    if (openedSharedQueen) {
                        return true;
                    }
                    return openSharedHistorySeasonFromUrl();
                })
                .then((openedShared) => {
                    if (!openedShared) {
                        renderLiveShareWaitingState("share", "Could not load this shared link right now.", true);
                    }
                })
                .catch(() => {
                    renderLiveShareWaitingState("share", "Could not load this shared link right now.", true);
                });
        } else {
            renderLiveShareWaitingState("private", "This viewer page needs the full shared link from the host.", true);
        }
        return;
    }

    if (!document.location.pathname.includes("history.html")) {
        ensureLiveSharePanel();
        maybeEnableAutomaticLiveShare();
        updateLiveSharePanel();
        applyInviteClaimFromUrl();
    }
}

async function saveSeasonToHistory() {
    if (typeof window.getUserHistoryAccess === "function") {
        const access = await window.getUserHistoryAccess();
        if (access.blocked) {
            alert("\u274C History access required.\n\n" + (access.reason || "You need history access to save seasons."));
            return;
        }
    }

    if (!hasLiveSeasonData()) {
        alert("No season data to save.");
        return;
    }

    const storedHistory = getLocalSeasonHistoryRecords();
    const seasonNum = storedHistory.length + 1;
    const defaultName = "Season " + seasonNum;
    const defaultType = inferSeasonTypeKeyFromState();
    const statsSnapshots = captureAllStatsHistorySnapshots();

    openSaveSeasonHistoryModal(defaultName, defaultType, (seasonName, savedSeasonType, targetFranchise) => {
        try {
            const record = buildCurrentSeasonHistoryRecord({ seasonName, savedSeasonType, statsSnapshots });
            if (!record) {
                alert("No season data to save.");
                return;
            }

            addSeasonRecordToHistory(record, {
                franchise: targetFranchise,
                source: "manual",
                notice: '"' + seasonName + '" saved to Season History!'
            });

            if (currentLiveShareRoomId) {
                syncCurrentSeasonToLiveShare(true).catch(() => {});
            }
        } catch (err) {
            alert("\u274C Could not save this season.\n\n" + (err && err.message ? err.message : String(err)));
            if (typeof console !== "undefined" && console.error) {
                console.error("saveSeasonToHistory failed:", err);
            }
        }
    });
}

function downloadSeasonBackup(record) {
    const backup = {
        type: "simulator-superstars-season-backup",
        version: 1,
        exportedAt: new Date().toISOString(),
        season: compactHistoryRecordForStorage(record)
    };
    const safeName = String(record.name || "season")
        .trim()
        .replace(/[^a-z0-9_-]+/gi, "-")
        .replace(/^-+|-+$/g, "") || "season";
    const blob = new Blob([JSON.stringify(backup)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = safeName + ".simseason.json";
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function exportCurrentSeasonBackup() {
    const record = buildCurrentSeasonHistoryRecord({
        seasonName: getCurrentLiveSeasonName() || "Season Backup",
        savedSeasonType: inferSeasonTypeKeyFromState(),
        statsSnapshots: captureAllStatsHistorySnapshots()
    });
    if (!record) {
        alert("No season data to export.");
        return false;
    }
    downloadSeasonBackup(record);
    return true;
}

function importSeasonBackup() {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = ".json,.simseason.json,application/json";
    input.addEventListener("change", async () => {
        const file = input.files && input.files[0];
        if (!file) return;
        try {
            const backup = JSON.parse(await file.text());
            if (!backup || backup.type !== "simulator-superstars-season-backup" || backup.version !== 1 || !backup.season) {
                throw new Error("This is not a valid Simulator Superstars season backup.");
            }
            const record = JSON.parse(JSON.stringify(backup.season));
            record.id = "season-" + Date.now() + "-" + Math.floor(Math.random() * 1000000);
            record.savedAt = new Date().toISOString();
            const stored = addSeasonRecordToHistory(record, {
                franchise: record.historyFranchise || getCurrentSeasonHistoryFranchise(),
                source: "backup-import",
                notice: '"' + (record.name || "Season") + '" imported into Season History!'
            });
            if (!stored) {
                throw new Error("Storage is still full. Delete an older season, then import this backup again.");
            }
            viewSeasonHistory();
        } catch (error) {
            const message = error && error.message ? error.message : String(error);
            if (typeof window.showInHouseAlert === "function") {
                window.showInHouseAlert(message, "Import Season");
            } else {
                alert(message);
            }
        }
    }, { once: true });
    input.click();
}

