function getSelectedCustomQueenIndex() {
    const select = document.getElementById("custom-remove");
    if (!select || select.selectedIndex < 0) {
        return -1;
    }
    return Number(select.options[select.selectedIndex].value);
}

function buildShareableCustomQueenRecord(idx = getSelectedCustomQueenIndex()) {
    const queen = allCustomQueens[idx];
    if (!queen) {
        return null;
    }

    const images = Array.isArray(queen.images) && queen.images.length > 0
        ? queen.images.map(image => resolveTrackedCustomImage(image))
        : [resolveTrackedCustomImage(queen.getCurrentImage())];

    return {
        _name: queen._name || queen.name,
        name: queen.name,
        _actingStat: queen._actingStat || 0,
        _comedyStat: queen._comedyStat || 0,
        _danceStat: queen._danceStat || 0,
        _designStat: queen._designStat || 0,
        _improvStat: queen._improvStat || 0,
        _runwayStat: queen._runwayStat || 0,
        _lipsyncStat: queen._lipsyncStat || 0,
        images,
        image: images[0] || "",
        isDuo: !!queen.isDuo,
        name1: queen.name1 || "",
        name2: queen.name2 || "",
        country: queen.country || null,
        custom: true,
        customqueen: true
    };
}

