    if (flags.titans_format) return "Titans Dragula";
    if (flags.dragula_format) return "Regular Dragula";
    if (flags.og_lsa) return "OG Lip Sync Assassin";
    if (flags.lipsync_assassin) return "Lip Sync Assassin";
    if (flags.all_winners && flags.as9FormatMod) return "Charity Format";
    if (flags.all_winners) return "All Winners";
    if (flags.slaysian_rules) return "Slaysian Format";
    if (flags.safetyFormat) return "Safety Format";
